    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // Gaps below the minimum plausible item size (<= 10) are pure waste.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 25.0;
    }

    // Reward tight fits strongly.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Penalize leaving a gap that exactly cannot serve the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward reserving space exactly for the next item (perfect chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; dampen new-bin appeal.
    let bin_pressure = (open_bins_count as f64).sqrt() * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when few bins or huge item.
        score += bin_pressure - 10.0 * fill_ratio;
    } else {
        score -= bin_pressure * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins below mean residual (fill the emptier ones evenly is bad;
    // instead favor bins with residual near item size = tight fit).
    let tightness = 1.0 - ((bin_residual - item_size) as f64 / bin_capacity as f64);
    score -= 5.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Base: prefer tight fits (low post residual), normalized pressure
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if residual after placement can host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // next item fits here: reward proportionally to how well it fills
            let fill_after_next = (post - nxt) / cap;
            score -= 10.0 * (1.0 - fill_after_next);
        } else {
            // dead space relative to next item: penalize
            score += 0.35 * (nxt - post);
        }
    } else {
        // last item: pure tight-fit preference
        score -= 8.0 * tightness;
    }

    // Penalize creating very small unusable fragments (<10 min item)
    if post > 0.0 && post < 10.0 {
        score += 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // prefer opening new bins when existing residuals are large or few bins
        score = 45.0 + 40.0 * crowding - 10.0 * progress - 2.0 * open_bins_count as f64;
        // don't open a new bin if item fits very snugly somewhere else is handled by others' low scores
        if item_size as f64 > 0.6 * cap {
            score -= 15.0; // big items: fresh bin is fine
        }
    } else {
        // mild bonus for using bins that are already below-average residual (consolidation)
        let res = bin_residual as f64;
        if res < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0 * ((res - mean_residual) / cap);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
