pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..10)
    // can use are pure waste -> heavy penalty.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // unusable micro-gap
        } else if post_residual < 20 {
            score += 25.0; // nearly unusable
        } else if post_residual < 35 {
            score += 8.0;  // only small items fit
        }
    } else {
        score -= 40.0; // perfect fit: fully packed bin
    }

    // Reward placements that leave room for the lookahead item exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            if post_residual == next_item_size {
                score -= 15.0; // lookahead perfect fit
            }
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0; // gap blocks the known next item
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: prefer filling existing bins as count grows.
    score -= (open_bins_count as f64) * 0.8;

    // Slight preference for tighter bins overall (small residual = well used).
    score += (bin_residual as f64) * 0.15;

    // Mild stream-progression tightening: later, avoid waste more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    // Prefer bins below mean residual (already fuller than average).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

