pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual penalty for wasted space.
    let waste = post_residual as f64;
    score += 0.5 * (waste * waste) / bin_capacity as f64;

    // Lookahead: if the next item fits into the post-residual, reward this bin
    // (keeps chains of compatible items together).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty so we don't strand
        // a large residual that nothing can use.
        score += 0.02 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits the item, strongly
    // prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize crowding when many bins compete but this fit is mediocre.
    if fitting_bins_count > 1 {
        score += 0.3 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate logic: only attractive when the item is large relative
    // to typical residuals, or when global residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a bin, discounted for large items and late stream.
        score += 30.0 - 20.0 * fill_ratio - 10.0 * progress;
        // If open bins are heavily fragmented (high mean residual, many bins),
        // opening fresh is less bad.
        score -= 0.05 * mean_residual * (open_bins_count as f64).ln().max(1.0);
        // Never open a new bin if a perfect-ish fit exists elsewhere.
        if post_residual <= 5 {
            score += 100.0;
        }
    }

    // Mild global pressure: when mean residual is small, conserve bins tightly.
    score -= 0.03 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling: residual fraction transformed smoothly
    let x = pr / cap; // in [0,1)
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep-like shaping of dead space
    score += poly * cap * (0.5 + 0.5 * progress);

    // Reward tight fits more aggressively as stream progresses
    let tightness = 1.0 - x;
    score -= tightness * tightness * (10.0 + 40.0 * progress);

    // Penalize bins whose residual deviates from mean (fragmentation avoidance)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * cap;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 25.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / cap);
    }

    // New-bin candidate: baseline cost that grows with open bins and progress
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.3 * progress) + 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Class index via integer division thresholds on post_residual (harmonic buckets)
    let class = post_residual / (bin_capacity / 8); // 8 harmonic classes: 0..=8
    match class {
        0 => score -= 60.0,           // near-perfect fit, excellent
        1 => score -= 35.0,           // very tight
        2 => score -= 18.0,
        3 => score -= 5.0,
        4 => score += 0.0,            // half-empty: neutral
        5 => score += 8.0,
        6 => score += 16.0,
        _ => score += 25.0,           // nearly empty bin used wastefully
    }

    // Dead-space penalty grows superlinearly for medium leftovers (hard to fill later)
    if frac > 0.25 && frac < 0.6 {
        score += 20.0 * (0.6 - frac) * (frac - 0.25) * 4.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // harmonic class of the double-fit leftover
            let double_left = post_residual - next_item_size;
            score -= 30.0 * (1.0 - double_left as f64 / cap);
        } else {
            // next item won't fit: leftover is final dead space
            score += 0.15 * pr;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate handling: empty bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap * 0.85;
        // cheaper to open new bin if current open bins are congested / stream is early
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        // if mean residual across open bins is small, opening a bin is attractive
        score -= (mean_residual / cap).max(0.0) * 40.0;
        // if many bins could fit, prefer reusing one
        score += fitting_bins_count as f64 * 12.0;
        // if item is large, new bin is fine (large items pair well later)
        if item_size >= bin_capacity / 2 {
            score -= 25.0;
        }
    }

    // Mild global pressure: with many open bins, prefer consolidation (lower residual wins anyway)
    score += 0.05 * open_bins_count as f64 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space zone: residuals 1..=9 are nearly unusable (min item is 1, but
    // statistically hard to fill); penalize non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 6.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Post residual that exactly matches the next item: reserve bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize if post_residual is slightly larger than next item (wasted reservation).
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; a new-bin candidate (residual == capacity) gets penalized.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64).ln().max(0.0) * 10.0;
    }

    // Prefer bins below mean residual (fill the emptier bins first) mildly,
    // but tight-fit logic above dominates.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Late in stream, be more aggressive at avoiding new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits in post_residual with small waste
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / 30.0).max(0.0);
    } else if next_item_size > post_residual {
        // Next item won't fit: dead space risk, penalize proportionally
        score += 10.0 + (next_item_size - post_residual) as f64 * 0.3;
    }

    // Reward tight fills relative to mean residual across open bins
    let tightness = (item_size as f64) / bin_capacity as f64;
    score -= 20.0 * tightness;
    if (bin_residual as f64) > mean_residual * 1.2 {
        score -= 8.0; // prefer consuming bins with unusually large residuals
    } else if (bin_residual as f64) < mean_residual * 0.8 {
        score += 6.0; // penalize wasting small residuals
    }

    // Last fitting bin: strong incentive to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Late-stream consolidation: favor closing out bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1), used as dynamic time horizon.
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };

    // Fill ratio of this bin before placement.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    // Reward tight fits: penalize bins whose post_residual is small relative to item size.
    let tightness = item_size as f64 / (post_residual.max(1) as f64 + item_size as f64);
    score -= 6.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0; // near-perfect fit, dead space under min item size
    } else if post_residual < 20 {
        score -= 4.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual > next_item_size {
            score -= 2.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here; slight penalty proportional to wasted lookahead chance
            score += 3.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * fill;
        if post_residual > 50 {
            score += 8.0; // terrible fit: would strand a huge residual
        }
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 20.0;
        // Open new bin when no existing bin fits well: large item, high mean residual,
        // or many open bins with fragmented space.
        let mean_r = if mean_residual.is_finite() { mean_residual } else { 0.0 };
        if fitting_bins_count == 0 || (item_size >= 50 && mean_r > item_size as f64 * 0.6) {
            score -= 30.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += 10.0 * progress;
        // More open bins -> slightly prefer new bin to balance load.
        score -= (open_bins_count as f64).min(5.0);
    } else {
        // Reward using fuller bins (best-fit bias) scaled by global mean residual.
        score -= fill * 5.0;
        // Penalize bins far from the mean residual when mean residual is small (good state to preserve).
        let dev = (bin_residual as f64 - mean_residual).abs();
        if mean_residual < 30.0 {
            score += 0.05 * dev;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress = progress.clamp(0.0, 1.0);

    // Smooth polynomial coupling: penalize residual quadratically, more strongly later in the stream
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;
    score += (rn * rn) * cap * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth cubic bonus
    score -= (1.0 - rn).powi(3) * item_size as f64 * 0.4;

    // Smooth interaction between post_residual and mean residual across open bins:
    // penalize bins whose residual deviates from the fleet mean (creates fragmentation)
    let dev = r - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Last-chance bin: strongly favor using it when it fits (avoid opening new bins)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead coupling: reward leaving a residual close to the next item size (smooth bell)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (r - nx) / cap;
        score -= 10.0 * (-(diff * diff * 40.0)).exp();
    }

    // Mild penalty for spreading across many open bins, smoothed by progress
    score += (open_bins_count as f64).sqrt() * (1.0 - progress) * 2.0;

    // New-bin candidate: make empty bins mildly attractive only when no tight fit exists,
    // via smooth dependence on post_residual of the new bin (= full capacity)
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by common item
    // granularity are more reusable than odd fragments.
    let pr = post_residual;
    let class_penalty = match pr {
        0 => -40.0,                          // perfect close
        x if x % 10 == 0 => -18.0,           // highly reusable residue
        x if x % 5 == 0 => -8.0,             // moderately reusable
        x if x <= 5 => 25.0,                 // dead space sliver
        _ => 0.0,
    };
    score += class_penalty as f64;

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 && next_item_size <= bin_capacity {
        if next_item_size <= pr && pr > 0 {
            // Chain fit: strong reward, scaled by how snug the chain is.
            let snug = (next_item_size as f64) / (pr as f64);
            score -= 15.0 + 20.0 * snug;
        } else if next_item_size > pr {
            // Next item won't fit here; penalize leaving large unusable gap
            // relative to the next item's demand.
            let gap = (pr as f64) / (next_item_size as f64);
            score += 10.0 * (1.0 - gap.min(1.0));
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: encourage filling existing ones rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * (open_bins_count as f64) * (1.0 - progress);

    // Prefer bins whose residual is below the mean (tighter bins first),
    // keeping fresher/looser bins for future large items.
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.10 * dev;

    // New-bin candidate: only attractive when nothing fits well; make an
    // empty bin moderately costly so it loses to good fits but wins over
    // terrible ones.
    if bin_residual == bin_capacity {
        score += 12.0 - 0.02 * (open_bins_count as f64);
        if post_residual + item_size == bin_capacity {
            // large item into fresh bin is fine
            score -= 6.0;
        }
    }

    // Integer-division threshold: residues in the awkward 6..9 band are the
    // least reusable (no standard item fits), punish them hardest.
    if pr >= 6 && pr <= 9 {
        score += 15.0;
    }
    if pr >= 51 && pr <= 59 {
        // half-capacity residues pair well with mid-size items
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 10.0 {
        score += 60.0 * (10.0 - gap) / 10.0;
    }
    // Medium gaps (10..20) are semi-dead: moderate penalty.
    if gap >= 10.0 && gap < 20.0 {
        score += 15.0 * (20.0 - gap) / 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        let pressure = 8.0 + 2.5 * open_bins_count as f64;
        score += pressure;
        // Opening a new bin is acceptable if current bin would leave a bad gap
        // and the next item could fill the fresh bin well.
        if gap > 0.0 && gap < 20.0 && next_item_size as f64 >= bin_capacity as f64 * 0.8 {
            score -= 30.0;
        }
    } else {
        // Favor tighter existing bins relative to mean residual.
        score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;
    }

    // Lookahead: if next item exactly fills the resulting gap, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // If next item cannot fit in the post residual, the gap is dead for the lookahead.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 20.0;
    }

    // Slight stream-progression tightening: later in the stream, be more frugal.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += gap * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item -> strong reward.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 0.5 {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here: mild reward proportional to closeness of match.
            let gap = post_residual as f64 - next;
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item will NOT fit: penalize creating dead space, worse if tiny.
            let dead = post_residual as f64;
            score += 8.0 * (1.0 - dead / bin_capacity as f64);
        }
    } else {
        // Last item: just minimize waste.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive if it gives room for the next item too.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 15.0;
        }
    }

    // Prefer filling bins that are already below average residual (consolidation).
    let r = bin_residual as f64;
    if r < mean_residual {
        score -= 3.0 * (mean_residual - r) / bin_capacity as f64;
    }

    // Early in the stream, be more willing to open bins; late, tighten packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.85 {
        score -= 40.0 * fit_ratio;
    } else {
        score += 10.0 * (1.0 - fit_ratio);
    }

    // Penalize creating dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size < post_residual {
            score -= 5.0;
        } else {
            // Next item won't fit here; slight penalty for stranding space.
            score += 8.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity or current bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = mean_residual / bin_capacity as f64;
        // Penalize new bins early when open bins still have room; relax later.
        score += 30.0 + 60.0 * (1.0 - progress) * openness - 20.0 * (item_size as f64 / bin_capacity as f64);
        // If no open bin fits, new bin becomes reasonable.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for bins with residual close to the global mean (balance).
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    // Encourage using many open bins rather than proliferating them.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with a non-linear (quadratic) penalty
    // for leaving dead space that grows as the stream progresses.
    let mut score = pr * (1.0 + 0.8 * progress * progress)
        + 120.0 * norm_pr * norm_pr * (0.5 + progress);

    // Smooth coupling: reward tight fits more strongly late in the stream.
    let fit_tightness = 1.0 - norm_pr;
    score -= 40.0 * fit_tightness * fit_tightness * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // (smoothly scaled by how well the item actually fills the bin).
    if fitting_bins_count == 1 {
        score -= 60.0 * (0.5 + 0.5 * fit_tightness);
    }

    // Lookahead coupling: penalize bins whose residual won't fit the next item
    // (wasted potential), reward ones that stay usable.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 15.0 * (1.0 - (pr - ni) / cap);
        } else {
            score += 10.0 * (ni - pr) / cap;
        }
    }

    // Slight preference for consolidating into fewer bins when many are open.
    score += 2.0 * (open_bins_count as f64).sqrt() * norm_pr;

    // New-bin candidate: make an empty bin mildly unattractive by default so
    // existing bins are used, but allow it to win when residuals are fragmented.
    if bin_residual == bin_capacity {
