        score = 45.0 + 50.0 * fragmentation - 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals in [1..10] are near-dead; [11..25] awkward; [26..50] decent; >50 great.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect close
    } else if pr <= 10 {
        score += 25.0; // dead space penalty
    } else if pr <= 25 {
        score += 10.0;
    } else if pr <= 50 {
        score -= 5.0;
    } else {
        score -= 12.0;
    }

    // Modulo-class coupling: does the leftover admit the next item exactly / with slack?
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        if slack == 0 {
            score -= 40.0; // chains perfectly with lookahead
        } else if slack <= 10 {
            score -= 15.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > pr {
        // next item won't fit here: leftover is likely stranded
        score += (next_item_size - pr) as f64 * 0.5;
    }

    // Integer-division threshold: bins whose residual is a multiple of common item
    // sizes (10/20/25) are more likely to be filled exactly later.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    } else if pr % 5 == 0 {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = (fitting_bins_count == 0) as i32;
        let late = step_index as f64 / (total_items.max(1) as f64);
        score = if pressure == 1 { -5.0 } else { bin_capacity as f64 + 40.0 + 20.0 * late };
    }

    // Prefer tight fills relative to mean residual of open bins.
    score -= (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (min item size 1, but practically small gaps
    // below ~15 are wasteful) get heavily penalized.
    if post_residual > 0 && post_residual < 15 {
        score += 40.0;
