    // Coupling: penalty scaled by how tight the fit is relative to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins (new bin has residual == capacity, so boost its score).
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0;
