    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Mild pressure to reuse existing bins as the stream fills up.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New empty bin: make it unattractive unless current bin leaves huge dead space.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin still chains well with next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead-aware).
    if next_item_size > 0 && post_residual > 0 {
        if (next_item_size as f64) > post_residual as f64 {
            // Dead space: penalize proportionally to how wasted it is.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 8.0 * waste;
