    }

    // New-bin candidate: only attractive when current bin is a very poor fit
    // (large post-residual relative to typical item sizes).
    if bin_residual == bin_capacity {
        let openness = 1.0 - progress;
        // Penalize opening new bins early / when open bins fit decently.
        score += 18.0 * (1.0 - openness) + 2.0 * open_bins_count as f64;
        // But if next item is large and this item is small, a fresh bin may pay off.
        if next_item_size > 0 && (next_item_size as f64) > 0.7 * bin_capacity as f64 && item_size < 30 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
