    // Strong reward for perfect and near-perfect fits.
    if post_residual == 0 {
        score -= 1150.0;
    } else if post_residual <= 4 {
        score -= 75.0 + (4 - post_residual) as f64 * 10.0;
    }

    // Harmonic residue classes: residuals divisible by small units absorb future items well.
    let pr = post_residual;
    let class_bonus: f64 = if pr % 10 == 0 {
        30.0
    } else if pr % 5 == 0 {
        15.0
    } else if pr % 2 == 0 {
        5.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Dead-space penalty: tiny slivers are nearly unusable (non-linear, sharpest near zero).
    if pr > 0 && pr < 12 {
        score += 26.0 - pr as f64 * 1.6;
    }

    // Lookahead: next item fit quality into the post-placement residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 140.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            // Reward tight next-fits more aggressively; slack <= 10 is still excellent.
            score -= if slack <= 10 { 58.0 - slack as f64 * 2.5 } else { 30.0 - (slack as f64).min(30.0) };
        } else {
            score += (next_item_size - pr) as f64 * 0.6;
        }
        // Two-step lookahead: after placing next item, would this bin close perfectly?
        if next_item_size < pr {
            let pr2 = pr - next_item_size;
            if pr2 <= 6 {
                score -= 38.0;
            } else if pr2 == next_item_size {
                score -= 20.0;
            }
        }
        // NEW: chain lookahead — residual left after a hypothetical next placement should
        // itself be a "nice" target (harmonic) or large enough for typical items.
        if next_item_size < pr {
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 {
                score -= 14.0;
            }
            if pr2 > 0 && pr2 < 15 {
                score += 10.0; // chain would strand a sliver here
            }
        }
    }

    // Last-chance bin: sole fitting bin strongly preferred over opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate handling: empty bin should only win when reuse options are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = (mean_residual / bin_capacity as f64) < 0.38;
        let reuse_is_bad = fitting_bins_count <= 1
            || (post_residual > 0 && post_residual < next_item_size && next_item_size <= bin_capacity);
        // Large items or tight streams late in the run benefit from a fresh bin.
        if item_size >= 62 || (tight && progress > 0.2) || reuse_is_bad {
            score -= 40.0 + 25.0 * progress;
        } else {
            score += 65.0; // strongly prefer reusing open bins early/mid stream
        }
        // Penalize opening a fresh bin for small items when open bins have generous space.
        if item_size <= 25 && mean_residual > bin_capacity as f64 * 0.45 {
            score += 30.0;
        }
    }

    // Prefer fuller bins (best-fit bias), slightly sharpened.
    score -= (bin_capacity - bin_residual) as f64 * 0.11;

    // Reward bins whose residual remains a flexible mid-range target after placement.
    if pr >= 25 && pr <= 60 {
        score -= 12.0;
    }

    // NEW: residual-utilization coupling — a residual that is an exact multiple of the
    // next item size is a prime target; a residual just below the next item is a trap.
    if next_item_size > 0 && pr > 0 {
        if pr % next_item_size == 0 {
            score -= 18.0;
        } else if pr < next_item_size && pr > 0 {
            // Residual too small for the next item: penalize proportionally to waste.
            score += (next_item_size - pr) as f64 * 0.35;
        }
    }

    // Mild penalty for bin proliferation, scaled by stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.2 + 0.2 * progress);

    // Waste-avoidance: penalize leaving residuals that no typical item (>= 20% capacity) can use.
    if pr > 0 && pr < bin_capacity / 5 {
        score += 8.0;
    }

    score
}

