    let class_bonus: f64 = if pr % 10 == 0 {
        36.0
    } else if pr % 5 == 0 {
        18.0
    } else if pr % 2 == 0 {
        5.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Lookahead: next item fit quality into the post-placement residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 178.0 + 40.0 * (1.0 - progress);
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= if slack <= 10 { 66.0 - slack as f64 * 2.6 } else { 34.0 - (slack as f64).min(30.0) * 0.5 };
        } else {
            score += (next_item_size - pr) as f64 * 0.68;
        }
        // Two-step lookahead: would this bin close (nearly) perfectly after next item?
        if next_item_size < pr {
            let pr2 = pr - next_item_size;
            if pr2 <= 6 {
                score -= 52.0;
            } else if pr2 == next_item_size {
                score -= 27.0;
            } else if pr2 % 10 == 0 {
                score -= 12.0;
            }
            // Chain absorbency: residual is a multiple of the item size.
            if pr2 >= 2 * item_size && pr2 % item_size.max(1) == 0 {
                score -= 8.0;
            }
            // Chain divisibility by next item suggests a repeatable fill.
            if pr2 > 6 && next_item_size > 1 && pr2 % next_item_size == 0 {
                score -= 15.0;
            }
            // Triple-stack chain: pr2 still fits a third copy of the item.
            if pr2 >= 3 * item_size as u32 {
                score -= 6.0;
            }
        }
    }

