    if open_bins_count > 8 && progress > 0.25 && progress < 0.85 && pr >= 40 {
        score -= 9.0;
    }

    // Dead-space ratio shaping with running small-item floor.
    if pr > 0 && next_item_size > 0 {
        let dead_threshold = (next_item_size + 12).min(bin_capacity);
        if pr < dead_threshold {
            let dead_frac = 1.0 - (pr as f64 / dead_threshold as f64);
            // Quadratic ramp: penalize deep dead-space disproportionately.
            score += 16.0 * dead_frac * dead_frac * (1.0 - progress) + 4.0 * dead_frac;
        } else if pr >= dead_threshold * 2 {
            score -= 8.0 + 4.0 * (1.0 - progress);
        } else {
            // Mid-zone residual exactly absorbable by next item gets extra credit.
            if pr == next_item_size + item_size {
                score -= 5.0;
            }
        }
    }

    // Endgame exactness: near the end, only exact/near-exact closures matter.
    if progress > 0.9 && pr > 0 {
        score += pr as f64 * 0.35;
        if pr <= next_item_size.max(1) {
            score -= 20.0;
        }
    }

    // Pair-absorbency — residual can host next item twice exactly.
    if pr > 0 && next_item_size > 1 && pr == 2 * next_item_size {
        score -= 22.0;
    }

    // Avoid stranding residuals just below the next item (worst-case dead space).
    if pr > 0 && next_item_size > 0 && pr < next_item_size {
        score += 9.0 * (1.0 - progress);
    }

    // NEW: gap-to-next shaping — residuals within a small window just above the
    // next item are excellent hosts; reward proportionally to snugness.
    if pr > next_item_size && next_item_size > 0 {
        let gap = pr - next_item_size;
        if gap <= 3 {
            score -= 30.0 - gap as f64 * 6.0;
        }
    }

    // NEW: dual-fit check — prefer bins whose post-residual can still host the
    // item itself again (homogeneous stacking potential).
    if pr >= item_size && pr % item_size.max(1) == 0 && item_size > 1 {
        score -= 10.0;
    }

    score
}

