        if pr % 3 == 0 && pr >= 6 {
            score -= 5.0;
        }
        if pr % 7 == 0 && pr >= 7 {
            score -= 4.0;
        }
        // NEW: strand-depth penalty — a residual just below the mean open
        // residual wastes the average fill opportunity; penalize quadratically
