        if dist < 0.25 {
            score -= 7.0 * (1.0 - dist / 0.25);
        }
    }

    // Dead-space ratio term — penalize bins whose post residual is a small
    // fraction of capacity that no plausible future item can use.
    if pr > 0 {
        let pr_f = pr as f64;
        let usable_floor = (next_item_size.max(1) as f64).min(cap_f * 0.3);
        if pr_f < usable_floor {
            let dsr = 1.0 - pr_f / usable_floor;
            score += 11.0 * dsr * dsr * (0.5 + 0.5 * (1.0 - progress));
        }
        // Residual divisibility shaping — residuals dividing cleanly by
        // common small item sizes are more likely to be filled later.
        if pr % 3 == 0 && pr >= 6 {
            score -= 5.0;
        }
        if pr % 7 == 0 && pr >= 7 {
            score -= 4.0;
        }
    }

