            // Refined triple-chain — next + item leaves near-perfect closure.
            if pr2 >= item_size.max(1) {
                let pr3 = pr2 - item_size.max(1);
                if pr3 <= 2 {
                    score -= 20.0 * (1.0 - progress);
                }
            }
            // NEW: second-order lookahead — after taking next, can the mean
            // residual still be absorbed? Penalize residuals that strand
            // the follow-up demand.
            if pr2 > 0 && mean_residual > 0.0 && pr2 < mean_residual as u32 && pr2 < next_item_size.max(1) * 2 {
                score += 5.0 * (1.0 - progress);
            }
        }
        // Pair-absorbency: residual hosts next item twice exactly.
        if pr > 1 && pr == 2 * next_item_size {
            score -= 22.0;
        }
        // Stranded residual just below next item.
        if pr > 0 && pr < next_item_size {
            let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
            score += (7.0 + 5.0 * gap_frac) * (1.0 - progress);
        }
    }

