        if pr >= next_item_size {
            let slack = pr - next_item_size;
            if slack <= 8 {
                score -= 4.0 * (1.0 - slack as f64 / 8.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        } else {
            let miss = next_item_size - pr;
            if miss <= 10 {
                score += (3.0 + 0.7 * (10 - miss) as f64) * (0.6 + 0.4 * (1.0 - progress));
            }
        }
    }

