            }
            // Triple-chain closure — next twice, then a tiny strand remains.
            if pr2 >= 2 * next_item_size {
                let pr3 = pr2 - 2 * next_item_size;
                if pr3 <= 3 {
                    score -= 24.0 * (1.0 - progress);
                }
            }
            // Refined triple-chain — next + item leaves near-perfect closure.
            if pr2 >= item_size.max(1) {
                let pr3 = pr2 - item_size.max(1);
                if pr3 <= 2 {
                    score -= 20.0 * (1.0 - progress);
                }
            }
        }
        if pr > 1 && pr == 2 * next_item_size {
