        }
    }

    // Quad-chain lookahead — residual hosts next item three times with
    // near-perfect closure, a strong absorbency signal.
    if next_item_size > 0 && pr >= 3 * next_item_size {
        let pr3 = pr - 3 * next_item_size;
        if pr3 <= 4 {
            score -= 18.0 * (1.0 - progress);
        }
    }

    // Item+next exact pair inside residual — both upcoming items fit
