        }
    }

    // Large-item protection — big items prefer bins leaving minimal slack
    // so their residual stays usable for small follow-ups.
    if item_size > 50 && pr > 0 && pr < 15 {
        score += 10.0 * (1.0 - pr as f64 / 15.0);
    }

    // NEW: divisibility absorbency — residuals that are clean multiples of
