    }

    // NEW: dead-space entropy guard — residuals just barely below the next
    // item size are the worst kind of waste; penalize the near-miss band
    // more sharply as the stream progresses.
    if pr > 0 && next_item_size > 0 && pr < next_item_size && next_item_size - pr <= 5 {
