pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Sharpened perfect/near-perfect closure rewards.
    if pr == 0 {
        score -= 1280.0;
    } else if pr <= 4 {
        score -= 92.0 + (4 - pr) as f64 * 13.0;
    } else if pr < 12 {
        score += 30.0 - pr as f64;
    }

    // Harmonic residue classes.
    let class_bonus: f64 = if pr % 10 == 0 {
        36.0
    } else if pr % 5 == 0 {
        18.0
    } else if pr % 2 == 0 {
        5.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Lookahead: next item fit quality into post-placement residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 178.0 + 40.0 * (1.0 - progress);
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= if slack <= 10 { 66.0 - slack as f64 * 2.6 } else { 34.0 - (slack as f64).min(30.0) * 0.5 };
        } else {
            score += (next_item_size - pr) as f64 * 0.68;
