    if next_item_size > 0 && pr >= item_size.max(1) {
        let pr2 = pr - item_size.max(1);
        if pr2 >= next_item_size {
            let slack2 = pr2 - next_item_size;
            if slack2 <= 3 {
                score -= (12.0 - slack2 as f64 * 2.0) * (1.0 - 0.5 * progress);
            }
        }
    }

    // NEW: residual-band matching to next-item demand — when the mean
    // residual is small (bins are nearly full), residuals just above the
    // next item size are premium; when mean residual is large, prefer
    // residuals that can host the next item with room to spare.
    if pr > 0 && next_item_size > 0 {
        let mr_frac = mean_residual / cap_f;
        if mr_frac < 0.2 && pr >= next_item_size && pr <= next_item_size + 6 {
            score -= 8.0 * (1.0 - progress);
        } else if mr_frac > 0.45 && pr >= next_item_size + 15 && pr <= next_item_size + 40 {
            score -= 5.0 * (1.0 - 0.5 * progress);
        }
    }

    score
}

