        }
        if pr > 0 && pr < item_size / 3 && item_size >= 30 {
            score -= 12.0;
        }
        // Fresh-bin viability gate — only open a new bin when the mean
        // open residual cannot absorb this item; otherwise fresh space is
        // wasted capacity that fragments the stream.
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size && fitting_bins_count > 1 && !late_large {
