        // take this item but their residuals are far above it, the leftover
        // slack after placement predicts future waste; a fresh bin sized to
        // the item keeps residuals small. Weigh by item size share.
        if fitting_bins_count >= 2 && item_size >= 40 {
            let best_gap = mean_residual - item_size as f64;
            if best_gap > 12.0 {
                score -= (best_gap / cap_f).min(0.25) * 80.0 * (1.0 - progress);
