    // next item would not fit, stronger early when bins are still plentiful.
    if pr > 0 && next_item_size > 0 && pr < next_item_size && open_bins_count > 3 {
        let unusable = (next_item_size - pr) as f64 / next_item_size as f64;
        score += 14.0 * unusable * unusable * (1.0 - progress);
    }

    // Mid-stream sweep for residuals matching common item-size sums —
    // residuals equal to combinations of small items (2x, item+small) get
    // absorbed quickly, keeping total dead space low.
    if pr > 0 && progress > 0.2 && progress < 0.9 {
        let small_sum = item_size.min(next_item_size.max(1));
        if pr == 2 * small_sum || pr == small_sum + 10 || pr == small_sum + 25 {
            score -= 7.0;
        }
    }

    // Endgame fresh-bin suppression — near the end, a new bin is almost
    // never recoverable; only allow it if the item is huge relative to what
    // any open residual could hold.
    if bin_residual == bin_capacity && progress > 0.85 {
        let biggest_resid = mean_residual.max(0.0);
        if item_size as f64 <= biggest_resid.max(1.0) && fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Residual pooling — mid-stream, prefer residuals close to a
    // multiple of the mean residual so future items with average sizes can
    // tile the remaining space without stranding slack. Scaled by openness.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.2 && progress < 0.85 {
        let mr = mean_residual;
        let k = (pr as f64 / mr).round().max(1.0);
        let dev = (pr as f64 - k * mr).abs() / mr;
        if dev < 0.15 && k >= 1.0 {
            score -= 10.0 * (1.0 - dev / 0.15) * (1.0 - 0.4 * progress);
        }
    }

    // Two-item lookahead tiling — if the next two plausible items
    // (next + mean-sized) exactly or nearly exhaust the residual, reward it;
    // this catches bins that stay productive beyond the immediate lookahead.
    if pr > 0 && next_item_size > 0 && mean_residual > 1.0 {
        let combo = next_item_size as f64 + mean_residual.min(cap_f * 0.4);
        let gap = pr as f64 - combo;
        if gap >= 0.0 && gap <= 5.0 {
            score -= (16.0 - gap) * 2.4 * (1.0 - 0.5 * progress);
        }
    }

    // Strand-risk shaping — residuals in the awkward 13..24 band rarely
    // absorb anything; penalize them more when many open bins exist (slack
    // is abundant elsewhere), less when bins are scarce (keep flexibility).
    if pr >= 13 && pr <= 24 {
        let crowd = if open_bins_count > 10 { 1.5 } else { 0.7 };
        score += 6.0 * crowd * (1.0 - 0.5 * progress);
    }

    // Dead-space floor tightening — residuals that cannot hold the
    // next item nor the mean-sized item are pure waste; push them toward
    // zero or above the absorbency floor with a smooth quadratic that
    // peaks for mid-gap residuals (worst dead-space zone).
    if pr > 0 && next_item_size > 0 {
        let floor = next_item_size.max(1) as f64;
        if (pr as f64) < floor {
            let x = pr as f64 / floor;
            score += (10.0 + 14.0 * (1.0 - x) * (1.0 - x)) * (1.0 - 0.6 * progress);
        }
    }

    // Near-exact residual shaping — residuals within 3 of the next
    // item size are one small item away from closure; reward them to keep
    // future placements exact rather than leaving permanent slack.
    if next_item_size > 0 && pr > next_item_size && pr <= next_item_size + 3 {
        score -= (18.0 - (pr - next_item_size) as f64 * 4.0) * (1.0 - 0.5 * progress);
    }

    // Open-bin budget shaping — when open bins already exceed the
    // waste budget implied by progress (bins used vs items placed), dampen
    // any choice that leaves large residuals; force consolidation toward
    // few, well-filled bins.
    if open_bins_count as f64 > (step_index as f64) * 0.35 && pr > 0 {
        let over = open_bins_count as f64 / (step_index as f64 + 1.0);
        score += (pr as f64 / cap_f) * 22.0 * over.min(1.5);
    }

    // NEW: dead-space budget accounting — track cumulative expected waste
    // as (open_bins * mean_residual) vs the theoretical floor; when the
    // slack inventory exceeds one full bin's worth, penalize any placement
    // that strands a residual below the next item (permanent waste) and
    // reward placements that close bins exactly. This directly targets the
    // diagnosed dead-space weakness by making aggregate slack visible.
    if mean_residual > 0.0 && open_bins_count > 1 {
        let slack_inventory = open_bins_count as f64 * mean_residual;
        let slack_pressure = ((slack_inventory - cap_f) / cap_f).clamp(0.0, 2.0);
        if pr > 0 && next_item_size > 0 && pr < next_item_size {
            score += 8.0 * slack_pressure * (1.0 - pr as f64 / next_item_size.max(1) as f64);
        } else if pr == 0 {
            score -= 10.0 * slack_pressure * (1.0 - 0.5 * progress);
        }
        // When slack is abundant, prefer the tightest possible fit harder.
        if slack_pressure > 0.5 && bin_residual >= item_size {
            let tight = 1.0 - (bin_residual - item_size) as f64 / cap_f;
            score -= 5.0 * slack_pressure * tight * (1.0 - 0.4 * progress);
        }
    }

    // NEW: residual complementarity — reward placements where the resulting
    // residual equals a plausible small item size (common in the 1..=20
    // band for unknown distributions), since such residuals are likely to
    // be consumed exactly by the stream's small-item tail.
    if pr >= 1 && pr <= 20 && progress < 0.9 {
        score -= 6.0 * (1.0 - progress) * (1.0 - pr as f64 / 21.0);
    }

    // NEW: large-residual consolidation gate — residuals above 60% capacity
    // mid-stream are valuable multi-item hosts; penalize spending them on a
    // single item unless the item is large itself.
    if pr > cap_f * 0.6 && progress > 0.2 && progress < 0.85 && item_size < bin_capacity / 3 {
        score += 9.0 * (1.0 - item_size as f64 / (bin_capacity / 3) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Sharpened closure rewards: exact closure is king.
    if pr == 0 {
        score -= 900.0;
    } else if pr <= 4 {
        score -= 70.0 + (4 - pr) as f64 * 12.0;
    } else if pr < 12 {
        score += 24.0 - pr as f64;
    }

    // Harmonic residue classes — divisible residuals get absorbed by repeats.
    let class_bonus: f64 = if pr % 10 == 0 {
        30.0
    } else if pr % 5 == 0 {
        14.0
    } else if pr % 2 == 0 {
        4.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Lookahead: next-item fit quality into the post-placement residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 150.0 + 35.0 * (1.0 - progress);
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= if slack <= 10 { 55.0 - slack as f64 * 2.4 } else { 28.0 - (slack as f64).min(30.0) * 0.5 };
        } else {
            score += (next_item_size - pr) as f64 * 0.6;
        }
        if next_item_size < pr {
            let pr2 = pr - next_item_size;
            if pr2 <= 6 {
                score -= 44.0;
            } else if pr2 == next_item_size {
                score -= 22.0;
            } else if pr2 % 10 == 0 {
                score -= 10.0;
            }
            if pr2 > 6 && next_item_size > 1 && pr2 % next_item_size == 0 {
                score -= 13.0;
            }
            if pr2 >= 2 * item_size && item_size > 0 && pr2 % item_size == 0 {
                score -= 7.0;
            }
            if pr2 >= 3 * item_size.max(1) {
                score -= 5.0;
            }
            // Chain lookahead via mean-residual proxy.
            if pr2 > 0 && mean_residual > 0.0 {
                let proxy = mean_residual.round() as u32;
                if proxy >= 1 && proxy <= pr2 {
                    score -= 8.0 * (1.0 - progress);
                }
            }
            // Triple-chain closure.
            if pr2 >= 2 * next_item_size {
                let pr3 = pr2 - 2 * next_item_size;
                if pr3 <= 3 {
                    score -= 20.0 * (1.0 - progress);
                }
            }
            // next + item leaves near-perfect closure.
            if pr2 >= item_size.max(1) {
                let pr3 = pr2 - item_size.max(1);
                if pr3 <= 2 {
                    score -= 17.0 * (1.0 - progress);
                }
            }
        }
        // Pair-absorbency.
        if pr > 1 && pr == 2 * next_item_size {
            score -= 19.0;
        }
        // Stranded residual just below next item.
        if pr > 0 && pr < next_item_size {
            let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
            score += (6.0 + 4.5 * gap_frac) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap_f) < 0.38;
        let reuse_is_bad = fitting_bins_count <= 1
            || (pr > 0 && next_item_size > pr && next_item_size <= bin_capacity);
        let late_large = item_size >= 60 && progress > 0.10;
        if late_large || (tight && progress > 0.15) || reuse_is_bad {
            score -= 40.0 + 26.0 * progress;
        } else {
            score += 60.0;
        }
        if item_size <= 25 && mean_residual > cap_f * 0.45 {
            score += 30.0;
        }
        if open_bins_count > 12 && progress < 0.3 {
            score += 10.0;
        }
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 20.0 + 15.0 * (1.0 - progress);
        }
        if next_item_size >= bin_capacity / 2 && mean_residual < (item_size + next_item_size) as f64 {
            score -= 9.0 + 12.0 * (1.0 - progress);
        }
        if item_size + next_item_size == bin_capacity {
            score -= 30.0 + 16.0 * (1.0 - progress);
        }
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size {
            let strand = mean_residual as u32 - item_size;
            if strand > 0 && strand < 8 && progress > 0.2 {
                score -= 12.0 + 5.0 * (1.0 - progress);
            }
        }
        // Fresh-bin viability gate: don't open a bin when mean residual
        // could absorb this item.
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size && fitting_bins_count > 1 && !late_large {
            score += 26.0 * (1.0 - progress);
        }
        // Fresh-bin scarcity coupling.
        if fitting_bins_count >= 2 && item_size >= 40 {
            let best_gap = mean_residual - item_size as f64;
            if best_gap > 12.0 {
                score -= (best_gap / cap_f).min(0.25) * 70.0 * (1.0 - progress);
            }
        }
        // Late-stream fresh-bin restraint.
        if progress > 0.7 {
            let exact_pair = item_size + next_item_size == bin_capacity;
            if !exact_pair && fitting_bins_count > 0 {
                score += 20.0 * (progress - 0.7) / 0.3;
            }
        }
        if progress > 0.85 && item_size as f64 <= mean_residual.max(1.0) && fitting_bins_count > 0 {
            score += 35.0;
        }
    }

    // Best-fit bias.
    score -= (bin_capacity - bin_residual) as f64 * 0.15;

    // Flexible mid-range residual target.
    if pr >= 25 && pr <= 65 {
        score -= 12.0;
    }

    // Proliferation penalty.
    score += open_bins_count as f64 * (0.2 + 0.2 * progress);

    // Waste-avoidance for tiny residuals.
    if pr > 0 && pr < bin_capacity / 5 {
        let scarcity = if fitting_bins_count > 2 { 0.6 } else { 1.4 };
        score += (9.0 + 4.0 * progress) * scarcity;
    }

    // Tightness bonus.
    if bin_residual >= item_size {
        let tightness = 1.0 - ((bin_residual - item_size) as f64 / cap_f);
        score -= 6.0 * tightness;
    }

    // Mean-residual alignment.
    let align = ((pr as f64 - mean_residual) / cap_f).abs();
    score += align * (if progress > 0.2 && progress < 0.8 { 4.0 } else { 5.5 });

    // Odd small residuals are dead-space candidates.
    if pr > 0 && pr < 20 && pr % 2 == 1 {
        score += 6.0;
    }

    // Mid-stream consolidation of large absorbable residuals.
    if open_bins_count > 8 && progress > 0.25 && progress < 0.85 && pr >= 40 {
        score -= 8.0;
    }

    // Dead-space ratio shaping with next-item floor.
    if pr > 0 && next_item_size > 0 {
        let dead_threshold = (next_item_size + 12).min(bin_capacity);
        if pr < dead_threshold {
            let dead_frac = 1.0 - (pr as f64 / dead_threshold as f64);
            score += 16.0 * dead_frac * (1.0 - progress);
        } else if pr >= dead_threshold * 2 {
            score -= 7.0 + 4.0 * (1.0 - progress);
        } else if pr == next_item_size + item_size {
            score -= 5.0;
        }
    }

    // Endgame exactness.
    if progress > 0.9 && pr > 0 {
        score += pr as f64 * 0.35;
        if pr <= next_item_size.max(1) {
            score -= 18.0;
        }
    }

    // Fragment guard against typical upcoming demand.
    if pr > 0 && progress > 0.1 {
        let typical = (mean_residual * 0.5).max(8.0).min(cap_f * 0.5);
        if (pr as f64) < typical {
            score += 5.5 * (1.0 - (pr as f64 / typical)) * (1.0 - progress);
        }
    }

    // Exact-closure sweep with plentiful fitting bins.
    if pr == 0 && fitting_bins_count > 2 {
        score -= 10.0 * (1.0 - progress);
    }

    // Dual lookahead — repeatable fill detection.
    if next_item_size > 0 && next_item_size < pr {
        let pr2 = pr - next_item_size;
        if pr2 > 0 && item_size > 1 && pr2 % item_size == 0 && next_item_size % item_size == 0 {
            score -= 9.0;
        }
    }

    // Half-capacity residual targeting mid-stream.
    if pr > 0 && progress > 0.15 && progress < 0.9 {
        let half = cap_f * 0.5;
        let dist = ((pr as f64 - half) / half).abs();
        if dist < 0.25 {
            score -= 6.5 * (1.0 - dist / 0.25);
        }
    }

    // Dead-space ratio term with smooth quadratic ramp.
    if pr > 0 {
        let pr_f = pr as f64;
        let usable_floor = (next_item_size.max(1) as f64).min(cap_f * 0.3);
        if pr_f < usable_floor {
            let dsr = 1.0 - pr_f / usable_floor;
            score += 10.0 * dsr * dsr * (0.5 + 0.5 * (1.0 - progress));
        }
        if pr % 3 == 0 && pr >= 6 {
            score -= 4.5;
        }
        if pr % 7 == 0 && pr >= 7 {
            score -= 3.5;
        }
    }

    // Bin-count pressure valve.
    if bin_residual != bin_capacity && mean_residual > 0.0 {
        let fill = 1.0 - mean_residual / cap_f;
        if fill > 0.75 && fitting_bins_count > 1 {
            score -= 5.5 * (fill - 0.75) / 0.25;
        } else if fill < 0.5 && fitting_bins_count > 1 {
            score += 3.5 * (0.5 - fill) / 0.5 * (1.0 - progress);
        }
    }

    // Dead-space waste accounting with quadratic ramp.
    if pr > 0 && next_item_size > 0 && next_item_size < bin_capacity {
        let waste_frac = 1.0 - (pr.min(next_item_size) as f64 / pr as f64);
        if waste_frac > 0.5 {
            score += 8.0 * (waste_frac - 0.5) * 2.0 * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Consolidation incentive matching mean residual.
    if progress > 0.35 && pr >= next_item_size.max(1) && mean_residual > 0.0 {
        let dev = ((pr as f64 - mean_residual) / cap_f).abs();
        if dev < 0.08 {
            score -= 5.5 * (1.0 - dev / 0.08);
        }
    }

    // Quad-chain lookahead.
    if next_item_size > 0 && pr >= 3 * next_item_size {
        let pr3 = pr - 3 * next_item_size;
        if pr3 <= 4 {
            score -= 16.0 * (1.0 - progress);
        }
    }

    // Item+next exact pair inside residual.
    if next_item_size > 0 && item_size > 0 && pr == item_size + next_item_size {
        score -= 24.0;
    }

    // Large-item protection.
    if item_size > 50 && pr > 0 && pr < 15 {
        score += 9.0 * (1.0 - pr as f64 / 15.0);
    }

    // Residual-divisibility absorbency with chain depth.
    if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 {
        let chain_len = pr / next_item_size;
        if chain_len >= 2 {
            score -= (7.0 + 5.5 * chain_len.min(4) as f64) * (1.0 - 0.5 * progress);
        }
    }

    // Dead-space variance dampener.
    if pr > 0 && next_item_size > 0 && pr < next_item_size && open_bins_count > 3 {
        let unusable = (next_item_size - pr) as f64 / next_item_size as f64;
        score += 12.0 * unusable * unusable * (1.0 - progress);
    }

    // Residual pooling — tile with mean residual.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.2 && progress < 0.85 {
        let mr = mean_residual;
        let k = (pr as f64 / mr).round().max(1.0);
        let dev = (pr as f64 - k * mr).abs() / mr;
        if dev < 0.15 {
            score -= 9.0 * (1.0 - dev / 0.15) * (1.0 - 0.4 * progress);
        }
    }

    // Two-item lookahead tiling.
    if pr > 0 && next_item_size > 0 && mean_residual > 1.0 {
        let combo = next_item_size as f64 + mean_residual.min(cap_f * 0.4);
        let gap = pr as f64 - combo;
        if gap >= 0.0 && gap <= 5.0 {
            score -= (15.0 - gap) * 2.2 * (1.0 - 0.5 * progress);
        }
    }

    // Strand-risk shaping in the awkward 13..24 band.
    if pr >= 13 && pr <= 24 {
        let crowd = if open_bins_count > 10 { 1.5 } else { 0.7 };
        score += 5.5 * crowd * (1.0 - 0.5 * progress);
    }

    // Dead-space floor tightening with quadratic peak in the worst zone.
    if pr > 0 && next_item_size > 0 {
        let floor = next_item_size.max(1) as f64;
        if (pr as f64) < floor {
            let x = pr as f64 / floor;
            score += (9.0 + 13.0 * (1.0 - x) * (1.0 - x)) * (1.0 - 0.6 * progress);
        }
    }

    // Near-exact residual shaping: one small item away from closure.
    if next_item_size > 0 && pr > next_item_size && pr <= next_item_size + 3 {
        score -= (16.0 - (pr - next_item_size) as f64 * 4.0) * (1.0 - 0.5 * progress);
    }

    // Open-bin budget shaping: force consolidation when bins proliferate.
    if open_bins_count as f64 > (step_index as f64) * 0.35 && pr > 0 {
        let over = open_bins_count as f64 / (step_index as f64 + 1.0);
        score += (pr as f64 / cap_f) * 20.0 * over.min(1.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
