                }
            }
        } else {
            let overshoot = (next_item_size - pr) as f64;
            score += overshoot * 0.68;
            // Stranded residual just below next item is dead space.
            let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
            score += (7.0 + 5.0 * gap_frac) * (1.0 - progress);
