    if pr > 0 && next_item_size > 1 && fitting_bins_count >= 2 {
        let gap = next_item_size as f64 - pr as f64;
        if gap > 0.0 && gap < (next_item_size as f64) * 0.6 {
            let competition = ((fitting_bins_count as f64 - 1.0) / 4.0).min(1.0);
            score += (gap * gap / (next_item_size as f64)) * (3.0 + 5.0 * competition);
        }
    }

    // NEW: reusable-band reward — residuals that can still hold either the
    // next item or the mean-sized item keep the bin productive; reward
    // proportionally to headroom above the demand floor, strongest mid-stream.
    if pr > 0 && progress > 0.1 && progress < 0.95 {
        let demand = (next_item_size.max(1) as f64).max(mean_residual * 0.6);
        if pr as f64 >= demand {
            let headroom = ((pr as f64 - demand) / cap_f).min(0.3);
            score -= 8.0 * headroom / 0.3 * (1.0 - 0.4 * progress);
        }
    }

    score
}

