    }

    // Residual-slope steering.
    if next_item_size > 0 && pr > 0 {
        let target = next_item_size as f64;
        let dev = (pr as f64 - target) / target.max(1.0);
        if dev.abs() < 0.5 {
            score -= 9.0 * (1.0 - (dev / 0.5) * (dev / 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    // Dual-fit depth probe (refined: stronger two-step closure, softer sliver penalty).
    if next_item_size > 0 && pr > next_item_size && mean_residual >= 1.0 {
        let pr2 = pr - next_item_size;
        let proxy = mean_residual.min(cap_f);
        if (pr2 as f64) >= proxy {
            score -= 13.0 * (1.0 - 0.5 * progress);
            if pr2 as f64 - proxy < 6.0 {
                score -= 10.0; // near-exact two-step closure
            }
        }
        if (pr2 as f64) < proxy && pr2 > 0 && pr2 < 10 {
            score += 8.0 * (1.0 - pr2 as f64 / 10.0);
        }
    }

    // Capacity-fraction dead-space gate.
    if pr > 0 && progress > 0.2 && progress < 0.9 {
        let lo = cap_f * 0.38;
        let hi = cap_f * 0.5;
        if (pr as f64) > lo && (pr as f64) < hi {
            let frac = 1.0 - ((pr as f64 - lo) / (hi - lo));
            score += 8.0 * frac * frac;
        }
    }

    // NEW MUTATION: exact-closure chain depth reward — when placing the
    // current item leaves a residual that the next item closes exactly
    // (pr == next), amplify with stream position: early exact closures
    // compound savings across many future bins, so weight them higher
    // early and taper late where bins are nearly committed anyway.
    if pr > 0 && next_item_size > 0 && pr == next_item_size {
        score -= 14.0 * (1.0 - 0.6 * progress);
    }

    // NEW MUTATION: dead-space variance steering — prefer residuals that
    // are multiples of the current item size, since repeated same-size
    // items tile them exactly; penalize residuals just below a multiple
    // of item_size (off-by-small waste), weighted by item prevalence
    // proxy (small items are more common in typical streams).
    if pr > 0 && item_size > 0 {
        let q = pr / item_size;
        let rem = pr % item_size;
        if rem == 0 && q >= 1 {
            score -= 7.0 * (1.0 - 0.4 * progress);
        } else if q >= 1 && rem <= 5 && item_size <= 40 {
            score += 5.0 + 1.2 * (5 - rem) as f64;
        }
    }

    // NEW MUTATION: two-residual consolidation gate — when the current
    // post-residual plus the mean residual can be closed exactly by the
    // next item split across bins, prefer keeping this residual aligned;
    // penalize residuals that fall in the narrow dead band between
    // next_item_size and next_item_size + mean_residual, which can
    // neither close now nor pool cleanly later.
    if pr > 0 && next_item_size > 0 && mean_residual > 1.0 && progress > 0.15 {
        let lo = next_item_size as f64;
        let hi = lo + mean_residual.min(cap_f * 0.3);
        if (pr as f64) > lo && (pr as f64) < hi {
            let frac = 1.0 - ((pr as f64 - lo) / (hi - lo));
            score += 7.0 * frac * frac * (1.0 - 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Sharpened perfect/near-perfect closure rewards.
    if pr == 0 {
        score -= 1280.0;
    } else if pr <= 4 {
        score -= 92.0 + (4 - pr) as f64 * 13.0;
    } else if pr < 12 {
        score += 30.0 - pr as f64;
    }

    // Harmonic residue classes.
    let class_bonus: f64 = if pr % 10 == 0 {
        36.0
    } else if pr % 5 == 0 {
        18.0
    } else if pr % 2 == 0 {
        5.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Lookahead: next item fit quality into post-placement residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 178.0 + 40.0 * (1.0 - progress);
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= if slack <= 10 { 66.0 - slack as f64 * 2.6 } else { 34.0 - (slack as f64).min(30.0) * 0.5 };
        } else {
            score += (next_item_size - pr) as f64 * 0.68;
        }
        if next_item_size < pr {
            let pr2 = pr - next_item_size;
            if pr2 <= 6 {
                score -= 52.0;
            } else if pr2 == next_item_size {
                score -= 27.0;
            } else if pr2 % 10 == 0 {
                score -= 12.0;
            }
            if pr2 > 6 && next_item_size > 1 && pr2 % next_item_size == 0 {
                score -= 15.0;
            }
            if pr2 >= 2 * item_size && item_size > 0 && pr2 % item_size == 0 {
                score -= 8.0;
            }
            if pr2 >= 3 * item_size.max(1) {
                score -= 6.0;
            }
            // Chain lookahead via mean-residual proxy.
            if pr2 > 0 && mean_residual > 0.0 {
                let proxy = mean_residual.round() as u32;
                if proxy >= 1 && proxy <= pr2 {
                    score -= 9.0 * (1.0 - progress);
                }
            }
            // Triple-chain closure.
            if pr2 >= 2 * next_item_size {
                let pr3 = pr2 - 2 * next_item_size;
                if pr3 <= 3 {
                    score -= 24.0 * (1.0 - progress);
                }
            }
            // next + item leaves near-perfect closure.
            if pr2 >= item_size.max(1) {
                let pr3 = pr2 - item_size.max(1);
                if pr3 <= 2 {
                    score -= 20.0 * (1.0 - progress);
                }
            }
        }
        // Pair-absorbency.
        if pr > 1 && pr == 2 * next_item_size {
            score -= 22.0;
        }
        // Stranded residual just below next item.
        if pr > 0 && pr < next_item_size {
            let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
            score += (7.0 + 5.0 * gap_frac) * (1.0 - progress);
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 66.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap_f) < 0.38;
        let reuse_is_bad = fitting_bins_count <= 1
            || (pr > 0 && next_item_size > pr && next_item_size <= bin_capacity);
        let late_large = item_size >= 60 && progress > 0.10;
        if late_large || (tight && progress > 0.15) || reuse_is_bad {
            score -= 46.0 + 30.0 * progress;
        } else {
            score += 70.0;
        }
        if item_size <= 25 && mean_residual > cap_f * 0.45 {
            score += 36.0;
        }
        if open_bins_count > 12 && progress < 0.3 {
            score += 12.0;
        }
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 24.0 + 18.0 * (1.0 - progress);
        }
        if next_item_size >= bin_capacity / 2 && mean_residual < (item_size + next_item_size) as f64 {
            score -= 10.0 + 14.0 * (1.0 - progress);
        }
        if item_size + next_item_size == bin_capacity
            && mean_residual < (item_size + next_item_size) as f64
        {
            score -= 20.0;
        }
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size {
            let strand = mean_residual as u32 - item_size;
            if strand > 0 && strand < 8 && progress > 0.2 {
                score -= 14.0 + 6.0 * (1.0 - progress);
            }
        }
        // Fresh-bin exact-pair bonus.
        if item_size + next_item_size == bin_capacity {
            score -= 34.0 + 20.0 * (1.0 - progress);
        }
        if pr > 0 && pr < item_size / 3 && item_size >= 30 {
            score -= 12.0;
        }
        // Fresh-bin viability gate.
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size && fitting_bins_count > 1 && !late_large {
            score += 30.0 * (1.0 - progress);
