    }

    // Dead-space floor tightening.
    if pr > 0 && next_item_size > 0 {
        let floor = next_item_size.max(1) as f64;
        if (pr as f64) < floor {
            let x = pr as f64 / floor;
            score += (10.0 + 14.0 * (1.0 - x) * (1.0 - x)) * (1.0 - 0.6 * progress);
        }
    }

    // Near-exact residual shaping.
    if next_item_size > 0 && pr > next_item_size && pr <= next_item_size + 3 {
        score -= (18.0 - (pr - next_item_size) as f64 * 4.0) * (1.0 - 0.5 * progress);
    }

    // Open-bin budget shaping.
    if open_bins_count as f64 > (step_index as f64) * 0.35 && pr > 0 {
        let over = open_bins_count as f64 / (step_index as f64 + 1.0);
        score += (pr as f64 / cap_f) * 22.0 * over.min(1.5);
    }

    // Dead-space minimization sweep.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let mr = mean_residual.min(cap_f);
        let usable_by_next = pr >= next_item_size;
        let usable_by_mean = (pr as f64) >= mr;
        if !usable_by_next && !usable_by_mean {
            let wasted = (next_item_size - pr) as f64;
            score += (6.0 + 0.25 * wasted) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Exact-fill cascade.
    if next_item_size > 0 && item_size > 1 && pr > next_item_size {
        let pr2 = pr - next_item_size;
        if pr2 % item_size == 0 && pr2 / item_size >= 1 && pr2 != 0 {
            score -= (10.0 + 4.0 * (pr2 / item_size).min(3) as f64) * (1.0 - 0.4 * progress);
        }
    }

    // Residual-slope steering.
    if next_item_size > 0 && pr > 0 {
        let target = next_item_size as f64;
        let dev = (pr as f64 - target) / target.max(1.0);
        if dev.abs() < 0.5 {
            score -= 9.0 * (1.0 - (dev / 0.5) * (dev / 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    // Dual-fit depth probe.
    if next_item_size > 0 && pr > next_item_size && mean_residual >= 1.0 {
        let pr2 = pr - next_item_size;
        let proxy = mean_residual.min(cap_f);
        if (pr2 as f64) >= proxy {
            score -= 11.0 * (1.0 - 0.5 * progress);
            if pr2 as f64 - proxy < 6.0 {
                score -= 8.0;
            }
        }
        if (pr2 as f64) < proxy && pr2 > 0 && pr2 < 10 {
            score += 9.0 * (1.0 - pr2 as f64 / 10.0);
        }
    }

    // Capacity-fraction dead-space gate.
    if pr > 0 && progress > 0.2 && progress < 0.9 {
        let lo = cap_f * 0.38;
        let hi = cap_f * 0.5;
        if (pr as f64) > lo && (pr as f64) < hi {
            let frac = 1.0 - ((pr as f64 - lo) / (hi - lo));
            score += 8.0 * frac * frac;
        }
    }

    // NEW MUTATION: dead-space recovery probe — when the residual after
    // placement can still absorb the mean-sized upcoming item with a
    // small remainder, reward the bin; but if the remainder is a sliver
    // (1..=5) that likely strands forever, penalize instead. This
    // sharpens the boundary between reusable and stranded space.
    if pr > 0 && mean_residual >= 2.0 {
        let mr = mean_residual.min(cap_f * 0.6);
        let gap = pr as f64 - mr;
        if gap >= 0.0 && gap <= 5.0 {
            score += 10.0 * (1.0 - gap / 5.0) * (1.0 - 0.4 * progress);
        } else if gap > 5.0 && gap < 12.0 {
            score -= 5.0 * (1.0 - (gap - 5.0) / 7.0) * (1.0 - 0.5 * progress);
        }
    }

    // NEW MUTATION: fitting-crowd tiebreak — when many bins can accept
    // the item, prefer the one whose post-residual best matches the
    // harmonic mean of next item and mean residual (a better predictor
    // of the near-future demand than either alone); when few bins fit,
    // relax the matching pressure to avoid over-constraining.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let harmonic = 2.0 * (next_item_size as f64 * mean_residual)
            / (next_item_size as f64 + mean_residual).max(1.0);
        let dev = ((pr as f64 - harmonic) / harmonic.max(1.0)).abs();
        let pressure = if fitting_bins_count >= 4 { 1.0 } else { 0.4 };
        if dev < 0.3 {
            score -= 7.0 * (1.0 - dev / 0.3) * pressure * (1.0 - 0.4 * progress);
        }
    }

    // NEW MUTATION: endgame sliver sweep — in the final stretch, any
    // residual below the next item is permanent waste; scale the penalty
    // with the wasted fraction so near-miss residuals are salvaged
    // rather than abandoned.
    if progress > 0.8 && pr > 0 && next_item_size > 0 && pr < next_item_size {
        let waste = 1.0 - pr as f64 / next_item_size as f64;
        score += 12.0 * waste * waste * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Sharpened perfect/near-perfect closure rewards.
    if pr == 0 {
        score -= 1280.0;
    } else if pr <= 4 {
        score -= 92.0 + (4 - pr) as f64 * 13.0;
    } else if pr < 12 {
        score += 30.0 - pr as f64;
    }

    // Harmonic residue classes.
    let class_bonus: f64 = if pr % 10 == 0 {
        36.0
    } else if pr % 5 == 0 {
        18.0
    } else if pr % 2 == 0 {
        5.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Lookahead: next item fit quality into post-placement residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 178.0 + 40.0 * (1.0 - progress);
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= if slack <= 10 { 66.0 - slack as f64 * 2.6 } else { 34.0 - (slack as f64).min(30.0) * 0.5 };
        } else {
            score += (next_item_size - pr) as f64 * 0.68;
        }
        if next_item_size < pr {
            let pr2 = pr - next_item_size;
            if pr2 <= 6 {
                score -= 52.0;
            } else if pr2 == next_item_size {
                score -= 27.0;
            } else if pr2 % 10 == 0 {
                score -= 12.0;
            }
            if pr2 > 6 && next_item_size > 1 && pr2 % next_item_size == 0 {
                score -= 15.0;
            }
            if pr2 >= 2 * item_size && item_size > 0 && pr2 % item_size == 0 {
                score -= 8.0;
            }
            if pr2 >= 3 * item_size.max(1) {
                score -= 6.0;
            }
            // Chain lookahead via mean-residual proxy.
            if pr2 > 0 && mean_residual > 0.0 {
                let proxy = mean_residual.round() as u32;
                if proxy >= 1 && proxy <= pr2 {
                    score -= 9.0 * (1.0 - progress);
                }
            }
            // Triple-chain closure.
            if pr2 >= 2 * next_item_size {
                let pr3 = pr2 - 2 * next_item_size;
                if pr3 <= 3 {
                    score -= 24.0 * (1.0 - progress);
                }
            }
            // next + item leaves near-perfect closure.
            if pr2 >= item_size.max(1) {
                let pr3 = pr2 - item_size.max(1);
                if pr3 <= 2 {
                    score -= 20.0 * (1.0 - progress);
                }
            }
        }
        // Pair-absorbency.
        if pr > 1 && pr == 2 * next_item_size {
            score -= 22.0;
        }
        // Stranded residual just below next item.
        if pr > 0 && pr < next_item_size {
            let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
            score += (7.0 + 5.0 * gap_frac) * (1.0 - progress);
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 66.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap_f) < 0.38;
        let reuse_is_bad = fitting_bins_count <= 1
            || (pr > 0 && next_item_size > pr && next_item_size <= bin_capacity);
        let late_large = item_size >= 60 && progress > 0.10;
        if late_large || (tight && progress > 0.15) || reuse_is_bad {
            score -= 46.0 + 30.0 * progress;
        } else {
            score += 70.0;
        }
        if item_size <= 25 && mean_residual > cap_f * 0.45 {
            score += 36.0;
        }
        if open_bins_count > 12 && progress < 0.3 {
            score += 12.0;
        }
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 24.0 + 18.0 * (1.0 - progress);
        }
        if next_item_size >= bin_capacity / 2 && mean_residual < (item_size + next_item_size) as f64 {
            score -= 10.0 + 14.0 * (1.0 - progress);
        }
        if item_size + next_item_size == bin_capacity
            && mean_residual < (item_size + next_item_size) as f64
        {
            score -= 20.0;
        }
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size {
            let strand = mean_residual as u32 - item_size;
            if strand > 0 && strand < 8 && progress > 0.2 {
                score -= 14.0 + 6.0 * (1.0 - progress);
            }
        }
        // Fresh-bin exact-pair bonus.
        if item_size + next_item_size == bin_capacity {
            score -= 34.0 + 20.0 * (1.0 - progress);
        }
        if pr > 0 && pr < item_size / 3 && item_size >= 30 {
            score -= 12.0;
        }
        // Fresh-bin viability gate.
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size && fitting_bins_count > 1 && !late_large {
            score += 30.0 * (1.0 - progress);
        }
        // Fresh-bin scarcity coupling.
        if fitting_bins_count >= 2 && item_size >= 40 {
            let best_gap = mean_residual - item_size as f64;
            if best_gap > 12.0 {
                score -= (best_gap / cap_f).min(0.25) * 80.0 * (1.0 - progress);
            }
        }
        // Fresh-bin only when the item cannot tile any open residual
        // with the next item — otherwise fresh space fragments the stream.
        if next_item_size > 0
            && fitting_bins_count >= 1
            && item_size + next_item_size <= bin_capacity
            && mean_residual >= (item_size + next_item_size) as f64
            && progress < 0.6
        {
            score += 18.0 * (1.0 - progress);
        }
        // Fresh-bin slot-arithmetic probe — open a new bin only when the
        // item tiles the fresh capacity into an integer number of
        // near-equal slots whose leftover is tiny.
        if item_size > 0 && bin_capacity % item_size == 0 {
            let slots = bin_capacity / item_size;
            if slots >= 2 && slots <= 4 && progress > 0.1 {
                score -= 14.0 * (slots as f64).min(3.0) * (1.0 - 0.5 * progress);
            }
        }
        // Fresh-bin residual-mirror check.
        if mean_residual > item_size as f64 * 1.6 && progress > 0.3 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
        // NEW MUTATION: fresh-bin two-slot pairing probe — a new bin is
        // valuable when the fresh capacity can hold exactly this item
        // plus the mean-residual-sized remainder, predicting a clean
        // two-item fill; otherwise fresh space fragments the stream.
        if next_item_size > 0 && mean_residual > 1.0 {
            let combo = item_size as f64 + mean_residual.min(cap_f * 0.5);
            let leftover = cap_f - combo;
            if leftover >= 0.0 && leftover <= 4.0 && progress > 0.15 {
                score -= 20.0 * (1.0 - leftover / 4.0) * (1.0 - 0.4 * progress);
            }
        }
    }

    // Best-fit bias.
    score -= (bin_capacity - bin_residual) as f64 * 0.16;

    // Flexible mid-range residual target.
    if pr >= 25 && pr <= 65 {
        score -= 14.0;
    }

    // Proliferation penalty.
    score += open_bins_count as f64 * (0.2 + 0.2 * progress);

    // Waste-avoidance for tiny residuals.
    if pr > 0 && pr < bin_capacity / 5 {
        let scarcity = if fitting_bins_count > 2 { 0.6 } else { 1.4 };
        score += (10.0 + 4.0 * progress) * scarcity;
    }

    // Tightness bonus.
    if bin_residual >= item_size {
        let tightness = 1.0 - ((bin_residual - item_size) as f64 / cap_f);
        score -= 6.0 * tightness;
    }

    // Mean-residual alignment.
    let align = ((pr as f64 - mean_residual) / cap_f).abs();
    score += align * (if progress > 0.2 && progress < 0.8 { 4.5 } else { 6.0 });

    // Odd small residuals are dead-space candidates.
    if pr > 0 && pr < 20 && pr % 2 == 1 {
        score += 7.0;
    }

    // Mid-stream consolidation of large absorbable residuals.
    if open_bins_count > 8 && progress > 0.25 && progress < 0.85 && pr >= 40 {
        score -= 9.0;
    }

    // Dead-space ratio shaping with next-item floor.
    if pr > 0 && next_item_size > 0 {
        let dead_threshold = (next_item_size + 12).min(bin_capacity);
        if pr < dead_threshold {
            let dead_frac = 1.0 - (pr as f64 / dead_threshold as f64);
            score += 18.0 * dead_frac * (1.0 - progress);
        } else if pr >= dead_threshold * 2 {
            score -= 8.0 + 4.0 * (1.0 - progress);
        } else if pr == next_item_size + item_size {
            score -= 5.0;
        }
    }

    // Endgame exactness.
    if progress > 0.9 && pr > 0 {
        score += pr as f64 * 0.35;
        if pr <= next_item_size.max(1) {
            score -= 20.0;
        }
    }

    // Fragment guard against typical upcoming demand.
    if pr > 0 && progress > 0.1 {
        let typical = (mean_residual * 0.5).max(8.0).min(cap_f * 0.5);
        if (pr as f64) < typical {
            score += 6.0 * (1.0 - (pr as f64 / typical)) * (1.0 - progress);
        }
    }

    // Exact-closure sweep with plentiful fitting bins.
    if pr == 0 && fitting_bins_count > 2 {
        score -= 12.0 * (1.0 - progress);
    }

    // Dual lookahead — repeatable fill detection.
    if next_item_size > 0 && next_item_size < pr {
        let pr2 = pr - next_item_size;
        if pr2 > 0 && item_size > 1 && pr2 % item_size == 0 && next_item_size % item_size == 0 {
            score -= 10.0;
        }
    }

    // Half-capacity residual targeting mid-stream.
    if pr > 0 && progress > 0.15 && progress < 0.9 {
        let half = cap_f * 0.5;
        let dist = ((pr as f64 - half) / half).abs();
        if dist < 0.25 {
            score -= 7.0 * (1.0 - dist / 0.25);
        }
    }

    // Dead-space ratio term with smooth quadratic ramp.
    if pr > 0 {
        let pr_f = pr as f64;
        let usable_floor = (next_item_size.max(1) as f64).min(cap_f * 0.3);
        if pr_f < usable_floor {
            let dsr = 1.0 - pr_f / usable_floor;
            score += 11.0 * dsr * dsr * (0.5 + 0.5 * (1.0 - progress));
        }
        if pr % 3 == 0 && pr >= 6 {
            score -= 5.0;
        }
        if pr % 7 == 0 && pr >= 7 {
            score -= 4.0;
        }
    }

    // Bin-count pressure valve.
    if bin_residual != bin_capacity && mean_residual > 0.0 {
        let fill = 1.0 - mean_residual / cap_f;
        if fill > 0.75 && fitting_bins_count > 1 {
            score -= 6.0 * (fill - 0.75) / 0.25;
        } else if fill < 0.5 && fitting_bins_count > 1 {
            score += 4.0 * (0.5 - fill) / 0.5 * (1.0 - progress);
        }
    }

    // Dead-space waste accounting with quadratic ramp.
    if pr > 0 && next_item_size > 0 && next_item_size < bin_capacity {
        let waste_frac = 1.0 - (pr.min(next_item_size) as f64 / pr as f64);
        if waste_frac > 0.5 {
            score += 9.0 * (waste_frac - 0.5) * 2.0 * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Consolidation incentive matching mean residual.
    if progress > 0.35 && pr >= next_item_size.max(1) && mean_residual > 0.0 {
        let dev = ((pr as f64 - mean_residual) / cap_f).abs();
        if dev < 0.08 {
            score -= 6.0 * (1.0 - dev / 0.08);
        }
    }

    // Quad-chain lookahead.
    if next_item_size > 0 && pr >= 3 * next_item_size {
        let pr3 = pr - 3 * next_item_size;
        if pr3 <= 4 {
            score -= 18.0 * (1.0 - progress);
        }
    }

    // Item+next exact pair inside residual.
    if next_item_size > 0 && item_size > 0 && pr == item_size + next_item_size {
        score -= 26.0;
    }

    // Late-stream fresh-bin restraint.
    if bin_residual == bin_capacity && progress > 0.7 {
        let exact_pair = item_size + next_item_size == bin_capacity;
        if !exact_pair && fitting_bins_count > 0 {
            score += 22.0 * (progress - 0.7) / 0.3;
        }
    }

    // Large-item protection.
    if item_size > 50 && pr > 0 && pr < 15 {
        score += 10.0 * (1.0 - pr as f64 / 15.0);
    }

    // Residual-divisibility absorbency.
    if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 {
        let chain_len = pr / next_item_size;
        if chain_len >= 2 {
            score -= (8.0 + 6.0 * chain_len.min(4) as f64) * (1.0 - 0.5 * progress);
        }
    }

    // Dead-space variance dampener.
    if pr > 0 && next_item_size > 0 && pr < next_item_size && open_bins_count > 3 {
        let unusable = (next_item_size - pr) as f64 / next_item_size as f64;
        score += 14.0 * unusable * unusable * (1.0 - progress);
    }

    // Mid-stream sweep for residuals matching common item-size sums.
    if pr > 0 && progress > 0.2 && progress < 0.9 {
        let small_sum = item_size.min(next_item_size.max(1));
        if pr == 2 * small_sum || pr == small_sum + 10 || pr == small_sum + 25 {
            score -= 7.0;
        }
    }

    // Endgame fresh-bin suppression.
    if bin_residual == bin_capacity && progress > 0.85 {
        let biggest_resid = mean_residual.max(0.0);
        if item_size as f64 <= biggest_resid.max(1.0) && fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Residual pooling.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.2 && progress < 0.85 {
        let mr = mean_residual;
        let k = (pr as f64 / mr).round().max(1.0);
        let dev = (pr as f64 - k * mr).abs() / mr;
        if dev < 0.15 && k >= 1.0 {
            score -= 10.0 * (1.0 - dev / 0.15) * (1.0 - 0.4 * progress);
        }
    }

    // Two-item lookahead tiling.
    if pr > 0 && next_item_size > 0 && mean_residual > 1.0 {
        let combo = next_item_size as f64 + mean_residual.min(cap_f * 0.4);
        let gap = pr as f64 - combo;
        if gap >= 0.0 && gap <= 5.0 {
            score -= (16.0 - gap) * 2.4 * (1.0 - 0.5 * progress);
        }
    }

    // Strand-risk shaping.
    if pr >= 13 && pr <= 24 {
        let crowd = if open_bins_count > 10 { 1.5 } else { 0.7 };
        score += 6.0 * crowd * (1.0 - 0.5 * progress);
    }

    // Dead-space floor tightening.
    if pr > 0 && next_item_size > 0 {
        let floor = next_item_size.max(1) as f64;
        if (pr as f64) < floor {
            let x = pr as f64 / floor;
            score += (10.0 + 14.0 * (1.0 - x) * (1.0 - x)) * (1.0 - 0.6 * progress);
        }
    }

    // Near-exact residual shaping.
    if next_item_size > 0 && pr > next_item_size && pr <= next_item_size + 3 {
        score -= (18.0 - (pr - next_item_size) as f64 * 4.0) * (1.0 - 0.5 * progress);
    }

    // Open-bin budget shaping.
    if open_bins_count as f64 > (step_index as f64) * 0.35 && pr > 0 {
        let over = open_bins_count as f64 / (step_index as f64 + 1.0);
        score += (pr as f64 / cap_f) * 22.0 * over.min(1.5);
    }

    // Dead-space minimization sweep.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let mr = mean_residual.min(cap_f);
        let usable_by_next = pr >= next_item_size;
        let usable_by_mean = (pr as f64) >= mr;
        if !usable_by_next && !usable_by_mean {
            let wasted = (next_item_size - pr) as f64;
            score += (6.0 + 0.25 * wasted) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Exact-fill cascade.
    if next_item_size > 0 && item_size > 1 && pr > next_item_size {
        let pr2 = pr - next_item_size;
        if pr2 % item_size == 0 && pr2 / item_size >= 1 && pr2 != 0 {
            score -= (10.0 + 4.0 * (pr2 / item_size).min(3) as f64) * (1.0 - 0.4 * progress);
        }
    }

    // Residual-slope steering.
    if next_item_size > 0 && pr > 0 {
        let target = next_item_size as f64;
        let dev = (pr as f64 - target) / target.max(1.0);
        if dev.abs() < 0.5 {
            score -= 9.0 * (1.0 - (dev / 0.5) * (dev / 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    // Dual-fit depth probe.
    if next_item_size > 0 && pr > next_item_size && mean_residual >= 1.0 {
        let pr2 = pr - next_item_size;
        let proxy = mean_residual.min(cap_f);
        if (pr2 as f64) >= proxy {
            score -= 11.0 * (1.0 - 0.5 * progress);
            if pr2 as f64 - proxy < 6.0 {
                score -= 8.0;
            }
        }
        if (pr2 as f64) < proxy && pr2 > 0 && pr2 < 10 {
            score += 9.0 * (1.0 - pr2 as f64 / 10.0);
        }
    }

    // Capacity-fraction dead-space gate.
    if pr > 0 && progress > 0.2 && progress < 0.9 {
        let lo = cap_f * 0.38;
        let hi = cap_f * 0.5;
        if (pr as f64) > lo && (pr as f64) < hi {
            let frac = 1.0 - ((pr as f64 - lo) / (hi - lo));
            score += 8.0 * frac * frac;
        }
    }

    // Dead-space recovery probe — residual absorbing a mean-sized item
    // with a small remainder is rewarded; sliver remainders penalized.
    if pr > 0 && mean_residual >= 2.0 {
        let mr = mean_residual.min(cap_f * 0.6);
        let gap = pr as f64 - mr;
        if gap >= 0.0 && gap <= 5.0 {
            score += 10.0 * (1.0 - gap / 5.0) * (1.0 - 0.4 * progress);
        } else if gap > 5.0 && gap < 12.0 {
            score -= 5.0 * (1.0 - (gap - 5.0) / 7.0) * (1.0 - 0.5 * progress);
        }
    }

    // Fitting-crowd tiebreak via harmonic demand proxy.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let harmonic = 2.0 * (next_item_size as f64 * mean_residual)
            / (next_item_size as f64 + mean_residual).max(1.0);
        let dev = ((pr as f64 - harmonic) / harmonic.max(1.0)).abs();
        let pressure = if fitting_bins_count >= 4 { 1.0 } else { 0.4 };
        if dev < 0.3 {
            score -= 7.0 * (1.0 - dev / 0.3) * pressure * (1.0 - 0.4 * progress);
        }
    }

    // Endgame sliver sweep.
    if progress > 0.8 && pr > 0 && next_item_size > 0 && pr < next_item_size {
        let waste = 1.0 - pr as f64 / next_item_size as f64;
        score += 12.0 * waste * waste * (progress - 0.8) / 0.2;
    }

    // NEW MUTATION: mid-stream dead-space ratio valve — when the stream
    // is running hot (more open bins than the theoretical fill rate),
    // aggressively reward bins whose post-residual is a small multiple
    // of the next item (likely to close soon), and penalize bins whose
    // post-residual sits in the awkward 1..=9 sliver band that neither
    // the next item nor the mean demand can absorb.
    if pr > 0 && next_item_size > 0 && progress > 0.25 {
        let bins_per_item = open_bins_count as f64 / (step_index as f64 + 1.0).max(1.0);
        if bins_per_item > 0.5 {
            let k = (pr as f64 / next_item_size as f64).floor();
            if k >= 1.0 && k <= 3.0 && pr % next_item_size == 0 {
                score -= 9.0 * (1.0 - 0.4 * progress) * bins_per_item.min(1.5);
            }
        }
        if pr <= 9 && pr < next_item_size {
            score += 8.0 * (1.0 - pr as f64 / 9.0) * (1.0 - 0.3 * progress);
        }
    }

    // NEW MUTATION: complementary salvage term — when the post-residual
    // exactly equals the mean residual (the stream's natural leftover
    // size), reward mildly so residual sizes converge and future items
    // have more uniform targets to fill.
    if pr > 0 && mean_residual > 2.0 && (pr as f64 - mean_residual).abs() <= 2.0 {
        score -= 6.0 * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Sharpened perfect/near-perfect closure rewards.
    if pr == 0 {
        score -= 1280.0;
    } else if pr <= 4 {
        score -= 92.0 + (4 - pr) as f64 * 13.0;
    } else if pr < 12 {
        score += 30.0 - pr as f64;
    }

    // Harmonic residue classes.
    let class_bonus: f64 = if pr % 10 == 0 {
        36.0
    } else if pr % 5 == 0 {
        18.0
    } else if pr % 2 == 0 {
        5.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Lookahead: next item fit quality into post-placement residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 178.0 + 40.0 * (1.0 - progress);
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= if slack <= 10 { 66.0 - slack as f64 * 2.6 } else { 34.0 - (slack as f64).min(30.0) * 0.5 };
        } else {
            score += (next_item_size - pr) as f64 * 0.68;
        }
        if next_item_size < pr {
            let pr2 = pr - next_item_size;
            if pr2 <= 6 {
                score -= 52.0;
            } else if pr2 == next_item_size {
                score -= 27.0;
            } else if pr2 % 10 == 0 {
                score -= 12.0;
            }
            if pr2 > 6 && next_item_size > 1 && pr2 % next_item_size == 0 {
                score -= 15.0;
            }
            if pr2 >= 2 * item_size && item_size > 0 && pr2 % item_size == 0 {
                score -= 8.0;
            }
            if pr2 >= 3 * item_size.max(1) {
                score -= 6.0;
            }
            // Chain lookahead via mean-residual proxy.
            if pr2 > 0 && mean_residual > 0.0 {
                let proxy = mean_residual.round() as u32;
                if proxy >= 1 && proxy <= pr2 {
                    score -= 9.0 * (1.0 - progress);
                }
            }
            // Triple-chain closure.
            if pr2 >= 2 * next_item_size {
                let pr3 = pr2 - 2 * next_item_size;
                if pr3 <= 3 {
                    score -= 24.0 * (1.0 - progress);
                }
            }
            // next + item leaves near-perfect closure.
            if pr2 >= item_size.max(1) {
                let pr3 = pr2 - item_size.max(1);
                if pr3 <= 2 {
                    score -= 20.0 * (1.0 - progress);
                }
            }
        }
        // Pair-absorbency.
        if pr > 1 && pr == 2 * next_item_size {
            score -= 22.0;
        }
        // Stranded residual just below next item.
        if pr > 0 && pr < next_item_size {
            let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
            score += (7.0 + 5.0 * gap_frac) * (1.0 - progress);
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 66.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap_f) < 0.38;
        let reuse_is_bad = fitting_bins_count <= 1
            || (pr > 0 && next_item_size > pr && next_item_size <= bin_capacity);
        let late_large = item_size >= 60 && progress > 0.10;
        if late_large || (tight && progress > 0.15) || reuse_is_bad {
            score -= 46.0 + 30.0 * progress;
        } else {
            score += 70.0;
        }
        if item_size <= 25 && mean_residual > cap_f * 0.45 {
            score += 36.0;
        }
        if open_bins_count > 12 && progress < 0.3 {
            score += 12.0;
        }
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 24.0 + 18.0 * (1.0 - progress);
        }
        if next_item_size >= bin_capacity / 2 && mean_residual < (item_size + next_item_size) as f64 {
            score -= 10.0 + 14.0 * (1.0 - progress);
        }
        if item_size + next_item_size == bin_capacity
            && mean_residual < (item_size + next_item_size) as f64
        {
            score -= 20.0;
        }
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size {
            let strand = mean_residual as u32 - item_size;
            if strand > 0 && strand < 8 && progress > 0.2 {
                score -= 14.0 + 6.0 * (1.0 - progress);
            }
        }
        // Fresh-bin exact-pair bonus.
        if item_size + next_item_size == bin_capacity {
            score -= 34.0 + 20.0 * (1.0 - progress);
        }
        if pr > 0 && pr < item_size / 3 && item_size >= 30 {
            score -= 12.0;
        }
        // Fresh-bin viability gate.
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size && fitting_bins_count > 1 && !late_large {
            score += 30.0 * (1.0 - progress);
        }
        // Fresh-bin scarcity coupling.
        if fitting_bins_count >= 2 && item_size >= 40 {
            let best_gap = mean_residual - item_size as f64;
            if best_gap > 12.0 {
                score -= (best_gap / cap_f).min(0.25) * 80.0 * (1.0 - progress);
            }
        }
        // Fresh-bin only when the item cannot tile any open residual
        // with the next item — otherwise fresh space fragments the stream.
        if next_item_size > 0
            && fitting_bins_count >= 1
            && item_size + next_item_size <= bin_capacity
            && mean_residual >= (item_size + next_item_size) as f64
            && progress < 0.6
        {
            score += 18.0 * (1.0 - progress);
        }
        // Fresh-bin slot-arithmetic probe.
        if item_size > 0 && bin_capacity % item_size == 0 {
            let slots = bin_capacity / item_size;
            if slots >= 2 && slots <= 4 && progress > 0.1 {
                score -= 14.0 * (slots as f64).min(3.0) * (1.0 - 0.5 * progress);
            }
        }
        // Fresh-bin residual-mirror check.
        if mean_residual > item_size as f64 * 1.6 && progress > 0.3 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
        // NEW MUTATION: fresh-bin salvage gate — open a new bin only when
        // the current item plus the next item leaves less than a sliver;
        // if the pair leaves a mid-range gap (10..40) that future items
        // could still fill, prefer reusing an open bin instead.
        if next_item_size > 0 && item_size + next_item_size < bin_capacity {
            let pair_left = bin_capacity - item_size - next_item_size;
            if pair_left >= 10 && pair_left <= 40 && progress > 0.2 {
                score += 10.0 + 0.2 * pair_left as f64;
            }
        }
    }

    // Best-fit bias.
    score -= (bin_capacity - bin_residual) as f64 * 0.16;

    // Flexible mid-range residual target.
    if pr >= 25 && pr <= 65 {
        score -= 14.0;
    }

    // Proliferation penalty.
    score += open_bins_count as f64 * (0.2 + 0.2 * progress);

    // Waste-avoidance for tiny residuals.
    if pr > 0 && pr < bin_capacity / 5 {
        let scarcity = if fitting_bins_count > 2 { 0.6 } else { 1.4 };
        score += (10.0 + 4.0 * progress) * scarcity;
    }

    // Tightness bonus.
    if bin_residual >= item_size {
        let tightness = 1.0 - ((bin_residual - item_size) as f64 / cap_f);
        score -= 6.0 * tightness;
    }

    // Mean-residual alignment.
    let align = ((pr as f64 - mean_residual) / cap_f).abs();
    score += align * (if progress > 0.2 && progress < 0.8 { 4.5 } else { 6.0 });

    // Odd small residuals are dead-space candidates.
    if pr > 0 && pr < 20 && pr % 2 == 1 {
        score += 7.0;
    }

    // Mid-stream consolidation of large absorbable residuals.
    if open_bins_count > 8 && progress > 0.25 && progress < 0.85 && pr >= 40 {
        score -= 9.0;
    }

    // Dead-space ratio shaping with next-item floor.
    if pr > 0 && next_item_size > 0 {
        let dead_threshold = (next_item_size + 12).min(bin_capacity);
        if pr < dead_threshold {
            let dead_frac = 1.0 - (pr as f64 / dead_threshold as f64);
            score += 18.0 * dead_frac * (1.0 - progress);
        } else if pr >= dead_threshold * 2 {
            score -= 8.0 + 4.0 * (1.0 - progress);
        } else if pr == next_item_size + item_size {
            score -= 5.0;
        }
    }

    // Endgame exactness.
    if progress > 0.9 && pr > 0 {
        score += pr as f64 * 0.35;
        if pr <= next_item_size.max(1) {
            score -= 20.0;
        }
    }

    // Fragment guard against typical upcoming demand.
    if pr > 0 && progress > 0.1 {
        let typical = (mean_residual * 0.5).max(8.0).min(cap_f * 0.5);
        if (pr as f64) < typical {
            score += 6.0 * (1.0 - (pr as f64 / typical)) * (1.0 - progress);
        }
    }

    // Exact-closure sweep with plentiful fitting bins.
    if pr == 0 && fitting_bins_count > 2 {
        score -= 12.0 * (1.0 - progress);
    }

    // Dual lookahead — repeatable fill detection.
    if next_item_size > 0 && next_item_size < pr {
        let pr2 = pr - next_item_size;
        if pr2 > 0 && item_size > 1 && pr2 % item_size == 0 && next_item_size % item_size == 0 {
            score -= 10.0;
        }
    }

    // Half-capacity residual targeting mid-stream.
    if pr > 0 && progress > 0.15 && progress < 0.9 {
        let half = cap_f * 0.5;
        let dist = ((pr as f64 - half) / half).abs();
        if dist < 0.25 {
            score -= 7.0 * (1.0 - dist / 0.25);
        }
    }

    // Dead-space ratio term with smooth quadratic ramp.
    if pr > 0 {
        let pr_f = pr as f64;
        let usable_floor = (next_item_size.max(1) as f64).min(cap_f * 0.3);
        if pr_f < usable_floor {
            let dsr = 1.0 - pr_f / usable_floor;
            score += 11.0 * dsr * dsr * (0.5 + 0.5 * (1.0 - progress));
        }
        if pr % 3 == 0 && pr >= 6 {
            score -= 5.0;
        }
        if pr % 7 == 0 && pr >= 7 {
            score -= 4.0;
        }
    }

    // Bin-count pressure valve.
    if bin_residual != bin_capacity && mean_residual > 0.0 {
        let fill = 1.0 - mean_residual / cap_f;
        if fill > 0.75 && fitting_bins_count > 1 {
            score -= 6.0 * (fill - 0.75) / 0.25;
        } else if fill < 0.5 && fitting_bins_count > 1 {
            score += 4.0 * (0.5 - fill) / 0.5 * (1.0 - progress);
        }
    }

    // Dead-space waste accounting with quadratic ramp.
    if pr > 0 && next_item_size > 0 && next_item_size < bin_capacity {
        let waste_frac = 1.0 - (pr.min(next_item_size) as f64 / pr as f64);
        if waste_frac > 0.5 {
            score += 9.0 * (waste_frac - 0.5) * 2.0 * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Consolidation incentive matching mean residual.
    if progress > 0.35 && pr >= next_item_size.max(1) && mean_residual > 0.0 {
        let dev = ((pr as f64 - mean_residual) / cap_f).abs();
        if dev < 0.08 {
            score -= 6.0 * (1.0 - dev / 0.08);
        }
    }

    // Quad-chain lookahead.
    if next_item_size > 0 && pr >= 3 * next_item_size {
        let pr3 = pr - 3 * next_item_size;
        if pr3 <= 4 {
            score -= 18.0 * (1.0 - progress);
        }
    }

    // Item+next exact pair inside residual.
    if next_item_size > 0 && item_size > 0 && pr == item_size + next_item_size {
        score -= 26.0;
    }

    // Late-stream fresh-bin restraint.
    if bin_residual == bin_capacity && progress > 0.7 {
        let exact_pair = item_size + next_item_size == bin_capacity;
        if !exact_pair && fitting_bins_count > 0 {
            score += 22.0 * (progress - 0.7) / 0.3;
        }
    }

    // Large-item protection.
    if item_size > 50 && pr > 0 && pr < 15 {
        score += 10.0 * (1.0 - pr as f64 / 15.0);
    }

    // Residual-divisibility absorbency.
    if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 {
        let chain_len = pr / next_item_size;
        if chain_len >= 2 {
            score -= (8.0 + 6.0 * chain_len.min(4) as f64) * (1.0 - 0.5 * progress);
        }
    }

    // Dead-space variance dampener.
    if pr > 0 && next_item_size > 0 && pr < next_item_size && open_bins_count > 3 {
        let unusable = (next_item_size - pr) as f64 / next_item_size as f64;
        score += 14.0 * unusable * unusable * (1.0 - progress);
    }

    // Mid-stream sweep for residuals matching common item-size sums.
    if pr > 0 && progress > 0.2 && progress < 0.9 {
        let small_sum = item_size.min(next_item_size.max(1));
        if pr == 2 * small_sum || pr == small_sum + 10 || pr == small_sum + 25 {
            score -= 7.0;
        }
    }

    // Endgame fresh-bin suppression.
    if bin_residual == bin_capacity && progress > 0.85 {
        let biggest_resid = mean_residual.max(0.0);
        if item_size as f64 <= biggest_resid.max(1.0) && fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Residual pooling.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.2 && progress < 0.85 {
        let mr = mean_residual;
        let k = (pr as f64 / mr).round().max(1.0);
        let dev = (pr as f64 - k * mr).abs() / mr;
        if dev < 0.15 && k >= 1.0 {
            score -= 10.0 * (1.0 - dev / 0.15) * (1.0 - 0.4 * progress);
        }
    }

    // Two-item lookahead tiling.
    if pr > 0 && next_item_size > 0 && mean_residual > 1.0 {
        let combo = next_item_size as f64 + mean_residual.min(cap_f * 0.4);
        let gap = pr as f64 - combo;
        if gap >= 0.0 && gap <= 5.0 {
            score -= (16.0 - gap) * 2.4 * (1.0 - 0.5 * progress);
        }
    }

    // Strand-risk shaping.
    if pr >= 13 && pr <= 24 {
        let crowd = if open_bins_count > 10 { 1.5 } else { 0.7 };
        score += 6.0 * crowd * (1.0 - 0.5 * progress);
    }

    // Dead-space floor tightening.
    if pr > 0 && next_item_size > 0 {
        let floor = next_item_size.max(1) as f64;
        if (pr as f64) < floor {
            let x = pr as f64 / floor;
            score += (10.0 + 14.0 * (1.0 - x) * (1.0 - x)) * (1.0 - 0.6 * progress);
        }
    }

    // Near-exact residual shaping.
    if next_item_size > 0 && pr > next_item_size && pr <= next_item_size + 3 {
        score -= (18.0 - (pr - next_item_size) as f64 * 4.0) * (1.0 - 0.5 * progress);
    }

    // Open-bin budget shaping.
    if open_bins_count as f64 > (step_index as f64) * 0.35 && pr > 0 {
        let over = open_bins_count as f64 / (step_index as f64 + 1.0);
        score += (pr as f64 / cap_f) * 22.0 * over.min(1.5);
    }

    // Dead-space minimization sweep.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let mr = mean_residual.min(cap_f);
        let usable_by_next = pr >= next_item_size;
        let usable_by_mean = (pr as f64) >= mr;
        if !usable_by_next && !usable_by_mean {
            let wasted = (next_item_size - pr) as f64;
            score += (6.0 + 0.25 * wasted) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Exact-fill cascade.
    if next_item_size > 0 && item_size > 1 && pr > next_item_size {
        let pr2 = pr - next_item_size;
        if pr2 % item_size == 0 && pr2 / item_size >= 1 && pr2 != 0 {
            score -= (10.0 + 4.0 * (pr2 / item_size).min(3) as f64) * (1.0 - 0.4 * progress);
        }
    }

    // Residual-slope steering.
    if next_item_size > 0 && pr > 0 {
        let target = next_item_size as f64;
        let dev = (pr as f64 - target) / target.max(1.0);
        if dev.abs() < 0.5 {
            score -= 9.0 * (1.0 - (dev / 0.5) * (dev / 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    // Dual-fit depth probe.
    if next_item_size > 0 && pr > next_item_size && mean_residual >= 1.0 {
        let pr2 = pr - next_item_size;
        let proxy = mean_residual.min(cap_f);
        if (pr2 as f64) >= proxy {
            score -= 11.0 * (1.0 - 0.5 * progress);
            if pr2 as f64 - proxy < 6.0 {
                score -= 8.0;
            }
        }
        if (pr2 as f64) < proxy && pr2 > 0 && pr2 < 10 {
            score += 9.0 * (1.0 - pr2 as f64 / 10.0);
        }
    }

    // Capacity-fraction dead-space gate.
    if pr > 0 && progress > 0.2 && progress < 0.9 {
        let lo = cap_f * 0.38;
        let hi = cap_f * 0.5;
        if (pr as f64) > lo && (pr as f64) < hi {
            let frac = 1.0 - ((pr as f64 - lo) / (hi - lo));
            score += 8.0 * frac * frac;
        }
    }

    // Dead-space recovery probe.
    if pr > 0 && mean_residual >= 2.0 {
        let mr = mean_residual.min(cap_f * 0.6);
        let gap = pr as f64 - mr;
        if gap >= 0.0 && gap <= 5.0 {
            score += 10.0 * (1.0 - gap / 5.0) * (1.0 - 0.4 * progress);
        } else if gap > 5.0 && gap < 12.0 {
            score -= 5.0 * (1.0 - (gap - 5.0) / 7.0) * (1.0 - 0.5 * progress);
        }
    }

    // Fitting-crowd tiebreak.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let harmonic = 2.0 * (next_item_size as f64 * mean_residual)
            / (next_item_size as f64 + mean_residual).max(1.0);
        let dev = ((pr as f64 - harmonic) / harmonic.max(1.0)).abs();
        let pressure = if fitting_bins_count >= 4 { 1.0 } else { 0.4 };
        if dev < 0.3 {
            score -= 7.0 * (1.0 - dev / 0.3) * pressure * (1.0 - 0.4 * progress);
        }
    }

    // Endgame sliver sweep.
    if progress > 0.8 && pr > 0 && next_item_size > 0 && pr < next_item_size {
        let waste = 1.0 - pr as f64 / next_item_size as f64;
        score += 12.0 * waste * waste * (progress - 0.8) / 0.2;
    }

    // NEW MUTATION: dead-space ratio refinement — the diagnosed weakness
    // is residual dead space. When the post-residual cannot hold either
    // the next item or the mean upcoming item, quantify the exact dead
    // fraction of the bin and penalize quadratically, but exempt bins
    // whose residual is a small, cheaply-closable remainder (<= 6).
    if pr > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        let mr = if mean_residual > 0.0 { mean_residual } else { n };
        let blocker = n.min(mr);
        if (pr as f64) < blocker && pr > 6 {
            let dead = 1.0 - pr as f64 / blocker;
            let urgency = if progress > 0.6 { 1.4 } else { 1.0 };
            score += 9.0 * dead * dead * urgency * (1.0 - 0.4 * progress);
        }
        // Complementary reward: post-residual exactly equals a sum of the
        // next item and the mean proxy — a probable two-step closure.
        if pr > next_item_size && mean_residual > 1.0 {
            let combo = next_item_size + mean_residual.round() as u32;
            if pr == combo {
                score -= 14.0 * (1.0 - 0.5 * progress);
            }
        }
    }

    // NEW MUTATION: residual-granularity steering — mid-stream, prefer
    // post-residuals that are multiples of small common sizes (3..=9),
    // since integer item streams more often close such gaps exactly.
    if pr > 0 && progress > 0.25 && progress < 0.9 {
        for d in 3..=9u32 {
            if pr % d == 0 && pr / d <= 12 {
                score -= 2.2 * (1.0 - 0.5 * progress);
                break;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Sharpened perfect / near-perfect closure rewards (borrowed strength).
    if pr == 0 {
        score -= 900.0;
    } else if pr <= 4 {
        score -= 80.0 + (4 - pr) as f64 * 12.0;
    } else if pr < 12 {
        score += 26.0 - pr as f64;
    }

    // Harmonic residue classes.
    if pr % 10 == 0 {
        score -= 32.0;
    } else if pr % 5 == 0 {
        score -= 16.0;
    } else if pr % 2 == 0 {
        score -= 4.0;
    }

    // Lookahead: next item fit quality into post-placement residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 160.0 + 40.0 * (1.0 - progress);
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= if slack <= 10 { 60.0 - slack as f64 * 2.5 } else { 30.0 - (slack as f64).min(30.0) * 0.5 };
            // Chain lookahead via mean-residual proxy.
            let pr2 = pr - next_item_size;
            if pr2 <= 6 {
                score -= 45.0;
            } else if pr2 == next_item_size {
                score -= 24.0;
            }
            if pr2 > 0 && mean_residual > 0.0 {
                let proxy = mean_residual.round() as u32;
                if proxy >= 1 && proxy <= pr2 {
                    score -= 8.0 * (1.0 - progress);
                }
            }
        } else {
            // Next item won't fit here; penalty scaled by overshoot.
            score += (next_item_size - pr) as f64 * 0.7;
            // Stranded residual just below next item.
            let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
            score += (6.0 + 5.0 * gap_frac) * (1.0 - progress);
        }
    } else {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / cap;
        let tight = (mean_residual / cap) < 0.38;
        let reuse_is_bad = fitting_bins_count <= 1
            || (pr > 0 && next_item_size > pr && next_item_size <= bin_capacity);
        let late_large = item_size >= 60 && progress > 0.10;
        if late_large || (tight && progress > 0.15) || reuse_is_bad {
            score -= 44.0 + 30.0 * progress;
        } else {
            score += 65.0;
        }
        // Small items into a fresh bin is wasteful when residuals are ample.
        if item_size <= 25 && mean_residual > cap * 0.45 {
            score += 36.0;
        }
        // Large item that no open bin can absorb.
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 24.0 + 18.0 * (1.0 - progress);
        }
        // Fresh-bin exact-pair bonus.
        if item_size + next_item_size == bin_capacity {
            score -= 32.0 + 20.0 * (1.0 - progress);
        }
        // Fresh-bin viability gate.
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size && fitting_bins_count > 1 && !late_large {
            score += 28.0 * (1.0 - progress);
        }
        // Fresh-bin scarcity coupling.
        if fitting_bins_count >= 2 && item_size >= 40 {
            let best_gap = mean_residual - item_size as f64;
            if best_gap > 12.0 {
                score -= (best_gap / cap).min(0.25) * 80.0 * (1.0 - progress);
            }
        }
        // Slot-arithmetic probe: tile fresh capacity into near-equal slots.
        if item_size > 0 && bin_capacity % item_size == 0 {
            let slots = bin_capacity / item_size;
            if slots >= 2 && slots <= 4 && progress > 0.1 {
                score -= 14.0 * (slots as f64).min(3.0) * (1.0 - 0.5 * progress);
            }
        }
        // Residual-mirror check: under-filled stream, new bin wastes capacity.
        if mean_residual > item_size as f64 * 1.6 && progress > 0.3 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
        // Late-stream fresh-bin restraint.
        if progress > 0.7 && !reuse_is_bad {
            score += 22.0 * (progress - 0.7) / 0.3;
        }
        // Endgame fresh-bin suppression.
        if progress > 0.85 && item_size as f64 <= mean_residual.max(1.0) && fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Best-fit bias.
    score -= (bin_capacity - bin_residual) as f64 * 0.16;

    // Mid-range residual target.
    if pr >= 25 && pr <= 65 {
        score -= 12.0;
    }

    // Proliferation penalty.
    score += open_bins_count as f64 * (0.2 + 0.2 * progress);

    // Waste-avoidance for tiny residuals.
    if pr > 0 && pr < bin_capacity / 5 {
        let scarcity = if fitting_bins_count > 2 { 0.6 } else { 1.4 };
        score += (10.0 + 4.0 * progress) * scarcity;
    }

    // Tightness bonus.
    if bin_residual >= item_size {
        let tightness = 1.0 - ((bin_residual - item_size) as f64 / cap);
        score -= 6.0 * tightness;
    }

    // Mean-residual alignment.
    let align = ((pr as f64 - mean_residual) / cap).abs();
    score += align * (if progress > 0.2 && progress < 0.8 { 4.5 } else { 6.0 });

    // Odd small residuals are dead-space candidates.
    if pr > 0 && pr < 20 && pr % 2 == 1 {
        score += 7.0;
    }

    // Dead-space shaping with next-item floor.
    if pr > 0 && next_item_size > 0 {
        let floor = next_item_size.max(1) as f64;
        if (pr as f64) < floor {
            let x = pr as f64 / floor;
            score += (10.0 + 14.0 * (1.0 - x) * (1.0 - x)) * (1.0 - 0.6 * progress);
        } else if pr >= 2 * next_item_size {
            score -= 8.0 + 4.0 * (1.0 - progress);
        }
    }

    // Endgame exactness.
    if progress > 0.9 && pr > 0 {
        score += pr as f64 * 0.35;
        if pr <= next_item_size.max(1) {
            score -= 20.0;
        }
    }

    // Fragment guard against typical upcoming demand.
    if pr > 0 && progress > 0.1 {
        let typical = (mean_residual * 0.5).max(8.0).min(cap * 0.5);
        if (pr as f64) < typical {
            score += 6.0 * (1.0 - (pr as f64 / typical)) * (1.0 - progress);
        }
    }

    // Dead-space recovery probe: reward near-mean leftovers, penalize slivers.
    if pr > 0 && mean_residual >= 2.0 {
        let mr = mean_residual.min(cap * 0.6);
        let gap = pr as f64 - mr;
        if gap >= 0.0 && gap <= 5.0 {
            score += 10.0 * (1.0 - gap / 5.0) * (1.0 - 0.4 * progress);
        } else if gap > 5.0 && gap < 12.0 {
            score -= 5.0 * (1.0 - (gap - 5.0) / 7.0) * (1.0 - 0.5 * progress);
        }
    }

    // Fitting-crowd tiebreak via harmonic mean of next item and mean residual.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let harmonic = 2.0 * (next_item_size as f64 * mean_residual)
            / (next_item_size as f64 + mean_residual).max(1.0);
        let dev = ((pr as f64 - harmonic) / harmonic.max(1.0)).abs();
        let pressure = if fitting_bins_count >= 4 { 1.0 } else { 0.4 };
        if dev < 0.3 {
            score -= 7.0 * (1.0 - dev / 0.3) * pressure * (1.0 - 0.4 * progress);
        }
    }

    // Endgame sliver sweep.
    if progress > 0.8 && pr > 0 && next_item_size > 0 && pr < next_item_size {
        let waste = 1.0 - pr as f64 / next_item_size as f64;
        score += 12.0 * waste * waste * (progress - 0.8) / 0.2;
    }

    // Residual-slope steering toward next item.
    if next_item_size > 0 && pr > 0 {
        let target = next_item_size as f64;
        let dev = (pr as f64 - target) / target.max(1.0);
        if dev.abs() < 0.5 {
            score -= 9.0 * (1.0 - (dev / 0.5) * (dev / 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Sharpened perfect/near-perfect closure rewards.
    if pr == 0 {
        score -= 1280.0;
    } else if pr <= 4 {
        score -= 92.0 + (4 - pr) as f64 * 13.0;
    } else if pr < 12 {
        score += 30.0 - pr as f64;
    }

    // Harmonic residue classes.
    let class_bonus: f64 = if pr % 10 == 0 {
        36.0
    } else if pr % 5 == 0 {
        18.0
    } else if pr % 2 == 0 {
        5.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Lookahead: next item fit quality into post-placement residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 178.0 + 40.0 * (1.0 - progress);
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= if slack <= 10 { 66.0 - slack as f64 * 2.6 } else { 34.0 - (slack as f64).min(30.0) * 0.5 };
        } else {
            score += (next_item_size - pr) as f64 * 0.68;
        }
        if next_item_size < pr {
            let pr2 = pr - next_item_size;
            if pr2 <= 6 {
                score -= 52.0;
            } else if pr2 == next_item_size {
                score -= 27.0;
            } else if pr2 % 10 == 0 {
                score -= 12.0;
            }
            if pr2 > 6 && next_item_size > 1 && pr2 % next_item_size == 0 {
                score -= 15.0;
            }
            if pr2 >= 2 * item_size && item_size > 0 && pr2 % item_size == 0 {
                score -= 8.0;
            }
            if pr2 >= 3 * item_size.max(1) {
                score -= 6.0;
            }
            // Chain lookahead via mean-residual proxy.
            if pr2 > 0 && mean_residual > 0.0 {
                let proxy = mean_residual.round() as u32;
                if proxy >= 1 && proxy <= pr2 {
                    score -= 9.0 * (1.0 - progress);
                }
            }
            // Triple-chain closure.
            if pr2 >= 2 * next_item_size {
                let pr3 = pr2 - 2 * next_item_size;
                if pr3 <= 3 {
                    score -= 24.0 * (1.0 - progress);
                }
            }
            // next + item leaves near-perfect closure.
            if pr2 >= item_size.max(1) {
                let pr3 = pr2 - item_size.max(1);
                if pr3 <= 2 {
                    score -= 20.0 * (1.0 - progress);
                }
            }
        }
        // Pair-absorbency.
        if pr > 1 && pr == 2 * next_item_size {
            score -= 22.0;
        }
        // Stranded residual just below next item.
        if pr > 0 && pr < next_item_size {
            let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
            score += (7.0 + 5.0 * gap_frac) * (1.0 - progress);
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 66.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap_f) < 0.38;
        let reuse_is_bad = fitting_bins_count <= 1
            || (pr > 0 && next_item_size > pr && next_item_size <= bin_capacity);
        let late_large = item_size >= 60 && progress > 0.10;
        if late_large || (tight && progress > 0.15) || reuse_is_bad {
            score -= 46.0 + 30.0 * progress;
        } else {
            score += 70.0;
        }
        if item_size <= 25 && mean_residual > cap_f * 0.45 {
            score += 36.0;
        }
        if open_bins_count > 12 && progress < 0.3 {
            score += 12.0;
        }
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 24.0 + 18.0 * (1.0 - progress);
        }
        if next_item_size >= bin_capacity / 2 && mean_residual < (item_size + next_item_size) as f64 {
            score -= 10.0 + 14.0 * (1.0 - progress);
        }
        if item_size + next_item_size == bin_capacity
            && mean_residual < (item_size + next_item_size) as f64
        {
            score -= 20.0;
        }
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size {
            let strand = mean_residual as u32 - item_size;
            if strand > 0 && strand < 8 && progress > 0.2 {
                score -= 14.0 + 6.0 * (1.0 - progress);
            }
        }
        // Fresh-bin exact-pair bonus.
        if item_size + next_item_size == bin_capacity {
            score -= 34.0 + 20.0 * (1.0 - progress);
        }
        if pr > 0 && pr < item_size / 3 && item_size >= 30 {
            score -= 12.0;
        }
        // Fresh-bin viability gate.
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size && fitting_bins_count > 1 && !late_large {
            score += 30.0 * (1.0 - progress);
        }
        // Fresh-bin scarcity coupling.
        if fitting_bins_count >= 2 && item_size >= 40 {
            let best_gap = mean_residual - item_size as f64;
            if best_gap > 12.0 {
                score -= (best_gap / cap_f).min(0.25) * 80.0 * (1.0 - progress);
            }
        }
        // Fresh-bin only when the item cannot tile any open residual
        // with the next item — otherwise fresh space fragments the stream.
        if next_item_size > 0
            && fitting_bins_count >= 1
            && item_size + next_item_size <= bin_capacity
            && mean_residual >= (item_size + next_item_size) as f64
            && progress < 0.6
        {
            score += 18.0 * (1.0 - progress);
        }
        // Fresh-bin slot-arithmetic probe — open a new bin only when the
        // item tiles the fresh capacity into an integer number of
        // near-equal slots whose leftover is tiny; otherwise fresh space
        // invites fragmentation.
        if item_size > 0 && bin_capacity % item_size == 0 {
            let slots = bin_capacity / item_size;
            if slots >= 2 && slots <= 4 && progress > 0.1 {
                score -= 14.0 * (slots as f64).min(3.0) * (1.0 - 0.5 * progress);
            }
        }
        // Fresh-bin residual-mirror check — if the mean open-bin residual
        // is already large relative to the item, the stream is
        // under-filled and a new bin wastes capacity.
        if mean_residual > item_size as f64 * 1.6 && progress > 0.3 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
        // NEW MUTATION: fresh-bin dead-space forecast — open a fresh bin
        // only when its expected final waste (capacity minus the largest
        // divisor of the item that fits) is smaller than the waste the
        // item would strand in the average open bin. This directly
        // targets the diagnosed dead-space weakness by comparing
        // projected stranded capacity, not just fit feasibility.
        if next_item_size > 0 && fitting_bins_count >= 1 && progress > 0.2 {
            let fresh_waste = cap_f - ((item_size * (bin_capacity / item_size.max(1))) as f64);
            let open_waste = (next_item_size as f64).min(mean_residual.max(1.0));
            if fresh_waste + 6.0 < open_waste {
                score -= 12.0 * (1.0 - fresh_waste / cap_f) * (1.0 - progress);
            } else if fresh_waste > open_waste + 10.0 {
                score += 10.0 * (1.0 - 0.5 * progress);
            }
        }
    }

    // Best-fit bias.
    score -= (bin_capacity - bin_residual) as f64 * 0.16;

    // Flexible mid-range residual target.
    if pr >= 25 && pr <= 65 {
        score -= 14.0;
    }

    // Proliferation penalty.
    score += open_bins_count as f64 * (0.2 + 0.2 * progress);

    // Waste-avoidance for tiny residuals.
    if pr > 0 && pr < bin_capacity / 5 {
        let scarcity = if fitting_bins_count > 2 { 0.6 } else { 1.4 };
        score += (10.0 + 4.0 * progress) * scarcity;
    }

    // Tightness bonus.
    if bin_residual >= item_size {
        let tightness = 1.0 - ((bin_residual - item_size) as f64 / cap_f);
        score -= 6.0 * tightness;
    }

    // Mean-residual alignment.
    let align = ((pr as f64 - mean_residual) / cap_f).abs();
    score += align * (if progress > 0.2 && progress < 0.8 { 4.5 } else { 6.0 });

    // Odd small residuals are dead-space candidates.
    if pr > 0 && pr < 20 && pr % 2 == 1 {
        score += 7.0;
    }

    // Mid-stream consolidation of large absorbable residuals.
    if open_bins_count > 8 && progress > 0.25 && progress < 0.85 && pr >= 40 {
        score -= 9.0;
    }

    // Dead-space ratio shaping with next-item floor.
    if pr > 0 && next_item_size > 0 {
        let dead_threshold = (next_item_size + 12).min(bin_capacity);
        if pr < dead_threshold {
            let dead_frac = 1.0 - (pr as f64 / dead_threshold as f64);
            score += 18.0 * dead_frac * (1.0 - progress);
        } else if pr >= dead_threshold * 2 {
            score -= 8.0 + 4.0 * (1.0 - progress);
        } else if pr == next_item_size + item_size {
            score -= 5.0;
        }
    }

    // Endgame exactness.
    if progress > 0.9 && pr > 0 {
        score += pr as f64 * 0.35;
        if pr <= next_item_size.max(1) {
            score -= 20.0;
        }
    }

    // Fragment guard against typical upcoming demand.
    if pr > 0 && progress > 0.1 {
        let typical = (mean_residual * 0.5).max(8.0).min(cap_f * 0.5);
        if (pr as f64) < typical {
            score += 6.0 * (1.0 - (pr as f64 / typical)) * (1.0 - progress);
        }
    }

    // Exact-closure sweep with plentiful fitting bins.
    if pr == 0 && fitting_bins_count > 2 {
        score -= 12.0 * (1.0 - progress);
    }

    // Dual lookahead — repeatable fill detection.
    if next_item_size > 0 && next_item_size < pr {
        let pr2 = pr - next_item_size;
        if pr2 > 0 && item_size > 1 && pr2 % item_size == 0 && next_item_size % item_size == 0 {
            score -= 10.0;
        }
    }

    // Half-capacity residual targeting mid-stream.
    if pr > 0 && progress > 0.15 && progress < 0.9 {
        let half = cap_f * 0.5;
        let dist = ((pr as f64 - half) / half).abs();
        if dist < 0.25 {
            score -= 7.0 * (1.0 - dist / 0.25);
        }
    }

    // Dead-space ratio term with smooth quadratic ramp.
    if pr > 0 {
        let pr_f = pr as f64;
        let usable_floor = (next_item_size.max(1) as f64).min(cap_f * 0.3);
        if pr_f < usable_floor {
            let dsr = 1.0 - pr_f / usable_floor;
            score += 11.0 * dsr * dsr * (0.5 + 0.5 * (1.0 - progress));
        }
        if pr % 3 == 0 && pr >= 6 {
            score -= 5.0;
        }
        if pr % 7 == 0 && pr >= 7 {
            score -= 4.0;
        }
    }

    // Bin-count pressure valve.
    if bin_residual != bin_capacity && mean_residual > 0.0 {
        let fill = 1.0 - mean_residual / cap_f;
        if fill > 0.75 && fitting_bins_count > 1 {
            score -= 6.0 * (fill - 0.75) / 0.25;
        } else if fill < 0.5 && fitting_bins_count > 1 {
            score += 4.0 * (0.5 - fill) / 0.5 * (1.0 - progress);
        }
    }

    // Dead-space waste accounting with quadratic ramp.
    if pr > 0 && next_item_size > 0 && next_item_size < bin_capacity {
        let waste_frac = 1.0 - (pr.min(next_item_size) as f64 / pr as f64);
        if waste_frac > 0.5 {
            score += 9.0 * (waste_frac - 0.5) * 2.0 * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Consolidation incentive matching mean residual.
    if progress > 0.35 && pr >= next_item_size.max(1) && mean_residual > 0.0 {
        let dev = ((pr as f64 - mean_residual) / cap_f).abs();
        if dev < 0.08 {
            score -= 6.0 * (1.0 - dev / 0.08);
        }
    }

    // Quad-chain lookahead.
    if next_item_size > 0 && pr >= 3 * next_item_size {
        let pr3 = pr - 3 * next_item_size;
        if pr3 <= 4 {
            score -= 18.0 * (1.0 - progress);
        }
    }

    // Item+next exact pair inside residual.
    if next_item_size > 0 && item_size > 0 && pr == item_size + next_item_size {
        score -= 26.0;
    }

    // Late-stream fresh-bin restraint.
    if bin_residual == bin_capacity && progress > 0.7 {
        let exact_pair = item_size + next_item_size == bin_capacity;
        if !exact_pair && fitting_bins_count > 0 {
            score += 22.0 * (progress - 0.7) / 0.3;
        }
    }

    // Large-item protection.
    if item_size > 50 && pr > 0 && pr < 15 {
        score += 10.0 * (1.0 - pr as f64 / 15.0);
    }

    // Residual-divisibility absorbency.
    if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 {
        let chain_len = pr / next_item_size;
        if chain_len >= 2 {
            score -= (8.0 + 6.0 * chain_len.min(4) as f64) * (1.0 - 0.5 * progress);
        }
    }

    // Dead-space variance dampener.
    if pr > 0 && next_item_size > 0 && pr < next_item_size && open_bins_count > 3 {
        let unusable = (next_item_size - pr) as f64 / next_item_size as f64;
        score += 14.0 * unusable * unusable * (1.0 - progress);
    }

    // Mid-stream sweep for residuals matching common item-size sums.
    if pr > 0 && progress > 0.2 && progress < 0.9 {
        let small_sum = item_size.min(next_item_size.max(1));
        if pr == 2 * small_sum || pr == small_sum + 10 || pr == small_sum + 25 {
            score -= 7.0;
        }
    }

    // Endgame fresh-bin suppression.
    if bin_residual == bin_capacity && progress > 0.85 {
        let biggest_resid = mean_residual.max(0.0);
        if item_size as f64 <= biggest_resid.max(1.0) && fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Residual pooling.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.2 && progress < 0.85 {
        let mr = mean_residual;
        let k = (pr as f64 / mr).round().max(1.0);
        let dev = (pr as f64 - k * mr).abs() / mr;
        if dev < 0.15 && k >= 1.0 {
            score -= 10.0 * (1.0 - dev / 0.15) * (1.0 - 0.4 * progress);
        }
    }

    // Two-item lookahead tiling.
    if pr > 0 && next_item_size > 0 && mean_residual > 1.0 {
        let combo = next_item_size as f64 + mean_residual.min(cap_f * 0.4);
        let gap = pr as f64 - combo;
        if gap >= 0.0 && gap <= 5.0 {
            score -= (16.0 - gap) * 2.4 * (1.0 - 0.5 * progress);
        }
    }

    // Strand-risk shaping.
    if pr >= 13 && pr <= 24 {
        let crowd = if open_bins_count > 10 { 1.5 } else { 0.7 };
        score += 6.0 * crowd * (1.0 - 0.5 * progress);
    }

    // Dead-space floor tightening.
    if pr > 0 && next_item_size > 0 {
        let floor = next_item_size.max(1) as f64;
        if (pr as f64) < floor {
            let x = pr as f64 / floor;
            score += (10.0 + 14.0 * (1.0 - x) * (1.0 - x)) * (1.0 - 0.6 * progress);
        }
    }

    // Near-exact residual shaping.
    if next_item_size > 0 && pr > next_item_size && pr <= next_item_size + 3 {
        score -= (18.0 - (pr - next_item_size) as f64 * 4.0) * (1.0 - 0.5 * progress);
    }

    // Open-bin budget shaping.
    if open_bins_count as f64 > (step_index as f64) * 0.35 && pr > 0 {
        let over = open_bins_count as f64 / (step_index as f64 + 1.0);
        score += (pr as f64 / cap_f) * 22.0 * over.min(1.5);
    }

    // Dead-space minimization sweep.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let mr = mean_residual.min(cap_f);
        let usable_by_next = pr >= next_item_size;
        let usable_by_mean = (pr as f64) >= mr;
        if !usable_by_next && !usable_by_mean {
            let wasted = (next_item_size - pr) as f64;
            score += (6.0 + 0.25 * wasted) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Exact-fill cascade.
    if next_item_size > 0 && item_size > 1 && pr > next_item_size {
        let pr2 = pr - next_item_size;
        if pr2 % item_size == 0 && pr2 / item_size >= 1 && pr2 != 0 {
            score -= (10.0 + 4.0 * (pr2 / item_size).min(3) as f64) * (1.0 - 0.4 * progress);
        }
    }

    // Residual-slope steering.
    if next_item_size > 0 && pr > 0 {
        let target = next_item_size as f64;
        let dev = (pr as f64 - target) / target.max(1.0);
        if dev.abs() < 0.5 {
            score -= 9.0 * (1.0 - (dev / 0.5) * (dev / 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    // Dual-fit depth probe.
    if next_item_size > 0 && pr > next_item_size && mean_residual >= 1.0 {
        let pr2 = pr - next_item_size;
        let proxy = mean_residual.min(cap_f);
        if (pr2 as f64) >= proxy {
            score -= 11.0 * (1.0 - 0.5 * progress);
            if pr2 as f64 - proxy < 6.0 {
                score -= 8.0;
            }
        }
        if (pr2 as f64) < proxy && pr2 > 0 && pr2 < 10 {
            score += 9.0 * (1.0 - pr2 as f64 / 10.0);
        }
    }

    // Capacity-fraction dead-space gate.
    if pr > 0 && progress > 0.2 && progress < 0.9 {
        let lo = cap_f * 0.38;
        let hi = cap_f * 0.5;
        if (pr as f64) > lo && (pr as f64) < hi {
            let frac = 1.0 - ((pr as f64 - lo) / (hi - lo));
            score += 8.0 * frac * frac;
        }
    }

    // Dead-space recovery probe — when the residual after placement can
    // still absorb the mean-sized upcoming item with a small remainder,
    // reward the bin; but if the remainder is a sliver (1..=5) that
    // likely strands forever, penalize instead.
    if pr > 0 && mean_residual >= 2.0 {
        let mr = mean_residual.min(cap_f * 0.6);
        let gap = pr as f64 - mr;
        if gap >= 0.0 && gap <= 5.0 {
            score += 10.0 * (1.0 - gap / 5.0) * (1.0 - 0.4 * progress);
        } else if gap > 5.0 && gap < 12.0 {
            score -= 5.0 * (1.0 - (gap - 5.0) / 7.0) * (1.0 - 0.5 * progress);
        }
    }

    // Fitting-crowd tiebreak — when many bins can accept the item,
    // prefer the one whose post-residual best matches the harmonic mean
    // of next item and mean residual; when few bins fit, relax the
    // matching pressure.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let harmonic = 2.0 * (next_item_size as f64 * mean_residual)
            / (next_item_size as f64 + mean_residual).max(1.0);
        let dev = ((pr as f64 - harmonic) / harmonic.max(1.0)).abs();
        let pressure = if fitting_bins_count >= 4 { 1.0 } else { 0.4 };
        if dev < 0.3 {
            score -= 7.0 * (1.0 - dev / 0.3) * pressure * (1.0 - 0.4 * progress);
        }
    }

    // Endgame sliver sweep — in the final stretch, any residual below the
    // next item is permanent waste; scale the penalty with the wasted
    // fraction so near-miss residuals are salvaged rather than abandoned.
    if progress > 0.8 && pr > 0 && next_item_size > 0 && pr < next_item_size {
        let waste = 1.0 - pr as f64 / next_item_size as f64;
        score += 12.0 * waste * waste * (progress - 0.8) / 0.2;
    }

    // NEW MUTATION: dead-space variance compactor — the parent's
    // residual variance (sigma_res = 0.2484) indicates scattered leftover
    // sizes across bins. Reward bins whose post-residual is an integer
    // multiple of the next item (predictable tiling) with a bonus that
    // grows as residual variance pressure rises, and penalize
    // residuals that fall into the "unreachable band" between the next
    // item and the next item plus the mean residual — space there is
    // too large to ignore yet too small to combine, the classic
    // dead-space trap.
    if pr > 0 && next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr % next_item_size == 0 {
            let tiles = pr / next_item_size;
            score -= (4.0 + 3.0 * tiles.min(4) as f64) * (0.5 + 0.5 * (1.0 - progress));
        }
        if pr > next_item_size && (pr as f64) < nx + mean_residual.min(nx) {
            score += 5.0 * (1.0 - 0.4 * progress);
        }
    }

    // NEW MUTATION: cross-bin waste budget — estimate the total dead
    // space locked in open bins (sum of residuals below next item,
    // proxied by mean_residual times the count of non-fitting bins) and
    // when that locked waste is high, intensify the pressure to close
    // bins exactly (pr == 0 or pr < small) rather than leave mid-size
    // residuals that will never combine. This converts the global
    // dead-space diagnosis into a per-decision signal.
    if pr > 0 && next_item_size > 0 && open_bins_count > 1 {
        let locked = mean_residual * (open_bins_count as f64 - 1.0);
        let pressure = (locked / (cap_f * (open_bins_count as f64).max(2.0))).min(1.0);
        if pressure > 0.25 {
            let target_scale = 12.0 * pressure * (1.0 - 0.5 * progress);
            if pr <= 8 {
                score -= target_scale;
            } else if pr > next_item_size && pr < next_item_size * 2 {
                score += target_scale * 0.5;
            }
        }
    }

    // NEW MUTATION: residual-midpoint shaping — residuals just below the
    // midpoint between next_item and next_item + item are the hardest to
    // fill later (they can take neither the next item alone nor the
    // pair). Steer away from that dead band with a smooth quadratic
    // penalty, complementing the existing hard thresholds.
    if pr > 0 && next_item_size > 0 && item_size > 0 {
        let lo = next_item_size as f64;
        let hi = (next_item_size + item_size) as f64;
        if hi > lo && (pr as f64) > lo && (pr as f64) < hi {
            let mid = 0.5 * (lo + hi);
            let half_w = 0.5 * (hi - lo);
            let d = ((pr as f64 - mid) / half_w).abs();
            score += 9.0 * (1.0 - d * d) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Sharpened perfect / near-perfect closure rewards (borrowed from best).
    if pr == 0 {
        score -= 900.0;
    } else if pr <= 4 {
        score -= 70.0 + (4 - pr) as f64 * 10.0;
    } else if pr < 12 {
        score += 24.0 - pr as f64;
    }

    // Harmonic residue classes.
    if pr % 10 == 0 && pr > 0 {
        score -= 30.0;
    } else if pr % 5 == 0 && pr > 0 {
        score -= 15.0;
    } else if pr % 2 == 0 && pr > 0 {
        score -= 4.0;
    }

    // Lookahead: next item fit quality into post-placement residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 150.0 + 35.0 * (1.0 - progress);
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= if slack <= 10 { 55.0 - slack as f64 * 2.4 } else { 28.0 - (slack as f64).min(30.0) * 0.5 };
        } else {
            score += (next_item_size - pr) as f64 * 0.6;
        }
        if next_item_size < pr {
            let pr2 = pr - next_item_size;
            if pr2 <= 6 {
                score -= 44.0;
            } else if pr2 == next_item_size {
                score -= 22.0;
            } else if pr2 % 10 == 0 {
                score -= 10.0;
            }
            if pr2 > 6 && next_item_size > 1 && pr2 % next_item_size == 0 {
                score -= 13.0;
            }
            // Chain lookahead via mean-residual proxy.
            if pr2 > 0 && mean_residual >= 1.0 {
                let proxy = mean_residual.round() as u32;
                if proxy >= 1 && proxy <= pr2 {
                    score -= 8.0 * (1.0 - progress);
                }
            }
            // Triple-chain closure.
            if pr2 >= 2 * next_item_size {
                let pr3 = pr2 - 2 * next_item_size;
                if pr3 <= 3 {
                    score -= 20.0 * (1.0 - progress);
                }
            }
        }
        // Stranded residual just below next item.
        if pr > 0 && pr < next_item_size {
            let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
            score += (6.0 + 5.0 * gap_frac) * (1.0 - progress);
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 25.0;
    }

    // Last-chance bin: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 70.0;
    }

    // New-bin candidate handling (gated, borrowed from best).
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap) < 0.38;
        let reuse_is_bad = fitting_bins_count <= 1
            || (pr > 0 && next_item_size > pr && next_item_size <= bin_capacity);
        let late_large = item_size >= 60 && progress > 0.10;
        if late_large || (tight && progress > 0.15) || reuse_is_bad {
            score -= 42.0 + 28.0 * progress;
        } else {
            score += 65.0;
        }
        if item_size <= 25 && mean_residual > cap * 0.45 {
            score += 32.0;
        }
        if open_bins_count > 12 && progress < 0.3 {
            score += 10.0;
        }
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 22.0 + 16.0 * (1.0 - progress);
        }
        if item_size + next_item_size == bin_capacity {
            score -= 30.0 + 18.0 * (1.0 - progress);
        }
        // Fresh-bin slot-arithmetic probe.
        if item_size > 0 && bin_capacity % item_size == 0 {
            let slots = bin_capacity / item_size;
            if slots >= 2 && slots <= 4 && progress > 0.1 {
                score -= 12.0 * (slots as f64).min(3.0) * (1.0 - 0.5 * progress);
            }
        }
        // Fresh-bin residual-mirror check.
        if mean_residual > item_size as f64 * 1.6 && progress > 0.3 {
            score += 15.0 * (1.0 - 0.5 * progress);
        }
        // Endgame fresh-bin suppression.
        if progress > 0.85 && item_size as f64 <= mean_residual.max(1.0) && fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Best-fit bias.
    score -= (bin_capacity - bin_residual) as f64 * 0.15;

    // Flexible mid-range residual target.
    if pr >= 25 && pr <= 65 {
        score -= 12.0;
    }

    // Proliferation penalty.
    score += open_bins_count as f64 * (0.2 + 0.2 * progress);

    // Waste-avoidance for tiny residuals.
    if pr > 0 && pr < bin_capacity / 5 {
        let scarcity = if fitting_bins_count > 2 { 0.6 } else { 1.3 };
        score += (9.0 + 4.0 * progress) * scarcity;
    }

    // Tightness bonus.
    if bin_residual >= item_size {
        let tightness = 1.0 - ((bin_residual - item_size) as f64 / cap);
        score -= 6.0 * tightness;
    }

    // Mean-residual alignment.
    let align = ((pr as f64 - mean_residual) / cap).abs();
    score += align * (if progress > 0.2 && progress < 0.8 { 4.0 } else { 5.5 });

    // Odd small residuals are dead-space candidates.
    if pr > 0 && pr < 20 && pr % 2 == 1 {
        score += 6.0;
    }

    // Dead-space ratio shaping with next-item floor.
    if pr > 0 && next_item_size > 0 {
        let dead_threshold = (next_item_size + 12).min(bin_capacity);
        if pr < dead_threshold {
            let dead_frac = 1.0 - (pr as f64 / dead_threshold as f64);
            score += 16.0 * dead_frac * (1.0 - progress);
        } else if pr >= dead_threshold * 2 {
            score -= 7.0 + 4.0 * (1.0 - progress);
        } else if pr == next_item_size + item_size {
            score -= 5.0;
        }
    }

    // Endgame exactness.
    if progress > 0.9 && pr > 0 {
        score += pr as f64 * 0.35;
        if pr <= next_item_size.max(1) {
            score -= 20.0;
        }
    }

    // Fragment guard against typical upcoming demand.
    if pr > 0 && progress > 0.1 {
        let typical = (mean_residual * 0.5).max(8.0).min(cap * 0.5);
        if (pr as f64) < typical {
            score += 6.0 * (1.0 - (pr as f64 / typical)) * (1.0 - progress);
        }
    }

    // Dead-space minimization sweep.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let mr = mean_residual.min(cap);
        let usable_by_next = pr >= next_item_size;
        let usable_by_mean = (pr as f64) >= mr;
        if !usable_by_next && !usable_by_mean {
            let wasted = (next_item_size - pr) as f64;
            score += (6.0 + 0.25 * wasted) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Exact-fill cascade.
    if next_item_size > 0 && item_size > 1 && pr > next_item_size {
        let pr2 = pr - next_item_size;
        if pr2 > 0 && pr2 % item_size == 0 {
            score -= (10.0 + 4.0 * (pr2 / item_size).min(3) as f64) * (1.0 - 0.4 * progress);
        }
    }

    // Residual-slope steering.
    if next_item_size > 0 && pr > 0 {
        let target = next_item_size as f64;
        let dev = (pr as f64 - target) / target.max(1.0);
        if dev.abs() < 0.5 {
            score -= 8.0 * (1.0 - (dev / 0.5) * (dev / 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    // NEW MUTATION: harmonic-demand matching — prefer bins whose post
    // residual matches the harmonic mean of next item and mean residual
    // (better predictor of near-future demand), pressure scaled by crowd.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let harmonic = 2.0 * (next_item_size as f64 * mean_residual)
            / (next_item_size as f64 + mean_residual).max(1.0);
        let dev = ((pr as f64 - harmonic) / harmonic.max(1.0)).abs();
        let pressure = if fitting_bins_count >= 4 { 1.0 } else { 0.4 };
        if dev < 0.3 {
            score -= 7.0 * (1.0 - dev / 0.3) * pressure * (1.0 - 0.4 * progress);
        }
    }

    // NEW MUTATION: dead-space recovery probe — reward when residual can
    // absorb a mean-sized upcoming item with small remainder; penalize
    // sliver remainders (1..=5) that likely strand forever.
    if pr > 0 && mean_residual >= 2.0 {
        let mr = mean_residual.min(cap * 0.6);
        let gap = pr as f64 - mr;
        if gap >= 0.0 && gap <= 5.0 {
            score += 9.0 * (1.0 - gap / 5.0) * (1.0 - 0.4 * progress);
        } else if gap > 5.0 && gap < 12.0 {
            score -= 4.0 * (1.0 - (gap - 5.0) / 7.0) * (1.0 - 0.5 * progress);
        }
    }

    // NEW MUTATION: endgame sliver sweep — residual below next item in the
    // final stretch is permanent waste; scale with wasted fraction.
    if progress > 0.8 && pr > 0 && next_item_size > 0 && pr < next_item_size {
        let waste = 1.0 - pr as f64 / next_item_size as f64;
        score += 12.0 * waste * waste * (progress - 0.8) / 0.2;
    }

    // NEW MUTATION: dual lookahead — repeatable fill detection.
    if next_item_size > 0 && next_item_size < pr {
        let pr2 = pr - next_item_size;
        if pr2 > 0 && item_size > 1 && pr2 % item_size == 0 && next_item_size % item_size == 0 {
            score -= 9.0;
        }
    }

    // NEW MUTATION: half-capacity residual targeting mid-stream.
    if pr > 0 && progress > 0.15 && progress < 0.9 {
        let half = cap * 0.5;
        let dist = ((pr as f64 - half) / half).abs();
        if dist < 0.25 {
            score -= 6.0 * (1.0 - dist / 0.25);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Sharpened perfect/near-perfect closure rewards.
    if pr == 0 {
        score -= 1280.0;
    } else if pr <= 4 {
        score -= 92.0 + (4 - pr) as f64 * 13.0;
    } else if pr < 12 {
        score += 30.0 - pr as f64;
    }

    // Harmonic residue classes.
    let class_bonus: f64 = if pr % 10 == 0 {
        36.0
    } else if pr % 5 == 0 {
        18.0
    } else if pr % 2 == 0 {
        5.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Lookahead: next item fit quality into post-placement residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 178.0 + 40.0 * (1.0 - progress);
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= if slack <= 10 { 66.0 - slack as f64 * 2.6 } else { 34.0 - (slack as f64).min(30.0) * 0.5 };
        } else {
            score += (next_item_size - pr) as f64 * 0.68;
        }
        if next_item_size < pr {
            let pr2 = pr - next_item_size;
            if pr2 <= 6 {
                score -= 52.0;
            } else if pr2 == next_item_size {
                score -= 27.0;
            } else if pr2 % 10 == 0 {
                score -= 12.0;
            }
            if pr2 > 6 && next_item_size > 1 && pr2 % next_item_size == 0 {
                score -= 15.0;
            }
            if pr2 >= 2 * item_size && item_size > 0 && pr2 % item_size == 0 {
                score -= 8.0;
            }
            if pr2 >= 3 * item_size.max(1) {
                score -= 6.0;
            }
            // Chain lookahead via mean-residual proxy.
            if pr2 > 0 && mean_residual > 0.0 {
                let proxy = mean_residual.round() as u32;
                if proxy >= 1 && proxy <= pr2 {
                    score -= 9.0 * (1.0 - progress);
                }
            }
            // Triple-chain closure.
            if pr2 >= 2 * next_item_size {
                let pr3 = pr2 - 2 * next_item_size;
                if pr3 <= 3 {
                    score -= 24.0 * (1.0 - progress);
                }
            }
            // next + item leaves near-perfect closure.
            if pr2 >= item_size.max(1) {
                let pr3 = pr2 - item_size.max(1);
                if pr3 <= 2 {
                    score -= 20.0 * (1.0 - progress);
                }
            }
        }
        // Pair-absorbency.
        if pr > 1 && pr == 2 * next_item_size {
            score -= 22.0;
        }
        // Stranded residual just below next item.
        if pr > 0 && pr < next_item_size {
            let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
            score += (7.0 + 5.0 * gap_frac) * (1.0 - progress);
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 66.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap_f) < 0.38;
        let reuse_is_bad = fitting_bins_count <= 1
            || (pr > 0 && next_item_size > pr && next_item_size <= bin_capacity);
        let late_large = item_size >= 60 && progress > 0.10;
        if late_large || (tight && progress > 0.15) || reuse_is_bad {
            score -= 46.0 + 30.0 * progress;
        } else {
            score += 70.0;
        }
        if item_size <= 25 && mean_residual > cap_f * 0.45 {
            score += 36.0;
        }
        if open_bins_count > 12 && progress < 0.3 {
            score += 12.0;
        }
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 24.0 + 18.0 * (1.0 - progress);
        }
        if next_item_size >= bin_capacity / 2 && mean_residual < (item_size + next_item_size) as f64 {
            score -= 10.0 + 14.0 * (1.0 - progress);
        }
        if item_size + next_item_size == bin_capacity
            && mean_residual < (item_size + next_item_size) as f64
        {
            score -= 20.0;
        }
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size {
            let strand = mean_residual as u32 - item_size;
            if strand > 0 && strand < 8 && progress > 0.2 {
                score -= 14.0 + 6.0 * (1.0 - progress);
            }
        }
        // Fresh-bin exact-pair bonus.
        if item_size + next_item_size == bin_capacity {
            score -= 34.0 + 20.0 * (1.0 - progress);
        }
        if pr > 0 && pr < item_size / 3 && item_size >= 30 {
            score -= 12.0;
        }
        // Fresh-bin viability gate.
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size && fitting_bins_count > 1 && !late_large {
            score += 30.0 * (1.0 - progress);
        }
        // Fresh-bin scarcity coupling.
        if fitting_bins_count >= 2 && item_size >= 40 {
            let best_gap = mean_residual - item_size as f64;
            if best_gap > 12.0 {
                score -= (best_gap / cap_f).min(0.25) * 80.0 * (1.0 - progress);
            }
        }
        // Fresh-bin only when the item cannot tile any open residual
        // with the next item — otherwise fresh space fragments the stream.
        if next_item_size > 0
            && fitting_bins_count >= 1
            && item_size + next_item_size <= bin_capacity
            && mean_residual >= (item_size + next_item_size) as f64
            && progress < 0.6
        {
            score += 18.0 * (1.0 - progress);
        }
        // Fresh-bin slot-arithmetic probe — open a new bin only when the
        // item tiles the fresh capacity into an integer number of
        // near-equal slots whose leftover is tiny; otherwise fresh space
        // invites fragmentation. Refined: weight by how close the next
        // item is to the slot remainder.
        if item_size > 0 && bin_capacity % item_size == 0 {
            let slots = bin_capacity / item_size;
            if slots >= 2 && slots <= 4 && progress > 0.1 {
                let mut bonus = 14.0 * (slots as f64).min(3.0) * (1.0 - 0.5 * progress);
                if next_item_size > 0 && next_item_size % item_size == 0 {
                    bonus *= 1.4;
                }
                score -= bonus;
            }
        }
        // Fresh-bin residual-mirror check — if the mean open-bin residual
        // is already large relative to the item, the stream is
        // under-filled and a new bin wastes capacity.
        if mean_residual > item_size as f64 * 1.6 && progress > 0.3 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
    }

    // Best-fit bias.
    score -= (bin_capacity - bin_residual) as f64 * 0.16;

    // Flexible mid-range residual target.
    if pr >= 25 && pr <= 65 {
        score -= 14.0;
    }

    // Proliferation penalty.
    score += open_bins_count as f64 * (0.2 + 0.2 * progress);

    // Waste-avoidance for tiny residuals.
    if pr > 0 && pr < bin_capacity / 5 {
        let scarcity = if fitting_bins_count > 2 { 0.6 } else { 1.4 };
        score += (10.0 + 4.0 * progress) * scarcity;
    }

    // Tightness bonus.
    if bin_residual >= item_size {
        let tightness = 1.0 - ((bin_residual - item_size) as f64 / cap_f);
        score -= 6.0 * tightness;
    }

    // Mean-residual alignment.
    let align = ((pr as f64 - mean_residual) / cap_f).abs();
    score += align * (if progress > 0.2 && progress < 0.8 { 4.5 } else { 6.0 });

    // Odd small residuals are dead-space candidates.
    if pr > 0 && pr < 20 && pr % 2 == 1 {
        score += 7.0;
    }

    // Mid-stream consolidation of large absorbable residuals.
    if open_bins_count > 8 && progress > 0.25 && progress < 0.85 && pr >= 40 {
        score -= 9.0;
    }

    // Dead-space ratio shaping with next-item floor.
    if pr > 0 && next_item_size > 0 {
        let dead_threshold = (next_item_size + 12).min(bin_capacity);
        if pr < dead_threshold {
            let dead_frac = 1.0 - (pr as f64 / dead_threshold as f64);
            score += 18.0 * dead_frac * (1.0 - progress);
        } else if pr >= dead_threshold * 2 {
            score -= 8.0 + 4.0 * (1.0 - progress);
        } else if pr == next_item_size + item_size {
            score -= 5.0;
        }
    }

    // Endgame exactness.
    if progress > 0.9 && pr > 0 {
        score += pr as f64 * 0.35;
        if pr <= next_item_size.max(1) {
            score -= 20.0;
        }
    }

    // Fragment guard against typical upcoming demand.
    if pr > 0 && progress > 0.1 {
        let typical = (mean_residual * 0.5).max(8.0).min(cap_f * 0.5);
        if (pr as f64) < typical {
            score += 6.0 * (1.0 - (pr as f64 / typical)) * (1.0 - progress);
        }
    }

    // Exact-closure sweep with plentiful fitting bins.
    if pr == 0 && fitting_bins_count > 2 {
        score -= 12.0 * (1.0 - progress);
    }

    // Dual lookahead — repeatable fill detection.
    if next_item_size > 0 && next_item_size < pr {
        let pr2 = pr - next_item_size;
        if pr2 > 0 && item_size > 1 && pr2 % item_size == 0 && next_item_size % item_size == 0 {
            score -= 10.0;
        }
    }

    // Half-capacity residual targeting mid-stream.
    if pr > 0 && progress > 0.15 && progress < 0.9 {
        let half = cap_f * 0.5;
        let dist = ((pr as f64 - half) / half).abs();
        if dist < 0.25 {
            score -= 7.0 * (1.0 - dist / 0.25);
        }
    }

    // Dead-space ratio term with smooth quadratic ramp.
    if pr > 0 {
        let pr_f = pr as f64;
        let usable_floor = (next_item_size.max(1) as f64).min(cap_f * 0.3);
        if pr_f < usable_floor {
            let dsr = 1.0 - pr_f / usable_floor;
            score += 11.0 * dsr * dsr * (0.5 + 0.5 * (1.0 - progress));
        }
        if pr % 3 == 0 && pr >= 6 {
            score -= 5.0;
        }
        if pr % 7 == 0 && pr >= 7 {
            score -= 4.0;
        }
    }

    // Bin-count pressure valve.
    if bin_residual != bin_capacity && mean_residual > 0.0 {
        let fill = 1.0 - mean_residual / cap_f;
        if fill > 0.75 && fitting_bins_count > 1 {
            score -= 6.0 * (fill - 0.75) / 0.25;
        } else if fill < 0.5 && fitting_bins_count > 1 {
            score += 4.0 * (0.5 - fill) / 0.5 * (1.0 - progress);
        }
    }

    // Dead-space waste accounting with quadratic ramp.
    if pr > 0 && next_item_size > 0 && next_item_size < bin_capacity {
        let waste_frac = 1.0 - (pr.min(next_item_size) as f64 / pr as f64);
        if waste_frac > 0.5 {
            score += 9.0 * (waste_frac - 0.5) * 2.0 * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Consolidation incentive matching mean residual.
    if progress > 0.35 && pr >= next_item_size.max(1) && mean_residual > 0.0 {
        let dev = ((pr as f64 - mean_residual) / cap_f).abs();
        if dev < 0.08 {
            score -= 6.0 * (1.0 - dev / 0.08);
        }
    }

    // Quad-chain lookahead.
    if next_item_size > 0 && pr >= 3 * next_item_size {
        let pr3 = pr - 3 * next_item_size;
        if pr3 <= 4 {
            score -= 18.0 * (1.0 - progress);
        }
    }

    // Item+next exact pair inside residual.
    if next_item_size > 0 && item_size > 0 && pr == item_size + next_item_size {
        score -= 26.0;
    }

    // Late-stream fresh-bin restraint.
    if bin_residual == bin_capacity && progress > 0.7 {
        let exact_pair = item_size + next_item_size == bin_capacity;
        if !exact_pair && fitting_bins_count > 0 {
            score += 22.0 * (progress - 0.7) / 0.3;
        }
    }

    // Large-item protection.
    if item_size > 50 && pr > 0 && pr < 15 {
        score += 10.0 * (1.0 - pr as f64 / 15.0);
    }

    // Residual-divisibility absorbency.
    if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 {
        let chain_len = pr / next_item_size;
        if chain_len >= 2 {
            score -= (8.0 + 6.0 * chain_len.min(4) as f64) * (1.0 - 0.5 * progress);
        }
    }

    // Dead-space variance dampener.
    if pr > 0 && next_item_size > 0 && pr < next_item_size && open_bins_count > 3 {
        let unusable = (next_item_size - pr) as f64 / next_item_size as f64;
        score += 14.0 * unusable * unusable * (1.0 - progress);
    }

    // Mid-stream sweep for residuals matching common item-size sums.
    if pr > 0 && progress > 0.2 && progress < 0.9 {
        let small_sum = item_size.min(next_item_size.max(1));
        if pr == 2 * small_sum || pr == small_sum + 10 || pr == small_sum + 25 {
            score -= 7.0;
        }
    }

    // Endgame fresh-bin suppression.
    if bin_residual == bin_capacity && progress > 0.85 {
        let biggest_resid = mean_residual.max(0.0);
        if item_size as f64 <= biggest_resid.max(1.0) && fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Residual pooling.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.2 && progress < 0.85 {
        let mr = mean_residual;
        let k = (pr as f64 / mr).round().max(1.0);
        let dev = (pr as f64 - k * mr).abs() / mr;
        if dev < 0.15 && k >= 1.0 {
            score -= 10.0 * (1.0 - dev / 0.15) * (1.0 - 0.4 * progress);
        }
    }

    // Two-item lookahead tiling.
    if pr > 0 && next_item_size > 0 && mean_residual > 1.0 {
        let combo = next_item_size as f64 + mean_residual.min(cap_f * 0.4);
        let gap = pr as f64 - combo;
        if gap >= 0.0 && gap <= 5.0 {
            score -= (16.0 - gap) * 2.4 * (1.0 - 0.5 * progress);
        }
    }

    // Strand-risk shaping.
    if pr >= 13 && pr <= 24 {
        let crowd = if open_bins_count > 10 { 1.5 } else { 0.7 };
        score += 6.0 * crowd * (1.0 - 0.5 * progress);
    }

    // Dead-space floor tightening.
    if pr > 0 && next_item_size > 0 {
        let floor = next_item_size.max(1) as f64;
        if (pr as f64) < floor {
            let x = pr as f64 / floor;
            score += (10.0 + 14.0 * (1.0 - x) * (1.0 - x)) * (1.0 - 0.6 * progress);
        }
    }

    // Near-exact residual shaping.
    if next_item_size > 0 && pr > next_item_size && pr <= next_item_size + 3 {
        score -= (18.0 - (pr - next_item_size) as f64 * 4.0) * (1.0 - 0.5 * progress);
    }

    // Open-bin budget shaping.
    if open_bins_count as f64 > (step_index as f64) * 0.35 && pr > 0 {
        let over = open_bins_count as f64 / (step_index as f64 + 1.0);
        score += (pr as f64 / cap_f) * 22.0 * over.min(1.5);
    }

    // Dead-space minimization sweep.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let mr = mean_residual.min(cap_f);
        let usable_by_next = pr >= next_item_size;
        let usable_by_mean = (pr as f64) >= mr;
        if !usable_by_next && !usable_by_mean {
            let wasted = (next_item_size - pr) as f64;
            score += (6.0 + 0.25 * wasted) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Exact-fill cascade.
    if next_item_size > 0 && item_size > 1 && pr > next_item_size {
        let pr2 = pr - next_item_size;
        if pr2 % item_size == 0 && pr2 / item_size >= 1 && pr2 != 0 {
            score -= (10.0 + 4.0 * (pr2 / item_size).min(3) as f64) * (1.0 - 0.4 * progress);
        }
    }

    // Residual-slope steering.
    if next_item_size > 0 && pr > 0 {
        let target = next_item_size as f64;
        let dev = (pr as f64 - target) / target.max(1.0);
        if dev.abs() < 0.5 {
            score -= 9.0 * (1.0 - (dev / 0.5) * (dev / 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    // Dual-fit depth probe.
    if next_item_size > 0 && pr > next_item_size && mean_residual >= 1.0 {
        let pr2 = pr - next_item_size;
        let proxy = mean_residual.min(cap_f);
        if (pr2 as f64) >= proxy {
            score -= 11.0 * (1.0 - 0.5 * progress);
            if pr2 as f64 - proxy < 6.0 {
                score -= 8.0;
            }
        }
        if (pr2 as f64) < proxy && pr2 > 0 && pr2 < 10 {
            score += 9.0 * (1.0 - pr2 as f64 / 10.0);
        }
    }

    // Capacity-fraction dead-space gate.
    if pr > 0 && progress > 0.2 && progress < 0.9 {
        let lo = cap_f * 0.38;
        let hi = cap_f * 0.5;
        if (pr as f64) > lo && (pr as f64) < hi {
            let frac = 1.0 - ((pr as f64 - lo) / (hi - lo));
            score += 8.0 * frac * frac;
        }
    }

    // Dead-space recovery probe — when the residual after placement can
    // still absorb the mean-sized upcoming item with a small remainder,
    // reward the bin; but if the remainder is a sliver (1..=5) that
    // likely strands forever, penalize instead. Refined: sharpen the
    // sliver boundary and extend the reward band slightly.
    if pr > 0 && mean_residual >= 2.0 {
        let mr = mean_residual.min(cap_f * 0.6);
        let gap = pr as f64 - mr;
        if gap >= 0.0 && gap <= 6.0 {
            if gap <= 2.0 {
                score += 13.0 * (1.0 - gap / 6.0) * (1.0 - 0.4 * progress);
            } else {
                score += 10.0 * (1.0 - gap / 6.0) * (1.0 - 0.4 * progress);
            }
        } else if gap > 6.0 && gap < 12.0 {
            score -= 5.0 * (1.0 - (gap - 6.0) / 6.0) * (1.0 - 0.5 * progress);
        }
    }

    // Fitting-crowd tiebreak — when many bins can accept the item,
    // prefer the one whose post-residual best matches the harmonic mean
    // of next item and mean residual; when few bins fit, relax the
    // matching pressure.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let harmonic = 2.0 * (next_item_size as f64 * mean_residual)
            / (next_item_size as f64 + mean_residual).max(1.0);
        let dev = ((pr as f64 - harmonic) / harmonic.max(1.0)).abs();
        let pressure = if fitting_bins_count >= 4 { 1.0 } else { 0.4 };
        if dev < 0.3 {
            score -= 7.0 * (1.0 - dev / 0.3) * pressure * (1.0 - 0.4 * progress);
        }
    }

    // Endgame sliver sweep — in the final stretch, any residual below
    // the next item is permanent waste; scale the penalty with the
    // wasted fraction so near-miss residuals are salvaged.
    if progress > 0.8 && pr > 0 && next_item_size > 0 && pr < next_item_size {
        let waste = 1.0 - pr as f64 / next_item_size as f64;
        score += 12.0 * waste * waste * (progress - 0.8) / 0.2;
    }

    // NEW MUTATION: dead-space ratio compaction sweep — target the
    // diagnosed weakness directly. When the post-residual is large
    // enough to hold both the next item AND the mean-sized demand after
    // it, the bin acts as a compaction sink; reward it proportionally
    // to how much of the residual that chain consumes. Conversely, when
    // the residual is a large multiple of the mean residual but not
    // exactly so, the leftover fragments — penalize the deviation.
    if pr > 0 && next_item_size > 0 && mean_residual >= 1.0 && progress < 0.9 {
        let chain_need = next_item_size as f64 + mean_residual;
        if (pr as f64) >= chain_need {
            let consumed = chain_need / pr as f64;
            score -= 9.0 * consumed * (1.0 - 0.5 * progress);
        }
        let k = (pr as f64 / mean_residual).floor();
        if k >= 2.0 {
            let leftover = pr as f64 - k * mean_residual;
            if leftover > 0.0 && leftover < next_item_size as f64 {
                score += 5.0 * (1.0 - leftover / next_item_size as f64) * (1.0 - progress);
            }
        }
    }

    // NEW MUTATION: residual-shape preservation — bins whose post-
    // residual remains a multiple of a common small divisor (2, 4, 8)
    // can absorb future power-of-two-like items cleanly; reward exact
    // power-of-two residuals mid-stream since typical streams mix many
    // even-sized items that then tile them without slivers.
    if pr > 0 && progress > 0.15 && progress < 0.9 {
        if pr == 8 || pr == 16 || pr == 32 || pr == 64 {
            score -= 6.0 * (1.0 - 0.4 * progress);
        } else if pr >= 12 && pr % 4 == 0 && pr % 8 != 0 && next_item_size % 4 == 0 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Perfect/near-perfect closure rewards.
    if pr == 0 {
        score -= 1280.0;
    } else if pr <= 4 {
        score -= 92.0 + (4 - pr) as f64 * 13.0;
    } else if pr < 12 {
        score += 30.0 - pr as f64;
    }

    // Harmonic residue classes.
    let class_bonus: f64 = if pr % 10 == 0 {
        36.0
    } else if pr % 5 == 0 {
        18.0
    } else if pr % 2 == 0 {
        5.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Lookahead: next item fit quality into post-placement residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 178.0 + 40.0 * (1.0 - progress);
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= if slack <= 10 { 66.0 - slack as f64 * 2.6 } else { 34.0 - (slack as f64).min(30.0) * 0.5 };
        } else {
            score += (next_item_size - pr) as f64 * 0.68;
        }
        if next_item_size < pr {
            let pr2 = pr - next_item_size;
            if pr2 <= 6 {
                score -= 52.0;
            } else if pr2 == next_item_size {
                score -= 27.0;
            } else if pr2 % 10 == 0 {
                score -= 12.0;
            }
            if pr2 > 6 && next_item_size > 1 && pr2 % next_item_size == 0 {
                score -= 15.0;
            }
            if pr2 >= 2 * item_size && item_size > 0 && pr2 % item_size == 0 {
                score -= 8.0;
            }
            if pr2 >= 3 * item_size.max(1) {
                score -= 6.0;
            }
            // Chain lookahead via mean-residual proxy.
            if pr2 > 0 && mean_residual > 0.0 {
                let proxy = mean_residual.round() as u32;
                if proxy >= 1 && proxy <= pr2 {
                    score -= 9.0 * (1.0 - progress);
                }
            }
            // Triple-chain closure.
            if pr2 >= 2 * next_item_size {
                let pr3 = pr2 - 2 * next_item_size;
                if pr3 <= 3 {
                    score -= 24.0 * (1.0 - progress);
                }
            }
            // next + item leaves near-perfect closure.
            if pr2 >= item_size.max(1) {
                let pr3 = pr2 - item_size.max(1);
                if pr3 <= 2 {
                    score -= 20.0 * (1.0 - progress);
                }
            }
        }
        if pr > 1 && pr == 2 * next_item_size {
            score -= 22.0;
        }
        if pr > 0 && pr < next_item_size {
            let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
            score += (7.0 + 5.0 * gap_frac) * (1.0 - progress);
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 66.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap_f) < 0.38;
        let reuse_is_bad = fitting_bins_count <= 1
            || (pr > 0 && next_item_size > pr && next_item_size <= bin_capacity);
        let late_large = item_size >= 60 && progress > 0.10;
        if late_large || (tight && progress > 0.15) || reuse_is_bad {
            score -= 46.0 + 30.0 * progress;
        } else {
            score += 70.0;
        }
        if item_size <= 25 && mean_residual > cap_f * 0.45 {
            score += 36.0;
        }
        if open_bins_count > 12 && progress < 0.3 {
            score += 12.0;
        }
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 24.0 + 18.0 * (1.0 - progress);
        }
        if next_item_size >= bin_capacity / 2 && mean_residual < (item_size + next_item_size) as f64 {
            score -= 10.0 + 14.0 * (1.0 - progress);
        }
        if item_size + next_item_size == bin_capacity
            && mean_residual < (item_size + next_item_size) as f64
        {
            score -= 20.0;
        }
        if item_size >= bin_capacity / 3 && next_item_size >= bin_capacity / 3
            && item_size + next_item_size > bin_capacity
        {
            score -= 8.0 + 10.0 * (1.0 - progress);
        }
        // Fresh-bin exact-pair bonus.
        if item_size + next_item_size == bin_capacity {
            score -= 34.0 + 20.0 * (1.0 - progress);
        }
        // Fresh-bin residual-mirror check: under-filled stream means a new
        // bin wastes capacity.
        if mean_residual > item_size as f64 * 1.6 && progress > 0.3 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
        // Fresh-bin viability gate.
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size && fitting_bins_count > 1 && !late_large {
            score += 30.0 * (1.0 - progress);
        }
        // Fresh-bin slot-arithmetic probe: tile capacity into near-equal slots.
        if item_size > 0 && bin_capacity % item_size == 0 {
            let slots = bin_capacity / item_size;
            if slots >= 2 && slots <= 4 && progress > 0.1 {
                score -= 14.0 * (slots as f64).min(3.0) * (1.0 - 0.5 * progress);
            }
        }
        // Endgame fresh-bin suppression.
        if progress > 0.85 && item_size as f64 <= mean_residual.max(1.0) && fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Best-fit bias.
    score -= (bin_capacity - bin_residual) as f64 * 0.17;

    // Flexible mid-range residual target.
    if pr >= 25 && pr <= 60 {
        score -= 14.0;
    }

    // Proliferation penalty.
    score += open_bins_count as f64 * (0.2 + 0.2 * progress);

    // Waste-avoidance for tiny residuals.
    if pr > 0 && pr < bin_capacity / 5 {
        let scarcity = if fitting_bins_count > 2 { 0.6 } else { 1.4 };
        score += (10.0 + 4.0 * progress) * scarcity;
    }

    // Tightness bonus.
    if bin_residual >= item_size {
        let tightness = 1.0 - ((bin_residual - item_size) as f64 / cap_f);
        score -= 6.0 * tightness;
    }

    // Mean-residual alignment.
    let align = ((pr as f64 - mean_residual) / cap_f).abs();
    score += align * (if progress > 0.2 && progress < 0.8 { 4.5 } else { 6.0 });

    // Odd small residuals are dead-space candidates.
    if pr > 0 && pr < 20 && pr % 2 == 1 {
        score += 7.0;
    }

    // Mid-stream consolidation of large absorbable residuals.
    if open_bins_count > 8 && progress > 0.25 && progress < 0.85 && pr >= 40 {
        score -= 9.0;
    }

    // Dead-space ratio shaping with next-item floor (scarcity-scaled).
    if pr > 0 && next_item_size > 0 {
        let dead_threshold = (next_item_size + 12).min(bin_capacity);
        if pr < dead_threshold {
            let dead_frac = 1.0 - (pr as f64 / dead_threshold as f64);
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 18.0 * dead_frac * (1.0 - progress) * (0.5 + 0.5 * scarcity);
        } else if pr >= dead_threshold * 2 {
            score -= 8.0 + 4.0 * (1.0 - progress);
        } else if pr == next_item_size + item_size {
            score -= 5.0;
        }
    }

    // Endgame exactness.
    if progress > 0.9 && pr > 0 {
        score += pr as f64 * 0.35;
        if pr <= next_item_size.max(1) {
            score -= 20.0;
        }
        if pr == next_item_size {
            score -= 15.0;
        }
    }

    // Fragment guard against typical upcoming demand.
    if pr > 0 && progress > 0.1 {
        let typical = (mean_residual * 0.5).max(8.0).min(cap_f * 0.5);
        if (pr as f64) < typical {
            score += 6.0 * (1.0 - (pr as f64 / typical)) * (1.0 - progress);
        }
    }

    // Exact-closure sweep.
    if pr == 0 && fitting_bins_count > 2 {
        score -= 12.0 * (1.0 - progress);
    }

    // Dual lookahead: repeatable fill.
    if next_item_size > 0 && next_item_size < pr {
        let pr2 = pr - next_item_size;
        if pr2 > 0 && item_size > 1 && pr2 % item_size == 0 && next_item_size % item_size == 0 {
            score -= 10.0;
        }
        if pr2 > 0 && pr2 >= next_item_size && (pr2 - next_item_size) < 4 {
            score -= 9.0 * (1.0 - progress);
        }
    }

    // Quad-chain lookahead.
    if next_item_size > 0 && pr >= 3 * next_item_size {
        let pr3 = pr - 3 * next_item_size;
        if pr3 <= 4 {
            score -= 18.0 * (1.0 - progress);
        }
    }

    // Item+next exact pair inside residual.
    if next_item_size > 0 && item_size > 0 && pr == item_size + next_item_size {
        score -= 26.0;
    }

    // Residual-divisibility absorbency.
    if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 {
        let chain_len = pr / next_item_size;
        if chain_len >= 2 {
            score -= (8.0 + 6.0 * chain_len.min(4) as f64) * (1.0 - 0.5 * progress);
        }
    }

    // Dead-space variance dampener.
    if pr > 0 && next_item_size > 0 && pr < next_item_size && open_bins_count > 3 {
        let unusable = (next_item_size - pr) as f64 / next_item_size as f64;
        score += 14.0 * unusable * unusable * (1.0 - progress);
    }

    // Residual pooling toward mean-residual multiples.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.2 && progress < 0.85 {
        let mr = mean_residual;
        let k = (pr as f64 / mr).round().max(1.0);
        let dev = (pr as f64 - k * mr).abs() / mr;
        if dev < 0.15 {
            score -= 10.0 * (1.0 - dev / 0.15) * (1.0 - 0.4 * progress);
        }
    }

    // Two-item lookahead tiling with mean-residual proxy.
    if pr > 0 && next_item_size > 0 && mean_residual > 1.0 {
        let combo = next_item_size as f64 + mean_residual.min(cap_f * 0.4);
        let gap = pr as f64 - combo;
        if gap >= 0.0 && gap <= 5.0 {
            score -= (16.0 - gap) * 2.4 * (1.0 - 0.5 * progress);
        }
    }

    // Dead-space floor tightening.
    if pr > 0 && next_item_size > 0 {
        let floor = next_item_size.max(1) as f64;
        if (pr as f64) < floor {
            let x = pr as f64 / floor;
            score += (10.0 + 14.0 * (1.0 - x) * (1.0 - x)) * (1.0 - 0.6 * progress);
        }
    }

    // Near-exact residual shaping.
    if next_item_size > 0 && pr > next_item_size && pr <= next_item_size + 3 {
        score -= (18.0 - (pr - next_item_size) as f64 * 4.0) * (1.0 - 0.5 * progress);
    }

    // Dead-space minimization sweep.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let mr = mean_residual.min(cap_f);
        let usable_by_next = pr >= next_item_size;
        let usable_by_mean = (pr as f64) >= mr;
        if !usable_by_next && !usable_by_mean {
            let wasted = (next_item_size - pr) as f64;
            score += (6.0 + 0.25 * wasted) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Exact-fill cascade.
    if next_item_size > 0 && item_size > 1 && pr > next_item_size {
        let pr2 = pr - next_item_size;
        if pr2 % item_size == 0 && pr2 / item_size >= 1 {
            score -= (10.0 + 4.0 * (pr2 / item_size).min(3) as f64) * (1.0 - 0.4 * progress);
        }
    }

    // Dual-fit depth probe.
    if next_item_size > 0 && pr > next_item_size && mean_residual >= 1.0 {
        let pr2 = pr - next_item_size;
        let proxy = mean_residual.min(cap_f);
        if (pr2 as f64) >= proxy {
            score -= 11.0 * (1.0 - 0.5 * progress);
            if pr2 as f64 - proxy < 6.0 {
                score -= 8.0;
            }
        }
        if (pr2 as f64) < proxy && pr2 > 0 && pr2 < 10 {
            score += 9.0 * (1.0 - pr2 as f64 / 10.0);
        }
    }

    // Dead-space recovery probe: distinguish reusable vs stranded remainder.
    if pr > 0 && mean_residual >= 2.0 {
        let mr = mean_residual.min(cap_f * 0.6);
        let gap = pr as f64 - mr;
        if gap >= 0.0 && gap <= 5.0 {
            score += 10.0 * (1.0 - gap / 5.0) * (1.0 - 0.4 * progress);
        } else if gap > 5.0 && gap < 12.0 {
            score -= 5.0 * (1.0 - (gap - 5.0) / 7.0) * (1.0 - 0.5 * progress);
        }
    }

    // Fitting-crowd tiebreak via harmonic mean of next item and mean residual.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let harmonic = 2.0 * (next_item_size as f64 * mean_residual)
            / (next_item_size as f64 + mean_residual).max(1.0);
        let dev = ((pr as f64 - harmonic) / harmonic.max(1.0)).abs();
        let pressure = if fitting_bins_count >= 4 { 1.0 } else { 0.4 };
        if dev < 0.3 {
            score -= 7.0 * (1.0 - dev / 0.3) * pressure * (1.0 - 0.4 * progress);
        }
    }

    // Endgame sliver sweep: residuals below next item become permanent waste.
    if progress > 0.8 && pr > 0 && next_item_size > 0 && pr < next_item_size {
        let waste = 1.0 - pr as f64 / next_item_size as f64;
        score += 12.0 * waste * waste * (progress - 0.8) / 0.2;
    }

    // Late-stream fresh-bin restraint.
    if bin_residual == bin_capacity && progress > 0.7 {
        let exact_pair = item_size + next_item_size == bin_capacity;
        if !exact_pair && fitting_bins_count > 0 {
            score += 22.0 * (progress - 0.7) / 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Sharpened closure rewards: perfect fit dominates everything.
    if pr == 0 {
        score -= 900.0;
    } else if pr <= 4 {
        score -= 80.0 + (4 - pr) as f64 * 12.0;
    } else if pr <= 10 {
        score += 40.0 - pr as f64;
    } else if pr <= 25 {
        score += 12.0;
    } else if pr <= 50 {
        score -= 5.0;
    } else {
        score -= 12.0;
    }

    // Harmonic residue classes.
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 30.0;
        } else if pr % 5 == 0 {
            score -= 14.0;
        } else if pr % 2 == 0 {
            score -= 4.0;
        }
        if pr < 20 && pr % 2 == 1 {
            score += 6.0;
        }
    }

    // Lookahead coupling with next item.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 150.0 + 40.0 * (1.0 - progress);
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            if slack <= 10 {
                score -= 60.0 - slack as f64 * 2.5;
            } else {
                score -= 30.0 - (slack as f64).min(30.0) * 0.5;
            }
            let pr2 = pr - next_item_size;
            if pr2 <= 6 {
                score -= 45.0;
            } else if pr2 == next_item_size {
                score -= 24.0;
            } else if pr2 % 10 == 0 {
                score -= 10.0;
            }
            if pr2 > 6 && next_item_size > 1 && pr2 % next_item_size == 0 {
                score -= 14.0;
            }
            if pr2 >= 2 * next_item_size {
                let pr3 = pr2 - 2 * next_item_size;
                if pr3 <= 3 {
                    score -= 20.0 * (1.0 - progress);
                }
            }
            if pr2 >= item_size.max(1) {
                let pr3 = pr2 - item_size.max(1);
                if pr3 <= 2 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
            if pr2 > 0 && mean_residual > 0.0 {
                let proxy = mean_residual.round() as u32;
                if proxy >= 1 && proxy <= pr2 {
                    score -= 8.0 * (1.0 - progress);
                }
            }
        } else {
            let overshoot = (next_item_size - pr) as f64 / cap;
            score += 10.0 * overshoot;
            if pr > 0 {
                let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
                score += (6.0 + 5.0 * gap_frac) * (1.0 - progress);
            }
        }
        if pr > 1 && pr == 2 * next_item_size {
            score -= 20.0;
        }
        if next_item_size > 0 && item_size > 0 && pr == item_size + next_item_size {
            score -= 24.0;
        }
    } else {
        score -= 20.0;
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 70.0;
    }

    // New-bin candidate handling: strict gate.
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap) < 0.38;
        let reuse_is_bad = fitting_bins_count <= 1
            || (pr > 0 && next_item_size > pr && next_item_size <= bin_capacity);
        let late_large = item_size >= 60 && progress > 0.10;
        if late_large || (tight && progress > 0.15) || reuse_is_bad {
            score -= 44.0 + 28.0 * progress;
        } else {
            score += 70.0;
        }
        if item_size <= 25 && mean_residual > cap * 0.45 {
            score += 34.0;
        }
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 22.0 + 16.0 * (1.0 - progress);
        }
        if item_size + next_item_size == bin_capacity {
            score -= 32.0 + 18.0 * (1.0 - progress);
        }
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size
            && fitting_bins_count > 1 && !late_large {
            score += 28.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 2 && item_size >= 40 {
            let best_gap = mean_residual - item_size as f64;
            if best_gap > 12.0 {
                score -= (best_gap / cap).min(0.25) * 75.0 * (1.0 - progress);
            }
        }
        if bin_capacity % item_size == 0 {
            let slots = bin_capacity / item_size;
            if slots >= 2 && slots <= 4 && progress > 0.1 {
                score -= 12.0 * (slots as f64).min(3.0) * (1.0 - 0.5 * progress);
            }
        }
        if mean_residual > item_size as f64 * 1.6 && progress > 0.3 {
            score += 15.0 * (1.0 - 0.5 * progress);
        }
        if progress > 0.85 && item_size as f64 <= mean_residual.max(1.0) && fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Best-fit bias.
    score -= (bin_capacity - bin_residual) as f64 * 0.16;

    // Proliferation penalty.
    score += open_bins_count as f64 * (0.2 + 0.2 * progress);

    // Waste-avoidance for tiny residuals.
    if pr > 0 && pr < bin_capacity / 5 {
        let scarcity = if fitting_bins_count > 2 { 0.6 } else { 1.4 };
        score += (10.0 + 4.0 * progress) * scarcity;
    }

    // Tightness bonus.
    if bin_residual >= item_size {
        let tightness = 1.0 - ((bin_residual - item_size) as f64 / cap);
        score -= 6.0 * tightness;
    }

    // Mean-residual alignment.
    let align = ((pr as f64 - mean_residual) / cap).abs();
    score += align * (if progress > 0.2 && progress < 0.8 { 4.5 } else { 6.0 });

    // Dead-space shaping against next-item floor.
    if pr > 0 && next_item_size > 0 {
        let floor = next_item_size.max(1) as f64;
        if (pr as f64) < floor {
            let x = pr as f64 / floor;
            score += (10.0 + 14.0 * (1.0 - x) * (1.0 - x)) * (1.0 - 0.6 * progress);
        } else if pr >= floor * 2 {
            score -= 7.0 + 3.0 * (1.0 - progress);
        }
    }

    // Endgame exactness.
    if progress > 0.9 && pr > 0 {
        score += pr as f64 * 0.35;
        if pr <= next_item_size.max(1) {
            score -= 20.0;
        }
    }

    // Fragment guard against typical upcoming demand.
    if pr > 0 && progress > 0.1 {
        let typical = (mean_residual * 0.5).max(8.0).min(cap * 0.5);
        if (pr as f64) < typical {
            score += 6.0 * (1.0 - (pr as f64 / typical)) * (1.0 - progress);
        }
    }

    // Near-exact residual shaping.
    if next_item_size > 0 && pr > next_item_size && pr <= next_item_size + 3 {
        score -= (18.0 - (pr - next_item_size) as f64 * 4.0) * (1.0 - 0.5 * progress);
    }

    // Dual-fit depth probe via mean-residual proxy.
    if next_item_size > 0 && pr > next_item_size && mean_residual >= 1.0 {
        let pr2 = pr - next_item_size;
        let proxy = mean_residual.min(cap);
        if (pr2 as f64) >= proxy {
            score -= 10.0 * (1.0 - 0.5 * progress);
            if pr2 as f64 - proxy < 6.0 {
                score -= 8.0;
            }
        }
    }

    // Residual pooling toward multiples of mean residual.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.2 && progress < 0.85 {
        let mr = mean_residual;
        let k = (pr as f64 / mr).round().max(1.0);
        let dev = (pr as f64 - k * mr).abs() / mr;
        if dev < 0.15 {
            score -= 10.0 * (1.0 - dev / 0.15) * (1.0 - 0.4 * progress);
        }
    }

    // Two-item lookahead tiling with mean-residual proxy.
    if pr > 0 && next_item_size > 0 && mean_residual > 1.0 {
        let combo = next_item_size as f64 + mean_residual.min(cap * 0.4);
        let gap = pr as f64 - combo;
        if gap >= 0.0 && gap <= 5.0 {
            score -= (16.0 - gap) * 2.4 * (1.0 - 0.5 * progress);
        }
    }

    // Strand-risk shaping.
    if pr >= 13 && pr <= 24 {
        let crowd = if open_bins_count > 10 { 1.5 } else { 0.7 };
        score += 6.0 * crowd * (1.0 - 0.5 * progress);
    }

    // Fitting-crowd harmonic tiebreak.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let harmonic = 2.0 * (next_item_size as f64 * mean_residual)
            / (next_item_size as f64 + mean_residual).max(1.0);
        let dev = ((pr as f64 - harmonic) / harmonic.max(1.0)).abs();
        let pressure = if fitting_bins_count >= 4 { 1.0 } else { 0.4 };
        if dev < 0.3 {
            score -= 7.0 * (1.0 - dev / 0.3) * pressure * (1.0 - 0.4 * progress);
        }
    }

    // Mid-stream consolidation of large absorbable residuals.
    if open_bins_count > 8 && progress > 0.25 && progress < 0.85 && pr >= 40 {
        score -= 9.0;
    }

    // Late-stream fresh-bin restraint.
    if bin_residual == bin_capacity && progress > 0.7 {
        let exact_pair = item_size + next_item_size == bin_capacity;
        if !exact_pair && fitting_bins_count > 0 {
            score += 22.0 * (progress - 0.7) / 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
