    // bin leaves either an exact fit or a comfortably reusable residual.
    if pr > 0 && next_item_size > 0 && fitting_bins_count <= 3 {
        let over = pr as f64 - next_item_size as f64;
        if over > 0.0 && over <= 5.0 {
            score += (3.0 + over) * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION: residual-variance-aware consolidation — when residuals
    // cluster tightly around the mean (low variance proxy via mean vs
    // half-capacity), reward residuals that land within a small band of
    // the mean so the stream keeps tiles interchangeable.
    if pr > 0 && mean_residual > 6.0 && progress > 0.25 && progress < 0.9 {
        let band = 4.0 + 4.0 * (1.0 - progress);
        let dev = (pr as f64 - mean_residual).abs();
        if dev <= band {
            score -= 5.0 * (1.0 - dev / band);
        }
    }

    // MUTATION: two-step exact-closure — placing the item then the next
    // item then exactly one mean-residual-sized top-up closes the bin
