        if pr % 3 == 0 && pr >= 6 {
            score -= 5.0;
        }
        if pr % 7 == 0 && pr >= 7 {
            score -= 4.0;
        }
    }

    // Bin-count pressure valve.
    if bin_residual != bin_capacity && mean_residual > 0.0 {
        let fill = 1.0 - mean_residual / cap_f;
        if fill > 0.75 && fitting_bins_count > 1 {
            score -= 6.0 * (fill - 0.75) / 0.25;
        } else if fill < 0.5 && fitting_bins_count > 1 {
            score += 4.0 * (0.5 - fill) / 0.5 * (1.0 - progress);
        }
    }

    // Dead-space waste accounting with quadratic ramp.
    if pr > 0 && next_item_size > 0 && next_item_size < bin_capacity {
        let waste_frac = 1.0 - (pr.min(next_item_size) as f64 / pr as f64);
        if waste_frac > 0.5 {
            score += 9.0 * (waste_frac - 0.5) * 2.0 * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Consolidation incentive matching mean residual.
    if progress > 0.35 && pr >= next_item_size.max(1) && mean_residual > 0.0 {
        let dev = ((pr as f64 - mean_residual) / cap_f).abs();
        if dev < 0.08 {
            score -= 6.0 * (1.0 - dev / 0.08);
        }
    }

    // Quad-chain lookahead.
    if next_item_size > 0 && pr >= 3 * next_item_size {
        let pr3 = pr - 3 * next_item_size;
        if pr3 <= 4 {
            score -= 18.0 * (1.0 - progress);
        }
    }

    // Item+next exact pair inside residual.
    if next_item_size > 0 && item_size > 0 && pr == item_size + next_item_size {
        score -= 26.0;
    }

    // Late-stream fresh-bin restraint.
    if bin_residual == bin_capacity && progress > 0.7 {
        let exact_pair = item_size + next_item_size == bin_capacity;
        if !exact_pair && fitting_bins_count > 0 {
            score += 22.0 * (progress - 0.7) / 0.3;
        }
    }

    // Large-item protection.
    if item_size > 50 && pr > 0 && pr < 15 {
        score += 10.0 * (1.0 - pr as f64 / 15.0);
    }

    // Residual-divisibility absorbency.
    if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 {
        let chain_len = pr / next_item_size;
        if chain_len >= 2 {
            score -= (8.0 + 6.0 * chain_len.min(4) as f64) * (1.0 - 0.5 * progress);
        }
    }

    // Dead-space variance dampener.
    if pr > 0 && next_item_size > 0 && pr < next_item_size && open_bins_count > 3 {
        let unusable = (next_item_size - pr) as f64 / next_item_size as f64;
        score += 14.0 * unusable * unusable * (1.0 - progress);
    }

    // Mid-stream sweep for residuals matching common item-size sums.
    if pr > 0 && progress > 0.2 && progress < 0.9 {
        let small_sum = item_size.min(next_item_size.max(1));
        if pr == 2 * small_sum || pr == small_sum + 10 || pr == small_sum + 25 {
            score -= 7.0;
        }
    }

    // Endgame fresh-bin suppression.
    if bin_residual == bin_capacity && progress > 0.85 {
        let biggest_resid = mean_residual.max(0.0);
        if item_size as f64 <= biggest_resid.max(1.0) && fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Residual pooling.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.2 && progress < 0.85 {
        let mr = mean_residual;
        let k = (pr as f64 / mr).round().max(1.0);
        let dev = (pr as f64 - k * mr).abs() / mr;
        if dev < 0.15 && k >= 1.0 {
            score -= 10.0 * (1.0 - dev / 0.15) * (1.0 - 0.4 * progress);
        }
    }

    // Two-item lookahead tiling.
    if pr > 0 && next_item_size > 0 && mean_residual > 1.0 {
        let combo = next_item_size as f64 + mean_residual.min(cap_f * 0.4);
        let gap = pr as f64 - combo;
        if gap >= 0.0 && gap <= 5.0 {
            score -= (16.0 - gap) * 2.4 * (1.0 - 0.5 * progress);
        }
    }

    // Strand-risk shaping.
    if pr >= 13 && pr <= 24 {
        let crowd = if open_bins_count > 10 { 1.5 } else { 0.7 };
        score += 6.0 * crowd * (1.0 - 0.5 * progress);
    }

    // Dead-space floor tightening.
    if pr > 0 && next_item_size > 0 {
        let floor = next_item_size.max(1) as f64;
        if (pr as f64) < floor {
            let x = pr as f64 / floor;
            score += (10.0 + 14.0 * (1.0 - x) * (1.0 - x)) * (1.0 - 0.6 * progress);
        }
    }

    // Near-exact residual shaping.
    if next_item_size > 0 && pr > next_item_size && pr <= next_item_size + 3 {
        score -= (18.0 - (pr - next_item_size) as f64 * 4.0) * (1.0 - 0.5 * progress);
    }

    // Open-bin budget shaping.
    if open_bins_count as f64 > (step_index as f64) * 0.35 && pr > 0 {
        let over = open_bins_count as f64 / (step_index as f64 + 1.0);
        score += (pr as f64 / cap_f) * 22.0 * over.min(1.5);
    }

    // Dead-space minimization sweep.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let mr = mean_residual.min(cap_f);
        let usable_by_next = pr >= next_item_size;
        let usable_by_mean = (pr as f64) >= mr;
        if !usable_by_next && !usable_by_mean {
            let wasted = (next_item_size - pr) as f64;
            score += (6.0 + 0.25 * wasted) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Exact-fill cascade.
    if next_item_size > 0 && item_size > 1 && pr > next_item_size {
        let pr2 = pr - next_item_size;
        if pr2 % item_size == 0 && pr2 / item_size >= 1 && pr2 != 0 {
            score -= (10.0 + 4.0 * (pr2 / item_size).min(3) as f64) * (1.0 - 0.4 * progress);
        }
    }

    // Residual-slope steering.
    if next_item_size > 0 && pr > 0 {
        let target = next_item_size as f64;
        let dev = (pr as f64 - target) / target.max(1.0);
        if dev.abs() < 0.5 {
            score -= 9.0 * (1.0 - (dev / 0.5) * (dev / 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    // Dual-fit depth probe.
    if next_item_size > 0 && pr > next_item_size && mean_residual >= 1.0 {
        let pr2 = pr - next_item_size;
        let proxy = mean_residual.min(cap_f);
        if (pr2 as f64) >= proxy {
            score -= 11.0 * (1.0 - 0.5 * progress);
            if pr2 as f64 - proxy < 6.0 {
                score -= 8.0;
            }
        }
        if (pr2 as f64) < proxy && pr2 > 0 && pr2 < 10 {
            score += 9.0 * (1.0 - pr2 as f64 / 10.0);
        }
    }

    // Capacity-fraction dead-space gate.
    if pr > 0 && progress > 0.2 && progress < 0.9 {
        let lo = cap_f * 0.38;
        let hi = cap_f * 0.5;
        if (pr as f64) > lo && (pr as f64) < hi {
            let frac = 1.0 - ((pr as f64 - lo) / (hi - lo));
            score += 8.0 * frac * frac;
        }
    }

    // Dead-space recovery probe.
    if pr > 0 && mean_residual >= 2.0 {
        let mr = mean_residual.min(cap_f * 0.6);
        let gap = pr as f64 - mr;
        if gap >= 0.0 && gap <= 5.0 {
            score += 10.0 * (1.0 - gap / 5.0) * (1.0 - 0.4 * progress);
        } else if gap > 5.0 && gap < 12.0 {
            score -= 5.0 * (1.0 - (gap - 5.0) / 7.0) * (1.0 - 0.5 * progress);
        }
    }

    // Fitting-crowd tiebreak via harmonic-mean demand matching.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let harmonic = 2.0 * (next_item_size as f64 * mean_residual)
            / (next_item_size as f64 + mean_residual).max(1.0);
        let dev = ((pr as f64 - harmonic) / harmonic.max(1.0)).abs();
        let pressure = if fitting_bins_count >= 4 { 1.0 } else { 0.4 };
        if dev < 0.3 {
            score -= 7.0 * (1.0 - dev / 0.3) * pressure * (1.0 - 0.4 * progress);
        }
    }

    // Endgame sliver sweep.
    if progress > 0.8 && pr > 0 && next_item_size > 0 && pr < next_item_size {
        let waste = 1.0 - pr as f64 / next_item_size as f64;
        score += 12.0 * waste * waste * (progress - 0.8) / 0.2;
    }

    // NEW MUTATION: dead-space ratio compaction sweep — the diagnosed
    // weakness is residual dead space. When a bin's post-residual can
    // still tile the *combined* near-future demand (next item + mean
    // residual proxy) into an exact fit, reward strongly; when the
    // leftover after absorbing that demand is an unreusable sliver,
    // penalize so space is conserved for bins that close cleanly.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.9 {
        let demand = next_item_size as f64 + mean_residual.min(cap_f * 0.5);
        let gap = pr as f64 - demand;
        if gap >= 0.0 && gap <= 6.0 {
            score -= (12.0 - gap) * 1.8 * (1.0 - 0.5 * progress);
        } else if gap > 6.0 && gap <= 14.0 && (gap as u32) < next_item_size {
            let sliver = gap as f64 / 14.0;
            score += 7.0 * sliver * (1.0 - 0.4 * progress);
        }
    }

    // NEW MUTATION: cross-bin compaction pull — when several bins fit,
    // prefer the bin whose post-residual is closest to an integer
    // multiple of the mean residual (pooled-space alignment), with a
    // sharper gate late in the stream where consolidation matters most.
    if pr > 0 && mean_residual >= 3.0 && fitting_bins_count >= 2 && progress > 0.3 {
        let mr = mean_residual;
        let k = ((pr as f64) / mr).floor().max(1.0);
        let rem = pr as f64 - k * mr;
        if rem >= 0.0 && rem <= 4.0 {
            let weight = 1.0 + (progress - 0.3);
            score -= (6.0 + 4.0 * (1.0 - rem / 4.0)) * weight.min(1.7);
        } else if rem > 4.0 && rem < mr {
            score += 4.0 * (1.0 - progress) * (rem / mr);
        }
    }

    // NEW MUTATION: tight-fit crowding bonus — when the item fills the
    // current residual almost exactly (slack <= 2), amplify the reward
    // in proportion to how scarce such tight fits are (few fitting bins
    // or low mean residual), sharpening compaction at the margin.
    if bin_residual >= item_size {
        let slack = bin_residual - item_size;
        if slack <= 2 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= (14.0 + 8.0 * (2 - slack) as f64) * scarcity * (1.0 - 0.4 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Sharpened perfect/near-perfect closure rewards.
    if pr == 0 {
        score -= 1280.0;
    } else if pr <= 4 {
        score -= 92.0 + (4 - pr) as f64 * 13.0;
    } else if pr < 12 {
        score += 30.0 - pr as f64;
    }

    // Harmonic residue classes.
    let class_bonus: f64 = if pr % 10 == 0 {
        36.0
    } else if pr % 5 == 0 {
        18.0
    } else if pr % 2 == 0 {
        5.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Lookahead: next item fit quality into post-placement residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 178.0 + 40.0 * (1.0 - progress);
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= if slack <= 10 { 66.0 - slack as f64 * 2.6 } else { 34.0 - (slack as f64).min(30.0) * 0.5 };
        } else {
            score += (next_item_size - pr) as f64 * 0.68;
        }
        if next_item_size < pr {
            let pr2 = pr - next_item_size;
            if pr2 <= 6 {
                score -= 52.0;
            } else if pr2 == next_item_size {
                score -= 27.0;
            } else if pr2 % 10 == 0 {
                score -= 12.0;
            }
            if pr2 > 6 && next_item_size > 1 && pr2 % next_item_size == 0 {
                score -= 15.0;
            }
            if pr2 >= 2 * item_size && item_size > 0 && pr2 % item_size == 0 {
                score -= 8.0;
            }
            if pr2 >= 3 * item_size.max(1) {
                score -= 6.0;
            }
            // Chain lookahead via mean-residual proxy.
            if pr2 > 0 && mean_residual > 0.0 {
                let proxy = mean_residual.round() as u32;
                if proxy >= 1 && proxy <= pr2 {
                    score -= 9.0 * (1.0 - progress);
                }
            }
            // Triple-chain closure.
            if pr2 >= 2 * next_item_size {
                let pr3 = pr2 - 2 * next_item_size;
                if pr3 <= 3 {
                    score -= 24.0 * (1.0 - progress);
                }
            }
            // next + item leaves near-perfect closure.
            if pr2 >= item_size.max(1) {
                let pr3 = pr2 - item_size.max(1);
                if pr3 <= 2 {
                    score -= 20.0 * (1.0 - progress);
                }
            }
        }
        // Pair-absorbency.
        if pr > 1 && pr == 2 * next_item_size {
            score -= 22.0;
        }
        // Stranded residual just below next item.
        if pr > 0 && pr < next_item_size {
            let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
            score += (7.0 + 5.0 * gap_frac) * (1.0 - progress);
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 66.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap_f) < 0.38;
        let reuse_is_bad = fitting_bins_count <= 1
            || (pr > 0 && next_item_size > pr && next_item_size <= bin_capacity);
        let late_large = item_size >= 60 && progress > 0.10;
        if late_large || (tight && progress > 0.15) || reuse_is_bad {
            score -= 46.0 + 30.0 * progress;
        } else {
            score += 70.0;
        }
        if item_size <= 25 && mean_residual > cap_f * 0.45 {
            score += 36.0;
        }
        if open_bins_count > 12 && progress < 0.3 {
            score += 12.0;
        }
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 24.0 + 18.0 * (1.0 - progress);
        }
        if next_item_size >= bin_capacity / 2 && mean_residual < (item_size + next_item_size) as f64 {
            score -= 10.0 + 14.0 * (1.0 - progress);
        }
        if item_size + next_item_size == bin_capacity
            && mean_residual < (item_size + next_item_size) as f64
        {
            score -= 20.0;
        }
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size {
            let strand = mean_residual as u32 - item_size;
            if strand > 0 && strand < 8 && progress > 0.2 {
                score -= 14.0 + 6.0 * (1.0 - progress);
            }
        }
        // Fresh-bin exact-pair bonus.
        if item_size + next_item_size == bin_capacity {
            score -= 34.0 + 20.0 * (1.0 - progress);
        }
        if pr > 0 && pr < item_size / 3 && item_size >= 30 {
            score -= 12.0;
        }
        // Fresh-bin viability gate.
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size && fitting_bins_count > 1 && !late_large {
            score += 30.0 * (1.0 - progress);
        }
        // Fresh-bin scarcity coupling.
        if fitting_bins_count >= 2 && item_size >= 40 {
            let best_gap = mean_residual - item_size as f64;
            if best_gap > 12.0 {
                score -= (best_gap / cap_f).min(0.25) * 80.0 * (1.0 - progress);
            }
        }
        // Fresh-bin only when the item cannot tile any open residual
        // with the next item — otherwise fresh space fragments the stream.
        if next_item_size > 0
            && fitting_bins_count >= 1
            && item_size + next_item_size <= bin_capacity
            && mean_residual >= (item_size + next_item_size) as f64
            && progress < 0.6
        {
            score += 18.0 * (1.0 - progress);
        }
        // Fresh-bin slot-arithmetic probe.
        if item_size > 0 && bin_capacity % item_size == 0 {
            let slots = bin_capacity / item_size;
            if slots >= 2 && slots <= 4 && progress > 0.1 {
                score -= 14.0 * (slots as f64).min(3.0) * (1.0 - 0.5 * progress);
            }
        }
        // Fresh-bin residual-mirror check.
        if mean_residual > item_size as f64 * 1.6 && progress > 0.3 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
        // Fresh-bin dead-space forecast.
        if next_item_size > 0
            && fitting_bins_count >= 2
            && mean_residual > 0.0
            && (item_size as f64 + next_item_size as f64 + mean_residual) <= cap_f
            && progress < 0.55
        {
            score += 14.0 * (1.0 - progress);
        }
    }

    // Best-fit bias.
    score -= (bin_capacity - bin_residual) as f64 * 0.16;

    // Flexible mid-range residual target.
    if pr >= 25 && pr <= 65 {
        score -= 14.0;
    }

    // Proliferation penalty.
    score += open_bins_count as f64 * (0.2 + 0.2 * progress);

    // Waste-avoidance for tiny residuals.
    if pr > 0 && pr < bin_capacity / 5 {
        let scarcity = if fitting_bins_count > 2 { 0.6 } else { 1.4 };
        score += (10.0 + 4.0 * progress) * scarcity;
    }

    // Tightness bonus.
    if bin_residual >= item_size {
        let tightness = 1.0 - ((bin_residual - item_size) as f64 / cap_f);
        score -= 6.0 * tightness;
    }

    // Mean-residual alignment.
    let align = ((pr as f64 - mean_residual) / cap_f).abs();
    score += align * (if progress > 0.2 && progress < 0.8 { 4.5 } else { 6.0 });

    // Odd small residuals are dead-space candidates.
    if pr > 0 && pr < 20 && pr % 2 == 1 {
        score += 7.0;
    }

    // Mid-stream consolidation of large absorbable residuals.
    if open_bins_count > 8 && progress > 0.25 && progress < 0.85 && pr >= 40 {
        score -= 9.0;
    }

    // Dead-space ratio shaping with next-item floor.
    if pr > 0 && next_item_size > 0 {
        let dead_threshold = (next_item_size + 12).min(bin_capacity);
        if pr < dead_threshold {
            let dead_frac = 1.0 - (pr as f64 / dead_threshold as f64);
            score += 18.0 * dead_frac * (1.0 - progress);
        } else if pr >= dead_threshold * 2 {
            score -= 8.0 + 4.0 * (1.0 - progress);
        } else if pr == next_item_size + item_size {
            score -= 5.0;
        }
    }

    // Endgame exactness.
    if progress > 0.9 && pr > 0 {
        score += pr as f64 * 0.35;
        if pr <= next_item_size.max(1) {
            score -= 20.0;
        }
    }

    // Fragment guard against typical upcoming demand.
    if pr > 0 && progress > 0.1 {
        let typical = (mean_residual * 0.5).max(8.0).min(cap_f * 0.5);
        if (pr as f64) < typical {
            score += 6.0 * (1.0 - (pr as f64 / typical)) * (1.0 - progress);
        }
    }

    // Exact-closure sweep with plentiful fitting bins.
    if pr == 0 && fitting_bins_count > 2 {
        score -= 12.0 * (1.0 - progress);
    }

    // Dual lookahead — repeatable fill detection.
    if next_item_size > 0 && next_item_size < pr {
        let pr2 = pr - next_item_size;
        if pr2 > 0 && item_size > 1 && pr2 % item_size == 0 && next_item_size % item_size == 0 {
            score -= 10.0;
        }
    }

    // Half-capacity residual targeting mid-stream.
    if pr > 0 && progress > 0.15 && progress < 0.9 {
        let half = cap_f * 0.5;
        let dist = ((pr as f64 - half) / half).abs();
        if dist < 0.25 {
            score -= 7.0 * (1.0 - dist / 0.25);
        }
    }

    // Dead-space ratio term with smooth quadratic ramp.
    if pr > 0 {
        let pr_f = pr as f64;
        let usable_floor = (next_item_size.max(1) as f64).min(cap_f * 0.3);
        if pr_f < usable_floor {
            let dsr = 1.0 - pr_f / usable_floor;
            score += 11.0 * dsr * dsr * (0.5 + 0.5 * (1.0 - progress));
        }
        if pr % 3 == 0 && pr >= 6 {
            score -= 5.0;
        }
        if pr % 7 == 0 && pr >= 7 {
            score -= 4.0;
        }
    }

    // Bin-count pressure valve.
    if bin_residual != bin_capacity && mean_residual > 0.0 {
        let fill = 1.0 - mean_residual / cap_f;
        if fill > 0.75 && fitting_bins_count > 1 {
            score -= 6.0 * (fill - 0.75) / 0.25;
        } else if fill < 0.5 && fitting_bins_count > 1 {
            score += 4.0 * (0.5 - fill) / 0.5 * (1.0 - progress);
        }
    }

    // Dead-space waste accounting with quadratic ramp.
    if pr > 0 && next_item_size > 0 && next_item_size < bin_capacity {
        let waste_frac = 1.0 - (pr.min(next_item_size) as f64 / pr as f64);
        if waste_frac > 0.5 {
            score += 9.0 * (waste_frac - 0.5) * 2.0 * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Consolidation incentive matching mean residual.
    if progress > 0.35 && pr >= next_item_size.max(1) && mean_residual > 0.0 {
        let dev = ((pr as f64 - mean_residual) / cap_f).abs();
        if dev < 0.08 {
            score -= 6.0 * (1.0 - dev / 0.08);
        }
    }

    // Quad-chain lookahead.
    if next_item_size > 0 && pr >= 3 * next_item_size {
        let pr3 = pr - 3 * next_item_size;
        if pr3 <= 4 {
            score -= 18.0 * (1.0 - progress);
        }
    }

    // Item+next exact pair inside residual.
    if next_item_size > 0 && item_size > 0 && pr == item_size + next_item_size {
        score -= 26.0;
    }

    // Late-stream fresh-bin restraint.
    if bin_residual == bin_capacity && progress > 0.7 {
        let exact_pair = item_size + next_item_size == bin_capacity;
        if !exact_pair && fitting_bins_count > 0 {
            score += 22.0 * (progress - 0.7) / 0.3;
        }
    }

    // Large-item protection.
    if item_size > 50 && pr > 0 && pr < 15 {
        score += 10.0 * (1.0 - pr as f64 / 15.0);
    }

    // Residual-divisibility absorbency.
    if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 {
        let chain_len = pr / next_item_size;
        if chain_len >= 2 {
            score -= (8.0 + 6.0 * chain_len.min(4) as f64) * (1.0 - 0.5 * progress);
        }
    }

    // Dead-space variance dampener.
    if pr > 0 && next_item_size > 0 && pr < next_item_size && open_bins_count > 3 {
        let unusable = (next_item_size - pr) as f64 / next_item_size as f64;
        score += 14.0 * unusable * unusable * (1.0 - progress);
    }

    // Mid-stream sweep for residuals matching common item-size sums.
    if pr > 0 && progress > 0.2 && progress < 0.9 {
        let small_sum = item_size.min(next_item_size.max(1));
        if pr == 2 * small_sum || pr == small_sum + 10 || pr == small_sum + 25 {
            score -= 7.0;
        }
    }

    // Endgame fresh-bin suppression.
    if bin_residual == bin_capacity && progress > 0.85 {
        let biggest_resid = mean_residual.max(0.0);
        if item_size as f64 <= biggest_resid.max(1.0) && fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Residual pooling.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.2 && progress < 0.85 {
        let mr = mean_residual;
        let k = (pr as f64 / mr).round().max(1.0);
        let dev = (pr as f64 - k * mr).abs() / mr;
        if dev < 0.15 && k >= 1.0 {
            score -= 10.0 * (1.0 - dev / 0.15) * (1.0 - 0.4 * progress);
        }
    }

    // Two-item lookahead tiling.
    if pr > 0 && next_item_size > 0 && mean_residual > 1.0 {
        let combo = next_item_size as f64 + mean_residual.min(cap_f * 0.4);
        let gap = pr as f64 - combo;
        if gap >= 0.0 && gap <= 5.0 {
            score -= (16.0 - gap) * 2.4 * (1.0 - 0.5 * progress);
        }
    }

    // Strand-risk shaping.
    if pr >= 13 && pr <= 24 {
        let crowd = if open_bins_count > 10 { 1.5 } else { 0.7 };
        score += 6.0 * crowd * (1.0 - 0.5 * progress);
    }

    // Dead-space floor tightening.
    if pr > 0 && next_item_size > 0 {
        let floor = next_item_size.max(1) as f64;
        if (pr as f64) < floor {
            let x = pr as f64 / floor;
            score += (10.0 + 14.0 * (1.0 - x) * (1.0 - x)) * (1.0 - 0.6 * progress);
        }
    }

    // Near-exact residual shaping.
    if next_item_size > 0 && pr > next_item_size && pr <= next_item_size + 3 {
        score -= (18.0 - (pr - next_item_size) as f64 * 4.0) * (1.0 - 0.5 * progress);
    }

    // Open-bin budget shaping.
    if open_bins_count as f64 > (step_index as f64) * 0.35 && pr > 0 {
        let over = open_bins_count as f64 / (step_index as f64 + 1.0);
        score += (pr as f64 / cap_f) * 22.0 * over.min(1.5);
    }

    // Dead-space minimization sweep.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let mr = mean_residual.min(cap_f);
        let usable_by_next = pr >= next_item_size;
        let usable_by_mean = (pr as f64) >= mr;
        if !usable_by_next && !usable_by_mean {
            let wasted = (next_item_size - pr) as f64;
            score += (6.0 + 0.25 * wasted) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Exact-fill cascade.
    if next_item_size > 0 && item_size > 1 && pr > next_item_size {
        let pr2 = pr - next_item_size;
        if pr2 % item_size == 0 && pr2 / item_size >= 1 && pr2 != 0 {
            score -= (10.0 + 4.0 * (pr2 / item_size).min(3) as f64) * (1.0 - 0.4 * progress);
        }
    }

    // Residual-slope steering.
    if next_item_size > 0 && pr > 0 {
        let target = next_item_size as f64;
        let dev = (pr as f64 - target) / target.max(1.0);
        if dev.abs() < 0.5 {
            score -= 9.0 * (1.0 - (dev / 0.5) * (dev / 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    // Dual-fit depth probe.
    if next_item_size > 0 && pr > next_item_size && mean_residual >= 1.0 {
        let pr2 = pr - next_item_size;
        let proxy = mean_residual.min(cap_f);
        if (pr2 as f64) >= proxy {
            score -= 11.0 * (1.0 - 0.5 * progress);
            if pr2 as f64 - proxy < 6.0 {
                score -= 8.0;
            }
        }
        if (pr2 as f64) < proxy && pr2 > 0 && pr2 < 10 {
            score += 9.0 * (1.0 - pr2 as f64 / 10.0);
        }
    }

    // Capacity-fraction dead-space gate.
    if pr > 0 && progress > 0.2 && progress < 0.9 {
        let lo = cap_f * 0.38;
        let hi = cap_f * 0.5;
        if (pr as f64) > lo && (pr as f64) < hi {
            let frac = 1.0 - ((pr as f64 - lo) / (hi - lo));
            score += 8.0 * frac * frac;
        }
    }

    // Dead-space recovery probe.
    if pr > 0 && mean_residual >= 2.0 {
        let mr = mean_residual.min(cap_f * 0.6);
        let gap = pr as f64 - mr;
        if gap >= 0.0 && gap <= 5.0 {
            score += 10.0 * (1.0 - gap / 5.0) * (1.0 - 0.4 * progress);
        } else if gap > 5.0 && gap < 12.0 {
            score -= 5.0 * (1.0 - (gap - 5.0) / 7.0) * (1.0 - 0.5 * progress);
        }
    }

    // Fitting-crowd tiebreak via harmonic-mean demand matching.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let harmonic = 2.0 * (next_item_size as f64 * mean_residual)
            / (next_item_size as f64 + mean_residual).max(1.0);
        let dev = ((pr as f64 - harmonic) / harmonic.max(1.0)).abs();
        let pressure = if fitting_bins_count >= 4 { 1.0 } else { 0.4 };
        if dev < 0.3 {
            score -= 7.0 * (1.0 - dev / 0.3) * pressure * (1.0 - 0.4 * progress);
        }
    }

    // Endgame sliver sweep.
    if progress > 0.8 && pr > 0 && next_item_size > 0 && pr < next_item_size {
        let waste = 1.0 - pr as f64 / next_item_size as f64;
        score += 12.0 * waste * waste * (progress - 0.8) / 0.2;
    }

    // Dead-space ratio compaction sweep.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.9 {
        let demand = next_item_size as f64 + mean_residual.min(cap_f * 0.5);
        let gap = pr as f64 - demand;
        if gap >= 0.0 && gap <= 6.0 {
            score -= (12.0 - gap) * 1.8 * (1.0 - 0.5 * progress);
        } else if gap > 6.0 && gap <= 14.0 && (gap as u32) < next_item_size {
            let sliver = gap as f64 / 14.0;
            score += 7.0 * sliver * (1.0 - 0.4 * progress);
        }
    }

    // Cross-bin compaction pull.
    if pr > 0 && mean_residual >= 3.0 && fitting_bins_count >= 2 && progress > 0.3 {
        let mr = mean_residual;
        let k = ((pr as f64) / mr).floor().max(1.0);
        let rem = pr as f64 - k * mr;
        if rem >= 0.0 && rem <= 4.0 {
            let weight = 1.0 + (progress - 0.3);
            score -= (6.0 + 4.0 * (1.0 - rem / 4.0)) * weight.min(1.7);
        } else if rem > 4.0 && rem < mr {
            score += 4.0 * (1.0 - progress) * (rem / mr);
        }
    }

    // Tight-fit crowding bonus.
    if bin_residual >= item_size {
        let slack = bin_residual - item_size;
        if slack <= 2 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= (14.0 + 8.0 * (2 - slack) as f64) * scarcity * (1.0 - 0.4 * progress);
        }
    }

    // NEW MUTATION: perfect-closure pair forecast — when the item plus the
    // next item lands within a small slack of the current residual, reward
    // proportionally to slack tightness, with an extra late-stream push so
    // near-exact two-item closures win over leaving dead space.
    if next_item_size > 0 && pr > 0 {
        let combo = item_size as f64 + next_item_size as f64;
        if combo <= pr as f64 {
            let slack2 = pr as f64 - combo;
            if slack2 <= 3.0 {
                score -= (20.0 - 5.0 * slack2) * (1.0 - 0.3 * progress);
            }
        }
    }

    // NEW MUTATION: dead-space slope dampener — when the residual after
    // this placement is small but nonzero and cannot host the next item,
    // penalize more sharply as bins proliferate, steering fills toward
    // bins that can still absorb upcoming demand.
    if pr > 0 && next_item_size > 0 && pr < next_item_size && open_bins_count > 6 {
        let unusable = (next_item_size - pr) as f64;
        score += (2.0 + 0.35 * unusable) * (0.5 + 0.5 * progress);
    }

    // NEW MUTATION: mean-residual exact-tiling sweep — when the post-residual
    // is an exact integer multiple of the mean residual (>= 2 tiles), reward
    // strongly mid/late stream; this pools leftover space into reusable
    // chunks and directly attacks the residual dead-space weakness.
    if pr >= 2 && mean_residual >= 2.0 && progress > 0.15 {
        let mr = mean_residual;
        let ratio = pr as f64 / mr;
        let k = ratio.round();
        if k >= 2.0 && (ratio - k).abs() < 0.02 {
            score -= (10.0 + 3.0 * k.min(5.0)) * (1.0 - 0.3 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Sharpened perfect/near-perfect closure rewards.
    if pr == 0 {
        score -= 1280.0;
    } else if pr <= 4 {
        score -= 92.0 + (4 - pr) as f64 * 13.0;
    } else if pr < 12 {
        score += 30.0 - pr as f64;
    }

    // Harmonic residue classes.
    let class_bonus: f64 = if pr % 10 == 0 {
        36.0
    } else if pr % 5 == 0 {
        18.0
    } else if pr % 2 == 0 {
        5.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Lookahead: next item fit quality into post-placement residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 178.0 + 40.0 * (1.0 - progress);
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= if slack <= 10 { 66.0 - slack as f64 * 2.6 } else { 34.0 - (slack as f64).min(30.0) * 0.5 };
        } else {
            score += (next_item_size - pr) as f64 * 0.68;
        }
        if next_item_size < pr {
            let pr2 = pr - next_item_size;
            if pr2 <= 6 {
                score -= 52.0;
            } else if pr2 == next_item_size {
                score -= 27.0;
            } else if pr2 % 10 == 0 {
                score -= 12.0;
            }
            if pr2 > 6 && next_item_size > 1 && pr2 % next_item_size == 0 {
                score -= 15.0;
            }
            if pr2 >= 2 * item_size && item_size > 0 && pr2 % item_size == 0 {
                score -= 8.0;
            }
            if pr2 >= 3 * item_size.max(1) {
                score -= 6.0;
            }
            // Chain lookahead via mean-residual proxy.
            if pr2 > 0 && mean_residual > 0.0 {
                let proxy = mean_residual.round() as u32;
                if proxy >= 1 && proxy <= pr2 {
                    score -= 9.0 * (1.0 - progress);
                }
            }
            // Triple-chain closure.
            if pr2 >= 2 * next_item_size {
                let pr3 = pr2 - 2 * next_item_size;
                if pr3 <= 3 {
                    score -= 24.0 * (1.0 - progress);
                }
            }
            // next + item leaves near-perfect closure.
            if pr2 >= item_size.max(1) {
                let pr3 = pr2 - item_size.max(1);
                if pr3 <= 2 {
                    score -= 20.0 * (1.0 - progress);
                }
            }
        }
        // Pair-absorbency.
        if pr > 1 && pr == 2 * next_item_size {
            score -= 22.0;
        }
        // Stranded residual just below next item.
        if pr > 0 && pr < next_item_size {
            let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
            score += (7.0 + 5.0 * gap_frac) * (1.0 - progress);
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 66.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap_f) < 0.38;
        let reuse_is_bad = fitting_bins_count <= 1
            || (pr > 0 && next_item_size > pr && next_item_size <= bin_capacity);
        let late_large = item_size >= 60 && progress > 0.10;
        if late_large || (tight && progress > 0.15) || reuse_is_bad {
            score -= 46.0 + 30.0 * progress;
        } else {
            score += 70.0;
        }
        if item_size <= 25 && mean_residual > cap_f * 0.45 {
            score += 36.0;
        }
        if open_bins_count > 12 && progress < 0.3 {
            score += 12.0;
        }
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 24.0 + 18.0 * (1.0 - progress);
        }
        if next_item_size >= bin_capacity / 2 && mean_residual < (item_size + next_item_size) as f64 {
            score -= 10.0 + 14.0 * (1.0 - progress);
        }
        if item_size + next_item_size == bin_capacity
            && mean_residual < (item_size + next_item_size) as f64
        {
            score -= 20.0;
        }
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size {
            let strand = mean_residual as u32 - item_size;
            if strand > 0 && strand < 8 && progress > 0.2 {
                score -= 14.0 + 6.0 * (1.0 - progress);
            }
        }
        // Fresh-bin exact-pair bonus.
        if item_size + next_item_size == bin_capacity {
            score -= 34.0 + 20.0 * (1.0 - progress);
        }
        if pr > 0 && pr < item_size / 3 && item_size >= 30 {
            score -= 12.0;
        }
        // Fresh-bin viability gate.
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size && fitting_bins_count > 1 && !late_large {
            score += 30.0 * (1.0 - progress);
        }
        // Fresh-bin scarcity coupling.
        if fitting_bins_count >= 2 && item_size >= 40 {
            let best_gap = mean_residual - item_size as f64;
            if best_gap > 12.0 {
                score -= (best_gap / cap_f).min(0.25) * 80.0 * (1.0 - progress);
            }
        }
        // Fresh-bin only when the item cannot tile any open residual
        // with the next item — otherwise fresh space fragments the stream.
        if next_item_size > 0
            && fitting_bins_count >= 1
            && item_size + next_item_size <= bin_capacity
            && mean_residual >= (item_size + next_item_size) as f64
            && progress < 0.6
        {
            score += 18.0 * (1.0 - progress);
        }
        // Fresh-bin slot-arithmetic probe.
        if item_size > 0 && bin_capacity % item_size == 0 {
            let slots = bin_capacity / item_size;
            if slots >= 2 && slots <= 4 && progress > 0.1 {
                score -= 14.0 * (slots as f64).min(3.0) * (1.0 - 0.5 * progress);
            }
        }
        // Fresh-bin residual-mirror check.
        if mean_residual > item_size as f64 * 1.6 && progress > 0.3 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
        // Fresh-bin dead-space forecast.
        if next_item_size > 0
            && fitting_bins_count >= 2
            && mean_residual > 0.0
            && (item_size as f64 + next_item_size as f64 + mean_residual) <= cap_f
            && progress < 0.55
        {
            score += 14.0 * (1.0 - progress);
        }
        // NEW MUTATION: fresh-bin exact-tiling gate — open a fresh bin only
        // when the item tiles the capacity nearly exactly (capacity is an
        // integer multiple of the item, or item + next fills it), which
        // guarantees zero dead space in the new bin; otherwise restrain.
        if item_size > 0 && next_item_size > 0 {
            let tiles_exactly = bin_capacity % item_size == 0
                && (bin_capacity / item_size) >= 2
                && (bin_capacity / item_size) <= 6;
            let pair_fills = item_size + next_item_size == bin_capacity;
            if tiles_exactly || pair_fills {
                score -= 20.0 * (1.0 - progress);
            } else if item_size > bin_capacity / 3 && fitting_bins_count > 1 {
                score += 10.0 * (1.0 - progress);
            }
        }
    }

    // Best-fit bias.
    score -= (bin_capacity - bin_residual) as f64 * 0.16;

    // Flexible mid-range residual target.
    if pr >= 25 && pr <= 65 {
        score -= 14.0;
    }

    // Proliferation penalty.
    score += open_bins_count as f64 * (0.2 + 0.2 * progress);

    // Waste-avoidance for tiny residuals.
    if pr > 0 && pr < bin_capacity / 5 {
        let scarcity = if fitting_bins_count > 2 { 0.6 } else { 1.4 };
        score += (10.0 + 4.0 * progress) * scarcity;
    }

    // Tightness bonus.
    if bin_residual >= item_size {
        let tightness = 1.0 - ((bin_residual - item_size) as f64 / cap_f);
        score -= 6.0 * tightness;
    }

    // Mean-residual alignment.
    let align = ((pr as f64 - mean_residual) / cap_f).abs();
    score += align * (if progress > 0.2 && progress < 0.8 { 4.5 } else { 6.0 });

    // Odd small residuals are dead-space candidates.
    if pr > 0 && pr < 20 && pr % 2 == 1 {
        score += 7.0;
    }

    // Mid-stream consolidation of large absorbable residuals.
    if open_bins_count > 8 && progress > 0.25 && progress < 0.85 && pr >= 40 {
        score -= 9.0;
    }

    // Dead-space ratio shaping with next-item floor.
    if pr > 0 && next_item_size > 0 {
        let dead_threshold = (next_item_size + 12).min(bin_capacity);
        if pr < dead_threshold {
            let dead_frac = 1.0 - (pr as f64 / dead_threshold as f64);
            score += 18.0 * dead_frac * (1.0 - progress);
        } else if pr >= dead_threshold * 2 {
            score -= 8.0 + 4.0 * (1.0 - progress);
        } else if pr == next_item_size + item_size {
            score -= 5.0;
        }
    }

    // Endgame exactness.
    if progress > 0.9 && pr > 0 {
        score += pr as f64 * 0.35;
        if pr <= next_item_size.max(1) {
            score -= 20.0;
        }
    }

    // Fragment guard against typical upcoming demand.
    if pr > 0 && progress > 0.1 {
        let typical = (mean_residual * 0.5).max(8.0).min(cap_f * 0.5);
        if (pr as f64) < typical {
            score += 6.0 * (1.0 - (pr as f64 / typical)) * (1.0 - progress);
        }
    }

    // Exact-closure sweep with plentiful fitting bins.
    if pr == 0 && fitting_bins_count > 2 {
        score -= 12.0 * (1.0 - progress);
    }

    // Dual lookahead — repeatable fill detection.
    if next_item_size > 0 && next_item_size < pr {
        let pr2 = pr - next_item_size;
        if pr2 > 0 && item_size > 1 && pr2 % item_size == 0 && next_item_size % item_size == 0 {
            score -= 10.0;
        }
    }

    // Half-capacity residual targeting mid-stream.
    if pr > 0 && progress > 0.15 && progress < 0.9 {
        let half = cap_f * 0.5;
        let dist = ((pr as f64 - half) / half).abs();
        if dist < 0.25 {
            score -= 7.0 * (1.0 - dist / 0.25);
        }
    }

    // Dead-space ratio term with smooth quadratic ramp.
    if pr > 0 {
        let pr_f = pr as f64;
        let usable_floor = (next_item_size.max(1) as f64).min(cap_f * 0.3);
        if pr_f < usable_floor {
            let dsr = 1.0 - pr_f / usable_floor;
            score += 11.0 * dsr * dsr * (0.5 + 0.5 * (1.0 - progress));
        }
        if pr % 3 == 0 && pr >= 6 {
            score -= 5.0;
        }
        if pr % 7 == 0 && pr >= 7 {
            score -= 4.0;
        }
    }

    // Bin-count pressure valve.
    if bin_residual != bin_capacity && mean_residual > 0.0 {
        let fill = 1.0 - mean_residual / cap_f;
        if fill > 0.75 && fitting_bins_count > 1 {
            score -= 6.0 * (fill - 0.75) / 0.25;
        } else if fill < 0.5 && fitting_bins_count > 1 {
            score += 4.0 * (0.5 - fill) / 0.5 * (1.0 - progress);
        }
    }

    // Dead-space waste accounting with quadratic ramp.
    if pr > 0 && next_item_size > 0 && next_item_size < bin_capacity {
        let waste_frac = 1.0 - (pr.min(next_item_size) as f64 / pr as f64);
        if waste_frac > 0.5 {
            score += 9.0 * (waste_frac - 0.5) * 2.0 * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Consolidation incentive matching mean residual.
    if progress > 0.35 && pr >= next_item_size.max(1) && mean_residual > 0.0 {
        let dev = ((pr as f64 - mean_residual) / cap_f).abs();
        if dev < 0.08 {
            score -= 6.0 * (1.0 - dev / 0.08);
        }
    }

    // Quad-chain lookahead.
    if next_item_size > 0 && pr >= 3 * next_item_size {
        let pr3 = pr - 3 * next_item_size;
        if pr3 <= 4 {
            score -= 18.0 * (1.0 - progress);
        }
    }

    // Item+next exact pair inside residual.
    if next_item_size > 0 && item_size > 0 && pr == item_size + next_item_size {
        score -= 26.0;
    }

    // Late-stream fresh-bin restraint.
    if bin_residual == bin_capacity && progress > 0.7 {
        let exact_pair = item_size + next_item_size == bin_capacity;
        if !exact_pair && fitting_bins_count > 0 {
            score += 22.0 * (progress - 0.7) / 0.3;
        }
    }

    // Large-item protection.
    if item_size > 50 && pr > 0 && pr < 15 {
        score += 10.0 * (1.0 - pr as f64 / 15.0);
    }

    // Residual-divisibility absorbency.
    if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 {
        let chain_len = pr / next_item_size;
        if chain_len >= 2 {
            score -= (8.0 + 6.0 * chain_len.min(4) as f64) * (1.0 - 0.5 * progress);
        }
    }

    // Dead-space variance dampener.
    if pr > 0 && next_item_size > 0 && pr < next_item_size && open_bins_count > 3 {
        let unusable = (next_item_size - pr) as f64 / next_item_size as f64;
        score += 14.0 * unusable * unusable * (1.0 - progress);
    }

    // Mid-stream sweep for residuals matching common item-size sums.
    if pr > 0 && progress > 0.2 && progress < 0.9 {
        let small_sum = item_size.min(next_item_size.max(1));
        if pr == 2 * small_sum || pr == small_sum + 10 || pr == small_sum + 25 {
            score -= 7.0;
        }
    }

    // Endgame fresh-bin suppression.
    if bin_residual == bin_capacity && progress > 0.85 {
        let biggest_resid = mean_residual.max(0.0);
        if item_size as f64 <= biggest_resid.max(1.0) && fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Residual pooling.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.2 && progress < 0.85 {
        let mr = mean_residual;
        let k = (pr as f64 / mr).round().max(1.0);
        let dev = (pr as f64 - k * mr).abs() / mr;
        if dev < 0.15 && k >= 1.0 {
            score -= 10.0 * (1.0 - dev / 0.15) * (1.0 - 0.4 * progress);
        }
    }

    // Two-item lookahead tiling.
    if pr > 0 && next_item_size > 0 && mean_residual > 1.0 {
        let combo = next_item_size as f64 + mean_residual.min(cap_f * 0.4);
        let gap = pr as f64 - combo;
        if gap >= 0.0 && gap <= 5.0 {
            score -= (16.0 - gap) * 2.4 * (1.0 - 0.5 * progress);
        }
    }

    // Strand-risk shaping.
    if pr >= 13 && pr <= 24 {
        let crowd = if open_bins_count > 10 { 1.5 } else { 0.7 };
        score += 6.0 * crowd * (1.0 - 0.5 * progress);
    }

    // Dead-space floor tightening.
    if pr > 0 && next_item_size > 0 {
        let floor = next_item_size.max(1) as f64;
        if (pr as f64) < floor {
            let x = pr as f64 / floor;
            score += (10.0 + 14.0 * (1.0 - x) * (1.0 - x)) * (1.0 - 0.6 * progress);
        }
    }

    // Near-exact residual shaping.
    if next_item_size > 0 && pr > next_item_size && pr <= next_item_size + 3 {
        score -= (18.0 - (pr - next_item_size) as f64 * 4.0) * (1.0 - 0.5 * progress);
    }

    // Open-bin budget shaping.
    if open_bins_count as f64 > (step_index as f64) * 0.35 && pr > 0 {
        let over = open_bins_count as f64 / (step_index as f64 + 1.0);
        score += (pr as f64 / cap_f) * 22.0 * over.min(1.5);
    }

    // Dead-space minimization sweep.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let mr = mean_residual.min(cap_f);
        let usable_by_next = pr >= next_item_size;
        let usable_by_mean = (pr as f64) >= mr;
        if !usable_by_next && !usable_by_mean {
            let wasted = (next_item_size - pr) as f64;
            score += (6.0 + 0.25 * wasted) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Exact-fill cascade.
    if next_item_size > 0 && item_size > 1 && pr > next_item_size {
        let pr2 = pr - next_item_size;
        if pr2 % item_size == 0 && pr2 / item_size >= 1 && pr2 != 0 {
            score -= (10.0 + 4.0 * (pr2 / item_size).min(3) as f64) * (1.0 - 0.4 * progress);
        }
    }

    // Residual-slope steering.
    if next_item_size > 0 && pr > 0 {
        let target = next_item_size as f64;
        let dev = (pr as f64 - target) / target.max(1.0);
        if dev.abs() < 0.5 {
            score -= 9.0 * (1.0 - (dev / 0.5) * (dev / 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    // Dual-fit depth probe.
    if next_item_size > 0 && pr > next_item_size && mean_residual >= 1.0 {
        let pr2 = pr - next_item_size;
        let proxy = mean_residual.min(cap_f);
        if (pr2 as f64) >= proxy {
            score -= 11.0 * (1.0 - 0.5 * progress);
            if pr2 as f64 - proxy < 6.0 {
                score -= 8.0;
            }
        }
        if (pr2 as f64) < proxy && pr2 > 0 && pr2 < 10 {
            score += 9.0 * (1.0 - pr2 as f64 / 10.0);
        }
    }

    // Capacity-fraction dead-space gate.
    if pr > 0 && progress > 0.2 && progress < 0.9 {
        let lo = cap_f * 0.38;
        let hi = cap_f * 0.5;
        if (pr as f64) > lo && (pr as f64) < hi {
            let frac = 1.0 - ((pr as f64 - lo) / (hi - lo));
            score += 8.0 * frac * frac;
        }
    }

    // Dead-space recovery probe.
    if pr > 0 && mean_residual >= 2.0 {
        let mr = mean_residual.min(cap_f * 0.6);
        let gap = pr as f64 - mr;
        if gap >= 0.0 && gap <= 5.0 {
            score += 10.0 * (1.0 - gap / 5.0) * (1.0 - 0.4 * progress);
        } else if gap > 5.0 && gap < 12.0 {
            score -= 5.0 * (1.0 - (gap - 5.0) / 7.0) * (1.0 - 0.5 * progress);
        }
    }

    // Fitting-crowd tiebreak via harmonic-mean demand matching.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let harmonic = 2.0 * (next_item_size as f64 * mean_residual)
            / (next_item_size as f64 + mean_residual).max(1.0);
        let dev = ((pr as f64 - harmonic) / harmonic.max(1.0)).abs();
        let pressure = if fitting_bins_count >= 4 { 1.0 } else { 0.4 };
        if dev < 0.3 {
            score -= 7.0 * (1.0 - dev / 0.3) * pressure * (1.0 - 0.4 * progress);
        }
    }

    // Endgame sliver sweep.
    if progress > 0.8 && pr > 0 && next_item_size > 0 && pr < next_item_size {
        let waste = 1.0 - pr as f64 / next_item_size as f64;
        score += 12.0 * waste * waste * (progress - 0.8) / 0.2;
    }

    // Dead-space ratio compaction sweep.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.9 {
        let demand = next_item_size as f64 + mean_residual.min(cap_f * 0.5);
        let gap = pr as f64 - demand;
        if gap >= 0.0 && gap <= 6.0 {
            score -= (12.0 - gap) * 1.8 * (1.0 - 0.5 * progress);
        } else if gap > 6.0 && gap <= 14.0 && (gap as u32) < next_item_size {
            let sliver = gap as f64 / 14.0;
            score += 7.0 * sliver * (1.0 - 0.4 * progress);
        }
    }

    // Cross-bin compaction pull.
    if pr > 0 && mean_residual >= 3.0 && fitting_bins_count >= 2 && progress > 0.3 {
        let mr = mean_residual;
        let k = ((pr as f64) / mr).floor().max(1.0);
        let rem = pr as f64 - k * mr;
        if rem >= 0.0 && rem <= 4.0 {
            let weight = 1.0 + (progress - 0.3);
            score -= (6.0 + 4.0 * (1.0 - rem / 4.0)) * weight.min(1.7);
        } else if rem > 4.0 && rem < mr {
            score += 4.0 * (1.0 - progress) * (rem / mr);
        }
    }

    // Tight-fit crowding bonus.
    if bin_residual >= item_size {
        let slack = bin_residual - item_size;
        if slack <= 2 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= (14.0 + 8.0 * (2 - slack) as f64) * scarcity * (1.0 - 0.4 * progress);
        }
    }

    // NEW MUTATION: dead-space conservation sweep — when the post-residual
    // cannot absorb the next item but is close to the mean residual, keep
    // the bin alive as a pooled target rather than fragmenting; when the
    // post-residual exceeds the next item by a small odd sliver that no
    // plausible demand can tile, penalize so tighter bins win instead.
    if pr > 0 && next_item_size > 0 && progress > 0.15 && progress < 0.95 {
        let pr_f = pr as f64;
        let nxt = next_item_size as f64;
        if pr_f < nxt && (nxt - pr_f) <= mean_residual.max(1.0) {
            score -= 8.0 * (1.0 - (nxt - pr_f) / nxt.max(1.0)) * (1.0 - 0.5 * progress);
        }
        let over = pr_f - nxt;
        if over > 0.0 && over < 9.0 && over as u32 % 2 == 1 && over < mean_residual {
            score += 6.0 * (1.0 - over / 9.0) * (1.0 - 0.4 * progress);
        }
    }

    // NEW MUTATION: multi-item tiling reward — when the post-residual can
    // hold the next item plus an integer count of the current item with
    // zero or near-zero leftover, reward strongly; this biases selection
    // toward bins that close exactly after two more placements.
    if pr > 0 && next_item_size > 0 && item_size > 0 && pr >= next_item_size + item_size {
        let pr2 = pr - next_item_size;
        let rem = pr2 % item_size;
        if rem == 0 {
            let count = pr2 / item_size;
            if count >= 1 && count <= 5 {
                score -= (10.0 + 5.0 * count.min(3) as f64) * (1.0 - 0.4 * progress);
            }
        } else if rem <= 2 {
            score -= 7.0 * (1.0 - 0.4 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Sharpened perfect/near-perfect closure rewards.
    if pr == 0 {
        score -= 1280.0;
    } else if pr <= 4 {
        score -= 92.0 + (4 - pr) as f64 * 13.0;
    } else if pr < 12 {
        score += 30.0 - pr as f64;
    }

    // Harmonic residue classes.
    let class_bonus: f64 = if pr % 10 == 0 {
        36.0
    } else if pr % 5 == 0 {
        18.0
    } else if pr % 2 == 0 {
        5.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Lookahead: next item fit quality into post-placement residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 178.0 + 40.0 * (1.0 - progress);
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= if slack <= 10 { 66.0 - slack as f64 * 2.6 } else { 34.0 - (slack as f64).min(30.0) * 0.5 };
        } else {
            score += (next_item_size - pr) as f64 * 0.68;
        }
        if next_item_size < pr {
            let pr2 = pr - next_item_size;
            if pr2 <= 6 {
                score -= 52.0;
            } else if pr2 == next_item_size {
                score -= 27.0;
            } else if pr2 % 10 == 0 {
                score -= 12.0;
            }
            if pr2 > 6 && next_item_size > 1 && pr2 % next_item_size == 0 {
                score -= 15.0;
            }
            if pr2 >= 2 * item_size && item_size > 0 && pr2 % item_size == 0 {
                score -= 8.0;
            }
            if pr2 >= 3 * item_size.max(1) {
                score -= 6.0;
            }
            // Chain lookahead via mean-residual proxy.
            if pr2 > 0 && mean_residual > 0.0 {
                let proxy = mean_residual.round() as u32;
                if proxy >= 1 && proxy <= pr2 {
                    score -= 9.0 * (1.0 - progress);
                }
            }
            // Triple-chain closure.
            if pr2 >= 2 * next_item_size {
                let pr3 = pr2 - 2 * next_item_size;
                if pr3 <= 3 {
                    score -= 24.0 * (1.0 - progress);
                }
            }
            // next + item leaves near-perfect closure.
            if pr2 >= item_size.max(1) {
                let pr3 = pr2 - item_size.max(1);
                if pr3 <= 2 {
                    score -= 20.0 * (1.0 - progress);
                }
            }
        }
        // Pair-absorbency.
        if pr > 1 && pr == 2 * next_item_size {
            score -= 22.0;
        }
        // Stranded residual just below next item.
        if pr > 0 && pr < next_item_size {
            let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
            score += (7.0 + 5.0 * gap_frac) * (1.0 - progress);
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 66.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap_f) < 0.38;
        let reuse_is_bad = fitting_bins_count <= 1
            || (pr > 0 && next_item_size > pr && next_item_size <= bin_capacity);
        let late_large = item_size >= 60 && progress > 0.10;
        if late_large || (tight && progress > 0.15) || reuse_is_bad {
            score -= 46.0 + 30.0 * progress;
        } else {
            score += 70.0;
        }
        if item_size <= 25 && mean_residual > cap_f * 0.45 {
            score += 36.0;
        }
        if open_bins_count > 12 && progress < 0.3 {
            score += 12.0;
        }
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 24.0 + 18.0 * (1.0 - progress);
        }
        if next_item_size >= bin_capacity / 2 && mean_residual < (item_size + next_item_size) as f64 {
            score -= 10.0 + 14.0 * (1.0 - progress);
        }
        if item_size + next_item_size == bin_capacity
            && mean_residual < (item_size + next_item_size) as f64
        {
            score -= 20.0;
        }
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size {
            let strand = mean_residual as u32 - item_size;
            if strand > 0 && strand < 8 && progress > 0.2 {
                score -= 14.0 + 6.0 * (1.0 - progress);
            }
        }
        // Fresh-bin exact-pair bonus.
        if item_size + next_item_size == bin_capacity {
            score -= 34.0 + 20.0 * (1.0 - progress);
        }
        if pr > 0 && pr < item_size / 3 && item_size >= 30 {
            score -= 12.0;
        }
        // Fresh-bin viability gate.
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size && fitting_bins_count > 1 && !late_large {
            score += 30.0 * (1.0 - progress);
        }
        // Fresh-bin scarcity coupling.
        if fitting_bins_count >= 2 && item_size >= 40 {
            let best_gap = mean_residual - item_size as f64;
            if best_gap > 12.0 {
                score -= (best_gap / cap_f).min(0.25) * 80.0 * (1.0 - progress);
            }
        }
        // Fresh-bin only when the item cannot tile any open residual
        // with the next item — otherwise fresh space fragments the stream.
        if next_item_size > 0
            && fitting_bins_count >= 1
            && item_size + next_item_size <= bin_capacity
            && mean_residual >= (item_size + next_item_size) as f64
            && progress < 0.6
        {
            score += 18.0 * (1.0 - progress);
        }
        // Fresh-bin slot-arithmetic probe.
        if item_size > 0 && bin_capacity % item_size == 0 {
            let slots = bin_capacity / item_size;
            if slots >= 2 && slots <= 4 && progress > 0.1 {
                score -= 14.0 * (slots as f64).min(3.0) * (1.0 - 0.5 * progress);
            }
        }
        // Fresh-bin residual-mirror check.
        if mean_residual > item_size as f64 * 1.6 && progress > 0.3 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
        // Fresh-bin dead-space forecast.
        if next_item_size > 0
            && fitting_bins_count >= 2
            && mean_residual > 0.0
            && (item_size as f64 + next_item_size as f64 + mean_residual) <= cap_f
            && progress < 0.55
        {
            score += 14.0 * (1.0 - progress);
        }
        // NEW MUTATION: fresh-bin residual-orbit check — opening a fresh
        // bin is justified only if the item's size leaves a post-residual
        // that is a poor target for the stream's typical demand. If the
        // fresh bin's post-residual (capacity - item) sits within the
        // dense demand band around the mean residual, the fresh bin will
        // absorb future items cleanly and should be preferred; otherwise
        // it will strand dead space and should be avoided.
        if mean_residual >= 2.0 {
            let fresh_pr = cap_f - item_size as f64;
            if fresh_pr > 0.0 {
                let orbit = ((fresh_pr - mean_residual) / mean_residual).abs();
                if orbit < 0.35 && fitting_bins_count >= 2 {
                    score += 10.0 + 12.0 * (1.0 - orbit / 0.35);
                } else if fresh_pr < next_item_size as f64 && next_item_size > 0 {
                    score += 9.0 * (1.0 - progress);
                }
            }
        }
    }

    // Best-fit bias.
    score -= (bin_capacity - bin_residual) as f64 * 0.16;

    // Flexible mid-range residual target.
    if pr >= 25 && pr <= 65 {
        score -= 14.0;
    }

    // Proliferation penalty.
    score += open_bins_count as f64 * (0.2 + 0.2 * progress);

    // Waste-avoidance for tiny residuals.
    if pr > 0 && pr < bin_capacity / 5 {
        let scarcity = if fitting_bins_count > 2 { 0.6 } else { 1.4 };
        score += (10.0 + 4.0 * progress) * scarcity;
    }

    // Tightness bonus.
    if bin_residual >= item_size {
        let tightness = 1.0 - ((bin_residual - item_size) as f64 / cap_f);
        score -= 6.0 * tightness;
    }

    // Mean-residual alignment.
    let align = ((pr as f64 - mean_residual) / cap_f).abs();
    score += align * (if progress > 0.2 && progress < 0.8 { 4.5 } else { 6.0 });

    // Odd small residuals are dead-space candidates.
    if pr > 0 && pr < 20 && pr % 2 == 1 {
        score += 7.0;
    }

    // Mid-stream consolidation of large absorbable residuals.
    if open_bins_count > 8 && progress > 0.25 && progress < 0.85 && pr >= 40 {
        score -= 9.0;
    }

    // Dead-space ratio shaping with next-item floor.
    if pr > 0 && next_item_size > 0 {
        let dead_threshold = (next_item_size + 12).min(bin_capacity);
        if pr < dead_threshold {
            let dead_frac = 1.0 - (pr as f64 / dead_threshold as f64);
            score += 18.0 * dead_frac * (1.0 - progress);
        } else if pr >= dead_threshold * 2 {
            score -= 8.0 + 4.0 * (1.0 - progress);
        } else if pr == next_item_size + item_size {
            score -= 5.0;
        }
    }

    // Endgame exactness.
    if progress > 0.9 && pr > 0 {
        score += pr as f64 * 0.35;
        if pr <= next_item_size.max(1) {
            score -= 20.0;
        }
    }

    // Fragment guard against typical upcoming demand.
    if pr > 0 && progress > 0.1 {
        let typical = (mean_residual * 0.5).max(8.0).min(cap_f * 0.5);
        if (pr as f64) < typical {
            score += 6.0 * (1.0 - (pr as f64 / typical)) * (1.0 - progress);
        }
    }

    // Exact-closure sweep with plentiful fitting bins.
    if pr == 0 && fitting_bins_count > 2 {
        score -= 12.0 * (1.0 - progress);
    }

    // Dual lookahead — repeatable fill detection.
    if next_item_size > 0 && next_item_size < pr {
        let pr2 = pr - next_item_size;
        if pr2 > 0 && item_size > 1 && pr2 % item_size == 0 && next_item_size % item_size == 0 {
            score -= 10.0;
        }
    }

    // Half-capacity residual targeting mid-stream.
    if pr > 0 && progress > 0.15 && progress < 0.9 {
        let half = cap_f * 0.5;
        let dist = ((pr as f64 - half) / half).abs();
        if dist < 0.25 {
            score -= 7.0 * (1.0 - dist / 0.25);
        }
    }

    // Dead-space ratio term with smooth quadratic ramp.
    if pr > 0 {
        let pr_f = pr as f64;
        let usable_floor = (next_item_size.max(1) as f64).min(cap_f * 0.3);
        if pr_f < usable_floor {
            let dsr = 1.0 - pr_f / usable_floor;
            score += 11.0 * dsr * dsr * (0.5 + 0.5 * (1.0 - progress));
        }
        if pr % 3 == 0 && pr >= 6 {
            score -= 5.0;
        }
        if pr % 7 == 0 && pr >= 7 {
            score -= 4.0;
        }
    }

    // Bin-count pressure valve.
    if bin_residual != bin_capacity && mean_residual > 0.0 {
        let fill = 1.0 - mean_residual / cap_f;
        if fill > 0.75 && fitting_bins_count > 1 {
            score -= 6.0 * (fill - 0.75) / 0.25;
        } else if fill < 0.5 && fitting_bins_count > 1 {
            score += 4.0 * (0.5 - fill) / 0.5 * (1.0 - progress);
        }
    }

    // Dead-space waste accounting with quadratic ramp.
    if pr > 0 && next_item_size > 0 && next_item_size < bin_capacity {
        let waste_frac = 1.0 - (pr.min(next_item_size) as f64 / pr as f64);
        if waste_frac > 0.5 {
            score += 9.0 * (waste_frac - 0.5) * 2.0 * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Consolidation incentive matching mean residual.
    if progress > 0.35 && pr >= next_item_size.max(1) && mean_residual > 0.0 {
        let dev = ((pr as f64 - mean_residual) / cap_f).abs();
        if dev < 0.08 {
            score -= 6.0 * (1.0 - dev / 0.08);
        }
    }

    // Quad-chain lookahead.
    if next_item_size > 0 && pr >= 3 * next_item_size {
        let pr3 = pr - 3 * next_item_size;
        if pr3 <= 4 {
            score -= 18.0 * (1.0 - progress);
        }
    }

    // Item+next exact pair inside residual.
    if next_item_size > 0 && item_size > 0 && pr == item_size + next_item_size {
        score -= 26.0;
    }

    // Late-stream fresh-bin restraint.
    if bin_residual == bin_capacity && progress > 0.7 {
        let exact_pair = item_size + next_item_size == bin_capacity;
        if !exact_pair && fitting_bins_count > 0 {
            score += 22.0 * (progress - 0.7) / 0.3;
        }
    }

    // Large-item protection.
    if item_size > 50 && pr > 0 && pr < 15 {
        score += 10.0 * (1.0 - pr as f64 / 15.0);
    }

    // Residual-divisibility absorbency.
    if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 {
        let chain_len = pr / next_item_size;
        if chain_len >= 2 {
            score -= (8.0 + 6.0 * chain_len.min(4) as f64) * (1.0 - 0.5 * progress);
        }
    }

    // Dead-space variance dampener.
    if pr > 0 && next_item_size > 0 && pr < next_item_size && open_bins_count > 3 {
        let unusable = (next_item_size - pr) as f64 / next_item_size as f64;
        score += 14.0 * unusable * unusable * (1.0 - progress);
    }

    // Mid-stream sweep for residuals matching common item-size sums.
    if pr > 0 && progress > 0.2 && progress < 0.9 {
        let small_sum = item_size.min(next_item_size.max(1));
        if pr == 2 * small_sum || pr == small_sum + 10 || pr == small_sum + 25 {
            score -= 7.0;
        }
    }

    // Endgame fresh-bin suppression.
    if bin_residual == bin_capacity && progress > 0.85 {
        let biggest_resid = mean_residual.max(0.0);
        if item_size as f64 <= biggest_resid.max(1.0) && fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Residual pooling.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.2 && progress < 0.85 {
        let mr = mean_residual;
        let k = (pr as f64 / mr).round().max(1.0);
        let dev = (pr as f64 - k * mr).abs() / mr;
        if dev < 0.15 && k >= 1.0 {
            score -= 10.0 * (1.0 - dev / 0.15) * (1.0 - 0.4 * progress);
        }
    }

    // Two-item lookahead tiling.
    if pr > 0 && next_item_size > 0 && mean_residual > 1.0 {
        let combo = next_item_size as f64 + mean_residual.min(cap_f * 0.4);
        let gap = pr as f64 - combo;
        if gap >= 0.0 && gap <= 5.0 {
            score -= (16.0 - gap) * 2.4 * (1.0 - 0.5 * progress);
        }
    }

    // Strand-risk shaping.
    if pr >= 13 && pr <= 24 {
        let crowd = if open_bins_count > 10 { 1.5 } else { 0.7 };
        score += 6.0 * crowd * (1.0 - 0.5 * progress);
    }

    // Dead-space floor tightening.
    if pr > 0 && next_item_size > 0 {
        let floor = next_item_size.max(1) as f64;
        if (pr as f64) < floor {
            let x = pr as f64 / floor;
            score += (10.0 + 14.0 * (1.0 - x) * (1.0 - x)) * (1.0 - 0.6 * progress);
        }
    }

    // Near-exact residual shaping.
    if next_item_size > 0 && pr > next_item_size && pr <= next_item_size + 3 {
        score -= (18.0 - (pr - next_item_size) as f64 * 4.0) * (1.0 - 0.5 * progress);
    }

    // Open-bin budget shaping.
    if open_bins_count as f64 > (step_index as f64) * 0.35 && pr > 0 {
        let over = open_bins_count as f64 / (step_index as f64 + 1.0);
        score += (pr as f64 / cap_f) * 22.0 * over.min(1.5);
    }

    // Dead-space minimization sweep.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let mr = mean_residual.min(cap_f);
        let usable_by_next = pr >= next_item_size;
        let usable_by_mean = (pr as f64) >= mr;
        if !usable_by_next && !usable_by_mean {
            let wasted = (next_item_size - pr) as f64;
            score += (6.0 + 0.25 * wasted) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Exact-fill cascade.
    if next_item_size > 0 && item_size > 1 && pr > next_item_size {
        let pr2 = pr - next_item_size;
        if pr2 % item_size == 0 && pr2 / item_size >= 1 && pr2 != 0 {
            score -= (10.0 + 4.0 * (pr2 / item_size).min(3) as f64) * (1.0 - 0.4 * progress);
        }
    }

    // Residual-slope steering.
    if next_item_size > 0 && pr > 0 {
        let target = next_item_size as f64;
        let dev = (pr as f64 - target) / target.max(1.0);
        if dev.abs() < 0.5 {
            score -= 9.0 * (1.0 - (dev / 0.5) * (dev / 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    // Dual-fit depth probe.
    if next_item_size > 0 && pr > next_item_size && mean_residual >= 1.0 {
        let pr2 = pr - next_item_size;
        let proxy = mean_residual.min(cap_f);
        if (pr2 as f64) >= proxy {
            score -= 11.0 * (1.0 - 0.5 * progress);
            if pr2 as f64 - proxy < 6.0 {
                score -= 8.0;
            }
        }
        if (pr2 as f64) < proxy && pr2 > 0 && pr2 < 10 {
            score += 9.0 * (1.0 - pr2 as f64 / 10.0);
        }
    }

    // Capacity-fraction dead-space gate.
    if pr > 0 && progress > 0.2 && progress < 0.9 {
        let lo = cap_f * 0.38;
        let hi = cap_f * 0.5;
        if (pr as f64) > lo && (pr as f64) < hi {
            let frac = 1.0 - ((pr as f64 - lo) / (hi - lo));
            score += 8.0 * frac * frac;
        }
    }

    // Dead-space recovery probe.
    if pr > 0 && mean_residual >= 2.0 {
        let mr = mean_residual.min(cap_f * 0.6);
        let gap = pr as f64 - mr;
        if gap >= 0.0 && gap <= 5.0 {
            score += 10.0 * (1.0 - gap / 5.0) * (1.0 - 0.4 * progress);
        } else if gap > 5.0 && gap < 12.0 {
            score -= 5.0 * (1.0 - (gap - 5.0) / 7.0) * (1.0 - 0.5 * progress);
        }
    }

    // Fitting-crowd tiebreak via harmonic-mean demand matching.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let harmonic = 2.0 * (next_item_size as f64 * mean_residual)
            / (next_item_size as f64 + mean_residual).max(1.0);
        let dev = ((pr as f64 - harmonic) / harmonic.max(1.0)).abs();
        let pressure = if fitting_bins_count >= 4 { 1.0 } else { 0.4 };
        if dev < 0.3 {
            score -= 7.0 * (1.0 - dev / 0.3) * pressure * (1.0 - 0.4 * progress);
        }
    }

    // Endgame sliver sweep.
    if progress > 0.8 && pr > 0 && next_item_size > 0 && pr < next_item_size {
        let waste = 1.0 - pr as f64 / next_item_size as f64;
        score += 12.0 * waste * waste * (progress - 0.8) / 0.2;
    }

    // Dead-space ratio compaction sweep.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.9 {
        let demand = next_item_size as f64 + mean_residual.min(cap_f * 0.5);
        let gap = pr as f64 - demand;
        if gap >= 0.0 && gap <= 6.0 {
            score -= (12.0 - gap) * 1.8 * (1.0 - 0.5 * progress);
        } else if gap > 6.0 && gap <= 14.0 && (gap as u32) < next_item_size {
            let sliver = gap as f64 / 14.0;
            score += 7.0 * sliver * (1.0 - 0.4 * progress);
        }
    }

    // Cross-bin compaction pull.
    if pr > 0 && mean_residual >= 3.0 && fitting_bins_count >= 2 && progress > 0.3 {
        let mr = mean_residual;
        let k = ((pr as f64) / mr).floor().max(1.0);
        let rem = pr as f64 - k * mr;
        if rem >= 0.0 && rem <= 4.0 {
            let weight = 1.0 + (progress - 0.3);
            score -= (6.0 + 4.0 * (1.0 - rem / 4.0)) * weight.min(1.7);
        } else if rem > 4.0 && rem < mr {
            score += 4.0 * (1.0 - progress) * (rem / mr);
        }
    }

    // Tight-fit crowding bonus.
    if bin_residual >= item_size {
        let slack = bin_residual - item_size;
        if slack <= 2 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= (14.0 + 8.0 * (2 - slack) as f64) * scarcity * (1.0 - 0.4 * progress);
        }
    }

    // NEW MUTATION: dead-space budget ledger — track the total dead space
    // this placement would strand relative to the stream's typical demand.
    // The post-residual is "live" if it can still host the next item OR
    // the mean-residual proxy; anything strictly between the two demand
    // levels is a fragmentation trap. Penalize proportionally to how much
    // of the residual is unusable, with an early-stream bias so bad
    // placement habits are corrected before they accumulate. Conversely,
    // a residual that tiles BOTH demands exactly (pr == next + proxy)
    // represents a fully committed bin and earns a strong closure bonus.
    if pr > 0 && next_item_size > 0 && mean_residual > 1.0 {
        let pr_f = pr as f64;
        let next_f = next_item_size as f64;
        let proxy = mean_residual.min(cap_f * 0.6);
        let lo_demand = next_f.min(proxy);
        let hi_demand = next_f.max(proxy);
        if pr_f < lo_demand {
            let dead = 1.0 - pr_f / lo_demand;
            score += 8.0 * dead * dead * (0.5 + 0.5 * (1.0 - progress));
        } else if pr_f > hi_demand {
            let usable = hi_demand / pr_f;
            if usable < 0.85 {
                score += 5.0 * (0.85 - usable) * (1.0 - 0.3 * progress);
            }
        }
        // Exact double-commitment closure.
        if (pr_f - (next_f + proxy)).abs() <= 1.0 {
            score -= 15.0 * (1.0 - 0.4 * progress);
        }
    }

    // NEW MUTATION: inter-bin residual ladder — when multiple bins fit,
    // prefer the bin whose post-residual keeps the global residual
    // distribution tight (low variance proxy). A post-residual far above
    // the mean residual creates a straggler bin that future items cannot
    // close; a post-residual slightly below the mean keeps the fleet
    // uniform and closable. Scale the pull by how many bins compete so
    // uniformity matters most when alternatives exist.
    if pr > 0 && fitting_bins_count >= 2 && mean_residual >= 1.0 {
        let spread = (pr as f64 - mean_residual).abs();
        let norm = spread / cap_f;
        if norm > 0.12 {
            score += 4.0 * norm.min(0.4) * (0.4 + 0.6 * fitting_bins_count.min(6) as f64 / 6.0);
        } else {
            score -= 3.0 * (1.0 - norm / 0.12) * (1.0 - 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Sharpened closure rewards.
    if pr == 0 {
        score -= 1250.0;
    } else if pr <= 4 {
        score -= 85.0 + (4 - pr) as f64 * 12.0;
    } else if pr < 12 {
        score += 26.0 - pr as f64;
    }

    // Harmonic residue classes.
    let class_bonus: f64 = if pr % 10 == 0 {
        34.0
    } else if pr % 5 == 0 {
        17.0
    } else if pr % 2 == 0 {
        5.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Lookahead: next item fit quality into post-placement residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 160.0 + 35.0 * (1.0 - progress);
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= if slack <= 10 { 60.0 - slack as f64 * 2.6 } else { 32.0 - (slack as f64).min(30.0) * 0.5 };
        } else {
            score += (next_item_size - pr) as f64 * 0.62;
        }
        if next_item_size < pr {
            let pr2 = pr - next_item_size;
            if pr2 <= 6 {
                score -= 46.0;
            } else if pr2 == next_item_size {
                score -= 24.0;
            } else if pr2 % 10 == 0 {
                score -= 11.0;
            }
            if pr2 > 6 && next_item_size > 1 && pr2 % next_item_size == 0 {
                score -= 14.0;
            }
            if pr2 >= 2 * item_size && item_size > 0 && pr2 % item_size == 0 {
                score -= 8.0;
            }
            // Chain lookahead via mean-residual proxy.
            if pr2 > 0 && mean_residual > 0.0 {
                let proxy = mean_residual.round() as u32;
                if proxy >= 1 && proxy <= pr2 {
                    score -= 9.0 * (1.0 - progress);
                }
            }
            // Triple-chain closure.
            if pr2 >= 2 * next_item_size {
                let pr3 = pr2 - 2 * next_item_size;
                if pr3 <= 3 {
                    score -= 22.0 * (1.0 - progress);
                }
            }
            // next + item leaves near-perfect closure.
            if pr2 >= item_size.max(1) {
                let pr3 = pr2 - item_size.max(1);
                if pr3 <= 2 {
                    score -= 18.0 * (1.0 - progress);
                }
            }
        }
        // Pair-absorbency.
        if pr > 1 && pr == 2 * next_item_size {
            score -= 20.0;
        }
        // Stranded residual just below next item.
        if pr > 0 && pr < next_item_size {
            let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
            score += (7.0 + 5.0 * gap_frac) * (1.0 - progress);
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 58.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap_f) < 0.38;
        let reuse_is_bad = fitting_bins_count <= 1
            || (pr > 0 && next_item_size > pr && next_item_size <= bin_capacity);
        let late_large = item_size >= 60 && progress > 0.10;
        if late_large || (tight && progress > 0.15) || reuse_is_bad {
            score -= 44.0 + 28.0 * progress;
        } else {
            score += 66.0;
        }
        if item_size <= 25 && mean_residual > cap_f * 0.45 {
            score += 32.0;
        }
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 22.0 + 16.0 * (1.0 - progress);
        }
        // Fresh-bin exact-pair bonus.
        if item_size + next_item_size == bin_capacity {
            score -= 32.0 + 18.0 * (1.0 - progress);
        }
        // Fresh-bin viability gate.
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size && fitting_bins_count > 1 && !late_large {
            score += 28.0 * (1.0 - progress);
        }
        // Fresh-bin scarcity coupling.
        if fitting_bins_count >= 2 && item_size >= 40 {
            let best_gap = mean_residual - item_size as f64;
            if best_gap > 12.0 {
                score -= (best_gap / cap_f).min(0.25) * 75.0 * (1.0 - progress);
            }
        }
        // Fresh-bin slot-arithmetic probe.
        if item_size > 0 && bin_capacity % item_size == 0 {
            let slots = bin_capacity / item_size;
            if slots >= 2 && slots <= 4 && progress > 0.1 {
                score -= 12.0 * (slots as f64).min(3.0) * (1.0 - 0.5 * progress);
            }
        }
        // Fresh-bin demand-forecast gate: keep fresh bins when combined
        // near-future demand cannot exhaust open residuals.
        if next_item_size > 0
            && fitting_bins_count >= 2
            && mean_residual > 0.0
            && (item_size as f64 + next_item_size as f64 + mean_residual) <= cap_f
            && progress < 0.55
        {
            score += 13.0 * (1.0 - progress);
        }
    }

    // Best-fit bias.
    score -= (bin_capacity - bin_residual) as f64 * 0.14;

    // Flexible mid-range residual target.
    if pr >= 25 && pr <= 65 {
        score -= 13.0;
    }

    // Proliferation penalty.
    score += open_bins_count as f64 * (0.2 + 0.2 * progress);

    // Waste-avoidance for tiny residuals.
    if pr > 0 && pr < bin_capacity / 5 {
        let scarcity = if fitting_bins_count > 2 { 0.6 } else { 1.4 };
        score += (10.0 + 4.0 * progress) * scarcity;
    }

    // Tightness bonus.
    if bin_residual >= item_size {
        let tightness = 1.0 - ((bin_residual - item_size) as f64 / cap_f);
        score -= 6.0 * tightness;
    }

    // Mean-residual alignment.
    let align = ((pr as f64 - mean_residual) / cap_f).abs();
    score += align * (if progress > 0.2 && progress < 0.8 { 4.5 } else { 6.0 });

    // Odd small residuals are dead-space candidates.
    if pr > 0 && pr < 20 && pr % 2 == 1 {
        score += 7.0;
    }

    // Dead-space ratio shaping with next-item floor.
    if pr > 0 && next_item_size > 0 {
        let dead_threshold = (next_item_size + 12).min(bin_capacity);
        if pr < dead_threshold {
            let dead_frac = 1.0 - (pr as f64 / dead_threshold as f64);
            score += 17.0 * dead_frac * (1.0 - progress);
        } else if pr >= dead_threshold * 2 {
            score -= 8.0 + 4.0 * (1.0 - progress);
        }
    }

    // Endgame exactness.
    if progress > 0.9 && pr > 0 {
        score += pr as f64 * 0.35;
        if pr <= next_item_size.max(1) {
            score -= 20.0;
        }
    }

    // Fragment guard against typical upcoming demand.
    if pr > 0 && progress > 0.1 {
        let typical = (mean_residual * 0.5).max(8.0).min(cap_f * 0.5);
        if (pr as f64) < typical {
            score += 6.0 * (1.0 - (pr as f64 / typical)) * (1.0 - progress);
        }
    }

    // Residual-divisibility absorbency.
    if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 {
        let chain_len = pr / next_item_size;
        if chain_len >= 2 {
            score -= (8.0 + 6.0 * chain_len.min(4) as f64) * (1.0 - 0.5 * progress);
        }
    }

    // Dead-space variance dampener.
    if pr > 0 && next_item_size > 0 && pr < next_item_size && open_bins_count > 3 {
        let unusable = (next_item_size - pr) as f64 / next_item_size as f64;
        score += 13.0 * unusable * unusable * (1.0 - progress);
    }

    // Residual pooling toward mean-residual multiples.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.2 && progress < 0.85 {
        let mr = mean_residual;
        let k = (pr as f64 / mr).round().max(1.0);
        let dev = (pr as f64 - k * mr).abs() / mr;
        if dev < 0.15 {
            score -= 10.0 * (1.0 - dev / 0.15) * (1.0 - 0.4 * progress);
        }
    }

    // Two-item lookahead tiling with mean-residual proxy.
    if pr > 0 && next_item_size > 0 && mean_residual > 1.0 {
        let combo = next_item_size as f64 + mean_residual.min(cap_f * 0.4);
        let gap = pr as f64 - combo;
        if gap >= 0.0 && gap <= 5.0 {
            score -= (16.0 - gap) * 2.2 * (1.0 - 0.5 * progress);
        }
    }

    // Dead-space floor tightening.
    if pr > 0 && next_item_size > 0 {
        let floor = next_item_size.max(1) as f64;
        if (pr as f64) < floor {
            let x = pr as f64 / floor;
            score += (10.0 + 14.0 * (1.0 - x) * (1.0 - x)) * (1.0 - 0.6 * progress);
        }
    }

    // Near-exact residual shaping.
    if next_item_size > 0 && pr > next_item_size && pr <= next_item_size + 3 {
        score -= (18.0 - (pr - next_item_size) as f64 * 4.0) * (1.0 - 0.5 * progress);
    }

    // Exact-fill cascade.
    if next_item_size > 0 && item_size > 1 && pr > next_item_size {
        let pr2 = pr - next_item_size;
        if pr2 % item_size == 0 {
            score -= (10.0 + 4.0 * (pr2 / item_size).min(3) as f64) * (1.0 - 0.4 * progress);
        }
    }

    // Dual-fit depth probe against mean residual.
    if next_item_size > 0 && pr > next_item_size && mean_residual >= 1.0 {
        let pr2 = pr - next_item_size;
        let proxy = mean_residual.min(cap_f);
        if (pr2 as f64) >= proxy {
            score -= 11.0 * (1.0 - 0.5 * progress);
            if pr2 as f64 - proxy < 6.0 {
                score -= 8.0;
            }
        }
    }

    // Tight-fit crowding bonus with scarcity weighting.
    if bin_residual >= item_size {
        let slack = bin_residual - item_size;
        if slack <= 2 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= (14.0 + 8.0 * (2 - slack) as f64) * scarcity * (1.0 - 0.4 * progress);
        }
    }

    // Dead-space minimization sweep.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let mr = mean_residual.min(cap_f);
        let usable_by_next = pr >= next_item_size;
        let usable_by_mean = (pr as f64) >= mr;
        if !usable_by_next && !usable_by_mean {
            let wasted = (next_item_size - pr) as f64;
            score += (6.0 + 0.25 * wasted) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Endgame fresh-bin suppression.
    if bin_residual == bin_capacity && progress > 0.85 {
        if item_size as f64 <= mean_residual.max(1.0) && fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Late-stream fresh-bin restraint.
    if bin_residual == bin_capacity && progress > 0.7 {
        let exact_pair = item_size + next_item_size == bin_capacity;
        if !exact_pair && fitting_bins_count > 0 {
            score += 20.0 * (progress - 0.7) / 0.3;
        }
    }

    // Large-item protection.
    if item_size > 50 && pr > 0 && pr < 15 {
        score += 10.0 * (1.0 - pr as f64 / 15.0);
    }

    // Dead-space ratio compaction sweep on combined demand.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.9 {
        let demand = next_item_size as f64 + mean_residual.min(cap_f * 0.5);
        let gap = pr as f64 - demand;
        if gap >= 0.0 && gap <= 6.0 {
            score -= (12.0 - gap) * 1.8 * (1.0 - 0.5 * progress);
        } else if gap > 6.0 && gap <= 14.0 && (gap as u32) < next_item_size {
            score += 7.0 * (gap / 14.0) * (1.0 - 0.4 * progress);
        }
    }

    // Cross-bin compaction pull toward mean-residual multiples.
    if pr > 0 && mean_residual >= 3.0 && fitting_bins_count >= 2 && progress > 0.3 {
        let mr = mean_residual;
        let k = ((pr as f64) / mr).floor().max(1.0);
        let rem = pr as f64 - k * mr;
        if rem >= 0.0 && rem <= 4.0 {
            let weight = 1.0 + (progress - 0.3);
            score -= (6.0 + 4.0 * (1.0 - rem / 4.0)) * weight.min(1.7);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap_f = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Strong reward for perfect and near-perfect closure (sharpened).
    if pr == 0 {
        score -= 1280.0;
    } else if pr <= 4 {
        score -= 92.0 + (4 - pr) as f64 * 13.0;
    } else if pr < 12 {
        score += 30.0 - pr as f64;
    }

    // Harmonic residue classes.
    let class_bonus: f64 = if pr % 10 == 0 {
        36.0
    } else if pr % 5 == 0 {
        18.0
    } else if pr % 2 == 0 {
        5.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Lookahead: next item fit quality into the post-placement residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 178.0 + 40.0 * (1.0 - progress);
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= if slack <= 10 { 66.0 - slack as f64 * 2.6 } else { 34.0 - (slack as f64).min(30.0) * 0.5 };
        } else {
            score += (next_item_size - pr) as f64 * 0.68;
        }
        // Two-step lookahead.
        if next_item_size < pr {
            let pr2 = pr - next_item_size;
            if pr2 <= 6 {
                score -= 52.0;
            } else if pr2 == next_item_size {
                score -= 27.0;
            } else if pr2 % 10 == 0 {
                score -= 12.0;
            }
            if pr2 > 6 && next_item_size > 1 && pr2 % next_item_size == 0 {
                score -= 15.0;
            }
            // Triple-chain closure.
            if pr2 >= 2 * next_item_size {
                let pr3 = pr2 - 2 * next_item_size;
                if pr3 <= 3 {
                    score -= 24.0 * (1.0 - progress);
                }
            }
            // next + item leaves near-perfect closure.
            if pr2 >= item_size.max(1) {
                let pr3 = pr2 - item_size.max(1);
                if pr3 <= 2 {
                    score -= 20.0 * (1.0 - progress);
                }
            }
            // Chain lookahead via mean-residual proxy.
            if pr2 > 0 && mean_residual > 0.0 {
                let proxy = mean_residual.round() as u32;
                if proxy >= 1 && proxy <= pr2 {
                    score -= 9.0 * (1.0 - progress);
                }
            }
        }
        // Pair-absorbency.
        if pr > 1 && pr == 2 * next_item_size {
            score -= 22.0;
        }
        // Stranded residual just below next item.
        if pr > 0 && pr < next_item_size {
            let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
            score += (7.0 + 5.0 * gap_frac) * (1.0 - progress);
        }
        // Item+next exact pair inside residual.
        if item_size > 0 && pr == item_size + next_item_size {
            score -= 26.0;
        }
        // Residual-divisibility absorbency.
        if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 {
            let chain_len = pr / next_item_size;
            if chain_len >= 2 {
                score -= (8.0 + 6.0 * chain_len.min(4) as f64) * (1.0 - 0.5 * progress);
            }
        }
        // Near-exact residual shaping.
        if pr > next_item_size && pr <= next_item_size + 3 {
            score -= (18.0 - (pr - next_item_size) as f64 * 4.0) * (1.0 - 0.5 * progress);
        }
    }

    // Last-chance bin: sole fitting bin strongly preferred.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 66.0;
    }

    // Tight-fit crowding bonus at the margin.
    if bin_residual >= item_size {
        let slack = bin_residual - item_size;
        if slack <= 2 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= (14.0 + 8.0 * (2 - slack) as f64) * scarcity * (1.0 - 0.4 * progress);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap_f) < 0.38;
        let reuse_is_bad = fitting_bins_count <= 1
            || (pr > 0 && next_item_size > pr && next_item_size <= bin_capacity);
        let late_large = item_size >= 60 && progress > 0.10;
        if late_large || (tight && progress > 0.15) || reuse_is_bad {
            score -= 46.0 + 30.0 * progress;
        } else {
            score += 70.0;
        }
        if item_size <= 25 && mean_residual > cap_f * 0.45 {
            score += 36.0;
        }
        if open_bins_count > 12 && progress < 0.3 {
            score += 12.0;
        }
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 24.0 + 18.0 * (1.0 - progress);
        }
        if next_item_size >= bin_capacity / 2 && mean_residual < (item_size + next_item_size) as f64 {
            score -= 10.0 + 14.0 * (1.0 - progress);
        }
        // Fresh-bin exact-pair bonus.
        if item_size + next_item_size == bin_capacity {
            score -= 34.0 + 20.0 * (1.0 - progress);
        }
        // Fresh-bin viability gate.
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size && fitting_bins_count > 1 && !late_large {
            score += 30.0 * (1.0 - progress);
        }
        // Fresh-bin scarcity coupling for large items.
        if fitting_bins_count >= 2 && item_size >= 40 {
            let best_gap = mean_residual - item_size as f64;
            if best_gap > 12.0 {
                score -= (best_gap / cap_f).min(0.25) * 80.0 * (1.0 - progress);
            }
        }
        // Fresh-bin slot-arithmetic probe.
        if item_size > 0 && bin_capacity % item_size == 0 {
            let slots = bin_capacity / item_size;
            if slots >= 2 && slots <= 4 && progress > 0.1 {
                score -= 14.0 * (slots as f64).min(3.0) * (1.0 - 0.5 * progress);
            }
        }
        // Fresh-bin only when item+next cannot tile open residuals.
        if next_item_size > 0
            && fitting_bins_count >= 1
            && item_size + next_item_size <= bin_capacity
            && mean_residual >= (item_size + next_item_size) as f64
            && progress < 0.6
        {
            score += 18.0 * (1.0 - progress);
        }
        // Late-stream fresh-bin suppression.
        if progress > 0.85 && item_size as f64 <= mean_residual.max(1.0) && fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Best-fit bias.
    score -= (bin_capacity - bin_residual) as f64 * 0.16;

    // Flexible mid-range residual target.
    if pr >= 25 && pr <= 65 {
        score -= 14.0;
    }

    // Proliferation penalty.
    score += open_bins_count as f64 * (0.2 + 0.2 * progress);

    // Waste-avoidance for tiny residuals.
    if pr > 0 && pr < bin_capacity / 5 {
        let scarcity = if fitting_bins_count > 2 { 0.6 } else { 1.4 };
        score += (10.0 + 4.0 * progress) * scarcity;
    }

    // Tightness bonus.
    if bin_residual >= item_size {
        let tightness = 1.0 - ((bin_residual - item_size) as f64 / cap_f);
        score -= 6.0 * tightness;
    }

    // Mean-residual alignment.
    let align = ((pr as f64 - mean_residual) / cap_f).abs();
    score += align * (if progress > 0.2 && progress < 0.8 { 4.5 } else { 6.0 });

    // Odd small residuals are dead-space candidates.
    if pr > 0 && pr < 20 && pr % 2 == 1 {
        score += 7.0;
    }

    // Mid-stream consolidation of large absorbable residuals.
    if open_bins_count > 8 && progress > 0.25 && progress < 0.85 && pr >= 40 {
        score -= 9.0;
    }

    // Dead-space ratio shaping with next-item floor.
    if pr > 0 && next_item_size > 0 {
        let dead_threshold = (next_item_size + 12).min(bin_capacity);
