    if bin_residual == bin_capacity && mean_residual > 0.0 {
        let mr = mean_residual.min(cap);
        let demand = item_size as f64 + next_item_size as f64;
        if mr >= demand * 1.15 && progress > 0.2 && progress < 0.85 && fitting_bins_count >= 2 {
            score += 20.0 * (1.0 - 0.5 * progress);
        } else if mr < demand * 0.55 && fitting_bins_count <= 3 {
            score -= 18.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 28): residual variance-aware consolidation — when the
    // chosen residual sits close to a multiple of the mean residual, the
    // bin pool stays homogeneous and future items tile predictably; reward
    // that homogeneity more strongly in the crowded mid-stream.
    if pr > 0 && mean_residual >= 3.0 && progress > 0.25 && progress < 0.9 {
        let mr = mean_residual;
        let k = ((pr as f64) / mr).round().max(1.0);
        let dev = ((pr as f64) - k * mr).abs();
        if dev <= 2.0 {
            score -= (9.0 - 2.0 * dev) * (1.0 - 0.3 * progress);
        }
    }

    // MUTATION (gen 28): dead-space gradient sharpening — extend the gen-27
    // quadratic ramp with a hard spike when the residual is within 2 units
    // of being usable, the most common near-miss waste band.
    if pr > 0 && next_item_size > 0 && pr < next_item_size && next_item_size - pr <= 2 {
        score += 10.0 * (1.0 - 0.4 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Sharpened perfect/near-perfect closure rewards.
    if pr == 0 {
        score -= 1280.0;
    } else if pr <= 4 {
        score -= 92.0 + (4 - pr) as f64 * 13.0;
