    }

    // MUTATION (gen 28): mid-stream slack quantization — pull residuals
    // toward exact multiples of the mean-residual proxy to reduce variance.
    if pr > 0 && mean_residual >= 3.0 && progress > 0.15 && progress < 0.9 {
        let mr = mean_residual.min(cap);
        let diff = (pr as f64 - mr).abs();
        if diff <= 2.0 {
            score -= 8.0 * (1.0 - diff / 3.0) * (1.0 - 0.3 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
