        } else if leftover < next_item_size as f64 * 0.55 {
            score += 12.0 * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION (gen 31): residual ladder rung-matching — residuals that
    // equal sums of 2 or 3 copies of the next item (minus a tiny epsilon
