        let pr2 = pr - 2 * next_item_size;
        if pr2 == 0 {
            score -= 20.0 + 14.0 * (1.0 - progress);
        } else if pr2 <= 2 {
            score += 6.0 * (1.0 - pr2 as f64 / 3.0);
        }
    }

    // Gen 28: fresh-bin mean-residual saturation gate.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && mean_residual > 0.0
        && (mean_residual as u32) < next_item_size
        && fitting_bins_count >= 1
        && progress > 0.1
        && progress < 0.85
    {
        let deficit = 1.0 - mean_residual / next_item_size as f64;
        score -= 18.0 * deficit * deficit * (1.0 - progress);
    }

    // Gen 28: mid-stream slack-quantization shaping.
    if pr > 0 && mean_residual >= 3.0 && progress > 0.15 && progress < 0.9 {
        let mr = mean_residual.min(cap);
        let diff = (pr as f64 - mr).abs();
        if diff <= 2.0 {
            score -= 8.0 * (1.0 - diff / 3.0) * (1.0 - 0.3 * progress);
        } else if diff > mr * 0.5 && diff < mr * 0.5 + 3.0 {
            score += 4.0 * (1.0 - progress);
        }
    }

    // Gen 29: dead-space gradient refinement — two-step demand horizon
    // (next + mean) so residuals stranding BOTH items get a sharper
    // quadratic penalty, while residuals fitting next+mean get a modest
    // reward steering compaction toward multi-item absorption.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let horizon = next_item_size as f64 + mean_residual.min(cap * 0.35);
        if (pr as f64) < horizon {
            let dead2 = 1.0 - pr as f64 / horizon;
            score += 7.0 * dead2 * dead2 * (1.0 - 0.4 * progress);
        } else if (pr as f64) >= horizon + 4.0 && (pr as f64) <= horizon + 16.0 {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // Gen 29: waste-slope fresh-bin gate — a fresh bin is only attractive
    // when opening it reduces projected dead space versus the best open
    // residual; penalize the fresh candidate when open space already
    // absorbs the pair cleanly.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && fitting_bins_count >= 1
        && item_size + next_item_size <= bin_capacity
        && progress > 0.05
    {
        let pair = (item_size + next_item_size) as f64;
        let open_leftover = (mean_residual - pair).max(0.0);
        let fresh_leftover = cap - pair;
        if open_leftover <= fresh_leftover && mean_residual >= pair {
            score += 20.0 * (1.0 - 0.5 * progress);
        } else if open_leftover > fresh_leftover + 8.0 {
            score -= 10.0 * ((open_leftover - fresh_leftover - 8.0) / cap).min(0.2) * 40.0 * (1.0 - progress);
        }
    }

    // Gen 29: endgame residual-saturation refinement — in the final
    // stretch, sharpen the near-exact closure band so residuals 1-2 units
    // above the next item beat looser fits.
    if progress > 0.75 && next_item_size > 0 && pr > next_item_size {
        let over = pr - next_item_size;
        if over <= 2 {
            score -= 14.0 * (1.0 - over as f64 / 3.0) * ((progress - 0.75) / 0.25);
        }
    }

    // MUTATION (gen 30): horizon-band tightening — extend the gen-29
    // two-step horizon with a third step (next + 2*mean) so residuals that
    // strand three items receive a mild quadratic penalty, and reward
    // residuals landing within 2 units of the horizon exactly (perfect
    // multi-item closure) with a progress-weighted bonus.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.9 {
        let horizon = next_item_size as f64 + mean_residual.min(cap * 0.35);
        let horizon3 = horizon + mean_residual.min(cap * 0.25);
        if (pr as f64) < horizon3 {
            let dead3 = 1.0 - pr as f64 / horizon3;
            score += 4.0 * dead3 * dead3 * (1.0 - 0.5 * progress);
        }
        let exact = (pr as f64 - horizon).abs();
        if exact <= 2.0 {
            score -= 9.0 * (1.0 - exact / 3.0) * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 30): fresh-bin triple-tile probe — when the fresh bin
    // can tile item_size exactly k>=3 times, opening it is near-optimal
    // (zero internal waste per slot); reinforce the existing slot probe
    // with a mean-residual comparison so we only open when open residuals
    // cannot tile the item at all.
    if bin_residual == bin_capacity
        && item_size > 0
        && bin_capacity % item_size == 0
        && progress > 0.1
        && progress < 0.9
    {
        let slots = bin_capacity / item_size;
        if slots >= 3 && slots <= 5 && (mean_residual as u32) % item_size != 0 {
            score -= 10.0 * slots.min(4) as f64 * (1.0 - 0.6 * progress);
        }
    }

    // MUTATION (gen 30): sliver-merging endgame sweep — residuals in the
    // 5..=11 band late in the stream are classic stranded slivers; when
    // the mean residual suggests other bins hold similar slivers, prefer
    // consuming this one now over leaving it for the endgame.
    if progress > 0.6 && pr >= 5 && pr <= 11 && mean_residual >= 3.0 {
        let similar = ((pr as f64 - mean_residual) / 4.0).abs() < 1.0;
        if similar {
            score -= 8.0 * (1.0 - 0.3 * progress);
        } else {
            score += 6.0 * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION (gen 31): horizon-continuation refinement — the gen-30
    // three-step horizon proved effective; deepen it with a fourth step
    // (next + 3*mean) at reduced weight, and sharpen the exact-band
    // reward to 1 unit so only true multi-item closure wins.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.9 {
        let mr = mean_residual.min(cap * 0.35);
        let horizon3 = next_item_size as f64 + mr + mean_residual.min(cap * 0.25);
        let horizon4 = horizon3 + mean_residual.min(cap * 0.2);
        if (pr as f64) < horizon4 {
            let dead4 = 1.0 - pr as f64 / horizon4;
            score += 2.5 * dead4 * dead4 * (1.0 - 0.5 * progress);
        }
        let exact = (pr as f64 - horizon3).abs();
        if exact <= 1.0 {
            score -= 4.0 * (1.0 - exact) * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION (gen 31): fresh-bin pair-absorption override — when the
    // open residuals cannot jointly absorb the item+next pair (their
    // mean falls short of the pair), opening a fresh bin guarantees the
    // pair lands together with zero fragmentation; but when any open
    // residual already exceeds the pair, fresh space is pure waste.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && fitting_bins_count >= 1
        && progress > 0.05
        && progress < 0.9
    {
        let pair = (item_size + next_item_size) as f64;
        if pair <= cap {
            if mean_residual < pair * 0.9 {
                let shortfall = 1.0 - mean_residual / (pair * 0.9);
                score -= 12.0 * shortfall * (1.0 - 0.4 * progress);
            } else if mean_residual >= pair {
                score += 10.0 * (1.0 - 0.5 * progress);
            }
        }
    }

    // MUTATION (gen 31): residual-parity dead-space polish — dead space
    // concentrated in residuals that are 1-3 units below the next item
    // is the dominant waste mode; a smooth cubic ramp distinguishes
    // near-miss residuals (recoverable) from far-miss ones (stranded).
    if pr > 0 && next_item_size > 0 && pr < next_item_size && progress > 0.1 {
        let gap = (next_item_size - pr) as f64;
        if gap <= 3.0 {
            score -= 6.0 * (1.0 - gap / 4.0) * (1.0 - 0.5 * progress);
        } else if gap <= 8.0 {
            score += 5.0 * ((gap - 3.0) / 5.0) * (1.0 - 0.3 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Sharpened perfect/near-perfect closure rewards.
    if pr == 0 {
        score -= 1280.0;
    } else if pr <= 4 {
        score -= 92.0 + (4 - pr) as f64 * 13.0;
    } else if pr < 12 {
        score += 30.0 - pr as f64;
    }

    // Harmonic residue classes.
    let class_bonus: f64 = if pr % 10 == 0 {
        36.0
    } else if pr % 5 == 0 {
        18.0
    } else if pr % 2 == 0 {
        5.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Lookahead: next item fit quality into post-placement residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 178.0 + 40.0 * (1.0 - progress);
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= if slack <= 10 { 66.0 - slack as f64 * 2.6 } else { 34.0 - (slack as f64).min(30.0) * 0.5 };
        } else {
            score += (next_item_size - pr) as f64 * 0.68;
        }
        if next_item_size < pr {
            let pr2 = pr - next_item_size;
            if pr2 <= 6 {
                score -= 52.0;
            } else if pr2 == next_item_size {
                score -= 27.0;
            } else if pr2 % 10 == 0 {
                score -= 12.0;
            }
            if pr2 > 6 && next_item_size > 1 && pr2 % next_item_size == 0 {
                score -= 15.0;
            }
            if pr2 >= 2 * item_size && item_size > 0 && pr2 % item_size == 0 {
                score -= 8.0;
            }
            if pr2 >= 3 * item_size.max(1) {
                score -= 6.0;
            }
            // Chain lookahead via mean-residual proxy.
            if pr2 > 0 && mean_residual > 0.0 {
                let proxy = mean_residual.round() as u32;
                if proxy >= 1 && proxy <= pr2 {
                    score -= 9.0 * (1.0 - progress);
                }
            }
            // Triple-chain closure.
            if pr2 >= 2 * next_item_size {
                let pr3 = pr2 - 2 * next_item_size;
                if pr3 <= 3 {
                    score -= 24.0 * (1.0 - progress);
                }
            }
            // next + item leaves near-perfect closure.
            if pr2 >= item_size.max(1) {
                let pr3 = pr2 - item_size.max(1);
                if pr3 <= 2 {
                    score -= 20.0 * (1.0 - progress);
                }
            }
        }
        // Pair-absorbency.
        if pr > 1 && pr == 2 * next_item_size {
            score -= 22.0;
        }
        // Stranded residual just below next item.
        if pr > 0 && pr < next_item_size {
            let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
            score += (7.0 + 5.0 * gap_frac) * (1.0 - progress);
        }
    } else {
        // Last item: any bin that fits is fine; prefer tightest.
        score -= 20.0;
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 66.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap) < 0.38;
        let reuse_is_bad = fitting_bins_count <= 1
            || (pr > 0 && next_item_size > pr && next_item_size <= bin_capacity);
        let late_large = item_size >= 60 && progress > 0.10;
        if late_large || (tight && progress > 0.15) || reuse_is_bad {
            score -= 46.0 + 30.0 * progress;
        } else {
            score += 70.0;
        }
        if item_size <= 25 && mean_residual > cap * 0.45 {
            score += 36.0;
        }
        if open_bins_count > 12 && progress < 0.3 {
            score += 12.0;
        }
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 24.0 + 18.0 * (1.0 - progress);
        }
        if next_item_size >= bin_capacity / 2 && mean_residual < (item_size + next_item_size) as f64 {
            score -= 10.0 + 14.0 * (1.0 - progress);
        }
        if item_size + next_item_size == bin_capacity
            && mean_residual < (item_size + next_item_size) as f64
        {
            score -= 20.0;
        }
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size {
            let strand = mean_residual as u32 - item_size;
            if strand > 0 && strand < 8 && progress > 0.2 {
                score -= 14.0 + 6.0 * (1.0 - progress);
            }
        }
        // Fresh-bin exact-pair bonus.
        if item_size + next_item_size == bin_capacity {
            score -= 34.0 + 20.0 * (1.0 - progress);
        }
        if pr > 0 && pr < item_size / 3 && item_size >= 30 {
            score -= 12.0;
        }
        // Fresh-bin viability gate.
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size && fitting_bins_count > 1 && !late_large {
            score += 30.0 * (1.0 - progress);
        }
        // Fresh-bin scarcity coupling.
        if fitting_bins_count >= 2 && item_size >= 40 {
            let best_gap = mean_residual - item_size as f64;
            if best_gap > 12.0 {
                score -= (best_gap / cap).min(0.25) * 80.0 * (1.0 - progress);
            }
        }
        // Fresh-bin only when the item cannot tile any open residual
        // with the next item — otherwise fresh space fragments the stream.
        if next_item_size > 0
            && fitting_bins_count >= 1
            && item_size + next_item_size <= bin_capacity
            && mean_residual >= (item_size + next_item_size) as f64
            && progress < 0.6
        {
            score += 18.0 * (1.0 - progress);
        }
        // Fresh-bin slot-arithmetic probe.
        if item_size > 0 && bin_capacity % item_size == 0 {
            let slots = bin_capacity / item_size;
            if slots >= 2 && slots <= 4 && progress > 0.1 {
                score -= 14.0 * (slots as f64).min(3.0) * (1.0 - 0.5 * progress);
            }
        }
        // Fresh-bin residual-mirror check.
        if mean_residual > item_size as f64 * 1.6 && progress > 0.3 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
        // Fresh-bin dead-space forecast.
        if next_item_size > 0
            && fitting_bins_count >= 2
            && mean_residual > 0.0
            && (item_size as f64 + next_item_size as f64 + mean_residual) <= cap
            && progress < 0.55
        {
            score += 14.0 * (1.0 - progress);
        }
        // Endgame fresh-bin hard gate.
        if progress > 0.7 && fitting_bins_count > 0 && !late_large {
            score += 45.0 * ((progress - 0.7) / 0.3);
        }
    }

    // Best-fit bias.
    score -= (bin_capacity - bin_residual) as f64 * 0.16;

    // Flexible mid-range residual target.
    if pr >= 25 && pr <= 65 {
        score -= 14.0;
    }

    // Proliferation penalty.
    score += open_bins_count as f64 * (0.2 + 0.2 * progress);

    // Waste-avoidance for tiny residuals.
    if pr > 0 && pr < bin_capacity / 5 {
        let scarcity = if fitting_bins_count > 2 { 0.6 } else { 1.4 };
        score += (10.0 + 4.0 * progress) * scarcity;
    }

    // Tightness bonus.
    if bin_residual >= item_size {
        let tightness = 1.0 - ((bin_residual - item_size) as f64 / cap);
        score -= 6.0 * tightness;
    }

    // Mean-residual alignment.
    let align = ((pr as f64 - mean_residual) / cap).abs();
    score += align * (if progress > 0.2 && progress < 0.8 { 4.5 } else { 6.0 });

    // Odd small residuals are dead-space candidates.
    if pr > 0 && pr < 20 && pr % 2 == 1 {
        score += 7.0;
    }

    // Mid-stream consolidation of large absorbable residuals.
    if open_bins_count > 8 && progress > 0.25 && progress < 0.85 && pr >= 40 {
        score -= 9.0;
    }

    // Dead-space ratio shaping with next-item floor.
    if pr > 0 && next_item_size > 0 {
        let dead_threshold = (next_item_size + 12).min(bin_capacity);
        if pr < dead_threshold {
            let dead_frac = 1.0 - (pr as f64 / dead_threshold as f64);
            score += 18.0 * dead_frac * (1.0 - progress);
        } else if pr >= dead_threshold * 2 {
            score -= 8.0 + 4.0 * (1.0 - progress);
        } else if pr == next_item_size + item_size {
            score -= 5.0;
        }
    }

    // Endgame exactness.
    if progress > 0.9 && pr > 0 {
        score += pr as f64 * 0.35;
        if pr <= next_item_size.max(1) {
            score -= 20.0;
        }
    }

    // Fragment guard against typical upcoming demand.
    if pr > 0 && progress > 0.1 {
        let typical = (mean_residual * 0.5).max(8.0).min(cap * 0.5);
        if (pr as f64) < typical {
            score += 6.0 * (1.0 - (pr as f64 / typical)) * (1.0 - progress);
        }
    }

    // Exact-closure sweep with plentiful fitting bins.
    if pr == 0 && fitting_bins_count > 2 {
        score -= 12.0 * (1.0 - progress);
    }

    // Dual lookahead — repeatable fill detection.
    if next_item_size > 0 && next_item_size < pr {
        let pr2 = pr - next_item_size;
        if pr2 > 0 && item_size > 1 && pr2 % item_size == 0 && next_item_size % item_size == 0 {
            score -= 10.0;
        }
    }

    // Half-capacity residual targeting mid-stream.
    if pr > 0 && progress > 0.15 && progress < 0.9 {
        let half = cap * 0.5;
        let dist = ((pr as f64 - half) / half).abs();
        if dist < 0.25 {
            score -= 7.0 * (1.0 - dist / 0.25);
        }
    }

    // Dead-space ratio term with smooth quadratic ramp.
    if pr > 0 {
        let pr_f = pr as f64;
        let usable_floor = (next_item_size.max(1) as f64).min(cap * 0.3);
        if pr_f < usable_floor {
            let dsr = 1.0 - pr_f / usable_floor;
            score += 11.0 * dsr * dsr * (0.5 + 0.5 * (1.0 - progress));
        }
        if pr % 3 == 0 && pr >= 6 {
            score -= 5.0;
        }
        if pr % 7 == 0 && pr >= 7 {
            score -= 4.0;
        }
    }

    // Bin-count pressure valve.
    if bin_residual != bin_capacity && mean_residual > 0.0 {
        let fill = 1.0 - mean_residual / cap;
        if fill > 0.75 && fitting_bins_count > 1 {
            score -= 6.0 * (fill - 0.75) / 0.25;
        } else if fill < 0.5 && fitting_bins_count > 1 {
            score += 4.0 * (0.5 - fill) / 0.5 * (1.0 - progress);
        }
    }

    // Dead-space waste accounting with quadratic ramp.
    if pr > 0 && next_item_size > 0 && next_item_size < bin_capacity {
        let waste_frac = 1.0 - (pr.min(next_item_size) as f64 / pr as f64);
        if waste_frac > 0.5 {
            score += 9.0 * (waste_frac - 0.5) * 2.0 * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Consolidation incentive matching mean residual.
    if progress > 0.35 && pr >= next_item_size.max(1) && mean_residual > 0.0 {
        let dev = ((pr as f64 - mean_residual) / cap).abs();
        if dev < 0.08 {
            score -= 6.0 * (1.0 - dev / 0.08);
        }
    }

    // Quad-chain lookahead.
    if next_item_size > 0 && pr >= 3 * next_item_size {
        let pr3 = pr - 3 * next_item_size;
        if pr3 <= 4 {
            score -= 18.0 * (1.0 - progress);
        }
    }

    // Item+next exact pair inside residual.
    if next_item_size > 0 && item_size > 0 && pr == item_size + next_item_size {
        score -= 26.0;
    }

    // Late-stream fresh-bin restraint.
    if bin_residual == bin_capacity && progress > 0.7 {
        let exact_pair = item_size + next_item_size == bin_capacity;
        if !exact_pair && fitting_bins_count > 0 {
            score += 22.0 * (progress - 0.7) / 0.3;
        }
    }

    // Large-item protection.
    if item_size > 50 && pr > 0 && pr < 15 {
        score += 10.0 * (1.0 - pr as f64 / 15.0);
    }

    // Residual-divisibility absorbency.
    if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 {
        let chain_len = pr / next_item_size;
        if chain_len >= 2 {
            score -= (8.0 + 6.0 * chain_len.min(4) as f64) * (1.0 - 0.5 * progress);
        }
    }

    // Dead-space variance dampener.
    if pr > 0 && next_item_size > 0 && pr < next_item_size && open_bins_count > 3 {
        let unusable = (next_item_size - pr) as f64 / next_item_size as f64;
        score += 14.0 * unusable * unusable * (1.0 - progress);
    }

    // Mid-stream sweep for residuals matching common item-size sums.
    if pr > 0 && progress > 0.2 && progress < 0.9 {
        let small_sum = item_size.min(next_item_size.max(1));
        if pr == 2 * small_sum || pr == small_sum + 10 || pr == small_sum + 25 {
            score -= 7.0;
        }
    }

    // Endgame fresh-bin suppression.
    if bin_residual == bin_capacity && progress > 0.85 {
        let biggest_resid = mean_residual.max(0.0);
        if item_size as f64 <= biggest_resid.max(1.0) && fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Residual pooling.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.2 && progress < 0.85 {
        let mr = mean_residual;
        let k = (pr as f64 / mr).round().max(1.0);
        let dev = (pr as f64 - k * mr).abs() / mr;
        if dev < 0.15 && k >= 1.0 {
            score -= 10.0 * (1.0 - dev / 0.15) * (1.0 - 0.4 * progress);
        }
    }

    // Two-item lookahead tiling.
    if pr > 0 && next_item_size > 0 && mean_residual > 1.0 {
        let combo = next_item_size as f64 + mean_residual.min(cap * 0.4);
        let gap = pr as f64 - combo;
        if gap >= 0.0 && gap <= 5.0 {
            score -= (16.0 - gap) * 2.4 * (1.0 - 0.5 * progress);
        }
    }

    // Strand-risk shaping.
    if pr >= 13 && pr <= 24 {
        let crowd = if open_bins_count > 10 { 1.5 } else { 0.7 };
        score += 6.0 * crowd * (1.0 - 0.5 * progress);
    }

    // Dead-space floor tightening.
    if pr > 0 && next_item_size > 0 {
        let floor = next_item_size.max(1) as f64;
        if (pr as f64) < floor {
            let x = pr as f64 / floor;
            score += (10.0 + 14.0 * (1.0 - x) * (1.0 - x)) * (1.0 - 0.6 * progress);
        }
    }

    // Near-exact residual shaping.
    if next_item_size > 0 && pr > next_item_size && pr <= next_item_size + 3 {
        score -= (18.0 - (pr - next_item_size) as f64 * 4.0) * (1.0 - 0.5 * progress);
    }

    // Open-bin budget shaping.
    if open_bins_count as f64 > (step_index as f64) * 0.35 && pr > 0 {
        let over = open_bins_count as f64 / (step_index as f64 + 1.0);
        score += (pr as f64 / cap) * 22.0 * over.min(1.5);
    }

    // Dead-space minimization sweep.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let mr = mean_residual.min(cap);
        let usable_by_next = pr >= next_item_size;
        let usable_by_mean = (pr as f64) >= mr;
        if !usable_by_next && !usable_by_mean {
            let wasted = (next_item_size - pr) as f64;
            score += (6.0 + 0.25 * wasted) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Exact-fill cascade.
    if next_item_size > 0 && item_size > 1 && pr > next_item_size {
        let pr2 = pr - next_item_size;
        if pr2 % item_size == 0 && pr2 / item_size >= 1 && pr2 != 0 {
            score -= (10.0 + 4.0 * (pr2 / item_size).min(3) as f64) * (1.0 - 0.4 * progress);
        }
    }

    // Residual-slope steering.
    if next_item_size > 0 && pr > 0 {
        let target = next_item_size as f64;
        let dev = (pr as f64 - target) / target.max(1.0);
        if dev.abs() < 0.5 {
            score -= 9.0 * (1.0 - (dev / 0.5) * (dev / 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    // Dual-fit depth probe.
    if next_item_size > 0 && pr > next_item_size && mean_residual >= 1.0 {
        let pr2 = pr - next_item_size;
        let proxy = mean_residual.min(cap);
        if (pr2 as f64) >= proxy {
            score -= 11.0 * (1.0 - 0.5 * progress);
            if pr2 as f64 - proxy < 6.0 {
                score -= 8.0;
            }
        }
        if (pr2 as f64) < proxy && pr2 > 0 && pr2 < 10 {
            score += 9.0 * (1.0 - pr2 as f64 / 10.0);
        }
    }

    // Capacity-fraction dead-space gate.
    if pr > 0 && progress > 0.2 && progress < 0.9 {
        let lo = cap * 0.38;
        let hi = cap * 0.5;
        if (pr as f64) > lo && (pr as f64) < hi {
            let frac = 1.0 - ((pr as f64 - lo) / (hi - lo));
            score += 8.0 * frac * frac;
        }
    }

    // Dead-space recovery probe.
    if pr > 0 && mean_residual >= 2.0 {
        let mr = mean_residual.min(cap * 0.6);
        let gap = pr as f64 - mr;
        if gap >= 0.0 && gap <= 5.0 {
            score += 10.0 * (1.0 - gap / 5.0) * (1.0 - 0.4 * progress);
        } else if gap > 5.0 && gap < 12.0 {
            score -= 5.0 * (1.0 - (gap - 5.0) / 7.0) * (1.0 - 0.5 * progress);
        }
    }

    // Fitting-crowd tiebreak via harmonic-mean demand matching.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let harmonic = 2.0 * (next_item_size as f64 * mean_residual)
            / (next_item_size as f64 + mean_residual).max(1.0);
        let dev = ((pr as f64 - harmonic) / harmonic.max(1.0)).abs();
        let pressure = if fitting_bins_count >= 4 { 1.0 } else { 0.4 };
        if dev < 0.3 {
            score -= 7.0 * (1.0 - dev / 0.3) * pressure * (1.0 - 0.4 * progress);
        }
    }

    // Endgame sliver sweep.
    if progress > 0.8 && pr > 0 && next_item_size > 0 && pr < next_item_size {
        let waste = 1.0 - pr as f64 / next_item_size as f64;
        score += 12.0 * waste * waste * (progress - 0.8) / 0.2;
    }

    // Dead-space ratio compaction sweep.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.9 {
        let demand = next_item_size as f64 + mean_residual.min(cap * 0.5);
        let gap = pr as f64 - demand;
        if gap >= 0.0 && gap <= 6.0 {
            score -= (12.0 - gap) * 1.8 * (1.0 - 0.5 * progress);
        } else if gap > 6.0 && gap <= 14.0 && (gap as u32) < next_item_size {
            let sliver = gap as f64 / 14.0;
            score += 7.0 * sliver * (1.0 - 0.4 * progress);
        }
    }

    // Cross-bin compaction pull.
    if pr > 0 && mean_residual >= 3.0 && fitting_bins_count >= 2 && progress > 0.3 {
        let mr = mean_residual;
        let k = ((pr as f64) / mr).floor().max(1.0);
        let rem = pr as f64 - k * mr;
        if rem >= 0.0 && rem <= 4.0 {
            let weight = 1.0 + (progress - 0.3);
            score -= (6.0 + 4.0 * (1.0 - rem / 4.0)) * weight.min(1.7);
        } else if rem > 4.0 && rem < mr {
            score += 4.0 * (1.0 - progress) * (rem / mr);
        }
    }

    // Tight-fit crowding bonus.
    if bin_residual >= item_size {
        let slack = bin_residual - item_size;
        if slack <= 2 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= (14.0 + 8.0 * (2 - slack) as f64) * scarcity * (1.0 - 0.4 * progress);
        }
    }

    // Perfect-fit dominance gate.
    if pr == 0 {
        if bin_residual == bin_capacity {
            score += 1400.0;
        }
        score -= 30.0 * (1.0 - progress);
    }

    // Scarcity-driven fresh-bin override.
    if bin_residual == bin_capacity
        && fitting_bins_count == 1
        && next_item_size > 0
        && pr > 0
        && next_item_size > pr
        && (pr as f64) < 0.2 * cap
        && progress < 0.8
    {
        score -= 55.0 * (1.0 - progress);
    }

    // Gen 27: residual-dead-space gradient.
    if pr > 0 && next_item_size > 0 {
        let demand = (next_item_size as f64).max(mean_residual * 0.8);
        if (pr as f64) < demand {
            let dead = 1.0 - pr as f64 / demand;
            score += 15.0 * dead * dead * (1.0 - 0.5 * progress);
        }
    }

    // Gen 27: two-step exact-closure ladder.
    if next_item_size > 0 && item_size > 0 && pr >= item_size + next_item_size {
        let pr2 = pr - item_size - next_item_size;
        if pr2 == 0 {
            score -= 30.0 + 25.0 * (1.0 - progress);
        } else if pr2 <= 3 {
            score -= 16.0 * (1.0 - progress);
        }
    }

    // Gen 27: fresh-bin divisibility discount.
    if bin_residual == bin_capacity
        && item_size > 0
        && bin_capacity % item_size == 0
        && mean_residual > 0.0
        && (mean_residual as u32) % item_size != 0
        && progress > 0.15
    {
        score -= 12.0 * (1.0 - 0.6 * progress);
    }

    // Gen 27: late-stream tight-slack refinement.
    if progress > 0.66 && bin_residual >= item_size {
        let slack = bin_residual - item_size;
        if slack >= 3 && slack <= 6 && pr > 0 {
            score += 5.0 + 2.0 * (progress - 0.66) / 0.34;
        }
    }

    // Gen 28: two-chain residual tileability probe.
    if next_item_size > 1 && pr >= 2 * next_item_size {
        let pr2 = pr - 2 * next_item_size;
        if pr2 == 0 {
            score -= 20.0 + 14.0 * (1.0 - progress);
        } else if pr2 <= 2 {
            score += 6.0 * (1.0 - pr2 as f64 / 3.0);
        }
    }

    // Gen 28: fresh-bin mean-residual saturation gate.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && mean_residual > 0.0
        && (mean_residual as u32) < next_item_size
        && fitting_bins_count >= 1
        && progress > 0.1
        && progress < 0.85
    {
        let deficit = 1.0 - mean_residual / next_item_size as f64;
        score -= 18.0 * deficit * deficit * (1.0 - progress);
    }

    // Gen 28: mid-stream slack-quantization shaping.
    if pr > 0 && mean_residual >= 3.0 && progress > 0.15 && progress < 0.9 {
        let mr = mean_residual.min(cap);
        let diff = (pr as f64 - mr).abs();
        if diff <= 2.0 {
            score -= 8.0 * (1.0 - diff / 3.0) * (1.0 - 0.3 * progress);
        } else if diff > mr * 0.5 && diff < mr * 0.5 + 3.0 {
            score += 4.0 * (1.0 - progress);
        }
    }

    // Gen 29: dead-space gradient refinement — two-step demand horizon
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let horizon = next_item_size as f64 + mean_residual.min(cap * 0.35);
        if (pr as f64) < horizon {
            let dead2 = 1.0 - pr as f64 / horizon;
            score += 7.0 * dead2 * dead2 * (1.0 - 0.4 * progress);
        } else if (pr as f64) >= horizon + 4.0 && (pr as f64) <= horizon + 16.0 {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // Gen 29: waste-slope fresh-bin gate
    if bin_residual == bin_capacity
        && next_item_size > 0
        && fitting_bins_count >= 1
        && item_size + next_item_size <= bin_capacity
        && progress > 0.05
    {
        let pair = (item_size + next_item_size) as f64;
        let open_leftover = (mean_residual - pair).max(0.0);
        let fresh_leftover = cap - pair;
        if open_leftover <= fresh_leftover && mean_residual >= pair {
            score += 20.0 * (1.0 - 0.5 * progress);
        } else if open_leftover > fresh_leftover + 8.0 {
            score -= 10.0 * ((open_leftover - fresh_leftover - 8.0) / cap).min(0.2) * 40.0 * (1.0 - progress);
        }
    }

    // Gen 29: endgame residual-saturation refinement
    if progress > 0.75 && next_item_size > 0 && pr > next_item_size {
        let over = pr - next_item_size;
        if over <= 2 {
            score -= 14.0 * (1.0 - over as f64 / 3.0) * ((progress - 0.75) / 0.25);
        }
    }

    // Gen 30: horizon-band tightening — third-step horizon.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.9 {
        let horizon = next_item_size as f64 + mean_residual.min(cap * 0.35);
        let horizon3 = horizon + mean_residual.min(cap * 0.25);
        if (pr as f64) < horizon3 {
            let dead3 = 1.0 - pr as f64 / horizon3;
            score += 4.0 * dead3 * dead3 * (1.0 - 0.5 * progress);
        }
        let exact = (pr as f64 - horizon).abs();
        if exact <= 2.0 {
            score -= 9.0 * (1.0 - exact / 3.0) * (1.0 - 0.4 * progress);
        }
    }

    // Gen 30: fresh-bin triple-tile probe.
    if bin_residual == bin_capacity
        && item_size > 0
        && bin_capacity % item_size == 0
        && progress > 0.1
        && progress < 0.9
    {
        let slots = bin_capacity / item_size;
        if slots >= 3 && slots <= 5 && (mean_residual as u32) % item_size != 0 {
            score -= 10.0 * slots.min(4) as f64 * (1.0 - 0.6 * progress);
        }
    }

    // Gen 30: sliver-merging endgame sweep.
    if progress > 0.6 && pr >= 5 && pr <= 11 && mean_residual >= 3.0 {
        let similar = ((pr as f64 - mean_residual) / 4.0).abs() < 1.0;
        if similar {
            score -= 8.0 * (1.0 - 0.3 * progress);
        } else {
            score += 6.0 * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION (gen 31): horizon-continuation refinement — the gen-30
    // horizon band proved effective; reinforce it by sharpening the
    // exact-closure bonus when the residual equals the horizon exactly
    // (perfect multi-item absorption) and extending the sliver-merge band
    // to 3..=14 with a mean-residual similarity test weighted by bin
    // crowding, so stranded slivers are consumed earlier mid-stream.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.9 {
        let horizon = next_item_size as f64 + mean_residual.min(cap * 0.35);
        if (pr as f64) == horizon {
            score -= 6.0 * (1.0 - 0.3 * progress);
        }
    }
    if progress > 0.45 && pr >= 3 && pr <= 14 && mean_residual >= 2.0 {
        let crowd = if open_bins_count > 8 { 1.3 } else { 0.8 };
        let similar = ((pr as f64 - mean_residual) / 3.0).abs() < 1.0;
        if similar {
            score -= 6.0 * crowd * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 31): fresh-bin pair-tile reinforcement — when the
    // fresh bin can hold exactly item+next with zero leftover, opening it
    // is provably waste-free for the pair; deepen the existing bonus with
    // a fitting-crowd condition so we only prefer fresh when open bins
    // are scarce or poorly matched.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && item_size + next_item_size == bin_capacity
        && mean_residual > 0.0
        && (mean_residual as u32) < item_size + next_item_size
        && progress > 0.05
        && progress < 0.9
    {
        score -= 12.0 * (1.0 - 0.5 * progress) * if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Sharpened closure rewards: exact fit is overwhelmingly preferred.
    if pr == 0 {
        score -= 1300.0;
    } else if pr <= 4 {
        score -= 90.0 + (4 - pr) as f64 * 13.0;
    } else if pr <= 10 {
        score += 40.0 - pr as f64; // sliver penalty
    } else if pr <= 25 {
        score += 14.0;
    } else if pr <= 50 {
        score -= 5.0;
    } else {
        score -= 12.0;
    }

    // Harmonic residue classes.
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 30.0;
        } else if pr % 5 == 0 {
            score -= 15.0;
        } else if pr % 2 == 0 {
            score -= 4.0;
        }
    }

    // Lookahead: next-item fit quality into the post residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 170.0 + 40.0 * (1.0 - progress);
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            if slack <= 10 {
                score -= 60.0 - slack as f64 * 2.5;
            } else {
                score -= 30.0 - (slack as f64).min(30.0) * 0.5;
            }
            let pr2 = pr - next_item_size;
            if pr2 <= 6 {
                score -= 50.0;
            } else if pr2 == next_item_size {
                score -= 26.0;
            } else if pr2 % 10 == 0 {
                score -= 10.0;
            }
            if pr2 >= 2 * next_item_size {
                let pr3 = pr2 - 2 * next_item_size;
                if pr3 <= 4 {
                    score -= 24.0 * (1.0 - progress);
                }
            }
            if pr2 >= item_size.max(1) {
                let pr3 = pr2 - item_size.max(1);
                if pr3 <= 2 {
                    score -= 20.0 * (1.0 - progress);
                }
            }
            // Chain lookahead via mean-residual proxy.
            if pr2 > 0 && mean_residual > 0.0 {
                let proxy = mean_residual.round() as u32;
                if proxy >= 1 && proxy <= pr2 {
                    score -= 9.0 * (1.0 - progress);
                }
            }
        } else {
            let overshoot = (next_item_size - pr) as f64 / cap;
            score += 10.0 * overshoot + 0.6 * (next_item_size - pr) as f64;
            // Stranded residual just below the next item.
            if pr > 0 {
                let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
                score += (7.0 + 5.0 * gap_frac) * (1.0 - progress);
            }
        }
        if pr > 1 && pr == 2 * next_item_size {
            score -= 22.0;
        }
    } else {
        score -= 20.0;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap) < 0.38;
        let reuse_is_bad = fitting_bins_count <= 1
            || (pr > 0 && next_item_size > pr && next_item_size <= bin_capacity);
        let late_large = item_size >= 60 && progress > 0.10;
        if late_large || (tight && progress > 0.15) || reuse_is_bad {
            score -= 46.0 + 30.0 * progress;
        } else {
            score += 70.0;
        }
        if item_size <= 25 && mean_residual > cap * 0.45 {
            score += 36.0;
        }
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 24.0 + 18.0 * (1.0 - progress);
        }
        if item_size + next_item_size == bin_capacity {
            score -= 34.0 + 20.0 * (1.0 - progress);
        }
        // Fresh-bin viability gate.
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size && fitting_bins_count > 1 && !late_large {
            score += 30.0 * (1.0 - progress);
        }
        // Fresh-bin scarcity coupling for large items.
        if fitting_bins_count >= 2 && item_size >= 40 {
            let best_gap = mean_residual - item_size as f64;
            if best_gap > 12.0 {
                score -= (best_gap / cap).min(0.25) * 80.0 * (1.0 - progress);
            }
        }
        // Late-stream fresh-bin restraint.
        if progress > 0.7 && !reuse_is_bad {
            score += 22.0 * (progress - 0.7) / 0.3;
        }
        if progress > 0.85 && item_size as f64 <= mean_residual.max(1.0) && fitting_bins_count > 0 {
            score += 40.0;
        }
        // MUTATION: waste-slope fresh-bin gate — prefer the open residual
        // when it already absorbs the (item, next) pair no worse than a
        // fresh bin would; penalize fresh space that fragments the stream.
        if next_item_size > 0
            && fitting_bins_count >= 1
            && item_size + next_item_size <= bin_capacity
            && progress > 0.05
        {
            let pair = (item_size + next_item_size) as f64;
            let open_leftover = (mean_residual - pair).max(0.0);
            let fresh_leftover = cap - pair;
            if open_leftover <= fresh_leftover && mean_residual >= pair {
                score += 20.0 * (1.0 - 0.5 * progress);
            } else if open_leftover > fresh_leftover + 8.0 {
                score -= 10.0 * ((open_leftover - fresh_leftover - 8.0) / cap).min(0.2) * 40.0 * (1.0 - progress);
            }
        }
        // MUTATION: fresh-bin saturation gate — when open residuals cannot
        // even hold the next item, opening fresh space is less wasteful.
        if next_item_size > 0
            && mean_residual > 0.0
            && (mean_residual as u32) < next_item_size
            && fitting_bins_count >= 1
            && progress > 0.1
            && progress < 0.85
        {
            let deficit = 1.0 - mean_residual / next_item_size as f64;
            score -= 18.0 * deficit * deficit * (1.0 - progress);
        }
    }

    // Best-fit bias.
    score -= (bin_capacity - bin_residual) as f64 * 0.16;

    // Mid-range residual target.
    if pr >= 25 && pr <= 65 {
        score -= 13.0;
    }

    // Proliferation penalty.
    score += open_bins_count as f64 * (0.2 + 0.2 * progress);

    // Tiny-residual waste avoidance.
    if pr > 0 && pr < bin_capacity / 5 {
        let scarcity = if fitting_bins_count > 2 { 0.6 } else { 1.4 };
        score += (10.0 + 4.0 * progress) * scarcity;
    }

    // Tightness bonus.
    if bin_residual >= item_size {
        let tightness = 1.0 - ((bin_residual - item_size) as f64 / cap);
        score -= 6.0 * tightness;
        let slack = bin_residual - item_size;
        if slack <= 2 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= (14.0 + 8.0 * (2 - slack) as f64) * scarcity * (1.0 - 0.4 * progress);
        }
    }

    // Mean-residual alignment.
    let align = ((pr as f64 - mean_residual) / cap).abs();
    score += align * (if progress > 0.2 && progress < 0.8 { 4.5 } else { 6.0 });

    // Odd small residuals are dead-space candidates.
    if pr > 0 && pr < 20 && pr % 2 == 1 {
        score += 7.0;
    }

    // Dead-space shaping relative to next-item demand.
    if pr > 0 && next_item_size > 0 {
        let dead_threshold = (next_item_size + 12).min(bin_capacity);
        if pr < dead_threshold {
            let dead_frac = 1.0 - (pr as f64 / dead_threshold as f64);
            score += 18.0 * dead_frac * (1.0 - progress);
        } else if pr >= dead_threshold * 2 {
            score -= 8.0 + 4.0 * (1.0 - progress);
        }
    }

    // Endgame exactness.
    if progress > 0.9 && pr > 0 {
        score += pr as f64 * 0.35;
        if pr <= next_item_size.max(1) {
            score -= 20.0;
        }
    }

    // Fragment guard against typical upcoming demand.
    if pr > 0 && progress > 0.1 {
        let typical = (mean_residual * 0.5).max(8.0).min(cap * 0.5);
        if (pr as f64) < typical {
            score += 6.0 * (1.0 - (pr as f64 / typical)) * (1.0 - progress);
        }
    }

    // Residual pooling toward mean-residual multiples.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.2 && progress < 0.85 {
        let mr = mean_residual;
        let k = (pr as f64 / mr).round().max(1.0);
        let dev = (pr as f64 - k * mr).abs() / mr;
        if dev < 0.15 {
            score -= 10.0 * (1.0 - dev / 0.15) * (1.0 - 0.4 * progress);
        }
    }

    // Two-item lookahead tiling with mean-residual proxy.
    if pr > 0 && next_item_size > 0 && mean_residual > 1.0 {
        let combo = next_item_size as f64 + mean_residual.min(cap * 0.4);
        let gap = pr as f64 - combo;
        if gap >= 0.0 && gap <= 5.0 {
            score -= (16.0 - gap) * 2.4 * (1.0 - 0.5 * progress);
        }
    }

    // Near-exact residual shaping.
    if next_item_size > 0 && pr > next_item_size && pr <= next_item_size + 3 {
        score -= (18.0 - (pr - next_item_size) as f64 * 4.0) * (1.0 - 0.5 * progress);
    }

    // Open-bin budget shaping.
    if open_bins_count as f64 > (step_index as f64) * 0.35 && pr > 0 {
        let over = open_bins_count as f64 / (step_index as f64 + 1.0);
        score += (pr as f64 / cap) * 22.0 * over.min(1.5);
    }

    // Dual-fit depth probe.
    if next_item_size > 0 && pr > next_item_size && mean_residual >= 1.0 {
        let pr2 = pr - next_item_size;
        let proxy = mean_residual.min(cap);
        if (pr2 as f64) >= proxy {
            score -= 11.0 * (1.0 - 0.5 * progress);
            if pr2 as f64 - proxy < 6.0 {
                score -= 8.0;
            }
        } else if pr2 > 0 && pr2 < 10 {
            score += 9.0 * (1.0 - pr2 as f64 / 10.0);
        }
    }

    // Exact-closure sweep with plentiful fitting bins.
    if pr == 0 && fitting_bins_count > 2 {
        score -= 12.0 * (1.0 - progress);
    }

    // Divisibility absorbency — residual exactly divisible by the next
    // item tiles cleanly; reward proportional to chain length.
    if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 {
        let chain_len = pr / next_item_size;
        if chain_len >= 2 {
            score -= (8.0 + 6.0 * chain_len.min(4) as f64) * (1.0 - 0.5 * progress);
        }
    }

    // Item+next exact pair inside residual.
    if next_item_size > 0 && pr == item_size + next_item_size {
        score -= 26.0;
    }

    // MUTATION: two-step exact-closure ladder — residuals that fit both
    // the current item and the next item exactly are top-tier; reward
    // near-exact ladders too.
    if next_item_size > 0 && item_size > 0 && pr >= item_size + next_item_size {
        let pr2 = pr - item_size - next_item_size;
        if pr2 == 0 {
            score -= 30.0 + 25.0 * (1.0 - progress);
        } else if pr2 <= 3 {
            score -= 16.0 * (1.0 - progress);
        }
    }

    // MUTATION: dead-space gradient refinement — two-step demand horizon
    // (next + mean) so residuals stranding BOTH items get a sharper
    // quadratic penalty, while residuals fitting next+mean get a modest
    // reward steering compaction toward multi-item absorption.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let horizon = next_item_size as f64 + mean_residual.min(cap * 0.35);
        if (pr as f64) < horizon {
            let dead2 = 1.0 - pr as f64 / horizon;
            score += 7.0 * dead2 * dead2 * (1.0 - 0.4 * progress);
        } else if (pr as f64) >= horizon + 4.0 && (pr as f64) <= horizon + 16.0 {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // MUTATION: endgame residual-saturation refinement — in the final
    // stretch, sharpen the near-exact closure band so residuals 1-2 units
    // above the next item beat looser fits.
    if progress > 0.75 && next_item_size > 0 && pr > next_item_size {
        let over = pr - next_item_size;
        if over <= 2 {
            score -= 14.0 * (1.0 - over as f64 / 3.0) * ((progress - 0.75) / 0.25);
        }
    }

    // MUTATION: sliver-merging sweep — residuals in the 5..=11 band late
    // in the stream are classic stranded slivers; when the mean residual
    // suggests other bins hold similar slivers, prefer consuming this one
    // now over leaving it for the endgame.
    if progress > 0.6 && pr >= 5 && pr <= 11 && mean_residual >= 3.0 {
        let similar = ((pr as f64 - mean_residual) / 4.0).abs() < 1.0;
        if similar {
            score -= 8.0 * (1.0 - 0.3 * progress);
        } else {
            score += 6.0 * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION: half-capacity residual targeting mid-stream — residuals
    // near half capacity are the most re-usable landing zones.
    if pr > 0 && progress > 0.15 && progress < 0.9 {
        let half = cap * 0.5;
        let dist = ((pr as f64 - half) / half).abs();
        if dist < 0.25 {
            score -= 7.0 * (1.0 - dist / 0.25);
        }
    }

    // MUTATION: large-item protection — never strand a residual too small
    // for a big item when a big item is arriving.
    if item_size > 50 && pr > 0 && pr < 15 {
        score += 10.0 * (1.0 - pr as f64 / 15.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Sharpened perfect/near-perfect closure rewards.
    if pr == 0 {
        score -= 1280.0;
    } else if pr <= 4 {
        score -= 92.0 + (4 - pr) as f64 * 13.0;
    } else if pr < 12 {
        score += 30.0 - pr as f64;
    }

    // Harmonic residue classes.
    let class_bonus: f64 = if pr % 10 == 0 {
        36.0
    } else if pr % 5 == 0 {
        18.0
    } else if pr % 2 == 0 {
        5.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Lookahead: next item fit quality into post-placement residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 178.0 + 40.0 * (1.0 - progress);
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= if slack <= 10 { 66.0 - slack as f64 * 2.6 } else { 34.0 - (slack as f64).min(30.0) * 0.5 };
        } else {
            score += (next_item_size - pr) as f64 * 0.68;
        }
        if next_item_size < pr {
            let pr2 = pr - next_item_size;
            if pr2 <= 6 {
                score -= 52.0;
            } else if pr2 == next_item_size {
                score -= 27.0;
            } else if pr2 % 10 == 0 {
                score -= 12.0;
            }
            if pr2 > 6 && next_item_size > 1 && pr2 % next_item_size == 0 {
                score -= 15.0;
            }
            if pr2 >= 2 * item_size && item_size > 0 && pr2 % item_size == 0 {
                score -= 8.0;
            }
            if pr2 >= 3 * item_size.max(1) {
                score -= 6.0;
            }
            // Chain lookahead via mean-residual proxy.
            if pr2 > 0 && mean_residual > 0.0 {
                let proxy = mean_residual.round() as u32;
                if proxy >= 1 && proxy <= pr2 {
                    score -= 9.0 * (1.0 - progress);
                }
            }
            // Triple-chain closure.
            if pr2 >= 2 * next_item_size {
                let pr3 = pr2 - 2 * next_item_size;
                if pr3 <= 3 {
                    score -= 24.0 * (1.0 - progress);
                }
            }
            // next + item leaves near-perfect closure.
            if pr2 >= item_size.max(1) {
                let pr3 = pr2 - item_size.max(1);
                if pr3 <= 2 {
                    score -= 20.0 * (1.0 - progress);
                }
            }
        }
        // Pair-absorbency.
        if pr > 1 && pr == 2 * next_item_size {
            score -= 22.0;
        }
        // Stranded residual just below next item.
        if pr > 0 && pr < next_item_size {
            let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
            score += (7.0 + 5.0 * gap_frac) * (1.0 - progress);
        }
    } else {
        // Last item: any bin that fits is fine; prefer tightest.
        score -= 20.0;
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 66.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap) < 0.38;
        let reuse_is_bad = fitting_bins_count <= 1
            || (pr > 0 && next_item_size > pr && next_item_size <= bin_capacity);
        let late_large = item_size >= 60 && progress > 0.10;
        if late_large || (tight && progress > 0.15) || reuse_is_bad {
            score -= 46.0 + 30.0 * progress;
        } else {
            score += 70.0;
        }
        if item_size <= 25 && mean_residual > cap * 0.45 {
            score += 36.0;
        }
        if open_bins_count > 12 && progress < 0.3 {
            score += 12.0;
        }
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 24.0 + 18.0 * (1.0 - progress);
        }
        if next_item_size >= bin_capacity / 2 && mean_residual < (item_size + next_item_size) as f64 {
            score -= 10.0 + 14.0 * (1.0 - progress);
        }
        if item_size + next_item_size == bin_capacity
            && mean_residual < (item_size + next_item_size) as f64
        {
            score -= 20.0;
        }
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size {
            let strand = mean_residual as u32 - item_size;
            if strand > 0 && strand < 8 && progress > 0.2 {
                score -= 14.0 + 6.0 * (1.0 - progress);
            }
        }
        // Fresh-bin exact-pair bonus.
        if item_size + next_item_size == bin_capacity {
            score -= 34.0 + 20.0 * (1.0 - progress);
        }
        if pr > 0 && pr < item_size / 3 && item_size >= 30 {
            score -= 12.0;
        }
        // Fresh-bin viability gate.
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size && fitting_bins_count > 1 && !late_large {
            score += 30.0 * (1.0 - progress);
        }
        // Fresh-bin scarcity coupling.
        if fitting_bins_count >= 2 && item_size >= 40 {
            let best_gap = mean_residual - item_size as f64;
            if best_gap > 12.0 {
                score -= (best_gap / cap).min(0.25) * 80.0 * (1.0 - progress);
            }
        }
        // Fresh-bin only when the item cannot tile any open residual
        // with the next item — otherwise fresh space fragments the stream.
        if next_item_size > 0
            && fitting_bins_count >= 1
            && item_size + next_item_size <= bin_capacity
            && mean_residual >= (item_size + next_item_size) as f64
            && progress < 0.6
        {
            score += 18.0 * (1.0 - progress);
        }
        // Fresh-bin slot-arithmetic probe.
        if item_size > 0 && bin_capacity % item_size == 0 {
            let slots = bin_capacity / item_size;
            if slots >= 2 && slots <= 4 && progress > 0.1 {
                score -= 14.0 * (slots as f64).min(3.0) * (1.0 - 0.5 * progress);
            }
        }
        // Fresh-bin residual-mirror check.
        if mean_residual > item_size as f64 * 1.6 && progress > 0.3 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
        // Fresh-bin dead-space forecast.
        if next_item_size > 0
            && fitting_bins_count >= 2
            && mean_residual > 0.0
            && (item_size as f64 + next_item_size as f64 + mean_residual) <= cap
            && progress < 0.55
        {
            score += 14.0 * (1.0 - progress);
        }
        // Endgame fresh-bin hard gate.
        if progress > 0.7 && fitting_bins_count > 0 && !late_large {
            score += 45.0 * ((progress - 0.7) / 0.3);
        }
    }

    // Best-fit bias.
    score -= (bin_capacity - bin_residual) as f64 * 0.16;

    // Flexible mid-range residual target.
    if pr >= 25 && pr <= 65 {
        score -= 14.0;
    }

    // Proliferation penalty.
    score += open_bins_count as f64 * (0.2 + 0.2 * progress);

    // Waste-avoidance for tiny residuals.
    if pr > 0 && pr < bin_capacity / 5 {
        let scarcity = if fitting_bins_count > 2 { 0.6 } else { 1.4 };
        score += (10.0 + 4.0 * progress) * scarcity;
    }

    // Tightness bonus.
    if bin_residual >= item_size {
        let tightness = 1.0 - ((bin_residual - item_size) as f64 / cap);
        score -= 6.0 * tightness;
    }

    // Mean-residual alignment.
    let align = ((pr as f64 - mean_residual) / cap).abs();
    score += align * (if progress > 0.2 && progress < 0.8 { 4.5 } else { 6.0 });

    // Odd small residuals are dead-space candidates.
    if pr > 0 && pr < 20 && pr % 2 == 1 {
        score += 7.0;
    }

    // Mid-stream consolidation of large absorbable residuals.
    if open_bins_count > 8 && progress > 0.25 && progress < 0.85 && pr >= 40 {
        score -= 9.0;
    }

    // Dead-space ratio shaping with next-item floor.
    if pr > 0 && next_item_size > 0 {
        let dead_threshold = (next_item_size + 12).min(bin_capacity);
        if pr < dead_threshold {
            let dead_frac = 1.0 - (pr as f64 / dead_threshold as f64);
            score += 18.0 * dead_frac * (1.0 - progress);
        } else if pr >= dead_threshold * 2 {
            score -= 8.0 + 4.0 * (1.0 - progress);
        } else if pr == next_item_size + item_size {
            score -= 5.0;
        }
    }

    // Endgame exactness.
    if progress > 0.9 && pr > 0 {
        score += pr as f64 * 0.35;
        if pr <= next_item_size.max(1) {
            score -= 20.0;
        }
    }

    // Fragment guard against typical upcoming demand.
    if pr > 0 && progress > 0.1 {
        let typical = (mean_residual * 0.5).max(8.0).min(cap * 0.5);
        if (pr as f64) < typical {
            score += 6.0 * (1.0 - (pr as f64 / typical)) * (1.0 - progress);
        }
    }

    // Exact-closure sweep with plentiful fitting bins.
    if pr == 0 && fitting_bins_count > 2 {
        score -= 12.0 * (1.0 - progress);
    }

    // Dual lookahead — repeatable fill detection.
    if next_item_size > 0 && next_item_size < pr {
        let pr2 = pr - next_item_size;
        if pr2 > 0 && item_size > 1 && pr2 % item_size == 0 && next_item_size % item_size == 0 {
            score -= 10.0;
        }
    }

    // Half-capacity residual targeting mid-stream.
    if pr > 0 && progress > 0.15 && progress < 0.9 {
        let half = cap * 0.5;
        let dist = ((pr as f64 - half) / half).abs();
        if dist < 0.25 {
            score -= 7.0 * (1.0 - dist / 0.25);
        }
    }

    // Dead-space ratio term with smooth quadratic ramp.
    if pr > 0 {
        let pr_f = pr as f64;
        let usable_floor = (next_item_size.max(1) as f64).min(cap * 0.3);
        if pr_f < usable_floor {
            let dsr = 1.0 - pr_f / usable_floor;
            score += 11.0 * dsr * dsr * (0.5 + 0.5 * (1.0 - progress));
        }
        if pr % 3 == 0 && pr >= 6 {
            score -= 5.0;
        }
        if pr % 7 == 0 && pr >= 7 {
            score -= 4.0;
        }
    }

    // Bin-count pressure valve.
    if bin_residual != bin_capacity && mean_residual > 0.0 {
        let fill = 1.0 - mean_residual / cap;
        if fill > 0.75 && fitting_bins_count > 1 {
            score -= 6.0 * (fill - 0.75) / 0.25;
        } else if fill < 0.5 && fitting_bins_count > 1 {
            score += 4.0 * (0.5 - fill) / 0.5 * (1.0 - progress);
        }
    }

    // Dead-space waste accounting with quadratic ramp.
    if pr > 0 && next_item_size > 0 && next_item_size < bin_capacity {
        let waste_frac = 1.0 - (pr.min(next_item_size) as f64 / pr as f64);
        if waste_frac > 0.5 {
            score += 9.0 * (waste_frac - 0.5) * 2.0 * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Consolidation incentive matching mean residual.
    if progress > 0.35 && pr >= next_item_size.max(1) && mean_residual > 0.0 {
        let dev = ((pr as f64 - mean_residual) / cap).abs();
        if dev < 0.08 {
            score -= 6.0 * (1.0 - dev / 0.08);
        }
    }

    // Quad-chain lookahead.
    if next_item_size > 0 && pr >= 3 * next_item_size {
        let pr3 = pr - 3 * next_item_size;
        if pr3 <= 4 {
            score -= 18.0 * (1.0 - progress);
        }
    }

    // Item+next exact pair inside residual.
    if next_item_size > 0 && item_size > 0 && pr == item_size + next_item_size {
        score -= 26.0;
    }

    // Late-stream fresh-bin restraint.
    if bin_residual == bin_capacity && progress > 0.7 {
        let exact_pair = item_size + next_item_size == bin_capacity;
        if !exact_pair && fitting_bins_count > 0 {
            score += 22.0 * (progress - 0.7) / 0.3;
        }
    }

    // Large-item protection.
    if item_size > 50 && pr > 0 && pr < 15 {
        score += 10.0 * (1.0 - pr as f64 / 15.0);
    }

    // Residual-divisibility absorbency.
    if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 {
        let chain_len = pr / next_item_size;
        if chain_len >= 2 {
            score -= (8.0 + 6.0 * chain_len.min(4) as f64) * (1.0 - 0.5 * progress);
        }
    }

    // Dead-space variance dampener.
    if pr > 0 && next_item_size > 0 && pr < next_item_size && open_bins_count > 3 {
        let unusable = (next_item_size - pr) as f64 / next_item_size as f64;
        score += 14.0 * unusable * unusable * (1.0 - progress);
    }

    // Mid-stream sweep for residuals matching common item-size sums.
    if pr > 0 && progress > 0.2 && progress < 0.9 {
        let small_sum = item_size.min(next_item_size.max(1));
        if pr == 2 * small_sum || pr == small_sum + 10 || pr == small_sum + 25 {
            score -= 7.0;
        }
    }

    // Endgame fresh-bin suppression.
    if bin_residual == bin_capacity && progress > 0.85 {
        let biggest_resid = mean_residual.max(0.0);
        if item_size as f64 <= biggest_resid.max(1.0) && fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Residual pooling.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.2 && progress < 0.85 {
        let mr = mean_residual;
        let k = (pr as f64 / mr).round().max(1.0);
        let dev = (pr as f64 - k * mr).abs() / mr;
        if dev < 0.15 && k >= 1.0 {
            score -= 10.0 * (1.0 - dev / 0.15) * (1.0 - 0.4 * progress);
        }
    }

    // Two-item lookahead tiling.
    if pr > 0 && next_item_size > 0 && mean_residual > 1.0 {
        let combo = next_item_size as f64 + mean_residual.min(cap * 0.4);
        let gap = pr as f64 - combo;
        if gap >= 0.0 && gap <= 5.0 {
            score -= (16.0 - gap) * 2.4 * (1.0 - 0.5 * progress);
        }
    }

    // Strand-risk shaping.
    if pr >= 13 && pr <= 24 {
        let crowd = if open_bins_count > 10 { 1.5 } else { 0.7 };
        score += 6.0 * crowd * (1.0 - 0.5 * progress);
    }

    // Dead-space floor tightening.
    if pr > 0 && next_item_size > 0 {
        let floor = next_item_size.max(1) as f64;
        if (pr as f64) < floor {
            let x = pr as f64 / floor;
            score += (10.0 + 14.0 * (1.0 - x) * (1.0 - x)) * (1.0 - 0.6 * progress);
        }
    }

    // Near-exact residual shaping.
    if next_item_size > 0 && pr > next_item_size && pr <= next_item_size + 3 {
        score -= (18.0 - (pr - next_item_size) as f64 * 4.0) * (1.0 - 0.5 * progress);
    }

    // Open-bin budget shaping.
    if open_bins_count as f64 > (step_index as f64) * 0.35 && pr > 0 {
        let over = open_bins_count as f64 / (step_index as f64 + 1.0);
        score += (pr as f64 / cap) * 22.0 * over.min(1.5);
    }

    // Dead-space minimization sweep.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let mr = mean_residual.min(cap);
        let usable_by_next = pr >= next_item_size;
        let usable_by_mean = (pr as f64) >= mr;
        if !usable_by_next && !usable_by_mean {
            let wasted = (next_item_size - pr) as f64;
            score += (6.0 + 0.25 * wasted) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Exact-fill cascade.
    if next_item_size > 0 && item_size > 1 && pr > next_item_size {
        let pr2 = pr - next_item_size;
        if pr2 % item_size == 0 && pr2 / item_size >= 1 && pr2 != 0 {
            score -= (10.0 + 4.0 * (pr2 / item_size).min(3) as f64) * (1.0 - 0.4 * progress);
        }
    }

    // Residual-slope steering.
    if next_item_size > 0 && pr > 0 {
        let target = next_item_size as f64;
        let dev = (pr as f64 - target) / target.max(1.0);
        if dev.abs() < 0.5 {
            score -= 9.0 * (1.0 - (dev / 0.5) * (dev / 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    // Dual-fit depth probe.
    if next_item_size > 0 && pr > next_item_size && mean_residual >= 1.0 {
        let pr2 = pr - next_item_size;
        let proxy = mean_residual.min(cap);
        if (pr2 as f64) >= proxy {
            score -= 11.0 * (1.0 - 0.5 * progress);
            if pr2 as f64 - proxy < 6.0 {
                score -= 8.0;
            }
        }
        if (pr2 as f64) < proxy && pr2 > 0 && pr2 < 10 {
            score += 9.0 * (1.0 - pr2 as f64 / 10.0);
        }
    }

    // Capacity-fraction dead-space gate.
    if pr > 0 && progress > 0.2 && progress < 0.9 {
        let lo = cap * 0.38;
        let hi = cap * 0.5;
        if (pr as f64) > lo && (pr as f64) < hi {
            let frac = 1.0 - ((pr as f64 - lo) / (hi - lo));
            score += 8.0 * frac * frac;
        }
    }

    // Dead-space recovery probe.
    if pr > 0 && mean_residual >= 2.0 {
        let mr = mean_residual.min(cap * 0.6);
        let gap = pr as f64 - mr;
        if gap >= 0.0 && gap <= 5.0 {
            score += 10.0 * (1.0 - gap / 5.0) * (1.0 - 0.4 * progress);
        } else if gap > 5.0 && gap < 12.0 {
            score -= 5.0 * (1.0 - (gap - 5.0) / 7.0) * (1.0 - 0.5 * progress);
        }
    }

    // Fitting-crowd tiebreak via harmonic-mean demand matching.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let harmonic = 2.0 * (next_item_size as f64 * mean_residual)
            / (next_item_size as f64 + mean_residual).max(1.0);
        let dev = ((pr as f64 - harmonic) / harmonic.max(1.0)).abs();
        let pressure = if fitting_bins_count >= 4 { 1.0 } else { 0.4 };
        if dev < 0.3 {
            score -= 7.0 * (1.0 - dev / 0.3) * pressure * (1.0 - 0.4 * progress);
        }
    }

    // Endgame sliver sweep.
    if progress > 0.8 && pr > 0 && next_item_size > 0 && pr < next_item_size {
        let waste = 1.0 - pr as f64 / next_item_size as f64;
        score += 12.0 * waste * waste * (progress - 0.8) / 0.2;
    }

    // Dead-space ratio compaction sweep.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.9 {
        let demand = next_item_size as f64 + mean_residual.min(cap * 0.5);
        let gap = pr as f64 - demand;
        if gap >= 0.0 && gap <= 6.0 {
            score -= (12.0 - gap) * 1.8 * (1.0 - 0.5 * progress);
        } else if gap > 6.0 && gap <= 14.0 && (gap as u32) < next_item_size {
            let sliver = gap as f64 / 14.0;
            score += 7.0 * sliver * (1.0 - 0.4 * progress);
        }
    }

    // Cross-bin compaction pull.
    if pr > 0 && mean_residual >= 3.0 && fitting_bins_count >= 2 && progress > 0.3 {
        let mr = mean_residual;
        let k = ((pr as f64) / mr).floor().max(1.0);
        let rem = pr as f64 - k * mr;
        if rem >= 0.0 && rem <= 4.0 {
            let weight = 1.0 + (progress - 0.3);
            score -= (6.0 + 4.0 * (1.0 - rem / 4.0)) * weight.min(1.7);
        } else if rem > 4.0 && rem < mr {
            score += 4.0 * (1.0 - progress) * (rem / mr);
        }
    }

    // Tight-fit crowding bonus.
    if bin_residual >= item_size {
        let slack = bin_residual - item_size;
        if slack <= 2 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= (14.0 + 8.0 * (2 - slack) as f64) * scarcity * (1.0 - 0.4 * progress);
        }
    }

    // Perfect-fit dominance gate.
    if pr == 0 {
        if bin_residual == bin_capacity {
            score += 1400.0;
        }
        score -= 30.0 * (1.0 - progress);
    }

    // Scarcity-driven fresh-bin override.
    if bin_residual == bin_capacity
        && fitting_bins_count == 1
        && next_item_size > 0
        && pr > 0
        && next_item_size > pr
        && (pr as f64) < 0.2 * cap
        && progress < 0.8
    {
        score -= 55.0 * (1.0 - progress);
    }

    // Gen 27: residual-dead-space gradient.
    if pr > 0 && next_item_size > 0 {
        let demand = (next_item_size as f64).max(mean_residual * 0.8);
        if (pr as f64) < demand {
            let dead = 1.0 - pr as f64 / demand;
            score += 15.0 * dead * dead * (1.0 - 0.5 * progress);
        }
    }

    // Gen 27: two-step exact-closure ladder.
    if next_item_size > 0 && item_size > 0 && pr >= item_size + next_item_size {
        let pr2 = pr - item_size - next_item_size;
        if pr2 == 0 {
            score -= 30.0 + 25.0 * (1.0 - progress);
        } else if pr2 <= 3 {
            score -= 16.0 * (1.0 - progress);
        }
    }

    // Gen 27: fresh-bin divisibility discount.
    if bin_residual == bin_capacity
        && item_size > 0
        && bin_capacity % item_size == 0
        && mean_residual > 0.0
        && (mean_residual as u32) % item_size != 0
        && progress > 0.15
    {
        score -= 12.0 * (1.0 - 0.6 * progress);
    }

    // Gen 27: late-stream tight-slack refinement.
    if progress > 0.66 && bin_residual >= item_size {
        let slack = bin_residual - item_size;
        if slack >= 3 && slack <= 6 && pr > 0 {
            score += 5.0 + 2.0 * (progress - 0.66) / 0.34;
        }
    }

    // Gen 28: two-chain residual tileability probe.
    if next_item_size > 1 && pr >= 2 * next_item_size {
        let pr2 = pr - 2 * next_item_size;
        if pr2 == 0 {
            score -= 20.0 + 14.0 * (1.0 - progress);
        } else if pr2 <= 2 {
            score += 6.0 * (1.0 - pr2 as f64 / 3.0);
        }
    }

    // Gen 28: fresh-bin mean-residual saturation gate.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && mean_residual > 0.0
        && (mean_residual as u32) < next_item_size
        && fitting_bins_count >= 1
        && progress > 0.1
        && progress < 0.85
    {
        let deficit = 1.0 - mean_residual / next_item_size as f64;
        score -= 18.0 * deficit * deficit * (1.0 - progress);
    }

    // Gen 28: mid-stream slack-quantization shaping.
    if pr > 0 && mean_residual >= 3.0 && progress > 0.15 && progress < 0.9 {
        let mr = mean_residual.min(cap);
        let diff = (pr as f64 - mr).abs();
        if diff <= 2.0 {
            score -= 8.0 * (1.0 - diff / 3.0) * (1.0 - 0.3 * progress);
        } else if diff > mr * 0.5 && diff < mr * 0.5 + 3.0 {
            score += 4.0 * (1.0 - progress);
        }
    }

    // Gen 29: dead-space gradient refinement — two-step demand horizon
    // (next + mean) so residuals stranding BOTH items get a sharper
    // quadratic penalty, while residuals fitting next+mean get a modest
    // reward steering compaction toward multi-item absorption.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let horizon = next_item_size as f64 + mean_residual.min(cap * 0.35);
        if (pr as f64) < horizon {
            let dead2 = 1.0 - pr as f64 / horizon;
            score += 7.0 * dead2 * dead2 * (1.0 - 0.4 * progress);
        } else if (pr as f64) >= horizon + 4.0 && (pr as f64) <= horizon + 16.0 {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // Gen 29: waste-slope fresh-bin gate — a fresh bin is only attractive
    // when opening it reduces projected dead space versus the best open
    // residual; penalize the fresh candidate when open space already
    // absorbs the pair cleanly.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && fitting_bins_count >= 1
        && item_size + next_item_size <= bin_capacity
        && progress > 0.05
    {
        let pair = (item_size + next_item_size) as f64;
        let open_leftover = (mean_residual - pair).max(0.0);
        let fresh_leftover = cap - pair;
        if open_leftover <= fresh_leftover && mean_residual >= pair {
            score += 20.0 * (1.0 - 0.5 * progress);
        } else if open_leftover > fresh_leftover + 8.0 {
            score -= 10.0 * ((open_leftover - fresh_leftover - 8.0) / cap).min(0.2) * 40.0 * (1.0 - progress);
        }
    }

    // Gen 29: endgame residual-saturation refinement — in the final
    // stretch, sharpen the near-exact closure band so residuals 1-2 units
    // above the next item beat looser fits.
    if progress > 0.75 && next_item_size > 0 && pr > next_item_size {
        let over = pr - next_item_size;
        if over <= 2 {
            score -= 14.0 * (1.0 - over as f64 / 3.0) * ((progress - 0.75) / 0.25);
        }
    }

    // Gen 30: horizon-band tightening — extend the two-step horizon with
    // a third step (next + 2*mean) so residuals that strand three items
    // receive a mild quadratic penalty, and reward residuals landing
    // within 2 units of the horizon exactly with a progress-weighted bonus.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.9 {
        let horizon = next_item_size as f64 + mean_residual.min(cap * 0.35);
        let horizon3 = horizon + mean_residual.min(cap * 0.25);
        if (pr as f64) < horizon3 {
            let dead3 = 1.0 - pr as f64 / horizon3;
            score += 4.0 * dead3 * dead3 * (1.0 - 0.5 * progress);
        }
        let exact = (pr as f64 - horizon).abs();
        if exact <= 2.0 {
            score -= 9.0 * (1.0 - exact / 3.0) * (1.0 - 0.4 * progress);
        }
    }

    // Gen 30: fresh-bin triple-tile probe — when the fresh bin can tile
    // item_size exactly k>=3 times, opening it is near-optimal; reinforce
    // with a mean-residual comparison so we only open when open residuals
    // cannot tile the item at all.
    if bin_residual == bin_capacity
        && item_size > 0
        && bin_capacity % item_size == 0
        && progress > 0.1
        && progress < 0.9
    {
        let slots = bin_capacity / item_size;
        if slots >= 3 && slots <= 5 && (mean_residual as u32) % item_size != 0 {
            score -= 10.0 * slots.min(4) as f64 * (1.0 - 0.6 * progress);
        }
    }

    // Gen 30: sliver-merging endgame sweep — residuals in the 5..=11 band
    // late in the stream are classic stranded slivers; when the mean
    // residual suggests other bins hold similar slivers, prefer consuming
    // this one now over leaving it for the endgame.
    if progress > 0.6 && pr >= 5 && pr <= 11 && mean_residual >= 3.0 {
        let similar = ((pr as f64 - mean_residual) / 4.0).abs() < 1.0;
        if similar {
            score -= 8.0 * (1.0 - 0.3 * progress);
        } else {
            score += 6.0 * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION (gen 31): mean-residual quantized closure ladder — instead
    // of only matching the mean residual exactly, reward residuals that
    // are integer multiples of the mean residual (the stream's natural
    // fill quantum), scaled by how close the multiple is to exact. This
    // steers placements so remaining space is reusable by the average
    // upcoming item, attacking dead-space directly.
    if pr > 0 && mean_residual >= 2.0 && progress > 0.1 && progress < 0.92 {
        let mr = mean_residual.min(cap * 0.5);
        let k = (pr as f64 / mr).round();
        if k >= 1.0 {
            let rem = (pr as f64 - k * mr).abs();
            if rem <= 3.0 {
                score -= (10.0 - 2.0 * rem) * (1.0 - 0.4 * progress) * (k / (k + 2.0)).max(0.4);
            } else if rem > mr * 0.6 {
                // Residual sits between quanta: likely stranded dead space.
                score += 5.0 * (1.0 - rem / (mr * 1.5)) * (1.0 - 0.5 * progress);
            }
        }
    }

    // MUTATION (gen 31): adaptive fresh-bin threshold — the parent's fixed
    // 0.38 tightness cutoff ignores stream position. Early on, opening a
    // bin is cheap; late, it strands capacity. Widen the fresh-bin
    // tolerance early, tighten it late, and couple to fitting-bin count
    // so a crowded bin field suppresses fresh openings harder.
    if bin_residual == bin_capacity && progress > 0.2 && progress < 0.85 {
        let crowd = (open_bins_count as f64 / 10.0).min(2.0);
        let tolerance = 0.38 + 0.10 * (1.0 - progress) - 0.06 * (crowd - 1.0).max(0.0);
        if (mean_residual / cap) < tolerance && fitting_bins_count > 1 {
            score += 10.0 * (tolerance - mean_residual / cap) / tolerance.max(0.01) * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION (gen 31): large-residual sink bonus — residuals above the
    // next item plus half the mean residual can still absorb a future
    // mid-size item; reward keeping them open mid-stream so they act as
    // flexible sinks rather than forcing premature tight fits.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0
        && progress > 0.25 && progress < 0.8
    {
        let sink_floor = next_item_size as f64 + 0.5 * mean_residual.min(cap * 0.4);
        if (pr as f64) >= sink_floor && (pr as f64) <= sink_floor + 10.0 {
            score -= 6.0 * (1.0 - ((pr as f64) - sink_floor) / 11.0) * (1.0 - 0.3 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    if pr == 0 {
        score -= 1280.0;
    } else if pr <= 4 {
        score -= 92.0 + (4 - pr) as f64 * 13.0;
    } else if pr < 12 {
        score += 30.0 - pr as f64;
    }

    let class_bonus: f64 = if pr % 10 == 0 {
        36.0
    } else if pr % 5 == 0 {
        18.0
    } else if pr % 2 == 0 {
        5.0
    } else {
        0.0
    };
    score -= class_bonus;

    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 178.0 + 40.0 * (1.0 - progress);
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= if slack <= 10 { 66.0 - slack as f64 * 2.6 } else { 34.0 - (slack as f64).min(30.0) * 0.5 };
        } else {
            score += (next_item_size - pr) as f64 * 0.68;
        }
        if next_item_size < pr {
            let pr2 = pr - next_item_size;
            if pr2 <= 6 {
                score -= 52.0;
            } else if pr2 == next_item_size {
                score -= 27.0;
            } else if pr2 % 10 == 0 {
                score -= 12.0;
            }
            if pr2 > 6 && next_item_size > 1 && pr2 % next_item_size == 0 {
                score -= 15.0;
            }
            if pr2 >= 2 * item_size && item_size > 0 && pr2 % item_size == 0 {
                score -= 8.0;
            }
            if pr2 >= 3 * item_size.max(1) {
                score -= 6.0;
            }
            if pr2 > 0 && mean_residual > 0.0 {
                let proxy = mean_residual.round() as u32;
                if proxy >= 1 && proxy <= pr2 {
                    score -= 9.0 * (1.0 - progress);
                }
            }
            if pr2 >= 2 * next_item_size {
                let pr3 = pr2 - 2 * next_item_size;
                if pr3 <= 3 {
                    score -= 24.0 * (1.0 - progress);
                }
            }
            if pr2 >= item_size.max(1) {
                let pr3 = pr2 - item_size.max(1);
                if pr3 <= 2 {
                    score -= 20.0 * (1.0 - progress);
                }
            }
        }
        if pr > 1 && pr == 2 * next_item_size {
            score -= 22.0;
        }
        if pr > 0 && pr < next_item_size {
            let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
            score += (7.0 + 5.0 * gap_frac) * (1.0 - progress);
        }
    } else {
        score -= 20.0;
    }

    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 66.0;
    }

    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap) < 0.38;
        let reuse_is_bad = fitting_bins_count <= 1
            || (pr > 0 && next_item_size > pr && next_item_size <= bin_capacity);
        let late_large = item_size >= 60 && progress > 0.10;
        if late_large || (tight && progress > 0.15) || reuse_is_bad {
            score -= 46.0 + 30.0 * progress;
        } else {
            score += 70.0;
        }
        if item_size <= 25 && mean_residual > cap * 0.45 {
            score += 36.0;
        }
        if open_bins_count > 12 && progress < 0.3 {
            score += 12.0;
        }
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 24.0 + 18.0 * (1.0 - progress);
        }
        if next_item_size >= bin_capacity / 2 && mean_residual < (item_size + next_item_size) as f64 {
            score -= 10.0 + 14.0 * (1.0 - progress);
        }
        if item_size + next_item_size == bin_capacity
            && mean_residual < (item_size + next_item_size) as f64
        {
            score -= 20.0;
        }
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size {
            let strand = mean_residual as u32 - item_size;
            if strand > 0 && strand < 8 && progress > 0.2 {
                score -= 14.0 + 6.0 * (1.0 - progress);
            }
        }
        if item_size + next_item_size == bin_capacity {
            score -= 34.0 + 20.0 * (1.0 - progress);
        }
        if pr > 0 && pr < item_size / 3 && item_size >= 30 {
            score -= 12.0;
        }
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size && fitting_bins_count > 1 && !late_large {
            score += 30.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 2 && item_size >= 40 {
            let best_gap = mean_residual - item_size as f64;
            if best_gap > 12.0 {
                score -= (best_gap / cap).min(0.25) * 80.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0
            && fitting_bins_count >= 1
            && item_size + next_item_size <= bin_capacity
            && mean_residual >= (item_size + next_item_size) as f64
            && progress < 0.6
        {
            score += 18.0 * (1.0 - progress);
        }
        if item_size > 0 && bin_capacity % item_size == 0 {
            let slots = bin_capacity / item_size;
            if slots >= 2 && slots <= 4 && progress > 0.1 {
                score -= 14.0 * (slots as f64).min(3.0) * (1.0 - 0.5 * progress);
            }
        }
        if mean_residual > item_size as f64 * 1.6 && progress > 0.3 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
        if next_item_size > 0
            && fitting_bins_count >= 2
            && mean_residual > 0.0
            && (item_size as f64 + next_item_size as f64 + mean_residual) <= cap
            && progress < 0.55
        {
            score += 14.0 * (1.0 - progress);
        }
        if progress > 0.7 && fitting_bins_count > 0 && !late_large {
            score += 45.0 * ((progress - 0.7) / 0.3);
        }
    }

    score -= (bin_capacity - bin_residual) as f64 * 0.16;

    if pr >= 25 && pr <= 65 {
        score -= 14.0;
    }

    score += open_bins_count as f64 * (0.2 + 0.2 * progress);

    if pr > 0 && pr < bin_capacity / 5 {
        let scarcity = if fitting_bins_count > 2 { 0.6 } else { 1.4 };
        score += (10.0 + 4.0 * progress) * scarcity;
    }

    if bin_residual >= item_size {
        let tightness = 1.0 - ((bin_residual - item_size) as f64 / cap);
        score -= 6.0 * tightness;
    }

    let align = ((pr as f64 - mean_residual) / cap).abs();
    score += align * (if progress > 0.2 && progress < 0.8 { 4.5 } else { 6.0 });

    if pr > 0 && pr < 20 && pr % 2 == 1 {
        score += 7.0;
    }

    if open_bins_count > 8 && progress > 0.25 && progress < 0.85 && pr >= 40 {
        score -= 9.0;
    }

    if pr > 0 && next_item_size > 0 {
        let dead_threshold = (next_item_size + 12).min(bin_capacity);
        if pr < dead_threshold {
            let dead_frac = 1.0 - (pr as f64 / dead_threshold as f64);
            score += 18.0 * dead_frac * (1.0 - progress);
        } else if pr >= dead_threshold * 2 {
            score -= 8.0 + 4.0 * (1.0 - progress);
        } else if pr == next_item_size + item_size {
            score -= 5.0;
        }
    }

    if progress > 0.9 && pr > 0 {
        score += pr as f64 * 0.35;
        if pr <= next_item_size.max(1) {
            score -= 20.0;
        }
    }

    if pr > 0 && progress > 0.1 {
        let typical = (mean_residual * 0.5).max(8.0).min(cap * 0.5);
        if (pr as f64) < typical {
            score += 6.0 * (1.0 - (pr as f64 / typical)) * (1.0 - progress);
        }
    }

    if pr == 0 && fitting_bins_count > 2 {
        score -= 12.0 * (1.0 - progress);
    }

    if next_item_size > 0 && next_item_size < pr {
        let pr2 = pr - next_item_size;
        if pr2 > 0 && item_size > 1 && pr2 % item_size == 0 && next_item_size % item_size == 0 {
            score -= 10.0;
        }
    }

    if pr > 0 && progress > 0.15 && progress < 0.9 {
        let half = cap * 0.5;
        let dist = ((pr as f64 - half) / half).abs();
        if dist < 0.25 {
            score -= 7.0 * (1.0 - dist / 0.25);
        }
    }

    if pr > 0 {
        let pr_f = pr as f64;
        let usable_floor = (next_item_size.max(1) as f64).min(cap * 0.3);
        if pr_f < usable_floor {
            let dsr = 1.0 - pr_f / usable_floor;
            score += 11.0 * dsr * dsr * (0.5 + 0.5 * (1.0 - progress));
        }
        if pr % 3 == 0 && pr >= 6 {
            score -= 5.0;
        }
        if pr % 7 == 0 && pr >= 7 {
            score -= 4.0;
        }
    }

    if bin_residual != bin_capacity && mean_residual > 0.0 {
        let fill = 1.0 - mean_residual / cap;
        if fill > 0.75 && fitting_bins_count > 1 {
            score -= 6.0 * (fill - 0.75) / 0.25;
        } else if fill < 0.5 && fitting_bins_count > 1 {
            score += 4.0 * (0.5 - fill) / 0.5 * (1.0 - progress);
        }
    }

    if pr > 0 && next_item_size > 0 && next_item_size < bin_capacity {
        let waste_frac = 1.0 - (pr.min(next_item_size) as f64 / pr as f64);
        if waste_frac > 0.5 {
            score += 9.0 * (waste_frac - 0.5) * 2.0 * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    if progress > 0.35 && pr >= next_item_size.max(1) && mean_residual > 0.0 {
        let dev = ((pr as f64 - mean_residual) / cap).abs();
        if dev < 0.08 {
            score -= 6.0 * (1.0 - dev / 0.08);
        }
    }

    if next_item_size > 0 && pr >= 3 * next_item_size {
        let pr3 = pr - 3 * next_item_size;
        if pr3 <= 4 {
            score -= 18.0 * (1.0 - progress);
        }
    }

    if next_item_size > 0 && item_size > 0 && pr == item_size + next_item_size {
        score -= 26.0;
    }

    if bin_residual == bin_capacity && progress > 0.7 {
        let exact_pair = item_size + next_item_size == bin_capacity;
        if !exact_pair && fitting_bins_count > 0 {
            score += 22.0 * (progress - 0.7) / 0.3;
        }
    }

    if item_size > 50 && pr > 0 && pr < 15 {
        score += 10.0 * (1.0 - pr as f64 / 15.0);
    }

    if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 {
        let chain_len = pr / next_item_size;
        if chain_len >= 2 {
            score -= (8.0 + 6.0 * chain_len.min(4) as f64) * (1.0 - 0.5 * progress);
        }
    }

    if pr > 0 && next_item_size > 0 && pr < next_item_size && open_bins_count > 3 {
        let unusable = (next_item_size - pr) as f64 / next_item_size as f64;
        score += 14.0 * unusable * unusable * (1.0 - progress);
    }

    if pr > 0 && progress > 0.2 && progress < 0.9 {
        let small_sum = item_size.min(next_item_size.max(1));
        if pr == 2 * small_sum || pr == small_sum + 10 || pr == small_sum + 25 {
            score -= 7.0;
        }
    }

    if bin_residual == bin_capacity && progress > 0.85 {
        let biggest_resid = mean_residual.max(0.0);
        if item_size as f64 <= biggest_resid.max(1.0) && fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    if pr > 0 && mean_residual >= 4.0 && progress > 0.2 && progress < 0.85 {
        let mr = mean_residual;
        let k = (pr as f64 / mr).round().max(1.0);
        let dev = (pr as f64 - k * mr).abs() / mr;
        if dev < 0.15 && k >= 1.0 {
            score -= 10.0 * (1.0 - dev / 0.15) * (1.0 - 0.4 * progress);
        }
    }

    if pr > 0 && next_item_size > 0 && mean_residual > 1.0 {
        let combo = next_item_size as f64 + mean_residual.min(cap * 0.4);
        let gap = pr as f64 - combo;
        if gap >= 0.0 && gap <= 5.0 {
            score -= (16.0 - gap) * 2.4 * (1.0 - 0.5 * progress);
        }
    }

    if pr >= 13 && pr <= 24 {
        let crowd = if open_bins_count > 10 { 1.5 } else { 0.7 };
        score += 6.0 * crowd * (1.0 - 0.5 * progress);
    }

    if pr > 0 && next_item_size > 0 {
        let floor = next_item_size.max(1) as f64;
        if (pr as f64) < floor {
            let x = pr as f64 / floor;
            score += (10.0 + 14.0 * (1.0 - x) * (1.0 - x)) * (1.0 - 0.6 * progress);
        }
    }

    if next_item_size > 0 && pr > next_item_size && pr <= next_item_size + 3 {
        score -= (18.0 - (pr - next_item_size) as f64 * 4.0) * (1.0 - 0.5 * progress);
    }

    if open_bins_count as f64 > (step_index as f64) * 0.35 && pr > 0 {
        let over = open_bins_count as f64 / (step_index as f64 + 1.0);
        score += (pr as f64 / cap) * 22.0 * over.min(1.5);
    }

    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let mr = mean_residual.min(cap);
        let usable_by_next = pr >= next_item_size;
        let usable_by_mean = (pr as f64) >= mr;
        if !usable_by_next && !usable_by_mean {
            let wasted = (next_item_size - pr) as f64;
            score += (6.0 + 0.25 * wasted) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    if next_item_size > 0 && item_size > 1 && pr > next_item_size {
        let pr2 = pr - next_item_size;
        if pr2 % item_size == 0 && pr2 / item_size >= 1 && pr2 != 0 {
            score -= (10.0 + 4.0 * (pr2 / item_size).min(3) as f64) * (1.0 - 0.4 * progress);
        }
    }

    if next_item_size > 0 && pr > 0 {
        let target = next_item_size as f64;
        let dev = (pr as f64 - target) / target.max(1.0);
        if dev.abs() < 0.5 {
            score -= 9.0 * (1.0 - (dev / 0.5) * (dev / 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    if next_item_size > 0 && pr > next_item_size && mean_residual >= 1.0 {
        let pr2 = pr - next_item_size;
        let proxy = mean_residual.min(cap);
        if (pr2 as f64) >= proxy {
            score -= 11.0 * (1.0 - 0.5 * progress);
            if pr2 as f64 - proxy < 6.0 {
                score -= 8.0;
            }
        }
        if (pr2 as f64) < proxy && pr2 > 0 && pr2 < 10 {
            score += 9.0 * (1.0 - pr2 as f64 / 10.0);
        }
    }

    if pr > 0 && progress > 0.2 && progress < 0.9 {
        let lo = cap * 0.38;
        let hi = cap * 0.5;
        if (pr as f64) > lo && (pr as f64) < hi {
            let frac = 1.0 - ((pr as f64 - lo) / (hi - lo));
            score += 8.0 * frac * frac;
        }
    }

    if pr > 0 && mean_residual >= 2.0 {
        let mr = mean_residual.min(cap * 0.6);
        let gap = pr as f64 - mr;
        if gap >= 0.0 && gap <= 5.0 {
            score += 10.0 * (1.0 - gap / 5.0) * (1.0 - 0.4 * progress);
        } else if gap > 5.0 && gap < 12.0 {
            score -= 5.0 * (1.0 - (gap - 5.0) / 7.0) * (1.0 - 0.5 * progress);
        }
    }

    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let harmonic = 2.0 * (next_item_size as f64 * mean_residual)
            / (next_item_size as f64 + mean_residual).max(1.0);
        let dev = ((pr as f64 - harmonic) / harmonic.max(1.0)).abs();
        let pressure = if fitting_bins_count >= 4 { 1.0 } else { 0.4 };
        if dev < 0.3 {
            score -= 7.0 * (1.0 - dev / 0.3) * pressure * (1.0 - 0.4 * progress);
        }
    }

    if progress > 0.8 && pr > 0 && next_item_size > 0 && pr < next_item_size {
        let waste = 1.0 - pr as f64 / next_item_size as f64;
        score += 12.0 * waste * waste * (progress - 0.8) / 0.2;
    }

    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.9 {
        let demand = next_item_size as f64 + mean_residual.min(cap * 0.5);
        let gap = pr as f64 - demand;
        if gap >= 0.0 && gap <= 6.0 {
            score -= (12.0 - gap) * 1.8 * (1.0 - 0.5 * progress);
        } else if gap > 6.0 && gap <= 14.0 && (gap as u32) < next_item_size {
            let sliver = gap as f64 / 14.0;
            score += 7.0 * sliver * (1.0 - 0.4 * progress);
        }
    }

    if pr > 0 && mean_residual >= 3.0 && fitting_bins_count >= 2 && progress > 0.3 {
        let mr = mean_residual;
        let k = ((pr as f64) / mr).floor().max(1.0);
        let rem = pr as f64 - k * mr;
        if rem >= 0.0 && rem <= 4.0 {
            let weight = 1.0 + (progress - 0.3);
            score -= (6.0 + 4.0 * (1.0 - rem / 4.0)) * weight.min(1.7);
        } else if rem > 4.0 && rem < mr {
            score += 4.0 * (1.0 - progress) * (rem / mr);
        }
    }

    if bin_residual >= item_size {
        let slack = bin_residual - item_size;
        if slack <= 2 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= (14.0 + 8.0 * (2 - slack) as f64) * scarcity * (1.0 - 0.4 * progress);
        }
    }

    if pr == 0 {
        if bin_residual == bin_capacity {
            score += 1400.0;
        }
        score -= 30.0 * (1.0 - progress);
    }

    if bin_residual == bin_capacity
        && fitting_bins_count == 1
        && next_item_size > 0
        && pr > 0
        && next_item_size > pr
        && (pr as f64) < 0.2 * cap
        && progress < 0.8
    {
        score -= 55.0 * (1.0 - progress);
    }

    if pr > 0 && next_item_size > 0 {
        let demand = (next_item_size as f64).max(mean_residual * 0.8);
        if (pr as f64) < demand {
            let dead = 1.0 - pr as f64 / demand;
            score += 15.0 * dead * dead * (1.0 - 0.5 * progress);
        }
    }

    if next_item_size > 0 && item_size > 0 && pr >= item_size + next_item_size {
        let pr2 = pr - item_size - next_item_size;
        if pr2 == 0 {
            score -= 30.0 + 25.0 * (1.0 - progress);
        } else if pr2 <= 3 {
            score -= 16.0 * (1.0 - progress);
        }
    }

    if bin_residual == bin_capacity
        && item_size > 0
        && bin_capacity % item_size == 0
        && mean_residual > 0.0
        && (mean_residual as u32) % item_size != 0
        && progress > 0.15
    {
        score -= 12.0 * (1.0 - 0.6 * progress);
    }

    if progress > 0.66 && bin_residual >= item_size {
        let slack = bin_residual - item_size;
        if slack >= 3 && slack <= 6 && pr > 0 {
            score += 5.0 + 2.0 * (progress - 0.66) / 0.34;
        }
    }

    if next_item_size > 1 && pr >= 2 * next_item_size {
        let pr2 = pr - 2 * next_item_size;
        if pr2 == 0 {
            score -= 20.0 + 14.0 * (1.0 - progress);
        } else if pr2 <= 2 {
            score += 6.0 * (1.0 - pr2 as f64 / 3.0);
        }
    }

    if bin_residual == bin_capacity
        && next_item_size > 0
        && mean_residual > 0.0
        && (mean_residual as u32) < next_item_size
        && fitting_bins_count >= 1
        && progress > 0.1
        && progress < 0.85
    {
        let deficit = 1.0 - mean_residual / next_item_size as f64;
        score -= 18.0 * deficit * deficit * (1.0 - progress);
    }

    if pr > 0 && mean_residual >= 3.0 && progress > 0.15 && progress < 0.9 {
        let mr = mean_residual.min(cap);
        let diff = (pr as f64 - mr).abs();
        if diff <= 2.0 {
            score -= 8.0 * (1.0 - diff / 3.0) * (1.0 - 0.3 * progress);
        } else if diff > mr * 0.5 && diff < mr * 0.5 + 3.0 {
            score += 4.0 * (1.0 - progress);
        }
    }

    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let horizon = next_item_size as f64 + mean_residual.min(cap * 0.35);
        if (pr as f64) < horizon {
            let dead2 = 1.0 - pr as f64 / horizon;
            score += 7.0 * dead2 * dead2 * (1.0 - 0.4 * progress);
        } else if (pr as f64) >= horizon + 4.0 && (pr as f64) <= horizon + 16.0 {
            score -= 5.0 * (1.0 - progress);
        }
    }

    if bin_residual == bin_capacity
        && next_item_size > 0
        && fitting_bins_count >= 1
        && item_size + next_item_size <= bin_capacity
        && progress > 0.05
    {
        let pair = (item_size + next_item_size) as f64;
        let open_leftover = (mean_residual - pair).max(0.0);
        let fresh_leftover = cap - pair;
        if open_leftover <= fresh_leftover && mean_residual >= pair {
            score += 20.0 * (1.0 - 0.5 * progress);
        } else if open_leftover > fresh_leftover + 8.0 {
            score -= 10.0 * ((open_leftover - fresh_leftover - 8.0) / cap).min(0.2) * 40.0 * (1.0 - progress);
        }
    }

    if progress > 0.75 && next_item_size > 0 && pr > next_item_size {
        let over = pr - next_item_size;
        if over <= 2 {
            score -= 14.0 * (1.0 - over as f64 / 3.0) * ((progress - 0.75) / 0.25);
        }
    }

    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.9 {
        let horizon = next_item_size as f64 + mean_residual.min(cap * 0.35);
        let horizon3 = horizon + mean_residual.min(cap * 0.25);
        if (pr as f64) < horizon3 {
            let dead3 = 1.0 - pr as f64 / horizon3;
            score += 4.0 * dead3 * dead3 * (1.0 - 0.5 * progress);
        }
        let exact = (pr as f64 - horizon).abs();
        if exact <= 2.0 {
            score -= 9.0 * (1.0 - exact / 3.0) * (1.0 - 0.4 * progress);
        }
    }

    if bin_residual == bin_capacity
        && item_size > 0
        && bin_capacity % item_size == 0
        && progress > 0.1
        && progress < 0.9
    {
        let slots = bin_capacity / item_size;
        if slots >= 3 && slots <= 5 && (mean_residual as u32) % item_size != 0 {
            score -= 10.0 * slots.min(4) as f64 * (1.0 - 0.6 * progress);
        }
    }

    if progress > 0.6 && pr >= 5 && pr <= 11 && mean_residual >= 3.0 {
        let similar = ((pr as f64 - mean_residual) / 4.0).abs() < 1.0;
        if similar {
            score -= 8.0 * (1.0 - 0.3 * progress);
        } else {
            score += 6.0 * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION (gen 31): fresh-bin pair-closure arbitration — when the
    // fresh bin would close EXACTLY with item+next (zero waste) while the
    // best open residual leaves a stranded sliver after absorbing the
    // item, opening a new bin is strictly better. Conversely, when the
    // open residual can absorb item+next within 3 units of closure,
    // strongly suppress the fresh candidate to prevent proliferation.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && item_size > 0
        && fitting_bins_count >= 1
        && progress > 0.05
        && progress < 0.9
    {
        let pair = item_size + next_item_size;
        if pair == bin_capacity {
            let open_absorbs_pair = (mean_residual as u32) >= pair;
            if !open_absorbs_pair {
                score -= 26.0 + 18.0 * (1.0 - progress);
            }
        } else if (mean_residual as u32) >= pair {
            let open_leftover = mean_residual as u32 - pair;
            if open_leftover <= 3 {
                score += 24.0 * (1.0 - 0.4 * progress);
            } else if open_leftover <= 10 {
                score += 8.0 * (1.0 - open_leftover as f64 / 11.0);
            }
        }
    }

    // MUTATION (gen 31): residual-quantization ladder — residuals that
    // are an exact multiple of a small common divisor (4 or 6) tile
    // cleanly against typical small items; reward them mid-stream so
    // compaction steers toward reusable space shapes.
    if pr > 0 && progress > 0.15 && progress < 0.9 {
        if pr % 4 == 0 && pr >= 8 {
            score -= 6.0 * (1.0 - 0.4 * progress);
        }
        if pr % 6 == 0 && pr >= 12 {
            score -= 5.0 * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 31): dead-space ratio slope refinement — sharpen the
    // gen-27 demand gradient near the top of the dead band (residual just
    // below demand) so near-miss residuals are penalized less than deep
    // dead space, encouraging selection of the closest fit.
    if pr > 0 && next_item_size > 0 {
        let demand = (next_item_size as f64).max(mean_residual * 0.8);
        if (pr as f64) < demand {
            let dead = 1.0 - pr as f64 / demand;
            if dead < 0.25 {
                score += 6.0 * dead * (1.0 - 0.5 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Sharpened perfect/near-perfect closure rewards.
    if pr == 0 {
        score -= 1280.0;
    } else if pr <= 4 {
        score -= 92.0 + (4 - pr) as f64 * 13.0;
    } else if pr < 12 {
        score += 30.0 - pr as f64;
    }

    // Harmonic residue classes.
    let class_bonus: f64 = if pr % 10 == 0 {
        36.0
    } else if pr % 5 == 0 {
        18.0
    } else if pr % 2 == 0 {
        5.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Lookahead: next item fit quality into post-placement residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 178.0 + 40.0 * (1.0 - progress);
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= if slack <= 10 { 66.0 - slack as f64 * 2.6 } else { 34.0 - (slack as f64).min(30.0) * 0.5 };
        } else {
            score += (next_item_size - pr) as f64 * 0.68;
        }
        if next_item_size < pr {
            let pr2 = pr - next_item_size;
            if pr2 <= 6 {
                score -= 52.0;
            } else if pr2 == next_item_size {
                score -= 27.0;
            } else if pr2 % 10 == 0 {
                score -= 12.0;
            }
            if pr2 > 6 && next_item_size > 1 && pr2 % next_item_size == 0 {
                score -= 15.0;
            }
            if pr2 >= 2 * item_size && item_size > 0 && pr2 % item_size == 0 {
                score -= 8.0;
            }
            if pr2 >= 3 * item_size.max(1) {
                score -= 6.0;
            }
            // Chain lookahead via mean-residual proxy.
            if pr2 > 0 && mean_residual > 0.0 {
                let proxy = mean_residual.round() as u32;
                if proxy >= 1 && proxy <= pr2 {
                    score -= 9.0 * (1.0 - progress);
                }
            }
            // Triple-chain closure.
            if pr2 >= 2 * next_item_size {
                let pr3 = pr2 - 2 * next_item_size;
                if pr3 <= 3 {
                    score -= 24.0 * (1.0 - progress);
                }
            }
            // next + item leaves near-perfect closure.
            if pr2 >= item_size.max(1) {
                let pr3 = pr2 - item_size.max(1);
                if pr3 <= 2 {
                    score -= 20.0 * (1.0 - progress);
                }
            }
        }
        // Pair-absorbency.
        if pr > 1 && pr == 2 * next_item_size {
            score -= 22.0;
        }
        // Stranded residual just below next item.
        if pr > 0 && pr < next_item_size {
            let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
            score += (7.0 + 5.0 * gap_frac) * (1.0 - progress);
        }
    } else {
        // Last item: any bin that fits is fine; prefer tightest.
        score -= 20.0;
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 66.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap) < 0.38;
        let reuse_is_bad = fitting_bins_count <= 1
            || (pr > 0 && next_item_size > pr && next_item_size <= bin_capacity);
        let late_large = item_size >= 60 && progress > 0.10;
        if late_large || (tight && progress > 0.15) || reuse_is_bad {
            score -= 46.0 + 30.0 * progress;
        } else {
            score += 70.0;
        }
        if item_size <= 25 && mean_residual > cap * 0.45 {
            score += 36.0;
        }
        if open_bins_count > 12 && progress < 0.3 {
            score += 12.0;
        }
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 24.0 + 18.0 * (1.0 - progress);
        }
        if next_item_size >= bin_capacity / 2 && mean_residual < (item_size + next_item_size) as f64 {
            score -= 10.0 + 14.0 * (1.0 - progress);
        }
        if item_size + next_item_size == bin_capacity
            && mean_residual < (item_size + next_item_size) as f64
        {
            score -= 20.0;
        }
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size {
            let strand = mean_residual as u32 - item_size;
            if strand > 0 && strand < 8 && progress > 0.2 {
                score -= 14.0 + 6.0 * (1.0 - progress);
            }
        }
        // Fresh-bin exact-pair bonus.
        if item_size + next_item_size == bin_capacity {
            score -= 34.0 + 20.0 * (1.0 - progress);
        }
        if pr > 0 && pr < item_size / 3 && item_size >= 30 {
            score -= 12.0;
        }
        // Fresh-bin viability gate.
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size && fitting_bins_count > 1 && !late_large {
            score += 30.0 * (1.0 - progress);
        }
        // Fresh-bin scarcity coupling.
        if fitting_bins_count >= 2 && item_size >= 40 {
            let best_gap = mean_residual - item_size as f64;
            if best_gap > 12.0 {
                score -= (best_gap / cap).min(0.25) * 80.0 * (1.0 - progress);
            }
        }
        // Fresh-bin only when the item cannot tile any open residual
        // with the next item — otherwise fresh space fragments the stream.
        if next_item_size > 0
            && fitting_bins_count >= 1
            && item_size + next_item_size <= bin_capacity
            && mean_residual >= (item_size + next_item_size) as f64
            && progress < 0.6
        {
            score += 18.0 * (1.0 - progress);
        }
        // Fresh-bin slot-arithmetic probe.
        if item_size > 0 && bin_capacity % item_size == 0 {
            let slots = bin_capacity / item_size;
            if slots >= 2 && slots <= 4 && progress > 0.1 {
                score -= 14.0 * (slots as f64).min(3.0) * (1.0 - 0.5 * progress);
            }
        }
        // Fresh-bin residual-mirror check.
        if mean_residual > item_size as f64 * 1.6 && progress > 0.3 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
        // Fresh-bin dead-space forecast.
        if next_item_size > 0
            && fitting_bins_count >= 2
            && mean_residual > 0.0
            && (item_size as f64 + next_item_size as f64 + mean_residual) <= cap
            && progress < 0.55
        {
            score += 14.0 * (1.0 - progress);
        }
        // Endgame fresh-bin hard gate.
        if progress > 0.7 && fitting_bins_count > 0 && !late_large {
            score += 45.0 * ((progress - 0.7) / 0.3);
        }
    }

    // Best-fit bias.
    score -= (bin_capacity - bin_residual) as f64 * 0.16;

    // Flexible mid-range residual target.
    if pr >= 25 && pr <= 65 {
        score -= 14.0;
    }

    // Proliferation penalty.
    score += open_bins_count as f64 * (0.2 + 0.2 * progress);

    // Waste-avoidance for tiny residuals.
    if pr > 0 && pr < bin_capacity / 5 {
        let scarcity = if fitting_bins_count > 2 { 0.6 } else { 1.4 };
        score += (10.0 + 4.0 * progress) * scarcity;
    }

    // Tightness bonus.
    if bin_residual >= item_size {
        let tightness = 1.0 - ((bin_residual - item_size) as f64 / cap);
        score -= 6.0 * tightness;
    }

    // Mean-residual alignment.
    let align = ((pr as f64 - mean_residual) / cap).abs();
    score += align * (if progress > 0.2 && progress < 0.8 { 4.5 } else { 6.0 });

    // Odd small residuals are dead-space candidates.
    if pr > 0 && pr < 20 && pr % 2 == 1 {
        score += 7.0;
    }

    // Mid-stream consolidation of large absorbable residuals.
    if open_bins_count > 8 && progress > 0.25 && progress < 0.85 && pr >= 40 {
        score -= 9.0;
    }

    // Dead-space ratio shaping with next-item floor.
    if pr > 0 && next_item_size > 0 {
        let dead_threshold = (next_item_size + 12).min(bin_capacity);
        if pr < dead_threshold {
            let dead_frac = 1.0 - (pr as f64 / dead_threshold as f64);
            score += 18.0 * dead_frac * (1.0 - progress);
        } else if pr >= dead_threshold * 2 {
            score -= 8.0 + 4.0 * (1.0 - progress);
        } else if pr == next_item_size + item_size {
            score -= 5.0;
        }
    }

    // Endgame exactness.
    if progress > 0.9 && pr > 0 {
        score += pr as f64 * 0.35;
        if pr <= next_item_size.max(1) {
            score -= 20.0;
        }
    }

    // Fragment guard against typical upcoming demand.
    if pr > 0 && progress > 0.1 {
        let typical = (mean_residual * 0.5).max(8.0).min(cap * 0.5);
        if (pr as f64) < typical {
            score += 6.0 * (1.0 - (pr as f64 / typical)) * (1.0 - progress);
        }
    }

    // Exact-closure sweep with plentiful fitting bins.
    if pr == 0 && fitting_bins_count > 2 {
        score -= 12.0 * (1.0 - progress);
    }

    // Dual lookahead — repeatable fill detection.
    if next_item_size > 0 && next_item_size < pr {
        let pr2 = pr - next_item_size;
        if pr2 > 0 && item_size > 1 && pr2 % item_size == 0 && next_item_size % item_size == 0 {
            score -= 10.0;
        }
    }

    // Half-capacity residual targeting mid-stream.
    if pr > 0 && progress > 0.15 && progress < 0.9 {
        let half = cap * 0.5;
        let dist = ((pr as f64 - half) / half).abs();
        if dist < 0.25 {
            score -= 7.0 * (1.0 - dist / 0.25);
        }
    }

    // Dead-space ratio term with smooth quadratic ramp.
    if pr > 0 {
        let pr_f = pr as f64;
        let usable_floor = (next_item_size.max(1) as f64).min(cap * 0.3);
        if pr_f < usable_floor {
            let dsr = 1.0 - pr_f / usable_floor;
            score += 11.0 * dsr * dsr * (0.5 + 0.5 * (1.0 - progress));
        }
        if pr % 3 == 0 && pr >= 6 {
            score -= 5.0;
        }
        if pr % 7 == 0 && pr >= 7 {
            score -= 4.0;
        }
    }

    // Bin-count pressure valve.
    if bin_residual != bin_capacity && mean_residual > 0.0 {
        let fill = 1.0 - mean_residual / cap;
        if fill > 0.75 && fitting_bins_count > 1 {
            score -= 6.0 * (fill - 0.75) / 0.25;
        } else if fill < 0.5 && fitting_bins_count > 1 {
            score += 4.0 * (0.5 - fill) / 0.5 * (1.0 - progress);
        }
    }

    // Dead-space waste accounting with quadratic ramp.
    if pr > 0 && next_item_size > 0 && next_item_size < bin_capacity {
        let waste_frac = 1.0 - (pr.min(next_item_size) as f64 / pr as f64);
        if waste_frac > 0.5 {
            score += 9.0 * (waste_frac - 0.5) * 2.0 * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Consolidation incentive matching mean residual.
    if progress > 0.35 && pr >= next_item_size.max(1) && mean_residual > 0.0 {
        let dev = ((pr as f64 - mean_residual) / cap).abs();
        if dev < 0.08 {
            score -= 6.0 * (1.0 - dev / 0.08);
        }
    }

    // Quad-chain lookahead.
    if next_item_size > 0 && pr >= 3 * next_item_size {
        let pr3 = pr - 3 * next_item_size;
        if pr3 <= 4 {
            score -= 18.0 * (1.0 - progress);
        }
    }

    // Item+next exact pair inside residual.
    if next_item_size > 0 && item_size > 0 && pr == item_size + next_item_size {
        score -= 26.0;
    }

    // Late-stream fresh-bin restraint.
    if bin_residual == bin_capacity && progress > 0.7 {
        let exact_pair = item_size + next_item_size == bin_capacity;
        if !exact_pair && fitting_bins_count > 0 {
            score += 22.0 * (progress - 0.7) / 0.3;
        }
    }

    // Large-item protection.
    if item_size > 50 && pr > 0 && pr < 15 {
        score += 10.0 * (1.0 - pr as f64 / 15.0);
    }

    // Residual-divisibility absorbency.
    if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 {
        let chain_len = pr / next_item_size;
        if chain_len >= 2 {
            score -= (8.0 + 6.0 * chain_len.min(4) as f64) * (1.0 - 0.5 * progress);
        }
    }

    // Dead-space variance dampener.
    if pr > 0 && next_item_size > 0 && pr < next_item_size && open_bins_count > 3 {
        let unusable = (next_item_size - pr) as f64 / next_item_size as f64;
        score += 14.0 * unusable * unusable * (1.0 - progress);
    }

    // Mid-stream sweep for residuals matching common item-size sums.
    if pr > 0 && progress > 0.2 && progress < 0.9 {
        let small_sum = item_size.min(next_item_size.max(1));
        if pr == 2 * small_sum || pr == small_sum + 10 || pr == small_sum + 25 {
            score -= 7.0;
        }
    }

    // Endgame fresh-bin suppression.
    if bin_residual == bin_capacity && progress > 0.85 {
        let biggest_resid = mean_residual.max(0.0);
        if item_size as f64 <= biggest_resid.max(1.0) && fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Residual pooling.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.2 && progress < 0.85 {
        let mr = mean_residual;
        let k = (pr as f64 / mr).round().max(1.0);
        let dev = (pr as f64 - k * mr).abs() / mr;
        if dev < 0.15 && k >= 1.0 {
            score -= 10.0 * (1.0 - dev / 0.15) * (1.0 - 0.4 * progress);
        }
    }

    // Two-item lookahead tiling.
    if pr > 0 && next_item_size > 0 && mean_residual > 1.0 {
        let combo = next_item_size as f64 + mean_residual.min(cap * 0.4);
        let gap = pr as f64 - combo;
        if gap >= 0.0 && gap <= 5.0 {
            score -= (16.0 - gap) * 2.4 * (1.0 - 0.5 * progress);
        }
    }

    // Strand-risk shaping.
    if pr >= 13 && pr <= 24 {
        let crowd = if open_bins_count > 10 { 1.5 } else { 0.7 };
        score += 6.0 * crowd * (1.0 - 0.5 * progress);
    }

    // Dead-space floor tightening.
    if pr > 0 && next_item_size > 0 {
        let floor = next_item_size.max(1) as f64;
        if (pr as f64) < floor {
            let x = pr as f64 / floor;
            score += (10.0 + 14.0 * (1.0 - x) * (1.0 - x)) * (1.0 - 0.6 * progress);
        }
    }

    // Near-exact residual shaping.
    if next_item_size > 0 && pr > next_item_size && pr <= next_item_size + 3 {
        score -= (18.0 - (pr - next_item_size) as f64 * 4.0) * (1.0 - 0.5 * progress);
    }

    // Open-bin budget shaping.
    if open_bins_count as f64 > (step_index as f64) * 0.35 && pr > 0 {
        let over = open_bins_count as f64 / (step_index as f64 + 1.0);
        score += (pr as f64 / cap) * 22.0 * over.min(1.5);
    }

    // Dead-space minimization sweep.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let mr = mean_residual.min(cap);
        let usable_by_next = pr >= next_item_size;
        let usable_by_mean = (pr as f64) >= mr;
        if !usable_by_next && !usable_by_mean {
            let wasted = (next_item_size - pr) as f64;
            score += (6.0 + 0.25 * wasted) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Exact-fill cascade.
    if next_item_size > 0 && item_size > 1 && pr > next_item_size {
        let pr2 = pr - next_item_size;
        if pr2 % item_size == 0 && pr2 / item_size >= 1 && pr2 != 0 {
            score -= (10.0 + 4.0 * (pr2 / item_size).min(3) as f64) * (1.0 - 0.4 * progress);
        }
    }

    // Residual-slope steering.
    if next_item_size > 0 && pr > 0 {
        let target = next_item_size as f64;
        let dev = (pr as f64 - target) / target.max(1.0);
        if dev.abs() < 0.5 {
            score -= 9.0 * (1.0 - (dev / 0.5) * (dev / 0.5)) * (1.0 - 0.5 * progress);
        }
    }

    // Dual-fit depth probe.
    if next_item_size > 0 && pr > next_item_size && mean_residual >= 1.0 {
        let pr2 = pr - next_item_size;
        let proxy = mean_residual.min(cap);
        if (pr2 as f64) >= proxy {
            score -= 11.0 * (1.0 - 0.5 * progress);
            if pr2 as f64 - proxy < 6.0 {
                score -= 8.0;
            }
        }
        if (pr2 as f64) < proxy && pr2 > 0 && pr2 < 10 {
            score += 9.0 * (1.0 - pr2 as f64 / 10.0);
        }
    }

    // Capacity-fraction dead-space gate.
    if pr > 0 && progress > 0.2 && progress < 0.9 {
        let lo = cap * 0.38;
        let hi = cap * 0.5;
        if (pr as f64) > lo && (pr as f64) < hi {
            let frac = 1.0 - ((pr as f64 - lo) / (hi - lo));
            score += 8.0 * frac * frac;
        }
    }

    // Dead-space recovery probe.
    if pr > 0 && mean_residual >= 2.0 {
        let mr = mean_residual.min(cap * 0.6);
        let gap = pr as f64 - mr;
        if gap >= 0.0 && gap <= 5.0 {
            score += 10.0 * (1.0 - gap / 5.0) * (1.0 - 0.4 * progress);
        } else if gap > 5.0 && gap < 12.0 {
            score -= 5.0 * (1.0 - (gap - 5.0) / 7.0) * (1.0 - 0.5 * progress);
        }
    }

    // Fitting-crowd tiebreak via harmonic-mean demand matching.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let harmonic = 2.0 * (next_item_size as f64 * mean_residual)
            / (next_item_size as f64 + mean_residual).max(1.0);
        let dev = ((pr as f64 - harmonic) / harmonic.max(1.0)).abs();
        let pressure = if fitting_bins_count >= 4 { 1.0 } else { 0.4 };
        if dev < 0.3 {
            score -= 7.0 * (1.0 - dev / 0.3) * pressure * (1.0 - 0.4 * progress);
        }
    }

    // Endgame sliver sweep.
    if progress > 0.8 && pr > 0 && next_item_size > 0 && pr < next_item_size {
        let waste = 1.0 - pr as f64 / next_item_size as f64;
        score += 12.0 * waste * waste * (progress - 0.8) / 0.2;
    }

    // Dead-space ratio compaction sweep.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.9 {
        let demand = next_item_size as f64 + mean_residual.min(cap * 0.5);
        let gap = pr as f64 - demand;
        if gap >= 0.0 && gap <= 6.0 {
            score -= (12.0 - gap) * 1.8 * (1.0 - 0.5 * progress);
        } else if gap > 6.0 && gap <= 14.0 && (gap as u32) < next_item_size {
            let sliver = gap as f64 / 14.0;
            score += 7.0 * sliver * (1.0 - 0.4 * progress);
        }
    }

    // Cross-bin compaction pull.
    if pr > 0 && mean_residual >= 3.0 && fitting_bins_count >= 2 && progress > 0.3 {
        let mr = mean_residual;
        let k = ((pr as f64) / mr).floor().max(1.0);
        let rem = pr as f64 - k * mr;
        if rem >= 0.0 && rem <= 4.0 {
            let weight = 1.0 + (progress - 0.3);
            score -= (6.0 + 4.0 * (1.0 - rem / 4.0)) * weight.min(1.7);
        } else if rem > 4.0 && rem < mr {
            score += 4.0 * (1.0 - progress) * (rem / mr);
        }
    }

    // Tight-fit crowding bonus.
    if bin_residual >= item_size {
        let slack = bin_residual - item_size;
        if slack <= 2 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= (14.0 + 8.0 * (2 - slack) as f64) * scarcity * (1.0 - 0.4 * progress);
        }
    }

    // Perfect-fit dominance gate.
    if pr == 0 {
        if bin_residual == bin_capacity {
            score += 1400.0;
        }
        score -= 30.0 * (1.0 - progress);
    }

    // Scarcity-driven fresh-bin override.
    if bin_residual == bin_capacity
        && fitting_bins_count == 1
        && next_item_size > 0
        && pr > 0
        && next_item_size > pr
        && (pr as f64) < 0.2 * cap
        && progress < 0.8
    {
        score -= 55.0 * (1.0 - progress);
    }

    // Gen 27: residual-dead-space gradient.
    if pr > 0 && next_item_size > 0 {
        let demand = (next_item_size as f64).max(mean_residual * 0.8);
        if (pr as f64) < demand {
            let dead = 1.0 - pr as f64 / demand;
            score += 15.0 * dead * dead * (1.0 - 0.5 * progress);
        }
    }

    // Gen 27: two-step exact-closure ladder.
    if next_item_size > 0 && item_size > 0 && pr >= item_size + next_item_size {
        let pr2 = pr - item_size - next_item_size;
        if pr2 == 0 {
            score -= 30.0 + 25.0 * (1.0 - progress);
        } else if pr2 <= 3 {
            score -= 16.0 * (1.0 - progress);
        }
    }

    // Gen 27: fresh-bin divisibility discount.
    if bin_residual == bin_capacity
        && item_size > 0
        && bin_capacity % item_size == 0
        && mean_residual > 0.0
        && (mean_residual as u32) % item_size != 0
        && progress > 0.15
    {
        score -= 12.0 * (1.0 - 0.6 * progress);
    }

    // Gen 27: late-stream tight-slack refinement.
    if progress > 0.66 && bin_residual >= item_size {
        let slack = bin_residual - item_size;
        if slack >= 3 && slack <= 6 && pr > 0 {
            score += 5.0 + 2.0 * (progress - 0.66) / 0.34;
        }
    }

    // Gen 28: two-chain residual tileability probe.
    if next_item_size > 1 && pr >= 2 * next_item_size {
        let pr2 = pr - 2 * next_item_size;
        if pr2 == 0 {
            score -= 20.0 + 14.0 * (1.0 - progress);
        } else if pr2 <= 2 {
            score += 6.0 * (1.0 - pr2 as f64 / 3.0);
        }
    }

    // Gen 28: fresh-bin mean-residual saturation gate.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && mean_residual > 0.0
        && (mean_residual as u32) < next_item_size
        && fitting_bins_count >= 1
        && progress > 0.1
        && progress < 0.85
    {
        let deficit = 1.0 - mean_residual / next_item_size as f64;
        score -= 18.0 * deficit * deficit * (1.0 - progress);
    }

    // Gen 28: mid-stream slack-quantization shaping.
    if pr > 0 && mean_residual >= 3.0 && progress > 0.15 && progress < 0.9 {
        let mr = mean_residual.min(cap);
        let diff = (pr as f64 - mr).abs();
        if diff <= 2.0 {
            score -= 8.0 * (1.0 - diff / 3.0) * (1.0 - 0.3 * progress);
        } else if diff > mr * 0.5 && diff < mr * 0.5 + 3.0 {
            score += 4.0 * (1.0 - progress);
        }
    }

    // Gen 29: dead-space gradient refinement — two-step demand horizon
    // (next + mean) so residuals stranding BOTH items get a sharper
    // quadratic penalty, while residuals fitting next+mean get a modest
    // reward steering compaction toward multi-item absorption.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let horizon = next_item_size as f64 + mean_residual.min(cap * 0.35);
        if (pr as f64) < horizon {
            let dead2 = 1.0 - pr as f64 / horizon;
            score += 7.0 * dead2 * dead2 * (1.0 - 0.4 * progress);
        } else if (pr as f64) >= horizon + 4.0 && (pr as f64) <= horizon + 16.0 {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // Gen 29: waste-slope fresh-bin gate — a fresh bin is only attractive
    // when opening it reduces projected dead space versus the best open
    // residual; penalize the fresh candidate when open space already
    // absorbs the pair cleanly.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && fitting_bins_count >= 1
        && item_size + next_item_size <= bin_capacity
        && progress > 0.05
    {
        let pair = (item_size + next_item_size) as f64;
        let open_leftover = (mean_residual - pair).max(0.0);
        let fresh_leftover = cap - pair;
        if open_leftover <= fresh_leftover && mean_residual >= pair {
            score += 20.0 * (1.0 - 0.5 * progress);
        } else if open_leftover > fresh_leftover + 8.0 {
            score -= 10.0 * ((open_leftover - fresh_leftover - 8.0) / cap).min(0.2) * 40.0 * (1.0 - progress);
        }
    }

    // Gen 29: endgame residual-saturation refinement — in the final
    // stretch, sharpen the near-exact closure band so residuals 1-2 units
    // above the next item beat looser fits.
    if progress > 0.75 && next_item_size > 0 && pr > next_item_size {
        let over = pr - next_item_size;
        if over <= 2 {
            score -= 14.0 * (1.0 - over as f64 / 3.0) * ((progress - 0.75) / 0.25);
        }
    }

    // Gen 30: horizon-band tightening — extend the gen-29
    // two-step horizon with a third step (next + 2*mean) so residuals that
    // strand three items receive a mild quadratic penalty, and reward
    // residuals landing within 2 units of the horizon exactly (perfect
    // multi-item closure) with a progress-weighted bonus.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.9 {
        let horizon = next_item_size as f64 + mean_residual.min(cap * 0.35);
        let horizon3 = horizon + mean_residual.min(cap * 0.25);
        if (pr as f64) < horizon3 {
            let dead3 = 1.0 - pr as f64 / horizon3;
            score += 4.0 * dead3 * dead3 * (1.0 - 0.5 * progress);
        }
        let exact = (pr as f64 - horizon).abs();
        if exact <= 2.0 {
            score -= 9.0 * (1.0 - exact / 3.0) * (1.0 - 0.4 * progress);
        }
    }

    // Gen 30: fresh-bin triple-tile probe — when the fresh bin
    // can tile item_size exactly k>=3 times, opening it is near-optimal
    // (zero internal waste per slot); reinforce the existing slot probe
    // with a mean-residual comparison so we only open when open residuals
    // cannot tile the item at all.
    if bin_residual == bin_capacity
        && item_size > 0
        && bin_capacity % item_size == 0
        && progress > 0.1
        && progress < 0.9
    {
        let slots = bin_capacity / item_size;
        if slots >= 3 && slots <= 5 && (mean_residual as u32) % item_size != 0 {
            score -= 10.0 * slots.min(4) as f64 * (1.0 - 0.6 * progress);
        }
    }

    // Gen 30: sliver-merging endgame sweep — residuals in the
    // 5..=11 band late in the stream are classic stranded slivers; when
    // the mean residual suggests other bins hold similar slivers, prefer
    // consuming this one now over leaving it for the endgame.
    if progress > 0.6 && pr >= 5 && pr <= 11 && mean_residual >= 3.0 {
        let similar = ((pr as f64 - mean_residual) / 4.0).abs() < 1.0;
        if similar {
            score -= 8.0 * (1.0 - 0.3 * progress);
        } else {
            score += 6.0 * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION (gen 31): slack-window fresh-bin gate refinement — replace
    // the coarse "reuse_is_bad" trigger with a graded comparison between
    // the best open residual and the fresh bin's leftover after placing
    // the item: open fresh only when its leftover beats the mean open
    // leftover by a margin that scales with remaining stream length.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && mean_residual > 0.0
        && fitting_bins_count >= 1
        && progress > 0.05
        && progress < 0.9
    {
        let fresh_leftover = cap - item_size as f64;
        let open_leftover = mean_residual - item_size as f64;
        if open_leftover > 0.0 {
            let margin = open_leftover - fresh_leftover;
            if margin > 4.0 {
                score -= (6.0 + margin.min(20.0) * 0.9) * (1.0 - 0.5 * progress);
            } else if margin < -6.0 {
                score += 10.0 * (1.0 - 0.4 * progress);
            }
        }
    }

    // MUTATION (gen 31): two-item exact-horizon ladder — when the residual
    // is within 1 unit of exactly absorbing next + mean, sharpen the
    // closure reward so multi-item absorption wins over single-item fits
    // that leave a slightly smaller but more fragmented remainder.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress > 0.2 {
        let horizon = next_item_size as f64 + mean_residual.min(cap * 0.35);
        let gap = (pr as f64 - horizon).abs();
        if gap <= 1.0 {
            score -= 12.0 * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 31): endgame fresh-bin veto tightening — in the last
    // 20% of the stream, opening a bin is almost never worth it unless the
    // item is large enough that no open residual could ever hold it; scale
    // the existing suppression by the item's relative size.
    if bin_residual == bin_capacity && progress > 0.8 {
        let rel = item_size as f64 / cap;
        if rel < 0.5 && fitting_bins_count > 0 {
            score += 18.0 * (1.0 - rel) * ((progress - 0.8) / 0.2);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Sharpened perfect/near-perfect closure rewards.
    if pr == 0 {
        score -= 1280.0;
    } else if pr <= 4 {
        score -= 92.0 + (4 - pr) as f64 * 13.0;
    } else if pr < 12 {
        score += 30.0 - pr as f64;
    }

    // Harmonic residue classes.
    let class_bonus: f64 = if pr % 10 == 0 {
        36.0
    } else if pr % 5 == 0 {
        18.0
    } else if pr % 2 == 0 {
        5.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Lookahead: next item fit quality into post-placement residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 178.0 + 40.0 * (1.0 - progress);
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= if slack <= 10 { 66.0 - slack as f64 * 2.6 } else { 34.0 - (slack as f64).min(30.0) * 0.5 };
        } else {
            score += (next_item_size - pr) as f64 * 0.68;
        }
        if next_item_size < pr {
            let pr2 = pr - next_item_size;
            if pr2 <= 6 {
                score -= 52.0;
            } else if pr2 == next_item_size {
                score -= 27.0;
            } else if pr2 % 10 == 0 {
                score -= 12.0;
            }
            if pr2 > 6 && next_item_size > 1 && pr2 % next_item_size == 0 {
                score -= 15.0;
            }
            if pr2 >= 2 * item_size && item_size > 0 && pr2 % item_size == 0 {
                score -= 8.0;
            }
            if pr2 >= 3 * item_size.max(1) {
                score -= 6.0;
            }
            // Chain lookahead via mean-residual proxy.
            if pr2 > 0 && mean_residual > 0.0 {
                let proxy = mean_residual.round() as u32;
                if proxy >= 1 && proxy <= pr2 {
                    score -= 9.0 * (1.0 - progress);
                }
            }
            // Triple-chain closure.
            if pr2 >= 2 * next_item_size {
                let pr3 = pr2 - 2 * next_item_size;
                if pr3 <= 3 {
                    score -= 24.0 * (1.0 - progress);
                }
            }
            // next + item leaves near-perfect closure.
            if pr2 >= item_size.max(1) {
                let pr3 = pr2 - item_size.max(1);
                if pr3 <= 2 {
                    score -= 20.0 * (1.0 - progress);
                }
            }
        }
        // Pair-absorbency.
        if pr > 1 && pr == 2 * next_item_size {
            score -= 22.0;
        }
        // Stranded residual just below next item.
        if pr > 0 && pr < next_item_size {
            let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
            score += (7.0 + 5.0 * gap_frac) * (1.0 - progress);
        }
    } else {
        // Last item: any bin that fits is fine; prefer tightest.
        score -= 20.0;
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 66.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap) < 0.38;
        let reuse_is_bad = fitting_bins_count <= 1
            || (pr > 0 && next_item_size > pr && next_item_size <= bin_capacity);
        let late_large = item_size >= 60 && progress > 0.10;
        if late_large || (tight && progress > 0.15) || reuse_is_bad {
            score -= 46.0 + 30.0 * progress;
        } else {
            score += 70.0;
        }
        if item_size <= 25 && mean_residual > cap * 0.45 {
            score += 36.0;
        }
        if open_bins_count > 12 && progress < 0.3 {
            score += 12.0;
        }
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 24.0 + 18.0 * (1.0 - progress);
        }
        if next_item_size >= bin_capacity / 2 && mean_residual < (item_size + next_item_size) as f64 {
            score -= 10.0 + 14.0 * (1.0 - progress);
        }
        if item_size + next_item_size == bin_capacity
            && mean_residual < (item_size + next_item_size) as f64
        {
            score -= 20.0;
        }
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size {
            let strand = mean_residual as u32 - item_size;
            if strand > 0 && strand < 8 && progress > 0.2 {
                score -= 14.0 + 6.0 * (1.0 - progress);
            }
        }
        // Fresh-bin exact-pair bonus.
        if item_size + next_item_size == bin_capacity {
            score -= 34.0 + 20.0 * (1.0 - progress);
        }
        if pr > 0 && pr < item_size / 3 && item_size >= 30 {
            score -= 12.0;
        }
        // Fresh-bin viability gate.
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size && fitting_bins_count > 1 && !late_large {
            score += 30.0 * (1.0 - progress);
        }
        // Fresh-bin scarcity coupling.
        if fitting_bins_count >= 2 && item_size >= 40 {
            let best_gap = mean_residual - item_size as f64;
            if best_gap > 12.0 {
                score -= (best_gap / cap).min(0.25) * 80.0 * (1.0 - progress);
            }
        }
        // Fresh-bin only when the item cannot tile any open residual
        // with the next item — otherwise fresh space fragments the stream.
        if next_item_size > 0
            && fitting_bins_count >= 1
            && item_size + next_item_size <= bin_capacity
            && mean_residual >= (item_size + next_item_size) as f64
            && progress < 0.6
        {
            score += 18.0 * (1.0 - progress);
        }
        // Fresh-bin slot-arithmetic probe.
        if item_size > 0 && bin_capacity % item_size == 0 {
            let slots = bin_capacity / item_size;
            if slots >= 2 && slots <= 4 && progress > 0.1 {
                score -= 14.0 * (slots as f64).min(3.0) * (1.0 - 0.5 * progress);
            }
        }
        // Fresh-bin residual-mirror check.
        if mean_residual > item_size as f64 * 1.6 && progress > 0.3 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
        // Fresh-bin dead-space forecast.
        if next_item_size > 0
            && fitting_bins_count >= 2
            && mean_residual > 0.0
            && (item_size as f64 + next_item_size as f64 + mean_residual) <= cap
            && progress < 0.55
        {
            score += 14.0 * (1.0 - progress);
        }
        // Endgame fresh-bin hard gate.
