    if pr > 0 && next_item_size > 0 {
        let demand = (next_item_size as f64).max(mean_residual * 0.8);
        if (pr as f64) < demand {
            let dead = 1.0 - pr as f64 / demand;
            score += 15.0 * dead * dead * (1.0 - 0.5 * progress);
