    // Lookahead on next item.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 178.0 + 40.0 * (1.0 - progress);
        } else if pr > next_item_size {
            let slack = pr - next_item_size;
            score -= if slack <= 10 { 66.0 - slack as f64 * 2.6 } else { 34.0 - (slack as f64).min(30.0) * 0.5 };
            // Two-step chain checks.
            if slack <= 6 {
                score -= 52.0;
            } else if slack == next_item_size {
                score -= 27.0;
            } else if slack % 10 == 0 {
                score -= 12.0;
            }
            if slack > 6 && next_item_size > 1 && slack % next_item_size == 0 {
                score -= 15.0;
            }
            // Triple-chain closure.
            if slack >= 2 * next_item_size {
                let pr3 = slack - 2 * next_item_size;
                if pr3 <= 3 {
                    score -= 24.0 * (1.0 - progress);
                }
            }
            // Chain lookahead via mean-residual proxy.
            if mean_residual > 0.0 {
                let proxy = mean_residual.round() as u32;
                if proxy >= 1 && proxy <= slack {
                    score -= 9.0 * (1.0 - progress);
                }
            }
