        let over = pr - next_item_size;
        if over <= 2 {
            score -= 14.0 * (1.0 - over as f64 / 3.0) * ((progress - 0.75) / 0.25);
        }
    }

    // MUTATION: two-chain residual tileability probe.
    if next_item_size > 1 && pr >= 2 * next_item_size {
        let pr2 = pr - 2 * next_item_size;
        if pr2 == 0 {
            score -= 20.0 + 14.0 * (1.0 - progress);
        }
    }

    // MUTATION: item+next exact pair inside residual.
    if next_item_size > 0 && item_size > 0 && pr == item_size + next_item_size {
        score -= 26.0;
    }

    // MUTATION: late-stream sliver-merging sweep.
    if progress > 0.6 && pr >= 5 && pr <= 11 && mean_residual >= 3.0 {
        let similar = ((pr as f64 - mean_residual) / 4.0).abs() < 1.0;
        if similar {
            score -= 8.0 * (1.0 - 0.3 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Sharpened perfect/near-perfect closure rewards.
    if pr == 0 {
        score -= 1280.0;
    } else if pr <= 4 {
        score -= 92.0 + (4 - pr) as f64 * 13.0;
    } else if pr < 12 {
        score += 30.0 - pr as f64;
