        && progress > 0.08
        && progress < 0.88
    {
        let fresh_left = cap - (item_size + next_item_size) as f64;
        let open_left = (mean_residual - (item_size + next_item_size) as f64).max(0.0);
        if fresh_left + 2.0 < open_left {
            score -= 16.0 * (1.0 - 0.5 * progress);
        } else if open_left + 2.0 < fresh_left && fitting_bins_count >= 1 {
            score += 12.0 * (1.0 - 0.4 * progress);
        }
    }

    // Gen 32: mid-stream residual ladder smoothing.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.25 && progress < 0.8 {
        let mr = mean_residual;
        let k = (pr as f64 / mr).round().max(1.0);
        let dev = (pr as f64 - k * mr).abs() / mr;
        if dev < 0.08 {
            score -= 14.0 * (1.0 - dev / 0.08) * (1.0 - 0.3 * progress);
        }
    }

    // Gen 33: graded waste-budget refinement.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.92 {
        let demand2 = (next_item_size as f64 + mean_residual.min(cap * 0.3)).max(next_item_size as f64);
        if (pr as f64) >= demand2 {
            let over = pr as f64 - demand2;
            let exact_pair = ((over - item_size as f64).abs()) <= 1.0;
            if exact_pair {
                score -= 11.0 * (1.0 - 0.4 * progress);
            } else if over < item_size as f64 {
                let strand = 1.0 - over / item_size.max(1) as f64;
                score += 5.0 * strand * (1.0 - 0.5 * progress);
            }
        }
    }

    // Gen 33: fresh-bin triple-parity veto.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && mean_residual > 0.0
        && fitting_bins_count >= 1
        && progress > 0.1
        && progress < 0.85
    {
        let open_capacity = mean_residual - item_size as f64;
        if open_capacity >= next_item_size as f64 && open_capacity < cap * 0.55 {
            score += 14.0 * (1.0 - 0.5 * progress);
        }
    }

    // Gen 33: residual ladder anti-fragmentation sweep.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.2 && progress < 0.88 {
        let mr = mean_residual.min(cap);
        let below = mr - pr as f64;
        if below > 0.0 && below <= 3.0 {
            let crowd = if open_bins_count > 10 { 1.3 } else { 1.0 };
            score += (4.0 + 3.0 * (1.0 - below / 4.0)) * crowd * (1.0 - 0.4 * progress);
        } else if below < 0.0 && -below <= 2.0 {
            score -= 5.0 * (1.0 - (-below) / 3.0) * (1.0 - 0.4 * progress);
        }
    }

    // Gen 33: endgame exact-closure ladder extension.
    if progress > 0.85 && next_item_size > 0 && pr == item_size.max(1) + next_item_size {
        score -= 14.0 * ((progress - 0.85) / 0.15);
    }

    // MUTATION (gen 35): multi-item waste-budget horizon — extend the
    // gen-33 graded ladder to a two-step horizon: residuals that absorb
    // demand2 plus a second mean-sized item exactly are the strongest
    // compaction targets mid-stream; residuals stranded just below that
    // double-horizon get a crowding-scaled penalty.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress > 0.15 && progress < 0.9 {
        let demand2 = (next_item_size as f64 + mean_residual.min(cap * 0.3)).max(next_item_size as f64);
        let double_horizon = demand2 + mean_residual.min(cap * 0.3);
        if (pr as f64) >= double_horizon {
            let over = pr as f64 - double_horizon;
            if over <= 2.0 {
                score -= 13.0 * (1.0 - over / 3.0) * (1.0 - 0.4 * progress);
            }
        } else if (pr as f64) < double_horizon && (pr as f64) >= demand2 + 6.0 {
            let shortfall = double_horizon - pr as f64;
            if shortfall <= 8.0 {
                let crowd = if open_bins_count > 9 { 1.35 } else { 0.8 };
                score += 4.5 * (1.0 - shortfall / 9.0) * crowd * (1.0 - 0.4 * progress);
            }
        }
    }

    // MUTATION (gen 35): fresh-bin exact double-parity bonus — when the
    // fresh bin can host exactly item + next + one mean-sized residual
    // worth of demand (near-perfect triple fill), opening it beats any
    // open bin; reward it with a progress-scaled discount.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && mean_residual > 0.0
        && progress > 0.1
        && progress < 0.85
    {
        let triple = item_size as f64 + next_item_size as f64 + mean_residual.min(cap * 0.35);
        if triple <= cap {
            let fresh_left = cap - triple;
            let open_left = (mean_residual - item_size as f64).max(0.0) - next_item_size as f64;
            if fresh_left <= 4.0 && open_left >= 0.0 {
                score -= (14.0 + 2.0 * (4.0 - fresh_left)) * (1.0 - 0.5 * progress);
            }
        }
    }

    // MUTATION (gen 35): endgame dual-residual pooling — in the final
    // quarter, residuals within 2 units of the mean residual are the
    // natural merge partners; reward exact matches and penalize near
    // misses with a smooth ramp that grows toward the very end.
    if progress > 0.75 && pr > 0 && mean_residual >= 4.0 {
        let mr = mean_residual.min(cap);
        let diff = (pr as f64 - mr).abs();
        if diff <= 2.0 {
            score -= 10.0 * (1.0 - diff / 3.0) * ((progress - 0.75) / 0.25);
        } else if diff > 2.0 && diff <= 5.0 {
            score += 5.0 * ((diff - 2.0) / 3.0) * ((progress - 0.75) / 0.25);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Sharpened closure rewards.
    if pr == 0 {
        score -= 1280.0;
    } else if pr <= 4 {
        score -= 92.0 + (4 - pr) as f64 * 13.0;
    } else if pr < 12 {
        score += 30.0 - pr as f64;
    }

    // Harmonic residue classes.
    let class_bonus: f64 = if pr % 10 == 0 {
        36.0
    } else if pr % 5 == 0 {
        18.0
    } else if pr % 2 == 0 {
        5.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Lookahead fit quality into post-placement residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 178.0 + 40.0 * (1.0 - progress);
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= if slack <= 10 { 66.0 - slack as f64 * 2.6 } else { 34.0 - (slack as f64).min(30.0) * 0.5 };
        } else {
            score += (next_item_size - pr) as f64 * 0.68;
        }
        if next_item_size < pr {
            let pr2 = pr - next_item_size;
            if pr2 <= 6 {
                score -= 52.0;
            } else if pr2 == next_item_size {
                score -= 27.0;
            } else if pr2 % 10 == 0 {
                score -= 12.0;
            }
            if pr2 > 6 && next_item_size > 1 && pr2 % next_item_size == 0 {
                score -= 15.0;
            }
            if pr2 >= 2 * item_size && item_size > 0 && pr2 % item_size == 0 {
                score -= 8.0;
            }
            if pr2 > 0 && mean_residual > 0.0 {
                let proxy = mean_residual.round() as u32;
                if proxy >= 1 && proxy <= pr2 {
                    score -= 9.0 * (1.0 - progress);
                }
            }
            if pr2 >= 2 * next_item_size {
                let pr3 = pr2 - 2 * next_item_size;
                if pr3 <= 3 {
                    score -= 24.0 * (1.0 - progress);
                }
            }
            if pr2 >= item_size.max(1) {
                let pr3 = pr2 - item_size.max(1);
                if pr3 <= 2 {
                    score -= 20.0 * (1.0 - progress);
                }
            }
            // MUTATION (gen 35): tileability ladder — count how many copies of
            // the mean residual tile into pr2; each clean tiling compounds the
            // discount, rewarding residuals that form a reusable pool.
            if mean_residual >= 3.0 && progress > 0.15 {
                let mr = mean_residual.min(cap * 0.5);
                let tiles = ((pr2 as f64) / mr).floor();
                if tiles >= 2.0 {
                    let rem = pr2 as f64 - tiles * mr;
                    if rem <= 2.0 {
                        score -= (5.0 + 3.0 * tiles.min(4.0)) * (1.0 - 0.5 * progress);
                    } else if rem < mr * 0.35 {
                        score += 4.0 * (rem / (mr * 0.35)) * (1.0 - 0.4 * progress);
                    }
                }
            }
        }
        if pr > 1 && pr == 2 * next_item_size {
            score -= 22.0;
        }
        if pr > 0 && pr < next_item_size {
            let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
            score += (7.0 + 5.0 * gap_frac) * (1.0 - progress);
        }
    } else {
        score -= 20.0;
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 66.0;
    }

    // Open-bin pressure.
    score -= (open_bins_count as f64) * 0.8;

    // Best-fit bias.
    score -= (bin_capacity - bin_residual) as f64 * 0.16;

    // Mean-residual alignment.
    let align = ((pr as f64 - mean_residual) / cap).abs();
    score += align * (if progress > 0.2 && progress < 0.8 { 4.5 } else { 6.0 });

    // Waste-avoidance for tiny residuals.
    if pr > 0 && pr < bin_capacity / 5 {
        let scarcity = if fitting_bins_count > 2 { 0.6 } else { 1.4 };
        score += (10.0 + 4.0 * progress) * scarcity;
    }

    // Tightness bonus.
    if bin_residual >= item_size {
        let tightness = 1.0 - ((bin_residual - item_size) as f64 / cap);
        score -= 6.0 * tightness;
    }

    // Tight-fit crowding bonus.
    if bin_residual >= item_size {
        let slack = bin_residual - item_size;
        if slack <= 2 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= (14.0 + 8.0 * (2 - slack) as f64) * scarcity * (1.0 - 0.4 * progress);
        }
    }

    // ---- Fresh-bin gating ----
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap) < 0.38;
        let reuse_is_bad = fitting_bins_count <= 1
            || (pr > 0 && next_item_size > pr && next_item_size <= bin_capacity);
        let late_large = item_size >= 60 && progress > 0.10;
        if late_large || (tight && progress > 0.15) || reuse_is_bad {
            score -= 46.0 + 30.0 * progress;
        } else {
            score += 70.0;
        }
        if item_size <= 25 && mean_residual > cap * 0.45 {
            score += 36.0;
        }
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 24.0 + 18.0 * (1.0 - progress);
        }
        if next_item_size >= bin_capacity / 2 && mean_residual < (item_size + next_item_size) as f64 {
            score -= 10.0 + 14.0 * (1.0 - progress);
        }
        if item_size + next_item_size == bin_capacity {
            score -= 34.0 + 20.0 * (1.0 - progress);
        }
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size && fitting_bins_count > 1 && !late_large {
            score += 30.0 * (1.0 - progress);
        }
        if item_size > 0 && bin_capacity % item_size == 0 {
            let slots = bin_capacity / item_size;
            if slots >= 2 && slots <= 4 && progress > 0.1 {
                score -= 14.0 * (slots as f64).min(3.0) * (1.0 - 0.5 * progress);
            }
        }
        if progress > 0.7 && fitting_bins_count > 0 && !late_large {
            score += 45.0 * ((progress - 0.7) / 0.3);
        }
        // Waste-parity gate.
        if next_item_size > 0
            && item_size + next_item_size <= bin_capacity
            && progress > 0.08
            && progress < 0.88
        {
            let fresh_left = cap - (item_size + next_item_size) as f64;
            let open_left = (mean_residual - (item_size + next_item_size) as f64).max(0.0);
            if fresh_left + 2.0 < open_left {
                score -= 16.0 * (1.0 - 0.5 * progress);
            } else if open_left + 2.0 < fresh_left && fitting_bins_count >= 1 {
                score += 12.0 * (1.0 - 0.4 * progress);
            }
        }
        // Endgame fresh-bin veto.
        if progress > 0.8 {
            let rel = item_size as f64 / cap;
            if rel < 0.5 && fitting_bins_count > 0 {
                score += 18.0 * (1.0 - rel) * ((progress - 0.8) / 0.2);
            }
        }
        // MUTATION (gen 35): fresh-bin mean-tiling veto — if the mean open
        // residual can still tile the fresh bin's whole capacity within a
        // small slack, opening a fresh bin duplicates space that already
        // exists; penalize proportionally to the tiling count.
        if mean_residual >= 4.0
            && fitting_bins_count >= 2
            && progress > 0.12
            && progress < 0.9
        {
            let mr = mean_residual.min(cap * 0.6);
            let tiles = (cap / mr).floor();
            let rem = cap - tiles * mr;
            if tiles >= 2.0 && rem <= 6.0 {
                score += (8.0 + 4.0 * tiles.min(5.0)) * (1.0 - 0.5 * progress);
            }
        }
        // MUTATION (gen 35): fresh-bin pair-tiling probe — when the item and
        // next item together tile the fresh bin exactly (or within 2 units),
        // a fresh bin is a guaranteed full pack; reward strongly.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let pair_left = bin_capacity - item_size - next_item_size;
            if pair_left == 0 {
                score -= 42.0;
            } else if pair_left <= 2 {
                score -= 24.0 * (1.0 - 0.4 * progress);
            }
        }
    }

    // Graded waste-budget ladder.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.92 {
        let demand2 = (next_item_size as f64 + mean_residual.min(cap * 0.3)).max(next_item_size as f64);
        if (pr as f64) >= demand2 {
            let over = pr as f64 - demand2;
            if (over - item_size as f64).abs() <= 1.0 {
                score -= 11.0 * (1.0 - 0.4 * progress);
            } else if over < item_size as f64 {
                let strand = 1.0 - over / item_size.max(1) as f64;
                score += 5.0 * strand * (1.0 - 0.5 * progress);
            }
        } else {
            let waste_frac = 1.0 - (pr as f64) / demand2;
            let crowd = if open_bins_count > 8 { 1.25 } else { 1.0 };
            score += 13.0 * waste_frac * waste_frac * crowd * (1.0 - 0.45 * progress);
        }
    }

    // Anti-fragmentation sweep.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.2 && progress < 0.88 {
        let mr = mean_residual.min(cap);
        let below = mr - pr as f64;
        if below > 0.0 && below <= 3.0 {
            let crowd = if open_bins_count > 10 { 1.3 } else { 1.0 };
            score += (4.0 + 3.0 * (1.0 - below / 4.0)) * crowd * (1.0 - 0.4 * progress);
        } else if below < 0.0 && -below <= 2.0 {
            score -= 5.0 * (1.0 - (-below) / 3.0) * (1.0 - 0.4 * progress);
        }
    }

    // Endgame exact pair closure.
    if progress > 0.85 && next_item_size > 0 && pr == item_size.max(1) + next_item_size {
        score -= 14.0 * ((progress - 0.85) / 0.15);
    }

    // Mid-stream consolidation of large absorbable residuals.
    if open_bins_count > 8 && progress > 0.25 && progress < 0.85 && pr >= 40 {
        score -= 9.0;
    }

    // Dead-space ratio shaping with next-item floor.
    if pr > 0 && next_item_size > 0 {
        let dead_threshold = (next_item_size + 12).min(bin_capacity);
        if pr < dead_threshold {
            let dead_frac = 1.0 - (pr as f64 / dead_threshold as f64);
            score += 18.0 * dead_frac * (1.0 - progress);
        } else if pr >= dead_threshold * 2 {
            score -= 8.0 + 4.0 * (1.0 - progress);
        }
    }

    // Endgame exactness.
    if progress > 0.9 && pr > 0 {
        score += pr as f64 * 0.35;
        if pr <= next_item_size.max(1) {
            score -= 20.0;
        }
    }

    // Perfect-fit dominance gate for the fresh-bin candidate.
    if pr == 0 && bin_residual == bin_capacity {
        score += 1400.0;
    }

    // MUTATION (gen 35): dead-space ratio compaction sweep with graded
    // band — residuals within 6 units above the two-step demand horizon
    // (next + capped mean) get a strong smooth discount; residuals that
    // overshoot the horizon but strand a mean-sized item get a mild
    // penalty, sharpening the parent's flat version.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.9 {
        let horizon = next_item_size as f64 + mean_residual.min(cap * 0.35);
        let gap = pr as f64 - horizon;
        if gap >= 0.0 && gap <= 6.0 {
            score -= (14.0 - gap * 1.6) * (1.0 - 0.4 * progress);
        } else if gap > 6.0 && gap < next_item_size as f64 {
            score += 6.0 * (gap / next_item_size as f64) * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 35): near-exact residual shaping — residuals one to
    // three units above the next item are the highest-value absorption
    // targets mid-stream; deepen the reward with a smooth quadratic ramp
