    if next_item_size > 0 && pr > next_item_size && pr <= next_item_size + 3 {
        let over = (pr - next_item_size) as f64;
        let crowd = if open_bins_count > 6 { 1.2 } else { 1.0 };
        score -= (16.0 - over * 3.0) * crowd * (1.0 - 0.5 * progress);
    }

    score
}

