    // MUTATION (gen 36): endgame exact-closure ladder extension.
    if progress > 0.85 && next_item_size > 0 && pr == item_size.max(1) + next_item_size {
        score -= 14.0 * ((progress - 0.85) / 0.15);
    }

    // MUTATION (gen 36): fresh-bin veto when open space suffices for item + next.
    if bin_residual == bin_capacity && next_item_size > 0 && mean_residual > 0.0
