        if open_capacity >= next_item_size as f64 && open_capacity < cap * 0.55 {
            score += 14.0 * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION (gen 36): fresh-bin scarcity override when only one fitting bin
    // and next item won't fit the resulting residual.
    if bin_residual == bin_capacity && fitting_bins_count == 1 && next_item_size > 0
        && pr > 0 && next_item_size > pr && (pr as f64) < 0.2 * cap && progress < 0.8
    {
        score -= 55.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
