        // MUTATION (gen 36): fresh-bin residual-mirror check — when open
        // bins already carry slack well above 1.6x the item, prefer
        // reusing them rather than fragmenting with fresh space.
        if mean_residual > item_size as f64 * 1.6 && progress > 0.3 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
        // MUTATION (gen 36): fresh-bin dead-space forecast — if the open
        // mean residual can absorb item + next, opening fresh space only
        // strands the pair.
        if next_item_size > 0
            && fitting_bins_count >= 2
            && mean_residual > 0.0
            && (item_size as f64 + next_item_size as f64 + mean_residual) <= cap
            && progress < 0.55
        {
            score += 14.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 36): graded waste-budget ladder — residuals that absorb
    // the two-step demand (next + mean proxy) exactly get a discount;
    // residuals that strand the current item get a smooth penalty.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.92 {
        let demand2 = (next_item_size as f64 + mean_residual.min(cap * 0.3)).max(next_item_size as f64);
        if (pr as f64) >= demand2 {
            let over = pr as f64 - demand2;
            if (over - item_size as f64).abs() <= 1.0 {
                score -= 11.0 * (1.0 - 0.4 * progress);
            } else if over < item_size as f64 {
                let strand = 1.0 - over / item_size.max(1) as f64;
                score += 5.0 * strand * (1.0 - 0.5 * progress);
            }
        } else {
            let waste_frac = 1.0 - (pr as f64) / demand2;
            let crowd = if open_bins_count > 8 { 1.25 } else { 1.0 };
            score += 13.0 * waste_frac * waste_frac * crowd * (1.0 - 0.45 * progress);
        }
    }

    // MUTATION (gen 36): anti-fragmentation sweep — residuals just below
    // the mean residual are the classic stranding source mid-stream.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.2 && progress < 0.88 {
        let mr = mean_residual.min(cap);
        let below = mr - pr as f64;
        if below > 0.0 && below <= 3.0 {
            let crowd = if open_bins_count > 10 { 1.3 } else { 1.0 };
            score += (4.0 + 3.0 * (1.0 - below / 4.0)) * crowd * (1.0 - 0.4 * progress);
        } else if below < 0.0 && -below <= 2.0 {
            score -= 5.0 * (1.0 - (-below) / 3.0) * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 36): endgame exact pair closure — item+next == pr
    // late in the stream deserves a progress-scaled bonus on top of the
    // flat term.
    if progress > 0.85 && next_item_size > 0 && pr == item_size.max(1) + next_item_size {
        score -= 14.0 * ((progress - 0.85) / 0.15);
    }

    // MUTATION (gen 36): residual pooling ladder — residuals that are a
    // near-integer multiple of the mean residual pool cleanly with other
    // bins' leftovers; reward them mid-stream to reduce dead space.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.2 && progress < 0.85 {
        let mr = mean_residual;
        let k = (pr as f64 / mr).round().max(1.0);
        let dev = (pr as f64 - k * mr).abs() / mr;
        if dev < 0.15 && k >= 1.0 {
            score -= 10.0 * (1.0 - dev / 0.15) * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 36): two-item lookahead tiling — residual that fits
    // next plus a mean-sized follow-up with small gap is a strong
    // compaction target.
    if pr > 0 && next_item_size > 0 && mean_residual > 1.0 {
        let combo = next_item_size as f64 + mean_residual.min(cap * 0.4);
        let gap = pr as f64 - combo;
        if gap >= 0.0 && gap <= 5.0 {
            score -= (16.0 - gap) * 2.4 * (1.0 - 0.5 * progress);
        }
    }

    // Mid-stream consolidation of large absorbable residuals.
    if open_bins_count > 8 && progress > 0.25 && progress < 0.85 && pr >= 40 {
        score -= 9.0;
    }

    // Dead-space ratio shaping with next-item floor.
    if pr > 0 && next_item_size > 0 {
        let dead_threshold = (next_item_size + 12).min(bin_capacity);
        if pr < dead_threshold {
            let dead_frac = 1.0 - (pr as f64 / dead_threshold as f64);
            score += 18.0 * dead_frac * (1.0 - progress);
        } else if pr >= dead_threshold * 2 {
            score -= 8.0 + 4.0 * (1.0 - progress);
        }
    }

    // Endgame exactness.
    if progress > 0.9 && pr > 0 {
        score += pr as f64 * 0.35;
        if pr <= next_item_size.max(1) {
            score -= 20.0;
        }
    }

    // Perfect-fit dominance gate for the fresh-bin candidate.
    if pr == 0 && bin_residual == bin_capacity {
        score += 1400.0;
    }

    score
}

