    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common
    // item-size classes (10, 20, 25, 50) are more reusable than odd ones.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let mut reusability = 0.0;
    if pr % 10 == 0 { reusability += 3.0; }
    if pr % 20 == 0 { reusability += 2.0; }
    if pr % 25 == 0 { reusability += 2.0; }
    if pr % 50 == 0 { reusability += 3.0; }
    if pr == 0 { reusability += 10.0; } // perfect fit: zero waste
    score -= reusability;

    // Penalize dead space that no plausible item (1..=80) can use well:
    // post_residual in awkward bands (e.g. 1..9 or 21..24, 26..29) is nearly unusable.
    let awkward = match pr {
        0 => 0.0,
        1..=9 => 6.0,
        10..=19 => 1.0,
        20..=24 => 3.0,
        25..=29 => 2.0,
        30..=49 => 0.5,
        _ => 0.0,
    };
    score += awkward;

    // Coupling with lookahead item: reward if next item fits exactly into post_residual,
    // penalize if next item barely doesn't fit (would force a new bin anyway).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 8.0; // perfect chain
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.25;
        } else {
            score += 1.5; // next item won't chain here
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when existing residuals are large
    // (item would leave big waste) or stream is early with few bins.
    if bin_residual == bin_capacity {
        let waste_penalty = (bin_residual as f64 - post_residual as f64 - item_size as f64).max(0.0);
        let pressure = mean_residual / cap; // high mean residual => open bins are full
        let base = 8.0 + 20.0 * (1.0 - pressure);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = base + waste_penalty * 0.5 - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative
        }
    }

    // Slight preference for tighter bins overall (waste minimization).
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    score
}

