        let combo = next_item_size as f64 + mean_residual.min(cap * 0.4);
        let gap = pr as f64 - combo;
        if gap >= 0.0 && gap <= 5.0 {
            score -= (16.0 - gap) * 2.4 * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION (gen 37): dual lookahead repeatable-fill probe — residuals
    // that tile into repeated copies of item + next signal a cascade of
    // perfect fills; discount them.
    if next_item_size > 0 && next_item_size < pr {
        let pr2 = pr - next_item_size;
        if pr2 > 0 && item_size > 1 && pr2 % item_size == 0 && next_item_size % item_size == 0 {
            score -= 10.0;
        }
    }

    // MUTATION (gen 37): quad-chain lookahead — residuals absorbing three
    // next-items with a tiny remainder deserve a late-stream discount.
    if next_item_size > 0 && pr >= 3 * next_item_size {
        let pr3 = pr - 3 * next_item_size;
        if pr3 <= 4 {
            score -= 18.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 37): strand-risk shaping — residuals in the 13–24 band
    // are too small for common items yet too large to close; penalize more
    // when bins are crowded, less when scarce.
    if pr >= 13 && pr <= 24 {
        let crowd = if open_bins_count > 10 { 1.5 } else { 0.7 };
        score += 6.0 * crowd * (1.0 - 0.5 * progress);
    }

    // MUTATION (gen 37): open-bin budget shaping — when bin count outruns
    // the stream pace, penalize residuals proportionally to discourage
    // further proliferation.
    if open_bins_count as f64 > (step_index as f64) * 0.35 && pr > 0 {
        let over = open_bins_count as f64 / (step_index as f64 + 1.0);
        score += (pr as f64 / cap) * 22.0 * over.min(1.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a realistic item are heavily penalized (unusable gaps).
    let dead_threshold: f64 = 9.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward residuals that can still host a next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize leaving a gap that just barely misses the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (2.0 + 4.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when existing fits are bad.
    if bin_residual == bin_capacity {
        score -= 3.0;
        score += mean_residual * 0.15;
    }

    // Slight preference for bins already below mean residual (denser bins).
    score += ((mean_residual - bin_residual as f64).max(-20.0).min(20.0)) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
