                if pr3 <= 2 {
                    score -= 20.0 * late;
                }
            }
        } else {
            let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
            score += (8.0 + 8.0 * gap_frac) * (0.4 + 0.6 * late);
        }
        // Pair absorbency.
        if pr > 1 && pr == 2 * next_item_size {
            score -= 24.0;
        }
        // Exact pair of current + next.
        if item_size > 0 && pr == item_size + next_item_size {
            score -= 28.0;
        }
