        let reuse_is_bad = fitting_bins_count <= 1
            || (next_item_size > 0 && pr > 0 && next_item_size > pr && next_item_size <= bin_capacity);
        let late_large = item_size >= 60 && progress > 0.10;
        if late_large || reuse_is_bad {
