        // Fresh-bin waste parity: prefer open leftovers when they suffice.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity && progress > 0.08 {
            let fresh_left = cap - (item_size + next_item_size) as f64;
            let open_left = (mean_residual - (item_size + next_item_size) as f64).max(0.0);
            if mean_residual >= (item_size + next_item_size) as f64 && open_left <= fresh_left + 2.0 {
                score += 20.0 * (0.4 + 0.6 * late);
            } else if fresh_left + 2.0 < open_left {
