}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: perfect match with next item is golden ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // This bin will be exactly filled by the next item: perfect packing.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits too: penalize leftover after BOTH placements.
            let second_leftover = post_residual - next_item_size;
            score += second_leftover as f64 * 0.8;
            // If the pair leaves tiny dead space, still reward heavily.
            if second_leftover <= 3 {
                score -= 35.0;
            }
        } else {
            // Next item does NOT fit in the leftover: dead space penalty,
            // stronger when post_residual is small (nearly unusable).
            let dead = post_residual as f64;
            let next_overhang = (next_item_size - post_residual) as f64;
            score += dead * 0.5 + next_overhang * 0.3;
            if post_residual < 10 {
                score += 15.0; // tiny unusable sliver
            }
        }
    } else {
        // Last item: just prefer tightest fit (score already = post_residual).
        score += 0.0;
    }

    // --- Tightness of current placement relative to bin capacity ---
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // --- Relative to mean residual: bins tighter than average are precious ---
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64) / mean_residual;
        if rel < 1.0 {
            // This bin is tighter than average: good candidate, reward.
            score -= (1.0 - rel) * 12.0;
        } else {
            // Looser than average: mild penalty.
            score += (rel - 1.0) * 4.0;
        }
    }

    // --- Last-chance bin: strongly favor using it to avoid opening a bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Competition exists: prefer the tightest, mild spread penalty.
        score += 3.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost. Attractive when existing bins
        // would be badly fragmented (high mean residual, poor lookahead match).
        let stream_progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 20.0;
        // Late in the stream, prefer consolidating into open bins.
        new_bin_score += stream_progress * 15.0;
        // If many open bins, discourage yet another one.
        new_bin_score += open_bins_count as f64 * 1.5;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            new_bin_score -= 8.0;
        }
        score += new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins whose post residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Perfect or near-perfect fills get a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Lookahead: reward bins whose post residual can host the next item well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_fit = post_residual - next_item_size;
            score -= 8.0 * (1.0 - next_fit as f64 / bin_capacity as f64);
        } else {
            // Dead space for the next item: penalize proportionally.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize bins far from the mean residual (prefer balanced usage),
    // but only mildly so exploration is not blocked.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Late in the stream: consolidate; fewer open bins preferred.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * progress * open_bins_count as f64;

    // New-bin candidate handling: opening a bin is attractive early or when
    // no open bin fits tightly; penalize it when a decent fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying with stream progress
        // (early on, spreading items is fine; late, consolidation matters).
        let open_cost = 30.0 * (1.0 - 0.5 * progress);
        // If this is the only fitting option, opening is cheap.
        let escape_discount = if fitting_bins_count == 1 { 20.0 } else { 0.0 };
        // If next item would fit in the fresh bin's huge residual, discount.
        let lookahead_discount = if next_item_size > 0 && next_item_size <= item_size { 5.0 } else { 0.0 };
        score += open_cost - escape_discount - lookahead_discount;
    }

    // Small tie-breaker: prefer bins with more residual used overall.
    score += 0.01 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Sharpened perfect/near-perfect closure rewards.
    if pr == 0 {
        score -= 1280.0;
    } else if pr <= 4 {
        score -= 92.0 + (4 - pr) as f64 * 13.0;
    } else if pr < 12 {
        score += 30.0 - pr as f64;
    }

    // Harmonic residue classes.
    let class_bonus: f64 = if pr % 10 == 0 {
        36.0
    } else if pr % 5 == 0 {
        18.0
    } else if pr % 2 == 0 {
        5.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Lookahead: next item fit quality into post-placement residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 178.0 + 40.0 * (1.0 - progress);
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= if slack <= 10 { 66.0 - slack as f64 * 2.6 } else { 34.0 - (slack as f64).min(30.0) * 0.5 };
        } else {
            score += (next_item_size - pr) as f64 * 0.68;
        }
        if next_item_size < pr {
            let pr2 = pr - next_item_size;
            if pr2 <= 6 {
                score -= 52.0;
            } else if pr2 == next_item_size {
                score -= 27.0;
            } else if pr2 % 10 == 0 {
                score -= 12.0;
            }
            if pr2 > 6 && next_item_size > 1 && pr2 % next_item_size == 0 {
                score -= 15.0;
            }
            if pr2 >= 2 * item_size && item_size > 0 && pr2 % item_size == 0 {
                score -= 8.0;
            }
            if pr2 >= 3 * item_size.max(1) {
                score -= 6.0;
            }
            // Chain lookahead via mean-residual proxy.
            if pr2 > 0 && mean_residual > 0.0 {
                let proxy = mean_residual.round() as u32;
                if proxy >= 1 && proxy <= pr2 {
                    score -= 9.0 * (1.0 - progress);
                }
            }
            // Triple-chain closure.
            if pr2 >= 2 * next_item_size {
                let pr3 = pr2 - 2 * next_item_size;
                if pr3 <= 3 {
                    score -= 24.0 * (1.0 - progress);
                }
            }
            // next + item leaves near-perfect closure.
            if pr2 >= item_size.max(1) {
                let pr3 = pr2 - item_size.max(1);
                if pr3 <= 2 {
                    score -= 20.0 * (1.0 - progress);
                }
            }
        }
        // Pair-absorbency.
        if pr > 1 && pr == 2 * next_item_size {
            score -= 22.0;
        }
        // Stranded residual just below next item.
        if pr > 0 && pr < next_item_size {
            let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
            score += (7.0 + 5.0 * gap_frac) * (1.0 - progress);
        }
    } else {
        // Last item: any bin that fits is fine; prefer tightest.
        score -= 20.0;
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 66.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap) < 0.38;
        let reuse_is_bad = fitting_bins_count <= 1
            || (pr > 0 && next_item_size > pr && next_item_size <= bin_capacity);
        let late_large = item_size >= 60 && progress > 0.10;
        if late_large || (tight && progress > 0.15) || reuse_is_bad {
            score -= 46.0 + 30.0 * progress;
        } else {
            score += 70.0;
        }
        if item_size <= 25 && mean_residual > cap * 0.45 {
            score += 36.0;
        }
        if open_bins_count > 12 && progress < 0.3 {
            score += 12.0;
        }
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 24.0 + 18.0 * (1.0 - progress);
        }
        if next_item_size >= bin_capacity / 2 && mean_residual < (item_size + next_item_size) as f64 {
            score -= 10.0 + 14.0 * (1.0 - progress);
        }
        if item_size + next_item_size == bin_capacity
            && mean_residual < (item_size + next_item_size) as f64
        {
            score -= 20.0;
        }
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size {
            let strand = mean_residual as u32 - item_size;
            if strand > 0 && strand < 8 && progress > 0.2 {
                score -= 14.0 + 6.0 * (1.0 - progress);
            }
        }
        // Fresh-bin exact-pair bonus.
        if item_size + next_item_size == bin_capacity {
