    // Dead-space recovery probe.
    if pr > 0 && mean_residual >= 2.0 {
        let mr = mean_residual.min(cap * 0.6);
        let gap = pr as f64 - mr;
        if gap >= 0.0 && gap <= 5.0 {
            score += 10.0 * (1.0 - gap / 5.0) * (1.0 - 0.4 * progress);
        } else if gap > 5.0 && gap < 12.0 {
            score -= 5.0 * (1.0 - (gap - 5.0) / 7.0) * (1.0 - 0.5 * progress);
        }
    }

    // Fitting-crowd tiebreak via harmonic-mean demand matching.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let harmonic = 2.0 * (next_item_size as f64 * mean_residual)
            / (next_item_size as f64 + mean_residual).max(1.0);
        let dev = ((pr as f64 - harmonic) / harmonic.max(1.0)).abs();
        let pressure = if fitting_bins_count >= 4 { 1.0 } else { 0.4 };
        if dev < 0.3 {
            score -= 7.0 * (1.0 - dev / 0.3) * pressure * (1.0 - 0.4 * progress);
        }
    }

    // Endgame sliver sweep.
    if progress > 0.8 && pr > 0 && next_item_size > 0 && pr < next_item_size {
        let waste = 1.0 - pr as f64 / next_item_size as f64;
        score += 12.0 * waste * waste * (progress - 0.8) / 0.2;
    }

    // Dead-space ratio compaction sweep.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.9 {
        let demand = next_item_size as f64 + mean_residual.min(cap * 0.5);
        let gap = pr as f64 - demand;
        if gap >= 0.0 && gap <= 6.0 {
            score -= (12.0 - gap) * 1.8 * (1.0 - 0.5 * progress);
        } else if gap > 6.0 && gap <= 14.0 && (gap as u32) < next_item_size {
            let sliver = gap as f64 / 14.0;
            score += 7.0 * sliver * (1.0 - 0.4 * progress);
        }
    }

    // Cross-bin compaction pull.
    if pr > 0 && mean_residual >= 3.0 && fitting_bins_count >= 2 && progress > 0.3 {
        let mr = mean_residual;
        let k = ((pr as f64) / mr).floor().max(1.0);
        let rem = pr as f64 - k * mr;
        if rem >= 0.0 && rem <= 4.0 {
            let weight = 1.0 + (progress - 0.3);
            score -= (6.0 + 4.0 * (1.0 - rem / 4.0)) * weight.min(1.7);
        } else if rem > 4.0 && rem < mr {
            score += 4.0 * (1.0 - progress) * (rem / mr);
        }
    }

    // Tight-fit crowding bonus.
    if bin_residual >= item_size {
        let slack = bin_residual - item_size;
        if slack <= 2 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= (14.0 + 8.0 * (2 - slack) as f64) * scarcity * (1.0 - 0.4 * progress);
        }
    }

    // Perfect-fit dominance gate.
    if pr == 0 {
        if bin_residual == bin_capacity {
            score += 1400.0;
        }
        score -= 30.0 * (1.0 - progress);
    }

    // Scarcity-driven fresh-bin override.
    if bin_residual == bin_capacity
        && fitting_bins_count == 1
        && next_item_size > 0
        && pr > 0
        && next_item_size > pr
        && (pr as f64) < 0.2 * cap
        && progress < 0.8
    {
        score -= 55.0 * (1.0 - progress);
    }

    // Gen 27: residual-dead-space gradient.
    if pr > 0 && next_item_size > 0 {
        let demand = (next_item_size as f64).max(mean_residual * 0.8);
        if (pr as f64) < demand {
            let dead = 1.0 - pr as f64 / demand;
            score += 15.0 * dead * dead * (1.0 - 0.5 * progress);
        }
    }

    // Gen 27: two-step exact-closure ladder.
    if next_item_size > 0 && item_size > 0 && pr >= item_size + next_item_size {
        let pr2 = pr - item_size - next_item_size;
        if pr2 == 0 {
            score -= 30.0 + 25.0 * (1.0 - progress);
        } else if pr2 <= 3 {
            score -= 16.0 * (1.0 - progress);
        }
    }

    // Gen 27: fresh-bin divisibility discount.
    if bin_residual == bin_capacity
        && item_size > 0
        && bin_capacity % item_size == 0
        && mean_residual > 0.0
        && (mean_residual as u32) % item_size != 0
        && progress > 0.15
    {
        score -= 12.0 * (1.0 - 0.6 * progress);
    }

    // Gen 27: late-stream tight-slack refinement.
    if progress > 0.66 && bin_residual >= item_size {
        let slack = bin_residual - item_size;
        if slack >= 3 && slack <= 6 && pr > 0 {
            score += 5.0 + 2.0 * (progress - 0.66) / 0.34;
        }
    }

    // Gen 28: two-chain residual tileability probe.
    if next_item_size > 1 && pr >= 2 * next_item_size {
        let pr2 = pr - 2 * next_item_size;
        if pr2 == 0 {
            score -= 20.0 + 14.0 * (1.0 - progress);
        } else if pr2 <= 2 {
            score += 6.0 * (1.0 - pr2 as f64 / 3.0);
        }
    }

    // Gen 28: fresh-bin mean-residual saturation gate.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && mean_residual > 0.0
        && (mean_residual as u32) < next_item_size
        && fitting_bins_count >= 1
        && progress > 0.1
        && progress < 0.85
    {
        let deficit = 1.0 - mean_residual / next_item_size as f64;
        score -= 18.0 * deficit * deficit * (1.0 - progress);
    }

    // Gen 28: mid-stream slack-quantization shaping.
    if pr > 0 && mean_residual >= 3.0 && progress > 0.15 && progress < 0.9 {
        let mr = mean_residual.min(cap);
        let diff = (pr as f64 - mr).abs();
        if diff <= 2.0 {
            score -= 8.0 * (1.0 - diff / 3.0) * (1.0 - 0.3 * progress);
        } else if diff > mr * 0.5 && diff < mr * 0.5 + 3.0 {
            score += 4.0 * (1.0 - progress);
        }
    }

    // Gen 29: dead-space gradient refinement — two-step demand horizon.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 {
        let horizon = next_item_size as f64 + mean_residual.min(cap * 0.35);
        if (pr as f64) < horizon {
            let dead2 = 1.0 - pr as f64 / horizon;
            score += 7.0 * dead2 * dead2 * (1.0 - 0.4 * progress);
        } else if (pr as f64) >= horizon + 4.0 && (pr as f64) <= horizon + 16.0 {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // Gen 29: waste-slope fresh-bin gate.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && fitting_bins_count >= 1
        && item_size + next_item_size <= bin_capacity
        && progress > 0.05
    {
        let pair = (item_size + next_item_size) as f64;
        let open_leftover = (mean_residual - pair).max(0.0);
        let fresh_leftover = cap - pair;
        if open_leftover <= fresh_leftover && mean_residual >= pair {
            score += 20.0 * (1.0 - 0.5 * progress);
        } else if open_leftover > fresh_leftover + 8.0 {
            score -= 10.0 * ((open_leftover - fresh_leftover - 8.0) / cap).min(0.2) * 40.0 * (1.0 - progress);
        }
    }

    // Gen 29: endgame residual-saturation refinement.
    if progress > 0.75 && next_item_size > 0 && pr > next_item_size {
        let over = pr - next_item_size;
        if over <= 2 {
            score -= 14.0 * (1.0 - over as f64 / 3.0) * ((progress - 0.75) / 0.25);
        }
    }

    // Gen 30: horizon-band tightening.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.9 {
        let horizon = next_item_size as f64 + mean_residual.min(cap * 0.35);
        let horizon3 = horizon + mean_residual.min(cap * 0.25);
        if (pr as f64) < horizon3 {
            let dead3 = 1.0 - pr as f64 / horizon3;
            score += 4.0 * dead3 * dead3 * (1.0 - 0.5 * progress);
        }
        let exact = (pr as f64 - horizon).abs();
        if exact <= 2.0 {
            score -= 9.0 * (1.0 - exact / 3.0) * (1.0 - 0.4 * progress);
        }
    }

    // Gen 30: fresh-bin triple-tile probe.
    if bin_residual == bin_capacity
        && item_size > 0
        && bin_capacity % item_size == 0
        && progress > 0.1
        && progress < 0.9
    {
        let slots = bin_capacity / item_size;
        if slots >= 3 && slots <= 5 && (mean_residual as u32) % item_size != 0 {
            score -= 10.0 * slots.min(4) as f64 * (1.0 - 0.6 * progress);
        }
    }

    // Gen 30: sliver-merging endgame sweep.
    if progress > 0.6 && pr >= 5 && pr <= 11 && mean_residual >= 3.0 {
        let similar = ((pr as f64 - mean_residual) / 4.0).abs() < 1.0;
        if similar {
            score -= 8.0 * (1.0 - 0.3 * progress);
        } else {
            score += 6.0 * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION (gen 31): slack-window fresh-bin gate refinement.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && mean_residual > 0.0
        && fitting_bins_count >= 1
        && progress > 0.05
        && progress < 0.9
    {
        let fresh_leftover = cap - item_size as f64;
        let open_leftover = mean_residual - item_size as f64;
        if open_leftover > 0.0 {
            let margin = open_leftover - fresh_leftover;
            if margin > 4.0 {
                score -= (6.0 + margin.min(20.0) * 0.9) * (1.0 - 0.5 * progress);
            } else if margin < -6.0 {
                score += 10.0 * (1.0 - 0.4 * progress);
            }
        }
    }

    // MUTATION (gen 31): two-item exact-horizon ladder.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress > 0.2 {
        let horizon = next_item_size as f64 + mean_residual.min(cap * 0.35);
        let gap = (pr as f64 - horizon).abs();
        if gap <= 1.0 {
            score -= 12.0 * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 31): endgame fresh-bin veto tightening.
    if bin_residual == bin_capacity && progress > 0.8 {
        let rel = item_size as f64 / cap;
        if rel < 0.5 && fitting_bins_count > 0 {
            score += 18.0 * (1.0 - rel) * ((progress - 0.8) / 0.2);
        }
    }

    // MUTATION (gen 32): waste-budget compaction.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.92 {
        let demand2 = (next_item_size as f64 + mean_residual.min(cap * 0.3)).max(next_item_size as f64);
        if (pr as f64) < demand2 {
            let waste_frac = 1.0 - (pr as f64) / demand2;
            let crowd = if open_bins_count > 8 { 1.25 } else { 1.0 };
            score += 13.0 * waste_frac * waste_frac * crowd * (1.0 - 0.45 * progress);
        } else {
            let absorbable = (pr as f64) >= item_size as f64 + demand2;
            if absorbable {
                score -= 8.0 * (1.0 - 0.5 * progress);
            }
        }
    }

    // MUTATION (gen 32): fresh-bin waste-parity gate.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && item_size + next_item_size <= bin_capacity
        && progress > 0.08
        && progress < 0.88
    {
        let fresh_left = cap - (item_size + next_item_size) as f64;
        let open_left = (mean_residual - (item_size + next_item_size) as f64).max(0.0);
        if fresh_left + 2.0 < open_left {
            score -= 16.0 * (1.0 - 0.5 * progress);
        } else if open_left + 2.0 < fresh_left && fitting_bins_count >= 1 {
            score += 12.0 * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 32): mid-stream residual ladder smoothing.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.25 && progress < 0.8 {
        let mr = mean_residual;
        let k = (pr as f64 / mr).round().max(1.0);
        let dev = (pr as f64 - k * mr).abs() / mr;
        if dev < 0.08 {
            score -= 14.0 * (1.0 - dev / 0.08) * (1.0 - 0.3 * progress);
        }
    }

    // MUTATION (gen 33): graded waste-budget refinement — replace the
    // binary absorbable reward in the gen-32 waste-budget term with a
    // graded ladder: residuals that absorb item + demand2 exactly get a
    // strong progress-scaled discount; residuals that absorb demand2 but
    // strand item get a mild penalty proportional to the stranded slack.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.92 {
        let demand2 = (next_item_size as f64 + mean_residual.min(cap * 0.3)).max(next_item_size as f64);
        if (pr as f64) >= demand2 {
            let over = pr as f64 - demand2;
            let exact_pair = ((over - item_size as f64).abs()) <= 1.0;
            if exact_pair {
                score -= 11.0 * (1.0 - 0.4 * progress);
            } else if over < item_size as f64 {
                let strand = 1.0 - over / item_size.max(1) as f64;
                score += 5.0 * strand * (1.0 - 0.5 * progress);
            }
        }
    }

    // MUTATION (gen 33): fresh-bin triple-parity veto — sharpen the
    // gen-32 waste-parity gate by also comparing the fresh leftover to
    // the mean open residual itself (not just the pair-adjusted one):
    // when open bins already hold enough space for the item plus another
    // mean-sized item, opening fresh space is nearly always waste.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && mean_residual > 0.0
        && fitting_bins_count >= 1
        && progress > 0.1
        && progress < 0.85
    {
        let open_capacity = mean_residual - item_size as f64;
        if open_capacity >= next_item_size as f64 && open_capacity < cap * 0.55 {
            score += 14.0 * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION (gen 33): residual ladder anti-fragmentation sweep —
    // residuals just below the mean residual (within 3 units) are the
    // classic fragmentation source mid-stream: they cannot absorb a
    // mean-sized item and will strand. Penalize them with a smooth ramp
    // that grows with open-bin crowding, while rewarding residuals just
    // above the mean that keep the pooling ladder intact.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.2 && progress < 0.88 {
        let mr = mean_residual.min(cap);
        let below = mr - pr as f64;
        if below > 0.0 && below <= 3.0 {
            let crowd = if open_bins_count > 10 { 1.3 } else { 1.0 };
            score += (4.0 + 3.0 * (1.0 - below / 4.0)) * crowd * (1.0 - 0.4 * progress);
        } else if below < 0.0 && -below <= 2.0 {
            score -= 5.0 * (1.0 - (-below) / 3.0) * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 33): endgame exact-closure ladder extension — in the
    // final 15%, residuals that absorb next + item exactly (leaving zero)
    // deserve a stronger reward than the parent's flat 26.0; scale it by
    // progress so late-stream exact pairings dominate all other choices.
    if progress > 0.85 && next_item_size > 0 && pr == item_size.max(1) + next_item_size {
        score -= 14.0 * ((progress - 0.85) / 0.15);
    }

    // MUTATION (gen 38): dead-space ratio compaction refinement — the
    // diagnosed weakness is suboptimal residual space. Extend the graded
    // waste-budget ladder with a continuous dead-space gradient that
    // rewards residuals whose post-fill leftover matches the mean open
    // residual (pooling-compatible), and penalizes leftovers that fall
    // just below it (fragmentation-prone). Smooth ramp, progress-scaled.
    if pr > 0 && next_item_size > 0 && mean_residual >= 3.0 && progress > 0.15 && progress < 0.9 {
        let mr = mean_residual.min(cap * 0.6);
        if (pr as f64) >= next_item_size as f64 {
            let left = pr as f64 - next_item_size as f64;
            let dev = (left - mr) / mr;
            if dev.abs() < 0.35 {
                let dir = if dev >= 0.0 { -1.0 } else { 1.0 };
                score += dir * 9.0 * (1.0 - (dev / 0.35).abs()) * (1.0 - 0.45 * progress);
            }
        }
    }

    // MUTATION (gen 38): fresh-bin dead-space parity — open a fresh bin
    // only when the fresh leftover after placing item+next is at least as
    // reusable as the mean open leftover; otherwise prefer consolidation.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && item_size + next_item_size <= bin_capacity
        && mean_residual > 0.0
        && progress > 0.1
        && progress < 0.85
    {
        let fresh_left = cap - (item_size + next_item_size) as f64;
        let open_left = (mean_residual - next_item_size as f64).max(0.0);
        if fresh_left + 1.0 >= open_left && open_left > 0.0 {
            score -= 10.0 * (1.0 - 0.5 * progress);
        } else if fresh_left + 1.0 < open_left {
            score += 8.0 * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 38): endgame sliver pooling ladder — in the final
    // stretch, residuals within one unit of the mean residual are prime
    // merge targets; reward them strongly and penalize near-misses to
    // squeeze out the last bins.
    if progress > 0.7 && pr > 0 && mean_residual >= 2.0 {
        let mr = mean_residual.min(cap);
        let dev = (pr as f64 - mr).abs();
        if dev <= 1.0 {
            score -= 10.0 * ((progress - 0.7) / 0.3);
        } else if dev <= 4.0 {
            score += 6.0 * (1.0 - dev / 4.0) * ((progress - 0.7) / 0.3);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fills (low post_residual weighted more). Late: waste tolerance rises.
    let w = 1.0 + 2.0 * progress * progress;
    let norm_pr = pr / cap;
    score += w * 12.0 * norm_pr * norm_pr * cap;

    // Reward near-perfect fits with a smooth quadratic bonus.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio * fit_ratio;

    // Penalize dead space relative to mean residual across open bins.
    score += 0.08 * (pr - mean_residual).abs();

    // Lookahead: if next item fits in post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }
    // If next item does not fit, penalize proportionally to wasted potential.
    if next_item_size > post_residual {
        score += 0.05 * next_item_size as f64;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress);
    }

    // New empty bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(1.0);
        score = cap * (1.0 - 0.35 * progress) + 3.0 * openness;
        if fitting_bins_count == 1 {
            score += 20.0; // discourage opening new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Sharpened perfect/near-perfect closure rewards.
    if pr == 0 {
        score -= 1280.0;
    } else if pr <= 4 {
        score -= 92.0 + (4 - pr) as f64 * 13.0;
    } else if pr < 12 {
        score += 30.0 - pr as f64;
    }

    // Harmonic residue classes.
    let class_bonus: f64 = if pr % 10 == 0 {
        36.0
    } else if pr % 5 == 0 {
        18.0
    } else if pr % 2 == 0 {
        5.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Lookahead: next item fit quality into post-placement residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 178.0 + 40.0 * (1.0 - progress);
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= if slack <= 10 { 66.0 - slack as f64 * 2.6 } else { 34.0 - (slack as f64).min(30.0) * 0.5 };
        } else {
            score += (next_item_size - pr) as f64 * 0.68;
        }
        if next_item_size < pr {
            let pr2 = pr - next_item_size;
            if pr2 <= 6 {
                score -= 52.0;
            } else if pr2 == next_item_size {
                score -= 27.0;
            } else if pr2 % 10 == 0 {
                score -= 12.0;
            }
            if pr2 > 6 && next_item_size > 1 && pr2 % next_item_size == 0 {
                score -= 15.0;
            }
            if pr2 >= 2 * item_size && item_size > 0 && pr2 % item_size == 0 {
                score -= 8.0;
            }
            if pr2 >= 3 * item_size.max(1) {
                score -= 6.0;
            }
            // Chain lookahead via mean-residual proxy.
            if pr2 > 0 && mean_residual > 0.0 {
                let proxy = mean_residual.round() as u32;
                if proxy >= 1 && proxy <= pr2 {
                    score -= 9.0 * (1.0 - progress);
                }
            }
            // Triple-chain closure.
            if pr2 >= 2 * next_item_size {
                let pr3 = pr2 - 2 * next_item_size;
                if pr3 <= 3 {
                    score -= 24.0 * (1.0 - progress);
                }
            }
            // next + item leaves near-perfect closure.
            if pr2 >= item_size.max(1) {
                let pr3 = pr2 - item_size.max(1);
                if pr3 <= 2 {
                    score -= 20.0 * (1.0 - progress);
                }
            }
        }
        // Pair-absorbency.
        if pr > 1 && pr == 2 * next_item_size {
            score -= 22.0;
        }
        // Stranded residual just below next item.
        if pr > 0 && pr < next_item_size {
            let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
            score += (7.0 + 5.0 * gap_frac) * (1.0 - progress);
        }
    } else {
        // Last item: any bin that fits is fine; prefer tightest.
        score -= 20.0;
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 66.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap) < 0.38;
        let reuse_is_bad = fitting_bins_count <= 1
            || (pr > 0 && next_item_size > pr && next_item_size <= bin_capacity);
        let late_large = item_size >= 60 && progress > 0.10;
        if late_large || (tight && progress > 0.15) || reuse_is_bad {
            score -= 46.0 + 30.0 * progress;
        } else {
            score += 70.0;
        }
        if item_size <= 25 && mean_residual > cap * 0.45 {
            score += 36.0;
        }
        if open_bins_count > 12 && progress < 0.3 {
            score += 12.0;
        }
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 24.0 + 18.0 * (1.0 - progress);
        }
        if next_item_size >= bin_capacity / 2 && mean_residual < (item_size + next_item_size) as f64 {
            score -= 10.0 + 14.0 * (1.0 - progress);
        }
        if item_size + next_item_size == bin_capacity
            && mean_residual < (item_size + next_item_size) as f64
        {
