    }

    // MUTATION (gen 39): slack-window fresh-bin gate.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && mean_residual > 0.0
        && fitting_bins_count >= 1
        && progress > 0.05
        && progress < 0.9
    {
        let fresh_leftover = cap - item_size as f64;
        let open_leftover = mean_residual - item_size as f64;
