    }

    // MUTATION (gen 39): endgame exact-pair ladder extension.
    if progress > 0.85 && next_item_size > 0 && pr == item_size.max(1) + next_item_size {
        score -= 14.0 * ((progress - 0.85) / 0.15);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize leftover space into capacity fractions.
    // Small leftovers (< ~capacity/8) are "dead space" -> penalize; large leftovers are reusable.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.125 {
        score += (0.125 - frac) * 180.0; // dead-space penalty
    } else if frac < 0.25 {
        score -= 6.0; // mildly attractive small-but-usable leftover
    } else {
        score -= 10.0; // large reusable leftover
    }

    // Modulo-10 harmonic class: leftovers that are multiples of common item sizes
    // (10, 20, 25, 50) are more likely to be exactly filled later.
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 { score -= 8.0; }
    if pr % 25 == 0 && pr > 0 { score -= 4.0; }
    if pr % 50 == 0 && pr > 0 { score -= 4.0; }

    // Lookahead: if next item exactly fills the post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            // next item fits: leftover class after hypothetical placement
            let next_post = pr - next_item_size;
            if next_post % 10 == 0 { score -= 6.0; }
            if next_post < bin_capacity / 8 { score += 4.0; }
        } else {
            // next item won't fit here: slight penalty proportional to mismatch
            score += ((next_item_size - pr) as f64).min(40.0) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Prefer tighter bins among fitting candidates (best-fit core with sharpening).
    score -= (bin_residual as f64).ln() * 3.0;

    // Penalize opening a new bin when decent alternatives exist.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 25.0 + 30.0 * pressure;
        if open_bins_count == 0 { score -= 60.0; } // must open first bin
    }

    // Late-stream consolidation: near the end, favor filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

