    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * 0.5;

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        score += 25.0 + pressure * 0.3;
        if fitting_bins_count > 0 && post_residual >= item_size as u32 {
