    {
        let slots = bin_capacity / item_size;
        if slots >= 3 && slots <= 5 && (mean_residual as u32) % item_size != 0 {
            score -= 10.0 * slots.min(4) as f64 * (1.0 - 0.6 * progress);
        }
    }

    // Gen 30: sliver-merging endgame sweep.
    if progress > 0.6 && pr >= 5 && pr <= 11 && mean_residual >= 3.0 {
        let similar = ((pr as f64 - mean_residual) / 4.0).abs() < 1.0;
        if similar {
            score -= 8.0 * (1.0 - 0.3 * progress);
        } else {
            score += 6.0 * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION (gen 31): slack-window fresh-bin gate refinement.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && mean_residual > 0.0
        && fitting_bins_count >= 1
        && progress > 0.05
        && progress < 0.9
    {
        let fresh_leftover = cap - item_size as f64;
        let open_leftover = mean_residual - item_size as f64;
        if open_leftover > 0.0 {
            let margin = open_leftover - fresh_leftover;
            if margin > 4.0 {
                score -= (6.0 + margin.min(20.0) * 0.9) * (1.0 - 0.5 * progress);
            } else if margin < -6.0 {
                score += 10.0 * (1.0 - 0.4 * progress);
            }
        }
    }

    // MUTATION (gen 31): two-item exact-horizon ladder.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress > 0.2 {
        let horizon = next_item_size as f64 + mean_residual.min(cap * 0.35);
        let gap = (pr as f64 - horizon).abs();
        if gap <= 1.0 {
            score -= 12.0 * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 31): endgame fresh-bin veto tightening.
    if bin_residual == bin_capacity && progress > 0.8 {
        let rel = item_size as f64 / cap;
        if rel < 0.5 && fitting_bins_count > 0 {
            score += 18.0 * (1.0 - rel) * ((progress - 0.8) / 0.2);
        }
    }

    // MUTATION (gen 32): waste-budget compaction.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.92 {
        let demand2 = (next_item_size as f64 + mean_residual.min(cap * 0.3)).max(next_item_size as f64);
        if (pr as f64) < demand2 {
            let waste_frac = 1.0 - (pr as f64) / demand2;
            let crowd = if open_bins_count > 8 { 1.25 } else { 1.0 };
            score += 13.0 * waste_frac * waste_frac * crowd * (1.0 - 0.45 * progress);
        } else {
            let absorbable = (pr as f64) >= item_size as f64 + demand2;
            if absorbable {
                score -= 8.0 * (1.0 - 0.5 * progress);
            }
        }
    }

    // MUTATION (gen 32): fresh-bin waste-parity gate.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && item_size + next_item_size <= bin_capacity
        && progress > 0.08
        && progress < 0.88
    {
        let fresh_left = cap - (item_size + next_item_size) as f64;
        let open_left = (mean_residual - (item_size + next_item_size) as f64).max(0.0);
        if fresh_left + 2.0 < open_left {
            score -= 16.0 * (1.0 - 0.5 * progress);
        } else if open_left + 2.0 < fresh_left && fitting_bins_count >= 1 {
            score += 12.0 * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 32): mid-stream residual ladder smoothing.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.25 && progress < 0.8 {
        let mr = mean_residual;
        let k = (pr as f64 / mr).round().max(1.0);
        let dev = (pr as f64 - k * mr).abs() / mr;
        if dev < 0.08 {
            score -= 14.0 * (1.0 - dev / 0.08) * (1.0 - 0.3 * progress);
        }
    }

    // MUTATION (gen 33): graded waste-budget refinement.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.92 {
        let demand2 = (next_item_size as f64 + mean_residual.min(cap * 0.3)).max(next_item_size as f64);
        if (pr as f64) >= demand2 {
            let over = pr as f64 - demand2;
            let exact_pair = ((over - item_size as f64).abs()) <= 1.0;
            if exact_pair {
                score -= 11.0 * (1.0 - 0.4 * progress);
            } else if over < item_size as f64 {
                let strand = 1.0 - over / item_size.max(1) as f64;
                score += 5.0 * strand * (1.0 - 0.5 * progress);
            }
        }
    }

    // MUTATION (gen 33): fresh-bin triple-parity veto.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && mean_residual > 0.0
        && fitting_bins_count >= 1
        && progress > 0.1
        && progress < 0.85
    {
        let open_capacity = mean_residual - item_size as f64;
        if open_capacity >= next_item_size as f64 && open_capacity < cap * 0.55 {
            score += 14.0 * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION (gen 33): residual ladder anti-fragmentation sweep.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.2 && progress < 0.88 {
        let mr = mean_residual.min(cap);
        let below = mr - pr as f64;
        if below > 0.0 && below <= 3.0 {
            let crowd = if open_bins_count > 10 { 1.3 } else { 1.0 };
            score += (4.0 + 3.0 * (1.0 - below / 4.0)) * crowd * (1.0 - 0.4 * progress);
        } else if below < 0.0 && -below <= 2.0 {
            score -= 5.0 * (1.0 - (-below) / 3.0) * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 33): endgame exact-closure ladder extension.
    if progress > 0.85 && next_item_size > 0 && pr == item_size.max(1) + next_item_size {
        score -= 14.0 * ((progress - 0.85) / 0.15);
    }

    // MUTATION (gen 41): graded dead-space gradient — replace the binary
    // "fits next / fits mean" dead-space test with a smooth two-sided
    // coupling: residuals slightly above the demand horizon are rewarded
    // proportionally to how little slack they strand, while residuals
    // just below the next item get an amplified quadratic penalty whose
    // weight grows with open-bin crowding (dead space is costlier when
    // many bins compete for the same items).
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.93 {
        let demand = (next_item_size as f64).max(mean_residual * 0.85);
        let prf = pr as f64;
        let crowd = if open_bins_count > 8 { 1.35 } else { 1.0 };
        if prf >= demand {
            let slack = prf - demand;
            if slack <= 4.0 {
                score -= (9.0 + 3.0 * (4.0 - slack)) * (1.0 - 0.5 * progress);
            } else if slack < item_size as f64 {
                score += 3.0 * (slack / item_size.max(1) as f64) * (1.0 - 0.5 * progress);
            }
        } else {
            let dead = 1.0 - prf / demand;
            score += 17.0 * dead * dead * crowd * (1.0 - 0.45 * progress);
        }
    }

    // MUTATION (gen 41): fresh-bin horizon-parity override — open a fresh
    // bin only when the fresh leftover after placing item+next beats the
    // best open leftover by a strict margin; otherwise the open-bin pool
    // absorbs the pair. This sharpens the parity gates into a single
    // margin comparison with a progress-scaled threshold.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && item_size + next_item_size <= bin_capacity
        && fitting_bins_count >= 1
        && progress > 0.05
        && progress < 0.9
    {
        let pair = (item_size + next_item_size) as f64;
        let fresh_left = cap - pair;
        let open_left = (mean_residual - pair).max(0.0);
        let margin = fresh_left - open_left;
        let thr = 3.0 + 4.0 * progress;
        if margin > thr {
            score -= (10.0 + margin.min(24.0) * 0.7) * (1.0 - 0.5 * progress);
        } else if margin < -thr {
            score += 13.0 * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 41): endgame sliver-pooling ladder — in the final 20%,
    // residuals that can chain two mean-sized items exactly (pr == 2*mean)
    // or absorb next+mean exactly get a strong discount, since late-stream
    // exact pooling is what closes the last bins without waste.
    if progress > 0.8 && pr > 0 && mean_residual >= 2.0 {
        let mr = mean_residual.min(cap * 0.6);
        let prf = pr as f64;
        if (prf - 2.0 * mr).abs() <= 1.0 {
            score -= 16.0 * ((progress - 0.8) / 0.2);
        } else if next_item_size > 0 && (prf - (next_item_size as f64 + mr)).abs() <= 1.0 {
            score -= 12.0 * ((progress - 0.8) / 0.2);
        }
    }

    // MUTATION (gen 41): near-closure slack shaping — residuals within 2
    // units of a multiple of the next item tile perfectly; reward them
    // with a mild progress-scaled discount to reinforce repeatable fills.
    if pr > 0 && next_item_size > 1 && progress > 0.1 && progress < 0.9 {
        let k = (pr as f64 / next_item_size as f64).round();
        if k >= 1.0 {
            let dev = (pr as f64 - k * next_item_size as f64).abs();
            if dev <= 2.0 {
                score -= 6.0 * (1.0 - dev / 3.0) * (1.0 - 0.4 * progress);
            }
        }
    }

    // MUTATION (gen 42): crowd-scaled horizon-parity refinement — the gen 41
    // fresh-bin margin gate ignores how many open bins compete for the pair.
    // When several bins could absorb item+next, a fresh bin is far costlier;
    // when only one can, the margin threshold should relax so scarce open
    // space is not wasted on a poor two-item fit.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && item_size + next_item_size <= bin_capacity
        && fitting_bins_count >= 1
        && progress > 0.05
        && progress < 0.9
    {
        let pair = (item_size + next_item_size) as f64;
        let fresh_left = cap - pair;
        let open_left = (mean_residual - pair).max(0.0);
        let margin = fresh_left - open_left;
        let crowd_scale = if fitting_bins_count >= 3 {
            1.6
        } else if fitting_bins_count == 2 {
            1.15
        } else {
            0.7
        };
        let thr = (3.0 + 4.0 * progress) * crowd_scale;
        if margin > thr {
            score -= (8.0 + margin.min(24.0) * 0.75) * (1.0 - 0.5 * progress);
        } else if margin < -thr {
            score += 11.0 * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 42): residual variance-aware dead-space damping — when
    // open residuals cluster tightly around the mean (low variance proxy via
    // mean_residual proximity of pr), pooling into the mean-sized residual is
    // safe; when residuals are scattered, avoid stranding near-mean slivers
    // and prefer exact closure. This sharpens the diagnosed dead-space
    // weakness with a distribution-shape signal rather than a level signal.
    if pr > 0 && mean_residual >= 3.0 && progress > 0.15 && progress < 0.9 {
        let mr = mean_residual.min(cap);
        let dev = (pr as f64 - mr) / mr.max(1.0);
        if dev.abs() < 0.12 {
            // Near-mean residual: reward pooling when many bins share the shape.
            let pool_w = if open_bins_count >= 6 { 1.0 } else { 0.5 };
            score -= 9.0 * (1.0 - (dev.abs() / 0.12)) * pool_w * (1.0 - 0.35 * progress);
        } else if dev > 0.25 && dev < 0.55 && pr > next_item_size {
            // Mid-band overshoot: mild reward for absorbing the next item too.
            if next_item_size > 0 && (pr as f64) - next_item_size as f64 >= mr {
                score -= 6.0 * (1.0 - 0.4 * progress);
            }
        }
    }

    // MUTATION (gen 42): graded dead-space gradient extension — reward
    // residuals that leave exactly one mean-item of slack after absorbing
    // the demand horizon; this chains the horizon term one step further
    // in the same direction as the successful gen 41 mutation.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress > 0.1 && progress < 0.9 {
        let demand = (next_item_size as f64).max(mean_residual * 0.85);
        let chain = demand + mean_residual.min(cap * 0.4);
        let prf = pr as f64;
        if prf >= chain && prf - chain <= 3.0 {
            score -= 10.0 * (1.0 - (prf - chain) / 4.0) * (1.0 - 0.45 * progress);
        }
    }

    // MUTATION (gen 42): endgame fresh-bin exact-pair reinforcement — in the
    // final stretch, opening a fresh bin is only justified when item+next
    // fills it exactly; otherwise the open pool must absorb everything.
    if bin_residual == bin_capacity && progress > 0.75 {
        if item_size + next_item_size == bin_capacity {
            score -= 24.0 * ((progress - 0.75) / 0.25);
        } else if fitting_bins_count > 0 {
            score += 14.0 * ((progress - 0.75) / 0.25);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Sharpened perfect/near-perfect closure rewards.
    if pr == 0 {
        score -= 1280.0;
    } else if pr <= 4 {
        score -= 92.0 + (4 - pr) as f64 * 13.0;
    } else if pr < 12 {
        score += 30.0 - pr as f64;
    }

    // Harmonic residue classes.
    let class_bonus: f64 = if pr % 10 == 0 {
        36.0
    } else if pr % 5 == 0 {
        18.0
    } else if pr % 2 == 0 {
        5.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Lookahead: next item fit quality into post-placement residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 178.0 + 40.0 * (1.0 - progress);
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= if slack <= 10 { 66.0 - slack as f64 * 2.6 } else { 34.0 - (slack as f64).min(30.0) * 0.5 };
        } else {
            score += (next_item_size - pr) as f64 * 0.68;
        }
        if next_item_size < pr {
            let pr2 = pr - next_item_size;
            if pr2 <= 6 {
                score -= 52.0;
            } else if pr2 == next_item_size {
                score -= 27.0;
            } else if pr2 % 10 == 0 {
                score -= 12.0;
            }
            if pr2 > 6 && next_item_size > 1 && pr2 % next_item_size == 0 {
                score -= 15.0;
            }
            if pr2 >= 2 * item_size && item_size > 0 && pr2 % item_size == 0 {
                score -= 8.0;
            }
            if pr2 >= 3 * item_size.max(1) {
                score -= 6.0;
            }
            // Chain lookahead via mean-residual proxy.
            if pr2 > 0 && mean_residual > 0.0 {
                let proxy = mean_residual.round() as u32;
                if proxy >= 1 && proxy <= pr2 {
                    score -= 9.0 * (1.0 - progress);
                }
            }
            // Triple-chain closure.
            if pr2 >= 2 * next_item_size {
                let pr3 = pr2 - 2 * next_item_size;
                if pr3 <= 3 {
                    score -= 24.0 * (1.0 - progress);
                }
            }
            // next + item leaves near-perfect closure.
            if pr2 >= item_size.max(1) {
                let pr3 = pr2 - item_size.max(1);
                if pr3 <= 2 {
                    score -= 20.0 * (1.0 - progress);
                }
            }
        }
        // Pair-absorbency.
        if pr > 1 && pr == 2 * next_item_size {
            score -= 22.0;
        }
        // Stranded residual just below next item.
        if pr > 0 && pr < next_item_size {
            let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
            score += (7.0 + 5.0 * gap_frac) * (1.0 - progress);
        }
    } else {
        // Last item: any bin that fits is fine; prefer tightest.
        score -= 20.0;
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 66.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap) < 0.38;
        let reuse_is_bad = fitting_bins_count <= 1
            || (pr > 0 && next_item_size > pr && next_item_size <= bin_capacity);
        let late_large = item_size >= 60 && progress > 0.10;
        if late_large || (tight && progress > 0.15) || reuse_is_bad {
            score -= 46.0 + 30.0 * progress;
        } else {
            score += 70.0;
        }
        if item_size <= 25 && mean_residual > cap * 0.45 {
            score += 36.0;
        }
        if open_bins_count > 12 && progress < 0.3 {
            score += 12.0;
        }
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 24.0 + 18.0 * (1.0 - progress);
        }
        if next_item_size >= bin_capacity / 2 && mean_residual < (item_size + next_item_size) as f64 {
            score -= 10.0 + 14.0 * (1.0 - progress);
        }
        if item_size + next_item_size == bin_capacity
            && mean_residual < (item_size + next_item_size) as f64
        {
            score -= 20.0;
        }
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size {
            let strand = mean_residual as u32 - item_size;
            if strand > 0 && strand < 8 && progress > 0.2 {
                score -= 14.0 + 6.0 * (1.0 - progress);
            }
        }
        // Fresh-bin exact-pair bonus.
        if item_size + next_item_size == bin_capacity {
            score -= 34.0 + 20.0 * (1.0 - progress);
        }
        if pr > 0 && pr < item_size / 3 && item_size >= 30 {
            score -= 12.0;
        }
        // Fresh-bin viability gate.
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size && fitting_bins_count > 1 && !late_large {
            score += 30.0 * (1.0 - progress);
        }
        // Fresh-bin scarcity coupling.
        if fitting_bins_count >= 2 && item_size >= 40 {
            let best_gap = mean_residual - item_size as f64;
            if best_gap > 12.0 {
                score -= (best_gap / cap).min(0.25) * 80.0 * (1.0 - progress);
            }
        }
        // Fresh-bin only when the item cannot tile any open residual
        // with the next item — otherwise fresh space fragments the stream.
        if next_item_size > 0
            && fitting_bins_count >= 1
            && item_size + next_item_size <= bin_capacity
            && mean_residual >= (item_size + next_item_size) as f64
            && progress < 0.6
        {
            score += 18.0 * (1.0 - progress);
        }
        // Fresh-bin slot-arithmetic probe.
        if item_size > 0 && bin_capacity % item_size == 0 {
            let slots = bin_capacity / item_size;
            if slots >= 2 && slots <= 4 && progress > 0.1 {
                score -= 14.0 * (slots as f64).min(3.0) * (1.0 - 0.5 * progress);
            }
        }
        // Fresh-bin residual-mirror check.
        if mean_residual > item_size as f64 * 1.6 && progress > 0.3 {
            score += 16.0 * (1.0 - 0.5 * progress);
        }
        // Fresh-bin dead-space forecast.
        if next_item_size > 0
            && fitting_bins_count >= 2
            && mean_residual > 0.0
            && (item_size as f64 + next_item_size as f64 + mean_residual) <= cap
            && progress < 0.55
        {
            score += 14.0 * (1.0 - progress);
        }
        // Endgame fresh-bin hard gate.
        if progress > 0.7 && fitting_bins_count > 0 && !late_large {
            score += 45.0 * ((progress - 0.7) / 0.3);
        }
    }

    // Best-fit bias.
    score -= (bin_capacity - bin_residual) as f64 * 0.16;

    // Flexible mid-range residual target.
    if pr >= 25 && pr <= 65 {
        score -= 14.0;
    }

    // Proliferation penalty.
    score += open_bins_count as f64 * (0.2 + 0.2 * progress);

    // Waste-avoidance for tiny residuals.
    if pr > 0 && pr < bin_capacity / 5 {
        let scarcity = if fitting_bins_count > 2 { 0.6 } else { 1.4 };
        score += (10.0 + 4.0 * progress) * scarcity;
    }

    // Tightness bonus.
    if bin_residual >= item_size {
        let tightness = 1.0 - ((bin_residual - item_size) as f64 / cap);
        score -= 6.0 * tightness;
    }

    // Mean-residual alignment.
    let align = ((pr as f64 - mean_residual) / cap).abs();
    score += align * (if progress > 0.2 && progress < 0.8 { 4.5 } else { 6.0 });

    // Odd small residuals are dead-space candidates.
    if pr > 0 && pr < 20 && pr % 2 == 1 {
        score += 7.0;
    }

    // Mid-stream consolidation of large absorbable residuals.
    if open_bins_count > 8 && progress > 0.25 && progress < 0.85 && pr >= 40 {
        score -= 9.0;
    }

    // Dead-space ratio shaping with next-item floor.
    if pr > 0 && next_item_size > 0 {
        let dead_threshold = (next_item_size + 12).min(bin_capacity);
        if pr < dead_threshold {
            let dead_frac = 1.0 - (pr as f64 / dead_threshold as f64);
            score += 18.0 * dead_frac * (1.0 - progress);
        } else if pr >= dead_threshold * 2 {
            score -= 8.0 + 4.0 * (1.0 - progress);
        } else if pr == next_item_size + item_size {
            score -= 5.0;
        }
    }

    // Endgame exactness.
    if progress > 0.9 && pr > 0 {
        score += pr as f64 * 0.35;
        if pr <= next_item_size.max(1) {
            score -= 20.0;
        }
    }

    // Fragment guard against typical upcoming demand.
    if pr > 0 && progress > 0.1 {
        let typical = (mean_residual * 0.5).max(8.0).min(cap * 0.5);
        if (pr as f64) < typical {
            score += 6.0 * (1.0 - (pr as f64 / typical)) * (1.0 - progress);
        }
    }

    // Exact-closure sweep with plentiful fitting bins.
    if pr == 0 && fitting_bins_count > 2 {
        score -= 12.0 * (1.0 - progress);
    }

    // Dual lookahead — repeatable fill detection.
    if next_item_size > 0 && next_item_size < pr {
        let pr2 = pr - next_item_size;
        if pr2 > 0 && item_size > 1 && pr2 % item_size == 0 && next_item_size % item_size == 0 {
            score -= 10.0;
        }
    }

    // Half-capacity residual targeting mid-stream.
    if pr > 0 && progress > 0.15 && progress < 0.9 {
        let half = cap * 0.5;
        let dist = ((pr as f64 - half) / half).abs();
        if dist < 0.25 {
            score -= 7.0 * (1.0 - dist / 0.25);
        }
    }

    // Dead-space ratio term with smooth quadratic ramp.
    if pr > 0 {
        let pr_f = pr as f64;
        let usable_floor = (next_item_size.max(1) as f64).min(cap * 0.3);
        if pr_f < usable_floor {
            let dsr = 1.0 - pr_f / usable_floor;
            score += 11.0 * dsr * dsr * (0.5 + 0.5 * (1.0 - progress));
        }
        if pr % 3 == 0 && pr >= 6 {
            score -= 5.0;
        }
        if pr % 7 == 0 && pr >= 7 {
            score -= 4.0;
        }
    }

    // Bin-count pressure valve.
    if bin_residual != bin_capacity && mean_residual > 0.0 {
        let fill = 1.0 - mean_residual / cap;
        if fill > 0.75 && fitting_bins_count > 1 {
            score -= 6.0 * (fill - 0.75) / 0.25;
        } else if fill < 0.5 && fitting_bins_count > 1 {
            score += 4.0 * (0.5 - fill) / 0.5 * (1.0 - progress);
        }
    }

