        }
    }

    // Perfect-fit dominance gate for the fresh-bin candidate.
    if pr == 0 && bin_residual == bin_capacity {
        score += 1400.0;
    }

    // MUTATION (gen 44): dead-space quanta elimination — residuals whose
    // leftover after absorbing next cannot fit a mean-sized follow-up
    // (i.e. pr2 < mean_residual) create bins that can never close. Reward
    // residuals where pr2 >= mean_residual within a tight margin, and
    // penalize the "orphan band" just under mean_residual proportionally
    // to how far the orphan is from being reusable.
    if pr > 0 && next_item_size > 0 && mean_residual >= 2.0 && progress < 0.9 {
        let pr2 = pr - next_item_size.min(pr);
        let mr = mean_residual.min(cap * 0.6);
        if pr2 > 0 {
            let orphan = mr - pr2 as f64;
            if orphan > 0.0 && orphan <= 6.0 {
                let crowd = if open_bins_count > 8 { 1.3 } else { 1.0 };
