    // MUTATION (gen 44): dual-horizon tiling probe — combine fine residual
    // fitting with lookahead by checking whether item+next leaves a
    // residual that itself tiles by the mean residual. Bins whose
    // post-pair leftover matches the stream's typical leftover are the
    // ones that close cleanly later; give them a progress-scaled pull.
    if pr > 0 && next_item_size > 0 && mean_residual >= 3.0 && progress > 0.15 && progress < 0.9 {
        let pair = item_size.max(1) + next_item_size;
        if pr >= pair {
            let rest = pr - pair;
            let k = (rest as f64 / mean_residual).round().max(1.0);
            let dev = (rest as f64 - k * mean_residual).abs() / mean_residual;
            if dev < 0.12 {
                score -= 9.0 * (1.0 - dev / 0.12) * (1.0 - 0.35 * progress);
