    // smooth open-count term. Conversely, when few bins remain reusable
    // (fitting_bins_count small) and the item is large, opening is cheap.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let open_ratio = open_bins_count as f64 / (step_index as f64 + 1.0).max(1.0);
        if mean_residual >= item_size as f64 && open_ratio > 0.3 && progress > 0.1 && progress < 0.85 {
            score += 10.0 * ((open_ratio - 0.3) / 0.4).min(1.0) * (1.0 - 0.4 * progress);
        }
        if item_size >= bin_capacity / 3 && fitting_bins_count <= 1 {
            score -= 12.0 + 10.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 44): endgame exact-multiple closure sweep — in the
    // final quarter, residuals that are exact multiples of the next item
    // (or of the mean residual) close without waste; reward them sharply
    // since late exact pooling is what saves the last bins.
    if progress > 0.75 && pr > 0 && next_item_size > 1 {
        let scale = ((progress - 0.75) / 0.25);
        if pr % next_item_size == 0 && pr / next_item_size >= 1 {
            score -= 10.0 * scale;
        } else if mean_residual >= 2.0 && (pr as f64) >= mean_residual {
            let k = (pr as f64 / mean_residual).round();
            if k >= 1.0 && (pr as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 8.0 * scale;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
