    }

    // Endgame exactness.
    if progress > 0.9 && pr > 0 {
        score += pr as f64 * 0.35;
        if pr <= next_item_size.max(1) {
            score -= 20.0;
        }
    }

    // Perfect-fit dominance gate for the fresh-bin candidate.
    if pr == 0 && bin_residual == bin_capacity {
        score += 1400.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Sharpened perfect/near-perfect closure rewards (borrowed strength).
    if pr == 0 {
        score -= 1280.0;
    } else if pr <= 4 {
        score -= 92.0 + (4 - pr) as f64 * 13.0;
