pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize waste, but non-linearly (quadratic dead-space penalty).
    let mut score = norm_pr * norm_pr * cap + 0.35 * pr;

    // Smooth coupling: waste matters more as the stream progresses.
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits: small post_residual relative to item size.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize leaving a residual that is nearly useless but not zero:
    // smooth trough around small residuals via a bell-shaped bonus.
    let small_res_bonus = (-norm_pr * 8.0).exp();
    score -= 6.0 * small_res_bonus;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: reward residuals that can still hold the next item.
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as i32 as f64;
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 5.0 * fits_next * (1.0 - gap);
        score += 3.0 * gap * (1.0 - fits_next);
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score += 0.4 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: neutral-ish baseline, slightly penalized early,
    // increasingly attractive late when open bins have poor fit.
    if bin_residual == bin_capacity {
        score = 10.0 - 14.0 * progress * progress + 0.02 * mean_residual;
    }

    score
}

