        } else if open_left + 2.0 < fresh_left && fitting_bins_count >= 1 {
            score += 12.0 * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 32): mid-stream residual ladder smoothing.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.25 && progress < 0.8 {
        let mr = mean_residual;
        let k = (pr as f64 / mr).round().max(1.0);
        let dev = (pr as f64 - k * mr).abs() / mr;
        if dev < 0.08 {
            score -= 14.0 * (1.0 - dev / 0.08) * (1.0 - 0.3 * progress);
        }
    }

    // MUTATION (gen 33): graded waste-budget refinement.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.92 {
        let demand2 = (next_item_size as f64 + mean_residual.min(cap * 0.3)).max(next_item_size as f64);
        if (pr as f64) >= demand2 {
            let over = pr as f64 - demand2;
            let exact_pair = ((over - item_size as f64).abs()) <= 1.0;
            if exact_pair {
                score -= 11.0 * (1.0 - 0.4 * progress);
            } else if over < item_size as f64 {
                let strand = 1.0 - over / item_size.max(1) as f64;
                score += 5.0 * strand * (1.0 - 0.5 * progress);
            }
        }
    }

    // MUTATION (gen 33): fresh-bin triple-parity veto.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && mean_residual > 0.0
        && fitting_bins_count >= 1
        && progress > 0.1
        && progress < 0.85
    {
        let open_capacity = mean_residual - item_size as f64;
        if open_capacity >= next_item_size as f64 && open_capacity < cap * 0.55 {
            score += 14.0 * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION (gen 33): residual ladder anti-fragmentation sweep.
    if pr > 0 && mean_residual >= 4.0 && progress > 0.2 && progress < 0.88 {
        let mr = mean_residual.min(cap);
        let below = mr - pr as f64;
        if below > 0.0 && below <= 3.0 {
            let crowd = if open_bins_count > 10 { 1.3 } else { 1.0 };
            score += (4.0 + 3.0 * (1.0 - below / 4.0)) * crowd * (1.0 - 0.4 * progress);
        } else if below < 0.0 && -below <= 2.0 {
            score -= 5.0 * (1.0 - (-below) / 3.0) * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 33): endgame exact-closure ladder extension.
    if progress > 0.85 && next_item_size > 0 && pr == item_size.max(1) + next_item_size {
        score -= 14.0 * ((progress - 0.85) / 0.15);
    }

    // MUTATION (gen 41): graded dead-space gradient.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.93 {
        let demand = (next_item_size as f64).max(mean_residual * 0.85);
        let prf = pr as f64;
        let crowd = if open_bins_count > 8 { 1.35 } else { 1.0 };
        if prf >= demand {
            let slack = prf - demand;
            if slack <= 4.0 {
                score -= (9.0 + 3.0 * (4.0 - slack)) * (1.0 - 0.5 * progress);
            } else if slack < item_size as f64 {
                score += 3.0 * (slack / item_size.max(1) as f64) * (1.0 - 0.5 * progress);
            }
        } else {
            let dead = 1.0 - prf / demand;
            score += 17.0 * dead * dead * crowd * (1.0 - 0.45 * progress);
        }
    }

    // MUTATION (gen 41): fresh-bin horizon-parity override.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && item_size + next_item_size <= bin_capacity
        && fitting_bins_count >= 1
        && progress > 0.05
        && progress < 0.9
    {
        let pair = (item_size + next_item_size) as f64;
        let fresh_left = cap - pair;
        let open_left = (mean_residual - pair).max(0.0);
        let margin = fresh_left - open_left;
        let thr = 3.0 + 4.0 * progress;
        if margin > thr {
            score -= (10.0 + margin.min(24.0) * 0.7) * (1.0 - 0.5 * progress);
        } else if margin < -thr {
            score += 13.0 * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 41): endgame sliver-pooling ladder.
    if progress > 0.8 && pr > 0 && mean_residual >= 2.0 {
        let mr = mean_residual.min(cap * 0.6);
        let prf = pr as f64;
        if (prf - 2.0 * mr).abs() <= 1.0 {
            score -= 16.0 * ((progress - 0.8) / 0.2);
        } else if next_item_size > 0 && (prf - (next_item_size as f64 + mr)).abs() <= 1.0 {
            score -= 12.0 * ((progress - 0.8) / 0.2);
        }
    }

    // MUTATION (gen 41): near-closure slack shaping.
    if pr > 0 && next_item_size > 1 && progress > 0.1 && progress < 0.9 {
        let k = (pr as f64 / next_item_size as f64).round();
        if k >= 1.0 {
            let dev = (pr as f64 - k * next_item_size as f64).abs();
            if dev <= 2.0 {
                score -= 6.0 * (1.0 - dev / 3.0) * (1.0 - 0.4 * progress);
            }
        }
    }

    // MUTATION (gen 44): multi-step lookahead depth — three-cycle probe.
    if next_item_size > 0
        && item_size > 0
        && progress > 0.15
        && progress < 0.9
        && pr >= 3 * next_item_size.max(1)
    {
        let cycle = 3 * next_item_size;
        let rem = pr - cycle;
        if rem == 0 {
            score -= 34.0 * (1.0 - 0.4 * progress);
        } else if rem <= 3 {
            score -= 18.0 * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 44): best-fit dominance tightening.
    if bin_residual >= item_size && fitting_bins_count >= 2 {
        let slack = bin_residual - item_size;
        if slack == 0 {
            score -= 10.0;
        } else if slack >= 3 && slack <= 8 && pr > 0 && next_item_size > 0 && (pr as u32) < next_item_size {
            score += 6.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 44): fresh-bin last-resort guard.
    if bin_residual == bin_capacity && pr == 0 && fitting_bins_count >= 1 {
        score += 1600.0;
    }

    // MUTATION (gen 45): fine-grained zero/one-slack dominance — extend the
    // exact-slack reward to slack == 1 with a slightly weaker weight, since
    // a single unit of leftover is still near-perfect compaction; combine
    // with lookahead so bins whose slack matches item+next also rank high.
    if bin_residual >= item_size && fitting_bins_count >= 2 {
        let slack = bin_residual - item_size;
        if slack == 1 {
            score -= 7.0 * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && slack >= next_item_size && slack <= next_item_size + 1 {
            score -= 9.0 * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 45): dead-space ratio lookahead coupling — when the
    // post-residual is dead space (below next item), penalize proportionally
    // to how much of the bin's remaining space is stranded; when it can
    // absorb next AND still tile with mean residual, reward the chain.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress > 0.1 && progress < 0.92 {
        let prf = pr as f64;
        let nf = next_item_size as f64;
        if prf < nf {
            let stranded = (nf - prf) / cap;
            score += 20.0 * stranded * (1.0 - 0.5 * progress) * (if fitting_bins_count > 2 { 1.2 } else { 0.9 });
        } else {
            let pr2 = prf - nf;
            let mr = mean_residual.min(cap * 0.5);
            let gap = (pr2 - mr).abs();
            if gap <= 2.0 {
                score -= 10.0 * (1.0 - gap / 3.0) * (1.0 - 0.4 * progress);
            }
        }
    }

    // MUTATION (gen 45): fresh-bin strict-dominance margin — open a fresh bin
    // only if the fresh leftover after placing item+next beats the best
    // open leftover by a progress-scaled margin; otherwise veto.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && item_size + next_item_size <= bin_capacity
        && fitting_bins_count >= 1
        && progress > 0.05
        && progress < 0.9
    {
        let pair = (item_size + next_item_size) as f64;
        let fresh_left = cap - pair;
        let open_left = (mean_residual - pair).max(0.0);
        let margin = fresh_left - open_left;
        let thr = 3.0 + 4.0 * progress;
        if margin > thr {
            score -= (10.0 + margin.min(24.0) * 0.7) * (1.0 - 0.5 * progress);
        } else if margin < -thr {
            score += 12.0 * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 45): mean-residual saturation deficit — when open
    // residuals are too small for the next item, a fresh bin absorbs the
    // pair cleanly; reward proportionally to the deficit.
    if bin_residual == bin_capacity
        && next_item_size > 0
        && mean_residual > 0.0
        && (mean_residual as u32) < next_item_size
        && fitting_bins_count >= 1
        && progress > 0.1
        && progress < 0.85
    {
        let deficit = 1.0 - mean_residual / next_item_size as f64;
        score -= 16.0 * deficit * deficit * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "dense" residue classes (multiples of a fine quantum) are more likely
    // to host future items, so reward them (subtract).
    let quantum: u32 = 10;
    let residue_class = post_residual % quantum;
    if post_residual > 0 {
        // exact multiple of quantum -> very reusable leftover
        if residue_class == 0 {
            score -= 12.0;
        } else {
            // penalize awkward classes proportionally to distance from quantum grid
            score += (residue_class as f64) * 0.9;
        }
    }

    // Integer-division thresholds on post_residual: classify leftover size.
    if post_residual == 0 {
        score -= 20.0; // perfect closure
    } else if post_residual <= 15 {
        score -= 6.0; // small dead space, acceptable
    } else if post_residual <= 30 {
        score += 4.0; // medium leftover: risky zone
    } else if post_residual <= 50 {
        score -= 3.0; // large leftover, still useful
    } else {
        score += 2.0; // huge leftover: this bin was nearly empty
    }

    // Capacity-fraction coupling: leftover near common item fractions
    // (1/4, 1/3, 1/2 of capacity) is statistically reusable.
    let quarter = cap * 0.25;
    let third = cap / 3.0;
    let half = cap * 0.5;
    for anchor in [quarter, third, half] {
        let d = (pr - anchor).abs();
        if d <= 5.0 {
            score -= (5.0 - d) * 1.5;
        }
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let npr = post_residual - next_item_size;
            score -= (npr as f64) * 0.15;
            if npr % quantum == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this leftover; penalize by gap size
            score += ((next_item_size - post_residual) as f64).min(30.0) * 0.2;
        }
    }

    // Last-chance dynamics: if this is the only fitting bin, avoid wasting it
    // on a tiny item unless the fit is tight.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tight = (item_size as f64) / (bin_residual as f64);
        if tight < 0.35 {
            score += 14.0; // don't burn the only bin on a small item
        } else {
            score -= 5.0 * tight;
        }
    }

    // New-bin candidate handling: opening a bin is fine early or when no
    // open bin gives a tight fit; discourage when stream is late and mean
    // residual is large (existing bins can absorb).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = (item_size as f64) / cap;
        // prefer new bin for large items or when mean residual is small
        score = 35.0 - 18.0 * tightness + 20.0 * progress * (mean_residual / cap).min(1.0);
        if post_residual % quantum == 0 && item_size >= bin_capacity / 2 {
            score -= 8.0; // fresh bin with a clean harmonic leftover
        }
    }

    // Mild global pressure: many open bins with high mean residual ->
    // encourage consolidation into existing bins.
    score += (open_bins_count as f64).ln() * 1.2 * (mean_residual / cap).clamp(0.0, 1.0);

    // Small tie-break on exact fill ratio class (integer division of item size)
    let item_class = item_size / 20; // 0..4 harmonic class of item size
    score -= item_class as f64 * 0.5;

    score
}

