        // Horizon-parity margin — fresh bin only when fresh leftover after
        // item+next beats best open leftover clearly.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity
            && fitting_bins_count >= 1 && progress > 0.05 && progress < 0.9
        {
            let pair = (item_size + next_item_size) as f64;
            let fresh_left = cap - pair;
            let open_left = (mean_residual - pair).max(0.0);
            let margin = fresh_left - open_left;
            let thr = 3.0 + 4.0 * progress;
            if margin > thr {
                score -= (10.0 + margin.min(24.0) * 0.7) * (1.0 - 0.5 * progress);
            } else if margin < -thr {
                score += 12.0 * (1.0 - 0.4 * progress);
            }
        }
        // Saturation deficit — fresh bin absorbs pair cleanly when open
        // residuals cannot host the next item.
        if next_item_size > 0 && mean_residual > 0.0
            && (mean_residual as u32) < next_item_size
            && fitting_bins_count >= 1 && progress > 0.1 && progress < 0.85
        {
            let deficit = 1.0 - mean_residual / next_item_size as f64;
            score -= 16.0 * deficit * deficit * (1.0 - progress);
        }
        // MUTATION (gen 46): fresh-bin horizon alignment — open a fresh bin
        // when the item+next pair fills it to a near-exact capacity fraction
        // matching the mean fill level, avoiding half-empty new bins.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity && progress > 0.08 {
            let pair_frac = (item_size + next_item_size) as f64 / cap;
            let fill_gap = (pair_frac - (1.0 - mean_residual / cap)).abs();
