        }
    }

    // MUTATION (gen 45): two-step exact-closure ladder.
    if next_item_size > 0 && item_size > 0 && pr >= item_size + next_item_size {
        let pr2 = pr - item_size - next_item_size;
        if pr2 == 0 {
            score -= 30.0 + 25.0 * (1.0 - progress);
        } else if pr2 <= 3 {
            score -= 16.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 45): late-stream tight-slack refinement.
    if progress > 0.66 && bin_residual >= item_size {
        let slack = bin_residual - item_size;
        if slack >= 3 && slack <= 6 && pr > 0 {
            score += 5.0 + 2.0 * (progress - 0.66) / 0.34;
        }
    }

    // MUTATION (gen 45): endgame sliver-pooling ladder.
    if progress > 0.8 && pr > 0 && mean_residual >= 2.0 {
        let mr = mean_residual.min(cap * 0.6);
        let prf = pr as f64;
        if (prf - 2.0 * mr).abs() <= 1.0 {
            score -= 16.0 * ((progress - 0.8) / 0.2);
        } else if next_item_size > 0 && (prf - (next_item_size as f64 + mr)).abs() <= 1.0 {
            score -= 12.0 * ((progress - 0.8) / 0.2);
        }
    }

    // MUTATION (gen 45): near-closure slack shaping — residuals within 2
    // units of a multiple of the next item tile perfectly.
    if pr > 0 && next_item_size > 1 && progress > 0.1 && progress < 0.9 {
        let k = (pr as f64 / next_item_size as f64).round();
        if k >= 1.0 {
            let dev = (pr as f64 - k * next_item_size as f64).abs();
            if dev <= 2.0 {
                score -= 6.0 * (1.0 - dev / 3.0) * (1.0 - 0.4 * progress);
            }
        }
    }

    // MUTATION (gen 46): residual-spectrum coupling — reward residuals that
    // tile the mean residual exactly (dead-space reuse across bins), with a
    // crowding-scaled quadratic ramp on the tiling remainder.
    if pr > 0 && mean_residual >= 2.0 && progress > 0.15 && progress < 0.9 {
        let mr = mean_residual.min(cap * 0.6);
        let k = (pr as f64 / mr).floor();
        if k >= 1.0 {
            let rem = pr as f64 - k * mr;
            let crowd = if open_bins_count > 10 { 1.25 } else { 1.0 };
            if rem == 0.0 {
                score -= (7.0 + 3.0 * k.min(4.0)) * crowd * (1.0 - 0.5 * progress);
            } else if rem <= 2.0 {
                score -= (4.0 * (1.0 - rem / 3.0)) * crowd * (1.0 - 0.5 * progress);
            } else if rem >= mr - 2.0 {
                // residual nearly one more mean-tile: very absorbent
                score -= 5.0 * (1.0 - (mr - rem) / 3.0) * (1.0 - 0.5 * progress);
            }
        }
    }

    // MUTATION (gen 46): waste-floor parity gate — penalize residuals that
    // leave an odd sliver relative to the combined (item + next) demand when
    // the bin cannot be closed exactly; reward parity with cap/2 tiling.
    if pr > 0 && next_item_size > 0 && progress > 0.2 && progress < 0.95 {
        let combined = (item_size + next_item_size) as f64;
        if combined < cap && pr as f64 > combined {
            let leftover = pr as f64 - combined;
            if leftover < 8.0 && leftover > 0.0 {
                score += (9.0 - leftover) * (1.0 - 0.5 * progress);
            } else if leftover == 0.0 {
                score -= 14.0 * (1.0 - 0.4 * progress);
            }
        }
        // half-capacity parity: residual near an exact multiple of cap/2
        let half = cap * 0.5;
        let kh = (pr as f64 / half).round();
        if kh >= 1.0 {
            let dev = (pr as f64 - kh * half).abs();
            if dev <= 1.5 {
                score -= 8.0 * (1.0 - dev / 2.5) * (1.0 - 0.5 * progress);
            }
        }
    }

    // MUTATION (gen 46): scarcity-aware tightness escalation — when only a
    // couple of bins fit, deepen the reward for slack <= 4 fits so the
    // remaining open capacity is consumed before opening new bins.
    if bin_residual >= item_size && fitting_bins_count <= 2 && progress < 0.9 {
        let slack = bin_residual - item_size;
        if slack <= 4 {
            let depth = 1.0 - slack as f64 / 5.0;
            score -= 10.0 * depth * depth * (1.0 - 0.6 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Perfect/near-perfect closure rewards.
    if pr == 0 {
        score -= 1265.0;
    } else if pr <= 4 {
        score -= 90.0 + (4 - pr) as f64 * 13.0;
    } else if pr < 12 {
        score += 28.0 - pr as f64;
    }

    // Harmonic residue classes.
    let class_bonus: f64 = if pr % 10 == 0 {
        35.0
    } else if pr % 5 == 0 {
        17.0
    } else if pr % 2 == 0 {
        5.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Lookahead fit quality into post-placement residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 172.0 + 38.0 * (1.0 - progress);
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= if slack <= 10 { 64.0 - slack as f64 * 2.6 } else { 33.0 - (slack as f64).min(30.0) * 0.5 };
        } else {
            score += (next_item_size - pr) as f64 * 0.65;
        }
        if next_item_size < pr {
            let pr2 = pr - next_item_size;
            if pr2 <= 5 {
                score -= 48.0;
            } else if pr2 == next_item_size {
                score -= 26.0;
            } else if pr2 % 10 == 0 {
                score -= 11.0;
            }
            if pr2 > 5 && next_item_size > 1 && pr2 % next_item_size == 0 {
                score -= 14.0;
            }
            if pr2 > 0 && mean_residual > 0.0 {
                let proxy = mean_residual.round() as u32;
                if proxy >= 1 && proxy <= pr2 {
                    score -= 9.0 * (1.0 - progress);
                }
            }
            if pr2 >= 2 * next_item_size {
                let pr3 = pr2 - 2 * next_item_size;
                if pr3 <= 3 {
                    score -= 23.0 * (1.0 - progress);
                }
            }
            if pr2 >= item_size.max(1) {
                let pr3 = pr2 - item_size.max(1);
                if pr3 <= 2 {
                    score -= 19.0 * (1.0 - progress);
                }
            }
        }
        if pr > 1 && pr == 2 * next_item_size {
            score -= 21.0;
        }
        if pr > 0 && pr < next_item_size {
            let gap_frac = 1.0 - (pr as f64 / next_item_size as f64);
            score += (7.0 + 5.0 * gap_frac) * (1.0 - progress);
        }
    } else {
        score -= 20.0;
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 62.0;
    }

    // Open-bin pressure: mild proliferation penalty with progress coupling.
    score += open_bins_count as f64 * (0.25 + 0.25 * progress) - 2.0;

    // Best-fit bias.
    score -= (bin_capacity - bin_residual) as f64 * 0.15;

    // Mean-residual alignment.
    let align = ((pr as f64 - mean_residual) / cap).abs();
    score += align * (if progress > 0.2 && progress < 0.8 { 4.5 } else { 6.0 });

    // Waste-avoidance for tiny residuals.
    if pr > 0 && pr < bin_capacity / 5 {
        let scarcity = if fitting_bins_count > 2 { 0.6 } else { 1.4 };
        score += (10.0 + 4.0 * progress) * scarcity;
    }

    // Tightness bonus.
    if bin_residual >= item_size {
        let tightness = 1.0 - ((bin_residual - item_size) as f64 / cap);
        score -= 6.0 * tightness;
        let slack = bin_residual - item_size;
        if slack <= 2 {
            let scarcity = if fitting_bins_count <= 2 { 1.6 } else { 1.0 };
            score -= (14.0 + 8.0 * (2 - slack) as f64) * scarcity * (1.0 - 0.4 * progress);
        }
    }

    // ---- Fresh-bin gating ----
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap) < 0.38;
        let reuse_is_bad = fitting_bins_count <= 1
            || (pr > 0 && next_item_size > pr && next_item_size <= bin_capacity);
        let late_large = item_size >= 60 && progress > 0.10;
        if late_large || (tight && progress > 0.15) || reuse_is_bad {
            score -= 45.0 + 29.0 * progress;
        } else {
            score += 68.0;
        }
        if item_size <= 25 && mean_residual > cap * 0.45 {
            score += 35.0;
        }
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 23.0 + 17.0 * (1.0 - progress);
        }
        if next_item_size >= bin_capacity / 2 && mean_residual < (item_size + next_item_size) as f64 {
            score -= 10.0 + 14.0 * (1.0 - progress);
        }
        if item_size + next_item_size == bin_capacity {
            score -= 33.0 + 19.0 * (1.0 - progress);
        }
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size && fitting_bins_count > 1 && !late_large {
            score += 29.0 * (1.0 - progress);
        }
        // Fresh-bin slot-arithmetic probe.
        if item_size > 0 && bin_capacity % item_size == 0 {
            let slots = bin_capacity / item_size;
            if slots >= 2 && slots <= 4 && progress > 0.1 {
                score -= 14.0 * (slots as f64).min(3.0) * (1.0 - 0.5 * progress);
            }
        }
        if progress > 0.7 && fitting_bins_count > 0 && !late_large {
            score += 44.0 * ((progress - 0.7) / 0.3);
        }
        // MUTATION (gen 46): horizon-parity margin — fresh bin only when its
        // leftover after hosting item+next beats the open-bin leftover clearly.
        if next_item_size > 0
            && item_size + next_item_size <= bin_capacity
            && fitting_bins_count >= 1
            && progress > 0.05
            && progress < 0.9
        {
            let pair = (item_size + next_item_size) as f64;
            let fresh_left = cap - pair;
            let open_left = (mean_residual - pair).max(0.0);
            let margin = fresh_left - open_left;
            let thr = 3.0 + 4.0 * progress;
            if margin > thr {
                score -= (10.0 + margin.min(24.0) * 0.7) * (1.0 - 0.5 * progress);
            } else if margin < -thr {
                score += 12.0 * (1.0 - 0.4 * progress);
            }
        }
        // MUTATION (gen 46): saturation deficit — open residuals too small
        // for the next item make a fresh bin attractive.
        if next_item_size > 0
            && mean_residual > 0.0
            && (mean_residual as u32) < next_item_size
            && fitting_bins_count >= 1
            && progress > 0.1
            && progress < 0.85
        {
            let deficit = 1.0 - mean_residual / next_item_size as f64;
            score -= 16.0 * deficit * deficit * (1.0 - progress);
        }
        // MUTATION (gen 46): endgame small-item veto.
        if progress > 0.8 {
            let rel = item_size as f64 / cap;
            if rel < 0.5 && fitting_bins_count > 0 {
                score += 18.0 * (1.0 - rel) * ((progress - 0.8) / 0.2);
            }
        }
    }

    // MUTATION (gen 46): graded dead-space gradient around the demand horizon.
    if pr > 0 && next_item_size > 0 && mean_residual > 0.0 && progress < 0.93 {
        let demand = (next_item_size as f64).max(mean_residual * 0.85);
        let prf = pr as f64;
        let crowd = if open_bins_count > 8 { 1.35 } else { 1.0 };
        if prf >= demand {
            let slack = prf - demand;
            if slack <= 4.0 {
                score -= (9.0 + 3.0 * (4.0 - slack)) * (1.0 - 0.5 * progress);
            } else if slack < item_size as f64 {
                score += 3.0 * (slack / item_size.max(1) as f64) * (1.0 - 0.5 * progress);
            }
        } else {
            let dead = 1.0 - prf / demand;
            score += 16.0 * dead * dead * crowd * (1.0 - 0.45 * progress);
        }
    }

    // MUTATION (gen 46): two-step exact-closure ladder.
    if next_item_size > 0 && item_size > 0 && pr >= item_size + next_item_size {
        let pr2 = pr - item_size - next_item_size;
        if pr2 == 0 {
            score -= 30.0 + 25.0 * (1.0 - progress);
        } else if pr2 <= 3 {
            score -= 16.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 46): near-closure slack shaping.
    if pr > 0 && next_item_size > 1 && progress > 0.1 && progress < 0.9 {
        let k = (pr as f64 / next_item_size as f64).round();
        if k >= 1.0 {
            let dev = (pr as f64 - k * next_item_size as f64).abs();
            if dev <= 2.0 {
                score -= 6.0 * (1.0 - dev / 3.0) * (1.0 - 0.4 * progress);
            }
        }
    }

    // MUTATION (gen 46): late-stream tight-slack refinement.
    if progress > 0.66 && bin_residual >= item_size {
        let slack = bin_residual - item_size;
        if slack >= 3 && slack <= 6 && pr > 0 {
            score += 5.0 + 2.0 * (progress - 0.66) / 0.34;
        }
    }

    // MUTATION (gen 46): endgame sliver-pooling ladder.
    if progress > 0.8 && pr > 0 && mean_residual >= 2.0 {
        let mr = mean_residual.min(cap * 0.6);
        let prf = pr as f64;
        if (prf - 2.0 * mr).abs() <= 1.0 {
            score -= 16.0 * ((progress - 0.8) / 0.2);
        } else if next_item_size > 0 && (prf - (next_item_size as f64 + mr)).abs() <= 1.0 {
            score -= 12.0 * ((progress - 0.8) / 0.2);
        }
    }

    // Mid-stream consolidation of large absorbable residuals.
    if open_bins_count > 8 && progress > 0.25 && progress < 0.85 && pr >= 40 {
        score -= 9.0;
    }

    // Dead-space ratio shaping with next-item floor.
    if pr > 0 && next_item_size > 0 {
        let dead_threshold = (next_item_size + 12).min(bin_capacity);
        if pr < dead_threshold {
            let dead_frac = 1.0 - (pr as f64 / dead_threshold as f64);
            score += 17.0 * dead_frac * (1.0 - progress);
        } else if pr >= dead_threshold * 2 {
            score -= 8.0 + 4.0 * (1.0 - progress);
        } else if pr == next_item_size + item_size {
            score -= 5.0;
        }
    }

    // Endgame exactness.
    if progress > 0.9 && pr > 0 {
        score += pr as f64 * 0.35;
        if pr <= next_item_size.max(1) {
            score -= 20.0;
        }
    }

    // Perfect-fit dominance gate for the fresh-bin candidate.
    if pr == 0 && bin_residual == bin_capacity {
        score += 1400.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Strong exact/near-exact closure rewards (borrowed, strengthened).
    if pr == 0 {
